"""Bounded native graph walk for approved theme export and provenance."""

node Theme {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version: str = "";
    has approved: bool = False;
}

node Screen {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has field_count: int = 0;
    has action_count: int = 0;
    has binding_count: int = 0;
    has navigation_target: str = "";
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provenance: str = "";
}

node Asset {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has licensing: str = "";
}

edge Contains {
    has label: str = "";
}

edge AppliesTheme {
    has theme_version: str = "";
}

edge BackedBy {
    has source: str = "";
}

edge UsesAsset {
    has licensing: str = "";
}

walker ThemeExporter {
    has budget: int = 16;

    can start with Root entry {
        print("Export traversal started");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Theme entry {
        if self.budget <= 0 {
            print("Traversal budget exhausted");
            disengage;
        }
        self.budget = self.budget - 1;
        print(f"theme {here.title} {here.version} approved={here.approved}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Screen entry {
        if self.budget <= 0 {
            print("Traversal budget exhausted");
            disengage;
        }
        self.budget = self.budget - 1;
        print(f"screen {here.title}: fields={here.field_count}, "
              f"actions={here.action_count}, bindings={here.binding_count}, "
              f"navigation={here.navigation_target}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Evidence entry {
        if self.budget <= 0 {
            print("Traversal budget exhausted");
            disengage;
        }
        self.budget = self.budget - 1;
        print(f"provenance {here.provenance}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Asset entry {
        if self.budget <= 0 {
            print("Traversal budget exhausted");
            disengage;
        }
        self.budget = self.budget - 1;
        print(f"asset {here.title}: license={here.licensing}");
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    theme = Theme(
        title="Approved Braavo theme",
        year=2026,
        version="theme-v3",
        approved=True
    );

    neutral = Screen(
        title="Neutral preview",
        year=2026,
        field_count=4,
        action_count=2,
        binding_count=3,
        navigation_target="Dashboard"
    );

    branded = Screen(
        title="Branded preview",
        year=2026,
        field_count=4,
        action_count=2,
        binding_count=3,
        navigation_target="Dashboard"
    );

    evidence = Evidence(
        title="Approved brand guide",
        year=2026,
        provenance="brand-guide-revision-7"
    );

    logo = Asset(
        title="Approved logo",
        year=2026,
        licensing="CC-BY-approved"
    );

    root +>:Contains(label="theme model"):+> theme;
    theme +>:AppliesTheme(theme_version="theme-v3"):+> neutral;
    theme +>:AppliesTheme(theme_version="theme-v3"):+> branded;
    theme +>:BackedBy(source="brand-guide-revision-7"):+> evidence;
    branded +>:UsesAsset(licensing="CC-BY-approved"):+> logo;

    root spawn ThemeExporter();
}

"""Offline map-building composition with typed pipeline edges and cycle detection."""

node ApplicationRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_id: str = "";
    has provenance: str = "";
    has lifecycle: str = "created";
}

node InputAdapter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_kind: str = "";
}

node ObservationBatch {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sample_count: int = 0;
}

node MappingStage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stage_kind: str = "";
}

edge ConfiguredInput { }
edge Supplies { has source: str = ""; }
edge PipelineStep { has order: int = 0; }

walker CompositionWalker {
    has seen_titles: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can configure with ApplicationRun entry {
        here.lifecycle = "running";
        print(f"run {here.run_id} started from {here.provenance}");
        visit [->:ConfiguredInput:->] else {
            disengage;
        }
    }

    can load with InputAdapter entry {
        if here.title in self.seen_titles {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}");
            disengage;
        }
        if here.available == False {
            print(f"adapter unavailable: {here.title}");
            disengage;
        }
        self.seen_titles = self.seen_titles + [here.title];
        print(f"adapter loaded: {here.title} ({here.source_kind})");
        visit [->:Supplies:->] else {
            disengage;
        }
    }

    can advance with ObservationBatch | MappingStage entry {
        if here.title in self.seen_titles {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}");
            disengage;
        }
        if here.available == False {
            print(f"pipeline item invalidated: {here.title}");
            disengage;
        }
        self.seen_titles = self.seen_titles + [here.title];
        print(f"processing {here.title} ({here.year})");
        visit [->:PipelineStep:->] else {
            disengage;
        }
    }

    can report with ApplicationRun exit {
        here.lifecycle = "completed";
        print(f"run {here.run_id} completed");
    }
}

with entry {
    run = ApplicationRun(
        title="Offline map build",
        run_id="run-106",
        provenance="synthetic multimodal sequence"
    );
    adapter = InputAdapter(
        title="Dataset adapter",
        source_kind="recorded observations"
    );
    observations = ObservationBatch(
        title="Normalized observations",
        sample_count=3
    );
    state = MappingStage(title="State estimation", stage_kind="state");
    geometry = MappingStage(title="Geometric mapping", stage_kind="geometry");
    visual = MappingStage(title="Visual processing", stage_kind="visual");
    semantic = MappingStage(title="Semantic mapping", stage_kind="semantic");

    root ++> run;
    run +>:ConfiguredInput:+> adapter;
    adapter +>:Supplies(source="validated dataset"):+> observations;
    observations +>:PipelineStep(order=1):+> state;
    state +>:PipelineStep(order=2):+> geometry;
    geometry +>:PipelineStep(order=3):+> visual;
    visual +>:PipelineStep(order=4):+> semantic;
    semantic +>:PipelineStep(order=5):+> geometry;

    runner = CompositionWalker();
    root spawn runner;

    print(f"cycle guard engaged: {runner.cycle_found}");
}

"""Incremental build invalidation over a typed dependency graph."""

node BuildConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has cache_valid: bool = True;
}

node SourceFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has content_hash: str = "";
    has cached_hash: str = "";
    has unit_kind: str = "component";
    has invalidated: bool = False;
}

edge DependsOn {
    has relation: str = "";
}

walker InvalidationAudit {
    has changed_path: str = "";
    has seen_paths: list[str] = [];
    has invalidated_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can begin with BuildConfig entry {
        print(f"Using incremental cache for {here.path}: {here.cache_valid}");
        visit [-->] else {
            disengage;
        }
    }

    can invalidate with SourceFile entry {
        if here.path in self.seen_paths {
            self.cycle_found = True;
            print(f"Dependency cycle detected at {here.path}");
            disengage;
        } else {
            self.seen_paths.append(here.path);
            here.invalidated = True;
            self.invalidated_count = self.invalidated_count + 1;
            reason = "content changed" if here.path == self.changed_path else "dependent invalidation";
            print(f"Recompile {here.path} ({here.unit_kind}): {reason}");
            visit [<--:DependsOn:--] else {
                disengage;
            }
        }
    }
}

with entry {
    config = BuildConfig(
        title="avenx.config.json",
        path="avenx.config.json",
        cache_valid=True
    );

    bridge = SourceFile(
        title="bridge.js",
        path="src/bridge.js",
        content_hash="new-bridge",
        cached_hash="old-bridge",
        unit_kind="bridge"
    );

    component = SourceFile(
        title="Button.js",
        path="src/Button.js",
        content_hash="button-v1",
        cached_hash="button-v1",
        unit_kind="component"
    );

    page = SourceFile(
        title="Home.js",
        path="src/Home.js",
        content_hash="home-v1",
        cached_hash="home-v1",
        unit_kind="page"
    );

    route = SourceFile(
        title="routes.js",
        path="src/routes.js",
        content_hash="routes-v1",
        cached_hash="routes-v1",
        unit_kind="route"
    );

    root ++> config ++> bridge;
    component +>:DependsOn(relation="imports"):+> bridge;
    page +>:DependsOn(relation="renders"):+> component;
    route +>:DependsOn(relation="routes_to"):+> page;
    bridge +>:DependsOn(relation="cycle-check"):+> route;

    auditor = InvalidationAudit(changed_path="src/bridge.js");
    root spawn auditor;

    print(f"Invalidated units: {auditor.invalidated_count}");
    print(f"Cycle found: {auditor.cycle_found}");
}

"""Dungeon quality analysis with typed graph traversal and cycle detection."""

node Dungeon {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Room {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "normal";
    has depth: int = 0;
    has exits: int = 0;
    has visited: bool = False;
}

edge Contains {
    has relation: str = "";
}

edge Passage {
    has length: int = 0;
    has critical: bool = False;
}

walker QualityAuditor {
    has rooms_seen: int = 0;
    has passage_count: int = 0;
    has dead_ends: int = 0;
    has cycle_hits: int = 0;
    has max_depth: int = 0;
    has cycle_rank: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can audit with Dungeon entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Room entry {
        if here.visited {
            self.cycle_hits += 1;
            print(f"cycle encounter at {here.title}");
        } else {
            here.visited = True;
            self.rooms_seen += 1;
            self.passage_count += here.exits;

            if here.depth > self.max_depth {
                self.max_depth = here.depth;
            }

            print(f"room {here.title}: kind={here.kind}, depth={here.depth}");

            visit [->:Passage:->] else {
                self.dead_ends += 1;
            }
        }
    }

    can report with Root exit {
        self.cycle_rank = self.passage_count - self.rooms_seen + 1;
        print(f"rooms={self.rooms_seen}, passages={self.passage_count}");
        print(f"dead_ends={self.dead_ends}, max_depth={self.max_depth}");
        print(f"cycle_rank={self.cycle_rank}, cycle_hits={self.cycle_hits}");
    }
}

