"""Roll up inventory through nested locations with typed-edge traversal."""

node Location {
    has title: str = "";
    has available: bool = True;
}

node Item {
    has title: str = "";
    has sku: str = "";
    has available: bool = True;
}

node StockEntry {
    has title: str = "";
    has quantity: int = 0;
    has available: bool = True;
}

edge Contains { }
edge ForItem { }

walker InventoryRollup {
    has item_count: int = 0;
    has unit_count: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can descend with Location entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with StockEntry entry {
        self.item_count += 1;
        self.unit_count += here.quantity;
        visit [->:ForItem:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"Nested inventory: {self.item_count} item(s), {self.unit_count} unit(s)");
    }
}

with entry {
    parent = Location(title="Warehouse");
    child = Location(title="Shelf B");
    stock = StockEntry(title="Shelf B stock", quantity=4);
    item = Item(title="Widget", sku="W-104");

    root +>:Contains:+> parent;
    parent +>:Contains:+> child;
    child +>:Contains:+> stock;
    stock +>:ForItem:+> item;

    root spawn InventoryRollup();
}

"""Bounded PR review graph with safe context traversal and cycle guards."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has full_name: str = "";
    has visited: bool = False;
}

node PullRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has number: int = 0;
    has event_action: str = "";
    has delivery_key: str = "";
    has base_sha: str = "";
    has head_sha: str = "";
    has author: str = "";
    has draft: bool = False;
    has closed: bool = False;
    has merged: bool = False;
    has head_present: bool = True;
    has changed_file_count: int = 0;
    has all_pages_loaded: bool = True;
    has visited: bool = False;
}

node ChangedFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has patch_lines: int = 0;
    has patch_bytes: int = 0;
    has binary: bool = False;
    has generated: bool = False;
    has lockfile: bool = False;
    has reviewable: bool = True;
    has visited: bool = False;
}

node ContextDocument {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has rule_key: str = "";
    has surface: str = "";
    has bytes: int = 0;
    has sensitive: bool = False;
    has visited: bool = False;
}

edge ContainsRepo { }
edge HasPullRequest { }
edge Changes { }
edge UsesContext { }

walker BoundedReviewer {
    has max_files: int = 3;
    has max_context_bytes: int = 1200;
    has files_seen: int = 0;
    has context_bytes: int = 0;
    has partial: bool = False;

    can start with Root entry {
        visit [->:ContainsRepo:->] else {
            disengage;
        }
    }

    can inspect with Repository entry {
        if here.visited {
            print("cycle detected at repository");
            disengage;
        }
        here.visited = True;
        print(f"repository: {here.full_name}");
        visit [->:HasPullRequest:->] else {
            disengage;
        }
    }

    can inspect with PullRequest entry {
        if here.visited {
            print("cycle detected at pull request");
            disengage;
        }
        here.visited = True;

        if here.closed {
            print(f"PR {here.number} is closed; no review run");
            disengage;
        }
        if here.merged {
            print(f"PR {here.number} is merged; no review run");
            disengage;
        }
        if here.head_present == False {
            print(f"PR {here.number} has a deleted head; partial review");
            self.partial = True;
            disengage;
        }
        if here.all_pages_loaded == False {
            print(f"PR {here.number} changed-file pages are incomplete");
            self.partial = True;
        }

        draft_state = "draft" if here.draft else "ready";
        print(f"PR {here.number}: {here.event_action} ({draft_state})");
        visit [->:Changes:->] else {
            disengage;
        }
    }

    can inspect with ChangedFile entry {
        if here.visited {
            print(f"cycle detected at file {here.title}");
            disengage;
        }
        here.visited = True;

        if self.files_seen >= self.max_files {
            self.partial = True;
            print(f"file limit reached; omitted {here.title}");
            disengage;
        }

        self.files_seen += 1;
        if here.binary {
            print(f"binary file skipped: {here.title}");
            disengage;
        }
        if here.generated {
            print(f"generated file summarized: {here.title}");
            disengage;
        }
        if here.lockfile {
            print(f"lockfile summarized: {here.title}");
            disengage;
        }

        print(f"bounded patch: {here.title} ({here.patch_bytes} bytes)");
        visit [->:UsesContext:->] else {
            disengage;
        }
    }

    can inspect with ContextDocument entry {
        if here.visited {
            print(f"cycle detected at context {here.title}");
            disengage;
        }
        here.visited = True;

        if self.context_bytes + here.bytes > self.max_context_bytes {
            self.partial = True;
            print(f"context budget reached; omitted {here.title}");
            disengage;
        }

        self.context_bytes += here.bytes;
        display_name = "[REDACTED]" if here.sensitive else here.title;
        print(f"context selected by {here.rule_key}: {display_name}");
    }
}

