"""Native QA review workflow with revision binding, validation gates, findings, and rework routing."""

node Task {
    has title: str = "";
    has expected_revision: str = "";
    has context_ready: bool = False;
    has prior_qa_revision: str = "";
}

node Revision {
    has label: str = "";
    has hash: str = "";
    has dev_validated: bool = False;
    has dev_validation_revision: str = "";
}

node QAReport {
    has result: str = "";
    has reviewed_revision: str = "";
    has blocking: bool = False;
    has finding: str = "";
    has remediation: str = "";
}

edge ReviewTask { }
edge TargetRevision { }
edge QAOutcome { }

walker QAReviewer {
    has expected_revision: str = "";
    has bound_qa_revision: str = "";
    has revision_hash: str = "";
    has context_ready: bool = False;
    has blocked: bool = False;
    has stale: bool = False;
    has blocked_reason: str = "";

    can start with Root entry {
        visit [->:ReviewTask:->] else {
            disengage;
        }
    }

    can inspect_task with Task entry {
        self.expected_revision = here.expected_revision;
        self.bound_qa_revision = here.prior_qa_revision;
        self.context_ready = here.context_ready;
        self.blocked = False;
        self.stale = False;
        self.blocked_reason = "";
        visit [-->] else {
            disengage;
        }
    }

    can inspect_revision with Revision entry {
        self.revision_hash = here.hash;

        if self.context_ready == False {
            self.blocked = True;
            self.blocked_reason = "required QA context is missing";
        } else {
            if here.dev_validated == False {
                self.blocked = True;
                self.blocked_reason = "developer validation is not successful";
            } else {
                if here.dev_validation_revision != here.hash {
                    self.blocked = True;
                    self.blocked_reason = "developer validation is stale";
                } else {
                    if here.hash != self.expected_revision {
                        self.blocked = True;
                        self.blocked_reason = "revision does not match the task";
                    } else {
                        if self.bound_qa_revision != "" {
                            if self.bound_qa_revision != here.hash {
                                self.stale = True;
                            }
                        }
                    }
                }
            }
        }

        visit [-->] else {
            disengage;
        }
    }

    can publish with QAReport entry {
        if self.blocked {
            print(f"BLOCKED: {self.blocked_reason}");
        } else {
            if self.stale {
                print(f"STALE: QA approval is not current for {self.revision_hash}");
            } else {
                if here.result == "PASS" {
                    if here.reviewed_revision == self.revision_hash {
                        print(f"PASS: QA approved exact revision {self.revision_hash}");
                    } else {
                        print(f"STALE: PASS reviewed {here.reviewed_revision}, "
                              f"but task is at {self.revision_hash}");
                    }
                } else {
                    if here.result == "FAIL" {
                        if here.blocking {
                            print(f"FAIL: {here.finding}; remediation: {here.remediation}");
                            print("REWORK: task returns to developer validation");
                        } else {
                            print(f"FAIL: {here.finding}; remediation: {here.remediation}");
                        }
                    } else {
                        print(f"BLOCKED: unsupported QA result {here.result}");
                    }
                }
            }
        }

        visit [-->] else {
            disengage;
        }
