"""Auditable branch lifecycle with typed relationships and cycle-safe walking."""

node AuditRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;

    def audit_key() -> str {
        return self.title;
    }

    def audit_line() -> str {
        return self.title;
    }

    def is_active_writer() -> bool {
        return False;
    }

    def is_retirement_candidate() -> bool {
        return False;
    }
}

node Branch(AuditRecord) {
    has ref_name: str = "";
    has commit_id: str = "";
    has lifecycle: str = "RETAINED";
    has writer_authority: str = "none";
    has protected_main: bool = False;
    has superseded: bool = False;
    has retirement_evidence: bool = False;

    override def audit_key() -> str {
        return f"branch:{self.ref_name}";
    }

    override def audit_line() -> str {
        return f"{self.ref_name} [{self.lifecycle}] @{self.commit_id} writer={self.writer_authority}";
    }

    override def is_active_writer() -> bool {
        return self.lifecycle == "ACTIVE_WRITER";
    }

    override def is_retirement_candidate() -> bool {
        return self.superseded
            and self.retirement_evidence
            and not self.protected_main
            and not self.available;
    }
}

node PullRequest(AuditRecord) {
    has number: int = 0;
    has draft: bool = False;
    has is_open: bool = False;

    override def audit_key() -> str {
        return f"pr:{self.number}";
    }

    override def audit_line() -> str {
        state_label = "DRAFT" if self.draft else "READY";
        return f"PR #{self.number} {state_label}";
    }

    override def is_active_writer() -> bool {
        return self.is_open and not self.draft;
    }
}

node WriterLease(AuditRecord) {
    has authority: str = "";
    has mutable: bool = False;
    has retired: bool = False;

    override def audit_key() -> str {
        return f"lease:{self.authority}";
    }

    override def audit_line() -> str {
        lease_label = "MUTABLE" if self.mutable else "READ_ONLY";
        return f"lease {self.authority} [{lease_label}]";
    }

    override def is_active_writer() -> bool {
        return self.mutable and not self.retired;
    }
}

edge DependsOn {
    has position: int = 0;
}

edge Supersedes {
    has evidence: str = "";
}

edge RepresentedBy {
    has scope: str = "";
}

edge HasLease {
    has scope: str = "";
}

walker LifecycleAuditor {
    has seen: list[str] = [];
    has audited: int = 0;
    has active_writers: int = 0;
    has retirement_candidates: int = 0;
    has cycle_hits: int = 0;

    can begin with Root entry {
        print("Auditing branch lifecycle from protected graph root");
        visit [-->];
    }

    can inspect with Branch | PullRequest | WriterLease entry {
        key = here.audit_key();

        if key in self.seen {
            self.cycle_hits = self.cycle_hits + 1;
            print(f"cycle detected at {key}; stopping this walk");
            disengage;
        }

        self.seen.append(key);
        self.audited = self.audited + 1;
        print(here.audit_line());

        if here.is_active_writer() {
            self.active_writers = self.active_writers + 1;
        }

        if here.is_retirement_candidate() {
            self.retirement_candidates = self.retirement_candidates + 1;
        }

        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"audited={self.audited}, active_writer_records={self.active_writers}, "
              f"retirement_candidates={self.retirement_candidates}, cycles={self.cycle_hits}");
    }
}

