"""A durable chat watchdog graph with bounded rollover and no replay."""

node Claim {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has prompt_id: str = "";
    has claim_id: str = "";
    has sequence: int = 0;
    has phase: str = "";
    has effect_invocations: int = 0;
    has age_minutes: int = 0;
    has stop_sent: bool = False;
    has proceed_sent: bool = False;
    has fresh_chat_created: bool = False;
    has successor_created: bool = False;
    has successor_claim_id: str = "";
    has terminal_status: str = "";
    has chat_id: str = "";
}

node Watchdog {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stop_after: int = 15;
    has rollover_after: int = 30;
}

node Chat {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has chat_id: str = "";
    has created: bool = False;
}

edge Runs { }
edge Monitors { }
edge Advances { }
edge InChat { }

walker RecoveryController {
    has stop_after: int = 15;
    has rollover_after: int = 30;
    has seen_claims: list[str] = [];

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can monitor with Watchdog entry {
        visit [->:Monitors:->] else { disengage; }
    }

    can reconcile with Claim entry {
        if here.claim_id in self.seen_claims {
            disengage;
        }
        self.seen_claims.append(here.claim_id);

        if here.phase == "POST_EFFECT" {
            if here.age_minutes >= self.stop_after {
                if not here.stop_sent {
                    here.stop_sent = True;
                }
                if not here.proceed_sent {
                    here.proceed_sent = True;
                }
            }

            if here.age_minutes >= self.rollover_after {
                if not here.fresh_chat_created {
                    next_claim_id = f"{here.claim_id}-successor";
                    next_chat_id = f"{here.chat_id}-fresh";

                    next_claim = Claim(
                        title="ITEM75",
                        prompt_id=f"{here.prompt_id}-successor",
                        claim_id=next_claim_id,
                        sequence=here.sequence + 1,
                        phase="READY",
                        chat_id=next_chat_id
                    );
                    next_chat = Chat(
                        title="Fresh successor chat",
                        chat_id=next_chat_id,
                        created=True
                    );

                    here +>:Advances:+> next_claim;
                    next_claim +>:InChat:+> next_chat;

                    here.fresh_chat_created = True;
                    here.successor_created = True;
                    here.successor_claim_id = next_claim_id;
                    here.terminal_status = "ROLLOVER_TO_SUCCESSOR";
                    here.phase = "ROLLED_OVER";
                }
            }
        }

        visit [->:Advances:->] else { disengage; }
    }
}

