"""Native dependency graph demo with typed edges, reachability, and cycle detection."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Project(Artifact) {
    has entry_class: str = "";
}

node SourceFile(Artifact) {
    has member_count: int = 0;
}

node Symbol(Artifact) {
    has exported: bool = False;
}

edge Contains { }
edge DependsOn {
    has reason: str = "";
}

walker DependencyAuditor {
    has seen: list[str] = [];
    has cycle_count: int = 0;

    can begin with Root entry {
        print("Starting dependency audit");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_project with Project entry {
        if here.title in self.seen {
            self.cycle_count += 1;
            print(f"cycle detected at project {here.title}");
        } else {
            self.seen.append(here.title);
            print(f"project: {here.title}, entry={here.entry_class}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_dependency with SourceFile | Symbol entry {
        if here.title in self.seen {
            self.cycle_count += 1;
            print(f"cycle detected at {here.title}");
        } else {
            self.seen.append(here.title);
            status = "ready" if here.available else "invalid";
            print(f"{status}: {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

