"""Native EOR critical-path planning and packetization demo."""

node PlanNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has state: str = "";
    has owner: str = "";
    has pass_condition: str = "";
    has current_state: str = "";
    has prerequisites: str = "";
    has downstream_unlock: str = "";
    has critical: bool = False;
    has slack: int = 0;
    has expected_change: str = "";
    has evidence_required: str = "";
    has failure_trigger: str = "";
    has dispatched: bool = False;
    has successor_emitted: bool = False;
    has successor_prompt: str = "";
    has critical_blocker: str = "";
    has maintenance_turns: int = 0;
    has replan_required: bool = False;
    has scope: str = "";
    has output: str = "";
    has acceptance_test: str = "";
    has authority: str = "";
    has integration_destination: str = "";
    has result: str = "";
    has source_packet: str = "";
}

node WorkPacket(PlanNode) {
    has action: str = "";
}

node Evidence(PlanNode) {
}

edge Dependency {
    has relation: str = "";
}

walker CriticalPathPlanner {
    has run_label: str = "";
    has critical_frontier: str = "";
    has dispatched_count: int = 0;

    can begin with Root entry {
        print(f"{self.run_label}: reconstructing durable EOR plan");
        visit [-->] else { print(f"{self.run_label}: empty plan"); }
    }

    can inspect with PlanNode entry {
        label = "CRITICAL" if here.critical else "SUPPORTING";
        print(f"{self.run_label}: {label} {here.kind} - {here.title} [{here.state}]");

        if here.critical and here.state != "PASS" {
            if self.critical_frontier == "" {
                self.critical_frontier = here.title;
                print(f"{self.run_label}: frontier = {here.title} (slack {here.slack})");
            }
        }

        if here.kind == "OBJECTIVE" {
            print(f"{self.run_label}: recompute blocker {here.critical_blocker}; unlock={here.downstream_unlock}");
            if not here.successor_emitted {
                here.successor_emitted = True;
                here.successor_prompt = f"I completed reconciliation for {here.title}. You now do {here.critical_blocker} because it is the next critical dependency toward {here.downstream_unlock}. PASS requires: {here.pass_condition}. Evidence: {here.evidence_required}. If it fails, replan from the returned evidence.";
                print(f"successor: {here.successor_prompt}");
            } else {
                print(f"{self.run_label}: restart-safe skip duplicate successor for {here.title}");
            }
        }

        if here.kind == "MAINTENANCE" and here.maintenance_turns >= 2 {
            here.replan_required = True;
            print(f"{self.run_label}: REPLAN strategy change after {here.maintenance_turns} maintenance turns");
        }

        visit [->:Dependency:->] else { print(f"{self.run_label}: reached dependency leaf"); }
    }

    can dispatch with WorkPacket entry {
        if not here.dispatched {
            here.dispatched = True;
            self.dispatched_count = self.dispatched_count + 1;
            print(f"{self.run_label}: dispatch {here.title} to {here.owner}");
        } else {
            print(f"{self.run_label}: restart-safe skip duplicate dispatch for {here.title}");
        }
        visit [->:Dependency:->] else { print(f"{self.run_label}: packet leaf"); }
    }

    can integrate with Evidence entry {
        if here.state == "PASS" {
            print(f"{self.run_label}: integrate evidence from {here.source_packet}: {here.result}");
        }
        visit [->:Dependency:->] else { print(f"{self.run_label}: evidence leaf"); }
    }
}

