"""Trusted-branch Droid security flow with inert candidate data and bounded traversal."""

node Authority {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has workflow_sha: str = "";
    has reviewed_default_branch: bool = False;
}

node Subject {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has repository: str = "";
    has pr_number: int = 0;
    has base_sha: str = "";
    has head_sha: str = "";
    has workflow_sha: str = "";
    has actor_login: str = "";
    has same_repository: bool = False;
    has actor_is_member: bool = False;
    has event_supported: bool = False;
    has edited_event: bool = False;
    has stale: bool = False;
}

node CandidateData {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has content_digest: str = "";
    has shell_step_present: bool = False;
    has repository_action_present: bool = False;
    has configuration_executed: bool = False;
}

node Receipt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has bound_pr_number: int = 0;
    has bound_head_sha: str = "";
    has provider_secret_available: bool = False;
    has output_valid: bool = False;
    has status: str = "pending";
    has writeback_allowed: bool = False;
}

edge Starts { }
edge Admits { }
edge Captures { }
edge Produces { }

walker DroidSecurityAudit {
    has hops: int = 0;
    has max_hops: int = 8;
    has accepted: bool = False;
    has admitted_workflow_sha: str = "";
    has subject_number: int = 0;
    has subject_head_sha: str = "";

    can start with Root entry {
        if self.hops >= self.max_hops {
            disengage;
        }
        self.hops += 1;
        visit [->:Starts:->] else {
            disengage;
        }
    }

    can authorize with Authority entry {
        if self.hops >= self.max_hops {
            disengage;
        }
        self.hops += 1;
        if here.reviewed_default_branch == False {
            disengage;
        }
        if here.available == False {
            disengage;
        }
        self.admitted_workflow_sha = here.workflow_sha;
        visit [->:Admits:->] else {
            disengage;
        }
    }

    can classify with Subject entry {
        if self.hops >= self.max_hops {
            disengage;
        }
        self.hops += 1;
        self.subject_number = here.pr_number;
        self.subject_head_sha = here.head_sha;
        self.accepted = False;

        if here.available {
            if here.same_repository {
                if here.actor_is_member {
                    if here.event_supported {
                        if here.edited_event == False {
                            if here.stale == False {
                                if here.workflow_sha == self.admitted_workflow_sha {
                                    self.accepted = True;
                                }
                            }
                        }
                    }
                }
            }
        }

        visit [->:Captures:->] else {
            disengage;
        }
    }

    can inspect with CandidateData entry {
        if self.hops >= self.max_hops {
            disengage;
        }
        self.hops += 1;

        if here.shell_step_present {
            self.accepted = False;
        }
        if here.repository_action_present {
            self.accepted = False;
        }
        if here.configuration_executed {
            self.accepted = False;
        }

        visit [->:Produces:->] else {
            disengage;
        }
    }

    can finalize with Receipt entry {
        if self.accepted == False {
            here.status = "rejected";
            here.writeback_allowed = False;
            disengage;
        }

        if here.bound_pr_number != self.subject_number {
            here.status = "rejected";
            here.writeback_allowed = False;
            disengage;
        }

        if here.bound_head_sha != self.subject_head_sha {
            here.status = "rejected";
            here.writeback_allowed = False;
            disengage;
        }

        if here.provider_secret_available == False {
            here.status = "blocked_external";
            here.writeback_allowed = False;
            disengage;
        }

        if here.output_valid == False {
            here.status = "failed";
            here.writeback_allowed = False;
            disengage;
        }

        here.status = "written";
        here.writeback_allowed = True;
        disengage;
    }
}

