    has secret: str = "";
}

node Request(TraceNode) {
}

node Task(TraceNode) {
}

node Service(TraceNode) {
    has service_name: str = "";
}

edge TraceLink {
    has relation: str = "";
}

walker TraceExecution {
    has correlation_id: str = "";
    has seen_nodes: list[str] = [];

    can start with Root entry {
        visit [->:TraceLink:->] else {
            disengage;
        }
    }

    can execute with Request | Task | Service entry {
        if here.node_key in self.seen_nodes {
            print(f'{{"level":"warn","event":"trace.cycle_detected","node":"{here.node_key}","correlationId":"{self.correlation_id}"}}');
            disengage;
        } else {
            self.seen_nodes.append(here.node_key);

            if self.correlation_id == "" {
                self.correlation_id = here.correlation_id;
            }

            here.correlation_id = self.correlation_id;
            prompt_log = here.prompt if len(here.prompt) <= 500 else here.prompt[0:500] + "...";
            output_log = here.output if len(here.output) <= 500 else here.output[0:500] + "...";
            api_key_log = "[REDACTED]" if here.api_key != "" else "";
            secret_log = "[REDACTED]" if here.secret != "" else "";
            level = "warn" if here.duration_ms > 10000 else "info";

            print(f'{{"level":"{level}","event":"task.execution_trace","node":"{here.node_key}","correlationId":"{self.correlation_id}","traceId":"{here.trace_id}","spanId":"{here.span_id}","parentSpanId":"{here.parent_span_id}","method":"{here.method}","path":"{here.path}","statusCode":{here.status_code},"durationMs":{here.duration_ms},"prompt":"{prompt_log}","output":"{output_log}","apiKey":"{api_key_log}","secret":"{secret_log}"}}');

            visit [->:TraceLink:->] else {
                disengage;
            }
        }
    }
}

