    has depth: int = 0;
    has result_count: int = 0;
    has seen_ids: list[int] = [];

    can start with Root entry {
        print(f"starting named query: {self.selected_query}");
        visit [-->] else { disengage; }
    }

    can configure_query with Query entry {
        if here.query_name == self.selected_query {
            self.query_context = here.context;
            self.query_projection = here.projection;
            self.query_relationship = here.relationship_kind;
            self.query_direction = here.direction;
            self.query_resolution = here.resolution;
            self.max_depth = here.max_depth;
            self.result_bound = here.result_bound;
            self.depth = 0;
            self.result_count = 0;
            self.seen_ids = [];

            print(f"query={here.query_name} projection={here.projection} "
                  f"relationship={here.relationship_kind} context={here.context} "
                  f"direction={here.direction} resolution={here.resolution} "
                  f"depth<={here.max_depth} results<={here.result_bound}");

            if here.relationship_kind != "declared_call" {
                print(f"rejected unqualified relationship in {here.query_name}");
                disengage;
            } else {
                visit [->:Target:->] else { disengage; }
            }
        }
    }

    can inspect_callable with Routine entry {
        if self.query_context == "all"
            or here.observation_context == self.query_context {
            if self.result_count >= self.result_bound {
                print(f"result bound reached for {self.selected_query}");
                disengage;
            } else {
                if here.callable_id in self.seen_ids {
                    cycle_kind = "definite recursive cycle"
                        if self.query_resolution == "definite"
                        else "potential cycle from conservative claims";
                    handle = Explanation(
                        handle=f"EH-{self.selected_query}-{here.callable_id}",
                        evidence=f"callable={here.title} id={here.callable_id} "
                                 f"context={here.observation_context}",
                        derivation=cycle_kind
                    );
                    here +>:Explains:+> handle;
                    print(f"cycle {cycle_kind}: handle={handle.handle} "
                          f"evidence={handle.evidence} "
                          f"derivation={handle.derivation}");
                    disengage;
                } else {
                    if self.depth >= self.max_depth {
                        print(f"depth bound reached at "
                              f"{here.title}#{here.callable_id}");
                    } else {
                        self.seen_ids.append(here.callable_id);
                        self.result_count += 1;
                        self.depth += 1;

                        print(f"{self.selected_query}: "
                              f"{here.title}#{here.callable_id} "
                              f"context={here.observation_context} "
                              f"static_call_sites={here.static_call_sites} "
                              f"runtime_invocations={here.runtime_invocations}");

                        if self.query_direction == "callers" {
                            visit [->:CallerOf:->] else { disengage; }
                        } else {
                            if self.query_resolution == "definite" {
                                visit [->:ResolvedCall:->]
                                    else { disengage; }
                            } else {
                                visit [->:DeclaredCall:->]
                                    else { disengage; }
                            }
                        }

                        self.depth -= 1;
                    }
                }
            }
        }
    }
}

