"""Bounded Valkey investigation graph with snapshot-scoped identities and call evidence."""

node ProgramSnapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has snapshot_id: str = "";
    has target_name: str = "";
}

node ObservationContext {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has context_id: str = "";
    has toolchain: str = "";
    has acquisition: str = "";
}

node CallableEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has entity_id: str = "";
    has display_name: str = "";
    has translation_unit: str = "";
    has local_scope: bool = True;
}

node CallSite {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has site_id: str = "";
    has source_line: int = 0;
    has resolution: str = "absent";
    has evidence_kind: str = "static";
    has complete: bool = False;
}

edge ObservedIn {
    has stage: str = "";
}

edge Contains {
    has membership: str = "";
}

edge Emits {
    has ordinal: int = 0;
}

edge Targets {
    has certainty: str = "";
}

walker CalleePathQuery {
    has query_name: str = "bounded-callee-path";
    has max_hops: int = 8;
    has hops: int = 0;

    can start with Root entry {
        print(f"query={self.query_name}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_snapshot with ProgramSnapshot entry {
        print(f"snapshot={here.snapshot_id} target={here.target_name}");
        if self.hops >= self.max_hops {
            print("bounded traversal stopped at snapshot");
            disengage;
        } else {
            self.hops = self.hops + 1;
            visit [->:ObservedIn:->] else {
                disengage;
            }
        }
    }

    can inspect_context with ObservationContext entry {
        print(f"context={here.context_id} acquisition={here.acquisition}");
        if self.hops >= self.max_hops {
            print("bounded traversal stopped at context");
            disengage;
        } else {
            self.hops = self.hops + 1;
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_callable with CallableEntity entry {
        print(f"callable={here.display_name} identity={here.entity_id}");
        if self.hops >= self.max_hops {
            print("cycle or depth limit reached");
            disengage;
        } else {
            self.hops = self.hops + 1;
            visit [->:Emits:->] else {
                disengage;
            }
        }
    }

    can inspect_call_site with CallSite entry {
        print(f"site={here.site_id} line={here.source_line} "
              f"resolution={here.resolution} evidence={here.evidence_kind}");

        if here.resolution == "absent" {
            print("target set is unknown, not proven impossible");
            disengage;
        } else {
            if self.hops >= self.max_hops {
                print("cycle or depth limit reached");
                disengage;
            } else {
                self.hops = self.hops + 1;
                visit [->:Targets:->] else {
                    disengage;
                }
            }
        }
    }
}

