"""Classify compiler-profile residuals with typed graph traversal and cycle guards."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has classifier_seen: bool = False;
    has guard_seen: bool = False;
}

node Profile(GraphItem) {
    has profile_id: str = "";
    has contract_version: str = "";
}

node Evaluation(GraphItem) {
    has evaluation_id: str = "";
    has candidate_id: str = "";
    has subject_key: str = "";
    has current: bool = True;
}

node RequirementRow(GraphItem) {
    has row_id: str = "";
    has proposition_id: str = "";
    has required: bool = True;
    has applicable: bool = True;
    has satisfied: bool = False;
    has terminal_state: str = "";
    has first_predicate: str = "";
    has residual_class: str = "";
    has blockers: list[str] = [];
    has canonical_owner: str = "";
    has authority_key: str = "";
    has seam_key: str = "";
    has proof_route_key: str = "";
    has legacy_exit_key: str = "";

    def is_residual() -> bool {
        return self.required and self.applicable and not self.satisfied;
    }
}

node Evidence(GraphItem) {
    has evidence_id: str = "";
    has current: bool = True;
    has source_kind: str = "";
}

edge Contains {
    has relation: str = "";
}

edge EvidenceLink {
    has route: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker ResidualClassifier {
    has rows_seen: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_profile with Profile entry {
        if here.classifier_seen {
            disengage;
        }
        here.classifier_seen = True;
        print(f"profile {here.profile_id} contract={here.contract_version}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_evaluation with Evaluation entry {
        if here.classifier_seen {
            disengage;
        }
        here.classifier_seen = True;
        print(f"evaluation {here.evaluation_id} candidate={here.candidate_id}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can classify with RequirementRow entry {
        if here.classifier_seen {
            disengage;
        }
        here.classifier_seen = True;
        self.rows_seen += 1;

        if here.is_residual() {
            if here.terminal_state == "CURRENT_PRODUCT_RED" {
                here.first_predicate = "product/reference/mechanism failure";
                here.residual_class = "product_semantic_defect";
            } else if here.terminal_state == "MISSING_PROOF" {
                here.first_predicate = "proof route/target/work absent";
                here.residual_class = "test_reachability_or_instrument_gap";
            } else if here.terminal_state == "STALE_EVIDENCE" {
                here.first_predicate = "currentness not proven or stale";
                here.residual_class = "currentness_gap";
            } else if here.terminal_state == "INVALID_EVIDENCE" {
                here.first_predicate = "source malformed or validator failed";
                here.residual_class = "invalid_or_conflicting_evidence";
            } else if here.terminal_state == "NO_SOURCE" {
                here.first_predicate = "source authority missing";
                here.residual_class = "source_or_adapter_gap";
            } else if here.terminal_state == "CANDIDATE_MISMATCH" {
                here.first_predicate = "candidate subject missing or mismatched";
                here.residual_class = "candidate_identity_gap";
            } else if here.terminal_state == "WORK_ZERO" {
                here.first_predicate = "required nonzero violated/not proven";
                here.residual_class = "work_or_performance_gap";
            } else if here.terminal_state == "LEGACY_REACHABLE" {
                here.first_predicate = "old path still reachable/called";
                here.residual_class = "legacy_retirement_gap";
            } else if here.terminal_state == "LIMITATION_MISMATCH" {
                here.first_predicate = "allowed-limitation mismatch/expiry";
                here.residual_class = "limitation_or_expected_failure_gap";
            } else if here.terminal_state == "CLAIM_CEILING" {
                here.first_predicate = "claim ceiling invalid or empty";
                here.residual_class = "claim_ceiling_gap";
            } else if here.terminal_state == "PRIVACY_FAILURE" {
                here.first_predicate = "privacy/redaction invalid";
                here.residual_class = "privacy_or_retention_gap";
            } else {
                here.first_predicate = "complete denominator missing/conflicting";
                here.residual_class = "contract_or_profile_gap";
            }

            print(
                f"RESIDUAL row={here.row_id} proposition={here.proposition_id} "
                f"class={here.residual_class} first={here.first_predicate} "
                f"owner={here.canonical_owner} blockers={here.blockers}"
            );
        } else {
            print(f"NON_RESIDUAL row={here.row_id}");
        }

        visit [->:EvidenceLink:->] else {
            disengage;
        }
    }

    can inspect_evidence with Evidence entry {
        if here.classifier_seen {
            disengage;
        }
        here.classifier_seen = True;
        print(f"evidence {here.evidence_id} source={here.source_kind}");
        visit [->:EvidenceLink:->] else {
            disengage;
        }
    }
}

walker CycleGuard {
    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can pass_profile with Profile entry {
        if here.guard_seen {
            disengage;
        }
        here.guard_seen = True;
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can pass_evaluation with Evaluation entry {
        if here.guard_seen {
            disengage;
        }
        here.guard_seen = True;
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can detect with RequirementRow entry {
        if here.guard_seen {
            print(f"CYCLE_SUPPRESSED row={here.row_id}");
            disengage;
        }
        here.guard_seen = True;
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

