"""Dependency-aware cache invalidation over operations and cached intermediates."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has seen: bool = False;
}

node Operation(Artifact) {
    has parameter: str = "";
}

node CacheResult(Artifact) {
    has fingerprint: str = "";
    has hits: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker CacheInvalidator {
    has visited_titles: list[str] = [];

    can start with Root entry {
        print("Starting dependency-aware invalidation");
        visit [-->] else {
            disengage;
        }
    }

    can invalidate with Operation | CacheResult entry {
        if here.title in self.visited_titles {
            print(f"Cycle detected at {here.title}; stopping this branch");
            disengage;
        }

        self.visited_titles.append(here.title);
        here.seen = True;

        if here.available {
            here.available = False;
            print(f"Invalidated {here.title}");
        } else {
            print(f"Already invalid: {here.title}");
        }

        visit [<--:DependsOn:--] else {
            disengage;
        }
    }
}

