"""Context-aware direct dependency planning without source or cache I/O."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "binary";
    has static_library: bool = False;
}

node DependencySpec {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has alias: str = "";
    has target_mask: str = "all";
    has test_only: bool = False;
    has source: str = "";
    has source_kind: str = "local";
    has package_identity: str = "";
    has locked_source: str = "";
    has locked_revision: str = "";
    has lock_complete: bool = True;
}

node LockRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
    has revision: str = "";
}

edge Declares { }
edge NextDeclaration { }
edge ResolvesTo { }
edge UsesLock { }

walker DependencyPlanner {
    has requested_target: str = "linux";
    has phase: str = "production";
    has root_kind: str = "binary";
    has active_plan: list[str] = [];
    has active_locks: list[str] = [];
    has built_identities: list[str] = [];
    has skipped: list[str] = [];

    can begin with Root entry {
        print(f"PLAN phase={self.phase}, target={self.requested_target}, root={self.root_kind}");
        visit [->:Declares:->] else { disengage; }
    }

    can plan with DependencySpec entry {
        target_active = here.target_mask == "all"
            or here.target_mask == self.requested_target;
        phase_active = (self.root_kind == "binary" and not here.test_only)
            or (self.phase == "test-validation" and here.test_only);
        lock_active = here.source_kind != "git" or here.lock_complete;

        if target_active and phase_active and lock_active {
            reason = "normal dependency" if not here.test_only
                else "test-only dependency in test-validation";
            reused = False;

            for identity in self.built_identities {
                if identity == here.package_identity {
                    reused = True;
                }
            }

            binding = "reuse exact package identity" if reused else "build once";
            record = f"{here.alias} <- {here.source} ({binding}; {reason})";
            self.active_plan.append(record);
            print(f"  ACTIVE {record}");

            if not reused {
                self.built_identities.append(here.package_identity);
            }

            if here.source_kind == "git" {
                lock_record = f"{here.alias} <- {here.locked_source}@{here.locked_revision}";
                self.active_locks.append(lock_record);
                print(f"  LOCK   {lock_record}");
            }
        } else {
            skip_reason = "target mask" if not target_active
                else "phase" if not phase_active
                else "incomplete lock";
            skipped_record = f"{self.phase}/{self.requested_target} {here.alias}: {skip_reason}";
            self.skipped.append(skipped_record);
            print(f"  SKIP   {skipped_record}");
        }

        visit [->:NextDeclaration:->] else { disengage; }
    }
}

