"""Candidate backward trace from a runtime failure to a COBOL fault paragraph."""

node FailureLog {
    has log_path: str = "";
    has program_name: str = "";
    has line_reference: int = 0;
    has exception_type: str = "";
    has message: str = "";
}

node JCLStep {
    has step_name: str = "";
    has script_path: str = "";
    has invoked_program: str = "";
}

node CobolProgram {
    has program_name: str = "";
    has source_path: str = "";
}

node Paragraph {
    has paragraph_name: str = "";
    has source_line: int = 0;
    has candidate: bool = False;
}

edge FailureToStep {
    has confidence: int = 0;
}

edge RunsProgram {
    has invocation_order: int = 0;
}

edge ContainsParagraph {
    has paragraph_order: int = 0;
}

edge CallsParagraph {
    has call_order: int = 0;
}

walker BackwardTrace {
    has remaining_depth: int = 8;
    has trace_count: int = 0;

    can start with Root entry {
        print("Candidate backward trace");
        visit [-->] else {
            disengage;
        }
    }

    can parse_failure with FailureLog entry {
        print(f"failure: {here.exception_type} at line {here.line_reference}");
        print(f"message: {here.message}");
        self.trace_count = self.trace_count + 1;
        visit [->:FailureToStep:->] else {
            disengage;
        }
    }

    can map_step with JCLStep entry {
        print(f"JCL step: {here.step_name} from {here.script_path}");
        self.trace_count = self.trace_count + 1;
        visit [->:RunsProgram:->] else {
            disengage;
        }
