        identity = f"{here.method}|{here.scheme}|{here.host}|{here.port}|{here.path}|{here.query}";
        self.seen.append(identity);

        print(f"start {identity}");
        visit [->:Pipeline:->] else {
            disengage;
        }
    }

    can inspect with RedirectResponse entry {
        if here.status != 301 and here.status != 302 and here.status != 303 and here.status != 307 and here.status != 308 {
            print(f"reject status {here.status}: not an automatic redirect");
            disengage;
        }

        if here.location_count != 1 or here.location_valid == False {
            print("reject redirect: Location is absent, duplicated, or malformed");
            disengage;
        }

        if self.redirect_count >= self.max_redirects {
            print("reject redirect: maximum reached before resolving Location");
            disengage;
        }

        unsafe = self.current_method == "POST" or self.current_method == "PUT" or self.current_method == "PATCH" or self.current_method == "DELETE";
        if unsafe and self.allow_unsafe == False {
            print("reject redirect: unsafe method is disabled");
            disengage;
        }

        self.redirect_count += 1;
        self.next_method = self.current_method;
        self.next_body_action = "None";

        if here.status == 303 {
            if self.current_method == "HEAD" {
                self.next_method = "HEAD";
            } else {
                self.next_method = "GET";
            }
            self.next_body_action = "Drop";
        }

        if (here.status == 301 or here.status == 302) and self.redirect_mode == "compatibility" and self.current_method == "POST" {
            self.next_method = "GET";
            self.next_body_action = "Drop";
        }

        preserving_body = self.next_body_action == "None" and self.current_body_kind != "none";
        if preserving_body and self.current_replay_token == "" {
            print("reject redirect: preserved body has no replay token");
            disengage;
        }

        if preserving_body {
            self.next_body_action = f"Replay({self.current_replay_token})";
        }

        print(f"checked Location {here.location}; selected {self.next_method} with {self.next_body_action}");
        visit [->:RedirectsTo:->] else {
            disengage;
        }
    }

    can inspect with HttpTarget entry {
        if self.current_scheme == "https" and here.scheme == "http" {
            print("reject redirect: HTTPS downgrade");
            disengage;
        }

        identity = f"{self.next_method}|{here.scheme}|{here.host}|{here.port}|{here.path}|{here.query}";
        if identity in self.seen {
            print(f"reject redirect loop: {identity}");
            disengage;
        }

        self.seen.append(identity);

        same_origin = self.current_scheme == here.scheme and self.current_host == here.host and self.current_port == here.port;
        disclosure = "strip Authorization, Cookie, Origin, and Referer";
        if same_origin == False {
            disclosure = "cross-origin: strip Authorization, Cookie, Origin, and Referer";
        }

        request_target = here.path;
        if here.query != "" {
            request_target = f"{here.path}?{here.query}";
        }

        fresh = FreshExchange(
            target_identity=identity,
            request_target=request_target,
            method=self.next_method,
            body_action=self.next_body_action,
            header_plan=f"rebuild Host and target for {here.host}:{here.port}",
            framing_plan="recompute Content-Length or Transfer-Encoding",
            disclosure_audit=disclosure
        );
        here +>:Produces:+> fresh;

        print(f"FreshExchange {identity}: {self.next_body_action}; {disclosure}");

        self.current_scheme = here.scheme;
        self.current_host = here.host;
        self.current_port = here.port;
        self.current_method = self.next_method;

        if self.next_body_action == "Drop" or self.next_body_action == "None" {
            self.current_body_kind = "none";
            self.current_replay_token = "";
        }

        visit [->:Continuation:->] else {
            disengage;
        }
    }
}

