"""Serial frontend query planner demo with typed dependencies and reuse."""

node Query {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has query_id: str = "";
    has expected_input: str = "";
    has current_input: str = "";
    has prior_output: str = "";
    has current_output: str = "";
    has prior_result: str = "";
    has current_result: str = "";
    has prior_child_output: str = "";
    has current_child_output: str = "";
    has status: str = "pending";
}

node InputFact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has identity: str = "";
}

edge DependsOn {
    has observed_output: str = "";
}

edge Reads {
    has key: str = "";
}

walker QueryPlanner {
    has seen: list[str] = [];
    has next_action: int = 1;
    has actions_emitted: int = 0;
    has aborted: bool = False;

    can start with Root entry {
        print("planner started");
        visit [-->] else {
            disengage;
        }
    }

    can plan with Query entry {
        if here.query_id in self.seen {
            print(f"cycle detected at {here.query_id}");
            self.aborted = True;
            disengage;
        } else {
            self.seen.append(here.query_id);
            print(f"suspend {here.query_id} while validating children");

            visit [->:Reads:->] else {
                print(f"no direct input recorded for {here.query_id}");
            }

            visit [->:DependsOn:->] else {
                print(f"{here.query_id} has no child queries");
            }

            reason = "reuse";
            if here.current_input != here.expected_input {
                reason = "direct input changed";
            } elif here.current_child_output != here.prior_child_output {
                reason = "child semantic output changed";
            }

            if reason == "reuse" {
                here.status = "reused";
                print(f"Reuse({self.next_action}) {here.query_id} "
                      f"output={here.prior_output} result={here.prior_result}");
            } else {
                here.status = "recomputed";
                print(f"Recompute({self.next_action}) {here.query_id}: {reason}");
            }

            self.next_action += 1;
            self.actions_emitted += 1;
        }
    }

    can inspect with InputFact entry {
        print(f"current direct input {here.key}={here.identity}");
    }

    can report with Root exit {
        if self.aborted {
            print("planning aborted");
        } else {
            print(f"planning complete: {self.actions_emitted} serial actions");
        }
    }
}

