walker DependencyAudit {
    has seen_titles: list[str] = [];
    has visited_count: int = 0;
    has cycle_count: int = 0;
    has unavailable_count: int = 0;
    has cycle_node: str = "";

    can begin with Root entry {
        visit [->:DependsOn:->] else {
            disengage;
        }
