    can inspect with LoweringContext | BackendRoute | ConversionPlan entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
            self.cycle_node = here.title;
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.visited_count += 1;

            if not here.available {
                self.unavailable_count += 1;
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

