"""Semantic IBT target census with ENDBR64 proofs and legacy preservation."""

node GeneratedFunction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ibt_required: bool = True;
    has expected_targets: int = 0;
    has checked_targets: int = 0;
    has valid_targets: int = 0;
    has proof_state: str = "Unknown";
    has visited: bool = False;
}

node LandingTarget {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has indirect: bool = True;
    has requires_endbr: bool = True;
    has at_target: bool = True;
    has unique_target: bool = True;
    has fresh_generation: bool = True;
    has opaque_bytes: bool = False;
    has legacy_bytes_preserved: bool = True;
    has visited: bool = False;
}

node SemanticInstruction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has semantic: bool = True;
    has is_endbr: bool = False;
    has opcode: str = "";
    has encoded_bytes: str = "";
}

edge Owns {
    has order: int = 0;
}

edge Targets {
    has family: str = "";
}

edge Encodes {
    has role: str = "";
}

walker ProofBuilder {
    has ibt_required: bool = True;
    has checked_targets: int = 0;
    has valid_targets: int = 0;
    has functions_seen: int = 0;
    has invalid_functions: int = 0;
    has last_record_ok: bool = False;
    has cycle_detected: bool = False;
    has census_closed: bool = False;
    has proof_complete: bool = False;

    can begin with Root entry {
        self.functions_seen = 0;
        self.invalid_functions = 0;
        self.cycle_detected = False;
        visit [-->];
    }

    can inspect_function with GeneratedFunction entry {
        if here.visited {
            self.cycle_detected = True;
            disengage;
        }

        here.visited = True;
        self.functions_seen += 1;
        self.ibt_required = here.ibt_required;
        self.checked_targets = 0;
        self.valid_targets = 0;

        visit [->:Targets:->];

        here.checked_targets = self.checked_targets;
        here.valid_targets = self.valid_targets;

        if here.checked_targets == here.expected_targets {
            if here.valid_targets == here.expected_targets {
                if here.ibt_required {
                    here.proof_state = "Ready";
                } else {
                    here.proof_state = "LegacyUnchanged";
                }
            } else {
                here.proof_state = "Incompatible";
                self.invalid_functions += 1;
            }
        } else {
            here.proof_state = "Incompatible";
            self.invalid_functions += 1;
        }
    }

    can inspect_target with LandingTarget entry {
        if here.visited {
            self.cycle_detected = True;
            disengage;
        }

        here.visited = True;
        self.last_record_ok = False;
        visit [->:Encodes:->];

        if here.indirect {
            if self.ibt_required {
                if here.requires_endbr {
                    if here.at_target {
                        if here.unique_target {
                            if here.fresh_generation {
                                if here.opaque_bytes == False {
                                    if self.last_record_ok {
                                        self.valid_targets += 1;
                                    }
                                }
                            }
                        }
                    }
                }
            } else {
                if here.legacy_bytes_preserved {
                    self.valid_targets += 1;
                }
            }
        } else {
            self.valid_targets += 1;
        }

        self.checked_targets += 1;
    }

    can inspect_instruction with SemanticInstruction entry {
        self.last_record_ok = False;

        if here.semantic {
            if here.is_endbr {
                if here.opcode == "ENDBR64" {
                    if here.encoded_bytes == "F3 0F 1E FA" {
                        self.last_record_ok = True;
                    }
                }
            }
        }
    }

    can finalize with Root exit {
        self.census_closed = self.functions_seen > 0;
        self.proof_complete = self.census_closed;

        if self.invalid_functions > 0 {
            self.proof_complete = False;
        }

        if self.cycle_detected {
            self.proof_complete = False;
        }
    }
}

