walker BoundedAudit {
    has run_token: int = 1;
    has max_steps: int = 20;
    has steps: int = 0;
    has cycle_hits: int = 0;
    has rejected_inputs: int = 0;
    has failed_checks: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can scan_seed with SeedCorpus entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            disengage;
        }
        visit [-->] else {
            disengage;
        }
    }

    can scan_parser with PureParser entry {
        self.steps += 1;
        if self.steps > self.max_steps {
            disengage;
        }
        if here.visit_token == self.run_token {
            self.cycle_hits += 1;
            disengage;
        }
        here.visit_token = self.run_token;

        if here.input_size <= here.max_input_size {
            here.admitted = True;
        } else {
            self.rejected_inputs += 1;
        }

        visit [-->] else {
            disengage;
        }
    }

    can scan_check with PropertyCheck entry {
        if here.output_size > here.max_output_size {
            self.failed_checks += 1;
        }
        if here.passed == False {
            self.failed_checks += 1;
        }
        visit [-->] else {
            disengage;
        }
    }
}

