walker ProofAuditor {
    has expected_target: str = "";
    has expected_abi: str = "";
    has expected_profile: str = "";
    has valid: bool = True;
    has live_artifacts: int = 0;
    has checked_proofs: int = 0;
    has checked_contributions: int = 0;

    can start with Root entry {
        visit [-->] else {
            self.valid = False;
            print("FAIL: empty native-link graph");
            disengage;
        }
    }

    can inspect_manifest with Manifest entry {
        self.expected_target = here.target;
        self.expected_abi = here.abi;
        self.expected_profile = here.profile;

        if here.valid == False {
            self.valid = False;
            print("FAIL: manifest is invalid");
        }

        visit [-->] else {
            self.valid = False;
            print("FAIL: manifest has no events");
            disengage;
        }
    }

    can inspect_artifact with CompilerArtifact entry {
        if here.live {
            self.live_artifacts += 1;

            if here.target != self.expected_target {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} target mismatch");
            }
            if here.abi != self.expected_abi {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} ABI mismatch");
            }
            if here.profile != self.expected_profile {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} profile mismatch");
            }
            if here.expected_proof_bytes == "" {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} has no proof bytes");
            }
        } else {
            print(f"IGNORED: dead artifact {here.artifact_identity}");
        }

        visit [-->] else {
            if here.live {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} has no proof attachment");
            }
            disengage;
        }
    }

    can inspect_attachment with ProofAttachment entry {
        if here.live {
            self.checked_proofs += 1;

            if here.valid == False {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} proof is malformed");
            }
            if here.result != "Compatible" {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} proof is {here.result}");
            }
            if here.target != self.expected_target {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} proof target mismatch");
            }
            if here.abi != self.expected_abi {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} proof ABI mismatch");
            }
            if here.profile != self.expected_profile {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} proof profile mismatch");
            }
            if here.producer == "" || here.schema == "" {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} proof provenance missing");
            }
            if here.inventory_identity == "" {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} inventory identity missing");
            }

            print(f"LIVE: compiler proof retained for {here.artifact_identity}");
        } else {
            print(f"IGNORED: dead proof row for {here.artifact_identity}");
        }

        visit [-->] else {
            if here.live {
                self.valid = False;
                print(f"FAIL: {here.artifact_identity} has no contribution coverage");
            }
            disengage;
        }
    }

    can inspect_contribution with Contribution entry {
        if here.live {
            self.checked_contributions += 1;

            if here.covered == False {
                self.valid = False;
                print(f"FAIL: uncovered live range {here.proof_range}");
            }
            if here.artifact_identity == "" {
                self.valid = False;
                print(f"FAIL: {here.contribution_identity} has no artifact identity");
            }
            if here.inventory_identity == "" {
                self.valid = False;
                print(f"FAIL: {here.contribution_identity} has no inventory identity");
            }

            print(f"RANGE: {here.contribution_identity} is covered");
        } else {
            print(f"IGNORED: dead contribution {here.contribution_identity}");
        }

        visit [-->] else {
            disengage;
        }
    }
}

