"""Dependency-aware curriculum planning with shared prerequisites and cycle detection."""

node CurriculumPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Concept {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Plan { }
edge Target {
    has rank: int = 0;
}
edge Prerequisite {
    has rationale: str = "";
}

walker CurriculumPlanner {
    has seen: list[str] = [];
    has active: list[str] = [];
    has ordered: list[str] = [];
    has failed: bool = False;

    can start with Root entry {
        visit [->:Plan:->] else {
            print("No curriculum plan found");
        }
    }

    can collect with CurriculumPlan entry {
        visit [->:Target:->] else {
            print("The curriculum has no targets");
        }
    }

    can order with Concept entry {
        if self.failed {
            disengage;
        }

        if here.title in self.active {
            print(f"Cycle detected at {here.title}");
            self.failed = True;
            disengage;
        } else {
            if here.title in self.seen {
                print(f"Shared prerequisite reused: {here.title}");
            } else {
                self.seen.append(here.title);
                self.active.append(here.title);

                visit [->:Prerequisite:->] else {
                    print(f"Base concept reached: {here.title}");
                }

                if self.failed {
                    disengage;
                }

                self.active.pop();
                self.ordered.append(here.title);
                print(f"Curriculum step: {here.title}");
            }
        }
    }

    can report with Root exit {
        if self.failed {
            print("Curriculum generation failed because the dependency graph has a cycle");
        } else {
            print(f"Ordered curriculum: {self.ordered}");
        }
    }
}

walker CycleAudit {
    has seen: list[str] = [];
    has active: list[str] = [];
    has failed: bool = False;

    can inspect with Concept entry {
        if here.title in self.active {
            print(f"Cycle audit found a cycle at {here.title}");
            self.failed = True;
            disengage;
        } else {
            if here.title in self.seen {
                print(f"Cycle audit skipped shared node {here.title}");
            } else {
                self.seen.append(here.title);
                self.active.append(here.title);

                visit [->:Prerequisite:->] else {
                    print(f"Cycle audit reached leaf {here.title}");
                }

                if self.failed {
                    disengage;
                }

                self.active.pop();
            }
        }
    }
}

