"""Decode a bounded Windows DNS adapter snapshot with typed graph traversal."""

node ResolverSnapshot {
    has address_family: int = 0;
    has flags: int = 38;
    has reserved_null: bool = True;
    has capability_bound: bool = True;
    has buffer_writable: bool = True;
    has size_writable: bool = True;
    has buffer_aligned: bool = True;
    has size_aligned: bool = True;
    has initial_buffer_size: int = 15000;
    has candidate_size: int = 24000;
    has requested_size: int = 24000;
    has calls_total: int = 2;
    has raw_status: int = 0;
    has growth_valid: bool = True;
}

node Adapter {
    has name: str = "";
    has length: int = 448;
    has layout_valid: bool = True;
    has oper_status: int = 1;
    has unicast_count: int = 1;
    has walked: bool = False;
}

node DnsServer {
    has address: str = "";
    has family: int = 4;
    has sockaddr_length: int = 16;
    has scope_id: int = 0;
    has port: int = 53;
    has key: str = "";
    has order: int = 0;
    has pointer_in_buffer: bool = True;
    has length_valid: bool = True;
    has address_valid: bool = True;
    has walked: bool = False;
}

node SearchSuffix {
    has value: str = "";
    has key: str = "";
    has order: int = 0;
    has wire_bytes: int = 0;
    has pointer_in_buffer: bool = True;
    has utf16_valid: bool = True;
    has walked: bool = False;
}

edge SnapshotRoot { }
edge ContainsAdapter { }
edge NextAdapter { }
edge FirstDnsServer { }
edge NextDnsServer { }
edge PrimarySuffix { }
edge FirstDnsSuffix { }
edge NextDnsSuffix { }

walker ResolverDecoder {
    has failed: bool = False;
    has published: bool = False;
    has error_code: str = "";
    has server_count: int = 0;
    has suffix_count: int = 0;
    has suffix_wire_bytes: int = 0;
    has server_keys: list[str] = [];
    has suffix_keys: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can validate with ResolverSnapshot entry {
        if here.address_family != 0 or here.flags != 38 {
            self.failed = True;
            self.error_code = "INVALID_CALL_ARGUMENTS";
            disengage;
        } else {
            if here.reserved_null == False or here.capability_bound == False {
                self.failed = True;
                self.error_code = "INVALID_CAPABILITY_BOUNDARY";
                disengage;
            } else {
                if here.buffer_writable == False or here.size_writable == False {
                    self.failed = True;
                    self.error_code = "INVALID_WRITABLE_BOUNDARY";
                    disengage;
                } else {
                    if here.buffer_aligned == False or here.size_aligned == False {
                        self.failed = True;
                        self.error_code = "INVALID_ALIGNMENT";
                        disengage;
                    } else {
                        if here.initial_buffer_size != 15000 {
                            self.failed = True;
                            self.error_code = "INVALID_INITIAL_BUFFER_SIZE";
                            disengage;
                        } else {
                            if here.calls_total < 1 or here.calls_total > 3 {
                                self.failed = True;
                                self.error_code = "CALL_LIMIT_EXCEEDED";
                                disengage;
                            } else {
                                if here.candidate_size > 1048576 {
                                    self.failed = True;
                                    self.error_code = "BUFFER_CAP_EXCEEDED";
                                    disengage;
                                } else {
                                    if here.raw_status != 0 or here.growth_valid == False {
                                        self.failed = True;
                                        self.error_code = "GET_ADAPTERS_ADDRESSES_FAILED";
                                        disengage;
                                    } else {
                                        print(f"bounded snapshot: {here.calls_total} calls, "
                                              f"{here.candidate_size} bytes");
                                        visit [-->];
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    can inspect with Adapter entry {
        if here.walked {
            self.failed = True;
            self.error_code = "ADAPTER_LIST_CYCLE";
            disengage;
        } else {
            here.walked = True;
            if here.layout_valid == False or here.length < 108 {
                self.failed = True;
                self.error_code = "TRUNCATED_ADAPTER";
                disengage;
            } else {
                if here.oper_status != 1 or here.unicast_count < 1 {
                    self.failed = True;
                    self.error_code = "NO_USABLE_UNICAST_ADDRESS";
                    disengage;
                } else {
                    print(f"adapter accepted: {here.name}");
                    visit [->:FirstDnsServer:->];
                    visit [->:PrimarySuffix:->];
                    if here.length >= 448 {
                        visit [->:FirstDnsSuffix:->];
                    }
                    visit [->:NextAdapter:->];
                }
            }
        }
    }

    can collect with DnsServer entry {
        if here.walked {
            self.failed = True;
            self.error_code = "DNS_SERVER_LIST_CYCLE";
            disengage;
        } else {
            here.walked = True;
            valid_record: bool = here.pointer_in_buffer
                and here.length_valid
                and here.address_valid;

            if here.family == 4 {
                if here.sockaddr_length != 16 or here.scope_id != 0 {
                    valid_record = False;
                }
            } else {
                if here.family != 6 or here.sockaddr_length != 28 {
                    valid_record = False;
                }
            }

            if valid_record == False or here.port != 53 {
                self.failed = True;
                self.error_code = "INVALID_DNS_SERVER_SOCKADDR";
                disengage;
            } else {
                if here.key in self.server_keys {
                    print(f"duplicate server ignored: {here.address}");
                } else {
                    self.server_keys.append(here.key);
                    self.server_count += 1;
                    if self.server_count > 8 {
                        self.failed = True;
                        self.error_code = "TOO_MANY_DNS_SERVERS";
                        disengage;
                    } else {
                        print(f"server[{here.order}] {here.address} "
                              f"scope={here.scope_id}");
                    }
                }
                visit [->:NextDnsServer:->];
            }
        }
    }

    can collect with SearchSuffix entry {
        if here.walked {
            self.failed = True;
            self.error_code = "DNS_SUFFIX_LIST_CYCLE";
            disengage;
        } else {
            here.walked = True;
            if here.pointer_in_buffer == False or here.utf16_valid == False
                or here.wire_bytes > 256 {
                self.failed = True;
                self.error_code = "INVALID_DNS_SUFFIX";
                disengage;
            } else {
                if here.key in self.suffix_keys {
                    print(f"duplicate suffix ignored: {here.value}");
                } else {
                    self.suffix_keys.append(here.key);
                    self.suffix_count += 1;
                    self.suffix_wire_bytes += here.wire_bytes;
                    if self.suffix_count > 6 {
                        self.failed = True;
                        self.error_code = "TOO_MANY_DNS_SUFFIXES";
                        disengage;
                    } else {
                        if self.suffix_wire_bytes > 256 {
                            self.failed = True;
                            self.error_code = "DNS_SUFFIX_WIRE_CAP_EXCEEDED";
                            disengage;
                        } else {
                            print(f"suffix[{here.order}] {here.value}");
                        }
                    }
                }
                visit [->:NextDnsSuffix:->];
            }
        }
    }

    can report with Root exit {
        if self.failed == False and self.server_count == 0 {
            self.failed = True;
            self.error_code = "NO_USABLE_DNS_SERVERS";
        }

        if self.failed {
            print(f"snapshot rejected: {self.error_code}");
        } else {
            self.published = True;
            print(f"snapshot published: {self.server_count} servers, "
                  f"{self.suffix_count} suffixes");
        }
    }
}

with entry {
    snapshot = ResolverSnapshot();

    adapter_one = Adapter(name="Ethernet");
