}

"""Underworld domain routing demo with staged readiness and cycle-safe traversal."""

node Domain {
    has name: str = "";
    has phase: str = "DRAFT";
    has generation: int = 0;
    has ready: bool = False;
    has active: bool = False;
    has committed: bool = False;
}

edge GatewayRoute {
    has source_generation: int = 0;
    has destination_generation: int = 0;
    has staged: bool = False;
}

walker DomainAuditor {
    has hops: int = 0;
    has max_hops: int = 5;

    can begin with Root entry {
        print("Auditing domain gateway routes");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Domain entry {
        self.hops += 1;
        readiness = "READY" if here.ready else "STAGED";
        activity = "ACTIVE" if here.active else "INACTIVE";
        persistence = "COMMITTED" if here.committed else "UNCOMMITTED";
        print(f"hop {self.hops}: {here.name} [{here.phase}] "
              f"{readiness}, {activity}, {persistence}, "
              f"generation {here.generation}");

        if self.hops >= self.max_hops {
            print("cycle guard: hop limit reached");
            disengage;
        } else {
            visit [->:GatewayRoute:->] else {
                print(f"no gateway route leaves {here.name}");
                disengage;
            }
        }
    }
}

with entry {
    overworld = Domain(
        name="Overworld",
        phase="ACTIVE",
        generation=12,
        ready=True,
        active=True,
        committed=True
    );
    underworld = Domain(
        name="Underworld",
        phase="STAGED",
        generation=13,
        ready=False,
        active=False,
        committed=False
    );

    root ++> overworld;
    overworld +>:GatewayRoute(
        source_generation=12,
        destination_generation=13,
        staged=True
    ): +> underworld;
    underworld +>:GatewayRoute(
        source_generation=13,
        destination_generation=12,
        staged=False
    ): +> overworld;

    root spawn DomainAuditor();
}

