"""Incremental building support propagation with typed edges and cycle detection."""

node TerrainCell {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has is_support_root: bool = True;
    has walk_token: int = 0;
}

node BuildPiece {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has supported: bool = False;
    has dirty: bool = True;
    has walk_token: int = 0;
}

edge Contains { }

edge Supports {
    has cost: int = 1;
}

walker SupportPropagator {
    has token: int = 1;
    has cycle_found: bool = False;
    has cycle_count: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can propagate with TerrainCell entry {
        if here.walk_token == self.token {
            self.cycle_found = True;
            self.cycle_count = self.cycle_count + 1;
        } else {
            here.walk_token = self.token;
            visit [->:Supports:->] else {
                disengage;
            }
        }
    }

    can propagate with BuildPiece entry {
        if here.walk_token == self.token {
            self.cycle_found = True;
            self.cycle_count = self.cycle_count + 1;
        } else {
            here.walk_token = self.token;
            here.supported = True;
            here.dirty = False;
            visit [->:Supports:->] else {
                disengage;
            }
        }
    }
}

