node Asset {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has asset_id: str = "";
    has family: str = "";
    has lifecycle: str = "reference/concept";
    has provenance: str = "";
    has license_attribution: str = "";
    has license_required: bool = False;
    has semantic_role: str = "";
    has visual_profile: str = "";
    has scale: str = "";
    has orientation: str = "";
    has geometry_stats: str = "";
    has lod_variants: str = "";
    has material_dependencies: str = "";
    has collider_policy: str = "";
    has rig_adapter: str = "";
    has gameplay_content_id: str = "";
    has stable_id: str = "";
    has validation_state: str = "unvalidated";
    has authoritative_source: str = "";
    has placeholder: bool = False;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has artifact_id: str = "";
    has artifact_kind: str = "";
    has path: str = "";
    has source_of_truth: str = "";
    has provenance: str = "";
    has license_attribution: str = "";
    has validation_state: str = "unvalidated";
}

edge Derives {
    has kind: str = "";
}

edge DependsOn {
    has required: bool = True;
}

edge Supersedes {
    has reason: str = "";
}

edge BindsRole {
    has role: str = "";
}

walker AssetAudit {
    has max_depth: int = 8;
    has depth: int = 0;
    has blocked: int = 0;

    can start with Root entry {
        print("Auditing reachable asset manifest records");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_asset with Asset entry {
        provenance_label = "recorded" if here.provenance != "" else "MISSING";
        license_label = "recorded" if here.license_attribution != "" else "MISSING";
        print(f"asset {here.asset_id}: {here.lifecycle}, "
              f"role={here.semantic_role}, provenance={provenance_label}, "
              f"license={license_label}, gameplay={here.gameplay_content_id}");

        if here.lifecycle == "approved/game-ready" {
            if here.provenance == "" {
                print(f"BLOCKED {here.asset_id}: provenance is required");
                self.blocked = self.blocked + 1;
            }
            if here.license_required && here.license_attribution == "" {
                print(f"BLOCKED {here.asset_id}: license attribution is required");
                self.blocked = self.blocked + 1;
            }
        }

        if self.depth >= self.max_depth {
            print(f"Traversal depth cap reached at {here.asset_id}");
            disengage;
        } else {
            self.depth = self.depth + 1;
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_artifact with Artifact entry {
        print(f"artifact {here.artifact_id}: {here.artifact_kind} at {here.path}, "
              f"source={here.source_of_truth}, validation={here.validation_state}");

        if self.depth >= self.max_depth {
            print(f"Traversal depth cap reached at {here.artifact_id}");
            disengage;
        } else {
            self.depth = self.depth + 1;
            visit [-->] else {
                disengage;
            }
        }
    }
}

