    has result: int = 0;
    has computed_epoch: int = 0;
    has invalidated: bool = False;
}

edge Requested {
    has reason: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker AnalysisAuditor {
    has seen_keys: list[str] = [];
    has context_epoch: int = 0;
    has cycle_found: bool = False;
    has stale_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_context with IrContext entry {
        self.context_epoch = here.invalidation_epoch;
        print(f"Auditing {here.context_name} at epoch {self.context_epoch}");
        visit [->:Requested:->] else {
            disengage;
        }
    }

    can inspect_analysis with Analysis entry {
        if here.key in self.seen_keys {
            self.cycle_found = True;
            print(f"Dependency cycle detected at {here.key}");
            disengage;
        } else {
            self.seen_keys.append(here.key);
            if here.invalidated or here.computed_epoch < self.context_epoch {
                self.stale_count += 1;
                print(f"Stale analysis: {here.key}");
            } else {
                print(f"Reusable analysis: {here.key} = {here.result}");
            }
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

