"""Building support validation with bounded structural collapse."""

node StructuralNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FailureScheduler(StructuralNode) {
    has pending_count: int = 0;
    has last_piece_id: int = 0;
    has next_deadline: int = 0;
}

node BuildPiece(StructuralNode) {
    has piece_id: int = 0;
    has committed: bool = False;
    has supported: bool = False;
    has pending_failure: bool = False;
    has failure_deadline: int = 0;
    has removed: bool = False;
    has cycle_detected: bool = False;

    def update_support(supported_now: bool, now: int, scheduler: FailureScheduler) {
        if self.removed {
            return;
        }

        self.supported = supported_now;

        if supported_now {
            if self.pending_failure {
                scheduler del ->:PendingFailure:-> self;
            }
            self.pending_failure = False;
            self.failure_deadline = 0;
        } else {
            if not self.committed {
                return;
            }

            if not self.pending_failure {
                self.pending_failure = True;
                self.failure_deadline = now + 1;
                scheduler.pending_count += 1;
                scheduler.last_piece_id = self.piece_id;
                scheduler.next_deadline = self.failure_deadline;
                scheduler +>:PendingFailure(deadline=self.failure_deadline):+> self;
            } elif now >= self.failure_deadline {
                scheduler del ->:PendingFailure:-> self;
                self.pending_failure = False;
                self.committed = False;
                self.removed = True;
                del self;
            }
        }
    }
}

node SupportAnchor(StructuralNode) {
    has anchor_strength: int = 100;
}

edge Supports {
    has load_limit: int = 0;
}

edge PendingFailure {
    has deadline: int = 0;
}

walker StructuralReachability {
    has visited_ids: list[int] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with SupportAnchor entry {
        visit [->:Supports:->] else {
            disengage;
        }
    }

    can inspect with BuildPiece entry {
        if here.piece_id in self.visited_ids {
            disengage;
        } else {
            self.visited_ids.append(here.piece_id);
            here.supported = True;
            visit [->:Supports:->] else {
                disengage;
            }
        }
    }
}

walker PlacementCheck {
    has scheduler: FailureScheduler | None = None;
    has now: int = 0;
    has target: BuildPiece | None = None;
    has seen_ids: list[int] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with BuildPiece entry {
        if self.target is None {
            self.target = here;
        }

        if here.piece_id in self.seen_ids {
            self.target.cycle_detected = True;
            self.target.update_support(False, self.now, self.scheduler);
            disengage;
        } else {
            self.seen_ids.append(here.piece_id);
            visit [<--:Supports:--] else {
                self.target.update_support(False, self.now, self.scheduler);
            }
        }
    }

    can inspect with SupportAnchor entry {
        self.target.update_support(True, self.now, self.scheduler);
        disengage;
    }
}

