    has piece_id: int = 0;
    has committed: bool = False;
    has supported: bool = False;
    has pending_failure: bool = False;
    has failure_deadline: int = 0;
    has removed: bool = False;
    has cycle_detected: bool = False;

    def apply_failure(now: int) {
        if self.committed {
            if self.pending_failure {
                if now >= self.failure_deadline {
                    self.removed = True;
                    self.committed = False;
                    self.pending_failure = False;
                }
            } else {
                self.pending_failure = True;
                self.failure_deadline = now + 1;
            }
        }
    }
}

node BuildPiece(StructuralNode) {
    has candidate: bool = False;
}

node SupportAnchor(StructuralNode) {
    has anchor_strength: int = 100;
}

edge Supports {
    has load_limit: int = 0;
}

walker StructuralAudit {
    has now: int = 0;
    has visited_ids: list[int] = [];
    has reached_anchor: bool = False;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_anchor with SupportAnchor entry {
        self.reached_anchor = True;
        here.supported = True;
    }

    can inspect_piece with BuildPiece entry {
        if here.removed {
            disengage;
        }

        if here.piece_id in self.visited_ids {
            here.cycle_detected = True;
            self.cycle_found = True;
            here.supported = False;
            here.apply_failure(self.now);
            disengage;
        }

        self.visited_ids.append(here.piece_id);

        visit [->:Supports:->] else {
            here.supported = False;
            here.apply_failure(self.now);
            disengage;
        }

        if self.reached_anchor {
            if self.cycle_found {
                here.supported = False;
                here.apply_failure(self.now);
            } else {
                here.supported = True;
                here.pending_failure = False;
                here.failure_deadline = 0;
            }
        } else {
            here.supported = False;
            here.apply_failure(self.now);
        }
    }
}

