                self.best_rank = here.category_rank;
                self.best_category = here.category;
                self.best_operation = here.operation;
                self.best_source = here.source;
                self.best_declaration = here.declaration_source;
                self.best_chain = chain_text;
            }
        }

        visit [->:Invokes:->] else {
            self.dead_ends += 1;
        }
    }
}

