walker ParentageAuditor {
    has seen: list[str] = [];
    has inspected: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Starting Core parentage audit");
        visit [->:Contains:->] else {
            print("No parentage targets");
            disengage;
        }
    }

    can inspect with CoreAnimal | HeritageAnimal entry {
        if here.canonical_id in self.seen {
            self.cycle_found = True;
            print(f"Cycle rejected at {here.title} ({here.canonical_id})");
            disengage;
        } else {
            self.seen = self.seen + [here.canonical_id];
            self.inspected = self.inspected + 1;
            owner = "Core command owner" if here.core_owned else "read-only Heritage projection";
            status = "active" if here.available else "archived";
            mark = "✟" if here.deceased else "";
            print(f"{owner}: {here.title} [{status}] {mark}");
            visit [->:Parentage:->] else {
                print(f"Lineage ends at {here.title}");
                disengage;
            }
        }
    }

    can report with Root exit {
        result = "cycle detected" if self.cycle_found else "lineage valid";
        print(f"Audit complete: {self.inspected} records inspected; {result}");
    }
}

