"""Deterministic whole-program fatal-route analysis over lowered functions."""

node Function {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has canonical_id: str = "";
    has source_decl: str = "";
    has return_kind: str = "value";
}

node Instruction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has function_id: str = "";
    has order: int = 0;
    has operation: str = "";
    has category: str = "none";
    has category_rank: int = 0;
    has source: str = "";
    has declaration_source: str = "";
}

edge Contains {
    has order: int = 0;
}

edge Invokes {
    has tail: bool = False;
}

walker FatalRouteAuditor {
    has current_chain: list[str] = [];
    has active_root: str = "";
    has best_function: str = "";
    has best_order: int = -1;
    has best_rank: int = -1;
    has best_category: str = "";
    has best_operation: str = "";
    has best_source: str = "";
    has best_declaration: str = "";
    has best_chain: str = "";
    has cycles: int = 0;
    has dead_ends: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_function with Function entry {
        root_walk = len(self.current_chain) == 0;

        if root_walk {
            self.active_root = here.canonical_id;
            self.best_function = "";
            self.best_order = -1;
            self.best_rank = -1;
            self.best_category = "";
            self.best_operation = "";
            self.best_source = "";
            self.best_declaration = "";
            self.best_chain = "";
        }

        already_seen = False;
        for name in self.current_chain {
            if name == here.canonical_id {
                already_seen = True;
            }
        }

        if already_seen {
            self.cycles += 1;
        } else {
            self.current_chain.append(here.canonical_id);
            visit [->:Contains:->] else {
                self.dead_ends += 1;
            }
            self.current_chain.pop();
        }

        if root_walk {
            if self.best_function == "" {
                print(f"root={self.active_root}|capability=NO_KNOWN_MANAGED_FATAL");
            } else {
                print(
                    f"root={self.active_root}|capability=REJECTED"
                    f"|category={self.best_category}"
                    f"|chain={self.best_chain}"
                    f"|leaf={self.best_operation}"
                    f"|declaration={self.best_declaration}"
                    f"|instruction={self.best_source}"
                );
            }
        }
    }

    can inspect_instruction with Instruction entry {
        if here.category_rank > 0 {
            chain_text = "";
            for (index, name) in enumerate(self.current_chain) {
                if index == 0 {
                    chain_text = name;
                } else {
                    chain_text = f"{chain_text} -> {name}";
                }
            }

            better = False;
            if self.best_function == "" {
                better = True;
            } elif here.function_id < self.best_function {
                better = True;
            } elif here.function_id == self.best_function {
                if here.order < self.best_order {
                    better = True;
                } elif here.order == self.best_order {
                    if here.category_rank < self.best_rank {
                        better = True;
                    } elif here.category_rank == self.best_rank {
                        if here.source < self.best_source {
                            better = True;
                        } elif here.source == self.best_source and chain_text < self.best_chain {
                            better = True;
                        }
                    }
                }
            }

            if better {
                self.best_function = here.function_id;
                self.best_order = here.order;
                self.best_rank = here.category_rank;
                self.best_category = here.category;
                self.best_operation = here.operation;
                self.best_source = here.source;
                self.best_declaration = here.declaration_source;
                self.best_chain = chain_text;
            }
        }

        visit [->:Invokes:->] else {
            self.dead_ends += 1;
        }
    }
}

