walker PhysicsAudit {
    has max_steps: int = 16;
    has steps: int = 0;
    has worlds_seen: int = 0;
    has actors_seen: int = 0;
    has props_seen: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_world with World entry {
        if self.steps >= self.max_steps {
            print("Traversal depth guard stopped a possible contact cycle");
            disengage;
        } else {
            self.steps += 1;
            self.worlds_seen += 1;
            print(f"world {here.title}: tick={here.tick}, gravity={here.gravity}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_actor with Actor entry {
        if self.steps >= self.max_steps {
            print("Traversal depth guard stopped a possible contact cycle");
            disengage;
        } else {
            self.steps += 1;
            self.actors_seen += 1;
            print(f"actor {here.title}: position={here.position}, force={here.input_force}");
            visit [->:Contacts:->] else {
                disengage;
            }
        }
    }

    can inspect_prop with Prop entry {
        if self.steps >= self.max_steps {
            print("Traversal depth guard stopped a possible contact cycle");
            disengage;
        } else {
            self.steps += 1;
            self.props_seen += 1;
            print(f"prop {here.title}: velocity={here.velocity}, contacts={here.contact_count}");
            visit [->:Contacts:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"audit complete: worlds={self.worlds_seen}, actors={self.actors_seen}, props={self.props_seen}, steps={self.steps}");
    }
}

