}

node ReplayVerifiedScientificDisposition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has record_id: str = "";
    has view_id: str = "";
    has view_head_generation: int = 0;
    has primary_label: str = "";
    has reason_topology: str = "";
    has policy_trace: str = "";
    has policy_profile: str = "";
    has evaluator_profile: str = "";
}

edge Candidate { }
edge ForgedCandidate { }
edge ContainsEvidence {
    has slot: int = 0;
}
edge DeclaredView { }
edge RelatedEvidence { }
edge ReplayProduces { }

walker ReplayVerifier {
    has expected_record_id: str = "";
    has expected_proposition_id: str = "";
    has expected_scientific_use_id: str = "";
    has expected_view_id: str = "";
    has expected_view_head_generation: int = 0;
    has expected_label: str = "";
    has expected_reason_topology: str = "";
    has expected_policy_trace: str = "";
    has expected_policy_profile: str = "";
    has expected_evaluator_profile: str = "";
    has expected_historical_cutoff: int = 0;
    has expected_evidence_count: int = 0;
    has evidence_seen: int = 0;
    has replayed_reason: str = "";
    has replayed_trace: str = "";
    has replayed_policy_profile: str = "";
    has replayed_evaluator_profile: str = "";
    has replayed_historical_cutoff: int = 0;
    has traversal_budget: int = 4;

    can begin with Root entry {
        visit [->:Candidate:->] else {
            disengage;
        }
    }

    can inspect_record with ScientificDispositionRecord entry {
        self.expected_record_id = here.record_id;
        self.expected_proposition_id = here.proposition_id;
        self.expected_scientific_use_id = here.scientific_use_id;
        self.expected_view_id = here.view_id;
        self.expected_view_head_generation = here.view_head_generation;
        self.expected_label = here.primary_label;
        self.expected_reason_topology = here.reason_topology;
        self.expected_policy_trace = here.policy_trace;
        self.expected_policy_profile = here.policy_profile;
        self.expected_evaluator_profile = here.evaluator_profile;
        self.expected_historical_cutoff = here.historical_cutoff;
        self.expected_evidence_count = here.evidence_count;
        self.evidence_seen = 0;
        visit [->:ContainsEvidence:->] else {
            print(f"[REPLAY FAIL] {here.record_id}: missing evidence");
            disengage;
        }
    }

    can inspect_evidence with EvidenceItem entry {
        if self.traversal_budget <= 0 {
            print("[CYCLE GUARD] replay stopped at the repeated evidence cycle");
            disengage;
        } else {
            self.traversal_budget -= 1;
            self.evidence_seen += 1;
            self.replayed_reason = here.reason_token;
            self.replayed_trace = here.policy_trace;
            self.replayed_policy_profile = here.policy_profile;
            self.replayed_evaluator_profile = here.evaluator_profile;
            self.replayed_historical_cutoff = here.historical_cutoff;

            if self.evidence_seen == 1 {
                if self.evidence_seen == self.expected_evidence_count
                    and here.record_id == self.expected_record_id
                    and here.proposition_id == self.expected_proposition_id
                    and here.scientific_use_id == self.expected_scientific_use_id
                    and here.view_id == self.expected_view_id
                    and here.view_head_generation == self.expected_view_head_generation
                    and self.expected_label == "accepted"
                    and self.replayed_reason == self.expected_reason_topology
                    and self.replayed_trace == self.expected_policy_trace
                    and self.replayed_policy_profile == self.expected_policy_profile
                    and self.replayed_evaluator_profile == self.expected_evaluator_profile
                    and self.replayed_historical_cutoff == self.expected_historical_cutoff
                    and here.admitted {
                    witness = ReplayVerifiedScientificDisposition(
                        record_id=self.expected_record_id,
                        view_id=self.expected_view_id,
                        view_head_generation=self.expected_view_head_generation,
                        primary_label=self.expected_label,
                        reason_topology=self.replayed_reason,
                        policy_trace=self.replayed_trace,
                        policy_profile=self.replayed_policy_profile,
                        evaluator_profile=self.replayed_evaluator_profile
                    );
                    here +>:ReplayProduces:+> witness;
                    print(f"[REPLAY PASS] {self.expected_record_id} minted an owner-created witness");
                } else {
                    print(f"[REPLAY FAIL] {self.expected_record_id}: complete result mismatch");
                }
            }

            visit [->:RelatedEvidence:->] else {
                disengage;
            }
        }
    }
}

walker ForgeryAuditor {
    can begin with Root entry {
        visit [->:ForgedCandidate:->] else {
            disengage;
        }
    }

    can inspect with ScientificDispositionRecord entry {
        if here.primary_label == "accepted"
            and here.reason_topology != "candidate:admitted" {
            print(f"[FORGED] {here.record_id}: matching label did not hide topology mismatch");
        } else {
            print(f"[FORGED] {here.record_id}: rejected");
        }
        visit [-->] else {
            disengage;
        }
    }
}

walker CurrentnessChecker {
    has returning: bool = False;
    has bound_view_id: str = "";
    has bound_view_head_generation: int = 0;

    can begin with Root entry {
        visit [->:Candidate:->] else {
            disengage;
        }
    }

    can follow_record with ScientificDispositionRecord entry {
        if self.returning {
            visit [->:DeclaredView:->] else {
                disengage;
            }
        } else {
            visit [->:ContainsEvidence:->] else {
                disengage;
            }
        }
    }

    can follow_evidence with EvidenceItem entry {
        if self.returning {
            visit [<--:ContainsEvidence:--] else {
                disengage;
            }
        } else {
            visit [->:ReplayProduces:->] else {
                disengage;
            }
        }
    }

    can follow_witness with ReplayVerifiedScientificDisposition entry {
        self.bound_view_id = here.view_id;
        self.bound_view_head_generation = here.view_head_generation;
        self.returning = True;
        visit [<--:ReplayProduces:--] else {
            disengage;
        }
    }

    can evaluate_view with ScientificView entry {
        if self.bound_view_id == here.view_id
            and self.bound_view_head_generation == here.head_generation {
            print(f"[CURRENT] {here.namespace} is current at H{here.head_generation}");
        } else {
            print(f"[STALE] {here.namespace}: witness H{self.bound_view_head_generation}, live H{here.head_generation}");
        }
        visit [-->] else {
            disengage;
        }
    }
}

