"""Self-contained first-biome acceptance graph with typed dependencies and cycle detection."""

node Biome {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Feature {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Encounter {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Supports {
    has purpose: str = "";
}

walker ScenarioAudit {
    has seen_titles: list[str] = [];
    has reachable_count: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Biome | Feature | Encounter entry {
        if (here.title in self.seen_titles) {
            self.cycle_count += 1;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.reachable_count += 1;
            status = "available" if here.available else "blocked";
            print(f"reachable: {here.title} [{status}] milestone={here.year}");
            visit [->:Supports:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"reachable nodes: {self.reachable_count}");
        print(f"cycles guarded: {self.cycle_count}");
    }
}

