"""Fail-closed HoneyBee Workspace removal preflight with typed graph traversal."""

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has workspace_id: str = "";
    has child_id: str = "";
    has expected_volume_guid: str = "";
    has expected_mount_path: str = "";
    has active_handles: int = 0;
}

node StorageVolume {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has child_id: str = "";
    has volume_guid: str = "";
    has mount_path: str = "";
    has active_handles: int = 0;
}

node ExternalProcess {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has process_id: str = "";
    has process_name: str = "";
    has held_volume_guid: str = "";
    has holds_library: bool = False;
}

edge MountedLibrary {
    has child_id: str = "";
    has volume_guid: str = "";
    has mount_path: str = "";
}

edge LibraryHandle {
    has process_id: str = "";
    has volume_guid: str = "";
}

walker RemovalPreflight {
    has seen_ids: list[str] = [];
    has expected_child_id: str = "";
    has expected_volume_guid: str = "";
    has expected_mount_path: str = "";
    has identity_verified: bool = False;
    has blocked: bool = False;
    has removal_token: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_workspace with Workspace entry {
        if here.workspace_id in self.seen_ids {
            print("[FAIL CLOSED] cycle detected; no removal mutation performed");
            disengage;
        }

        self.seen_ids.append(here.workspace_id);
        self.expected_child_id = here.child_id;
        self.expected_volume_guid = here.expected_volume_guid;
        self.expected_mount_path = here.expected_mount_path;
        self.identity_verified = False;
        self.blocked = here.active_handles > 0;
        self.removal_token = "";

        print(f"preflight: Workspace \"{here.title}\"");
        visit [->:MountedLibrary:->] else {
            disengage;
        }
    }

    can verify_volume with StorageVolume entry {
        if here.child_id != self.expected_child_id
            or here.volume_guid != self.expected_volume_guid
            or here.mount_path != self.expected_mount_path {
            self.identity_verified = False;
            self.blocked = True;
            print("[FAIL CLOSED] Child, volume, or mount identity mismatch");
            print("No Workspace files or Library storage were removed");
        } else {
            self.identity_verified = True;
            print(f"verified Child {here.child_id}, volume {here.volume_guid}");
            if here.active_handles > 0 {
                self.blocked = True;
                print("[FAIL CLOSED] storage reports active handles");
            }
        }

        visit [->:LibraryHandle:->] else {
            disengage;
        }
    }

    can inspect_process with ExternalProcess entry {
        if not self.identity_verified {
            self.blocked = True;
            self.removal_token = "";
            print("[FAIL CLOSED] removal token was not issued");
        } else if here.holds_library || self.blocked {
            self.blocked = True;
            self.removal_token = "";
            print("workspace.in-use");
            print(f"Workspace \"{here.title}\" is still being used by another process.");
            print("Close Unity, terminals, IDEs, and AI CLI processes using this Workspace, then retry.");
            print("No Workspace files or Library storage were removed.");
            print(f"best-effort diagnostic: {here.process_name} ({here.process_id})");
        } else {
            self.removal_token = f"remove:{self.expected_child_id}:{self.expected_volume_guid}";
            print("exclusive volume ownership acquired");
            print(f"identity-bound removal token issued: {self.removal_token}");
            print("verified junction and Git worktree may now be removed");
        }
    }
}

