        }

        if self.hops < self.max_hops {
            self.hops += 1;
            visit [-->] else {
                disengage;
            }
        } else {
            self.failures += 1;
            disengage;
        }
    }

    can inspect_artifact with EvidenceArtifact entry {
        self.checked_artifacts += 1;
        valid = here.present;
        if here.manifest_valid == False {
            valid = False;
        }
        if here.capsule_present == False {
            valid = False;
        }
        if here.path_safe == False {
            valid = False;
        }
        if here.files_unique == False {
            valid = False;
        }
        if here.evidence_nonempty == False {
            valid = False;
        }
        if here.runner_family != self.expected_runner {
            valid = False;
        }
        if here.action_identity != self.expected_action {
            valid = False;
        }
        if here.capsule_schema != self.expected_capsule_schema {
            valid = False;
        }

        if here.qualification_issue == 219 {
            if here.name != self.expected_219_artifact {
                valid = False;
            }
            if here.sha256 != self.expected_219_digest {
                valid = False;
            }
        } else {
            if here.qualification_issue == 224 {
                if here.name != self.expected_224_artifact {
                    valid = False;
                }
                if here.sha256 != self.expected_224_digest {
                    valid = False;
                }
            } else {
                if here.qualification_issue == 243 {
                    if here.name != self.expected_243_artifact {
                        valid = False;
                    }
                    if here.sha256 != self.expected_243_digest {
                        valid = False;
                    }
                } else {
                    valid = False;
                }
            }
        }

        if valid {
            print(f"artifact {here.name} verified");
        } else {
            print(f"artifact {here.name} rejected");
            self.failures += 1;
        }

        if self.hops < self.max_hops {
            self.hops += 1;
            visit [-->] else {
                disengage;
            }
        } else {
            self.failures += 1;
            disengage;
        }
    }

    can inspect_file with ProductFile entry {
        self.checked_files += 1;
        valid = here.installed;
        if here.allowed == False {
            valid = False;
        }
        if here.byte_exact == False {
            valid = False;
        }

        if valid {
            print(f"materialized exact bytes: {here.path}");
        } else {
            print(f"product file rejected: {here.path}");
            self.failures += 1;
        }
    }

    can capture_authority with MaterializationAuthority entry {
        self.authority = here;
        print(f"authority object schema {here.schema_version} captured");
    }

    can report with Root exit {
        if self.authority is not None {
            self.authority.authorized = self.failures == 0;
            if self.authority.authorized {
                print(f"PRODUCT MATERIALIZATION AUTHORIZED; checked {self.checked_qualifications} qualifications, {self.checked_artifacts} artifacts, and {self.checked_files} files");
            } else {
                print(f"PRODUCT MATERIALIZATION REJECTED with {self.failures} failures");
            }
        }
    }
}

