"""Replayable spatial lineage with typed inputs, derivations, parent states, and cycle detection."""

node SpatialState {
    has state_id: str = "";
    has state_kind: str = "";
    has schema_version: int = 1;
    has derivation_ref: str = "";
    has output_state_digest: str = "";
    has lineage_digest: str = "";
}

node SpatialDerivation {
    has derivation_id: str = "";
    has namespace: str = "";
    has generation: int = 0;
    has derivation_digest: str = "";
    has recipe: str = "";
}

node DirectSpatialInput {
    has input_id: str = "";
    has input_kind: str = "";
    has input_digest: str = "";
}

edge DerivedBy {
}

edge AdmitsInput {
    has role: str = "";
}

edge ParentState {
}

walker LineageAuditor {
    has active_ids: list[str] = [];

    can start with Root entry {
        print("Auditing derived spatial states from the root");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with SpatialState entry {
        if here.state_id in self.active_ids {
            print(f"[CYCLE] replay stopped at {here.state_id}");
            disengage;
        } else {
            self.active_ids.append(here.state_id);
            print(f"[STATE] {here.state_id}: kind={here.state_kind}, "
                  f"output={here.output_state_digest}, "
                  f"lineage={here.lineage_digest}");
            visit [->:ParentState:->] else {
                print(f"[LEAF] {here.state_id} has no parent states");
            }
            self.active_ids.pop();
        }
    }
}

walker RecipeAuditor {
    can start with Root entry {
        print("Auditing derivation recipes");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with SpatialState entry {
        print(f"[DERIVATION REF] {here.state_id} uses {here.derivation_ref}");
        visit [->:DerivedBy:->] else {
            print(f"[MISSING] {here.state_id} has no derivation recipe");
        }
    }

    can inspect_recipe with SpatialDerivation entry {
        print(f"[RECIPE] {here.derivation_id}: {here.recipe}, "
              f"digest={here.derivation_digest}");
        visit [-->] else {
            print(f"[RECIPE END] {here.derivation_id}");
        }
    }
}

walker InputAuditor {
    can start with Root entry {
        print("Auditing typed direct input roles");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with SpatialState entry {
        visit [->:AdmitsInput:->] else {
            print(f"[NO INPUT] {here.state_id}");
        }
    }

    can inspect_input with DirectSpatialInput entry {
        print(f"[INPUT] {here.input_id}: {here.input_kind}, "
              f"digest={here.input_digest}");
        visit [-->] else {
            print(f"[INPUT END] {here.input_id}");
        }
    }
}

with entry {
    observation = DirectSpatialInput(
