    );

    recipe_a = SpatialDerivation(
        derivation_id="mapper-a",
        namespace="symthaea.spatial",
        generation=1,
        derivation_digest="recipe-digest-a",
        recipe="grid-v1; calibrated-camera-a"
    );
    recipe_b = SpatialDerivation(
        derivation_id="mapper-b",
        namespace="symthaea.spatial",
        generation=1,
        derivation_digest="recipe-digest-b",
        recipe="grid-v1; calibrated-camera-b"
    );
    recipe_update = SpatialDerivation(
        derivation_id="mapper-update",
        namespace="symthaea.spatial",
        generation=2,
        derivation_digest="recipe-digest-update",
        recipe="incremental-grid-v1; conflict-rule-max"
    );

    field_a = SpatialState(
        state_id="field-a",
        state_kind="geometric_evidence_field",
        schema_version=1,
        derivation_ref="mapper-a",
        output_state_digest="same-output-digest",
        lineage_digest="lineage-a"
    );
    field_b = SpatialState(
        state_id="field-b",
        state_kind="geometric_evidence_field",
        schema_version=1,
        derivation_ref="mapper-b",
        output_state_digest="same-output-digest",
        lineage_digest="lineage-b"
    );
    field_next = SpatialState(
        state_id="field-next",
        state_kind="geometric_evidence_field",
        schema_version=1,
        derivation_ref="mapper-update",
        output_state_digest="next-output-digest",
        lineage_digest="lineage-next"
    );

    cycle_left = SpatialState(
        state_id="cycle-left",
        state_kind="geometric_evidence_field",
        schema_version=1,
        derivation_ref="mapper-a",
        output_state_digest="cycle-left-output",
        lineage_digest="cycle-left-lineage"
    );
    cycle_right = SpatialState(
        state_id="cycle-right",
        state_kind="geometric_evidence_field",
        schema_version=1,
        derivation_ref="mapper-b",
        output_state_digest="cycle-right-output",
        lineage_digest="cycle-right-lineage"
    );

    root ++> field_next;
    root ++> field_b;

    field_next +>:ParentState:+> field_a;
    field_a +>:DerivedBy:+> recipe_a;
    field_b +>:DerivedBy:+> recipe_b;
    field_next +>:DerivedBy:+> recipe_update;

    field_a +>:AdmitsInput(role="sensor_observation"):+> observation;
    field_b +>:AdmitsInput(role="sensor_observation"):+> observation;
    field_next +>:AdmitsInput(role="new_direct_observation"):+> new_observation;

    cycle_left +>:ParentState:+> cycle_right;
    cycle_right +>:ParentState:+> cycle_left;

    print(f"same output digest: "
          f"{field_a.output_state_digest == field_b.output_state_digest}");
    print(f"different lineage digest: "
          f"{field_a.lineage_digest != field_b.lineage_digest}");

    root spawn LineageAuditor();
    root spawn RecipeAuditor();
    root spawn InputAuditor();
    cycle_left spawn LineageAuditor();
}

"""Audit a barline candidate and trace its downstream measure impact."""

node ScorePage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node BarlineCandidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has x: int = 0;
    has y_top: int = 0;
    has y_bottom: int = 0;
    has confidence: float = 0.0;
    has accepted: bool = True;
    has canonical_barline: bool = False;
}

node MeasurePlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has region_count: int = 1;
    has first_measure: int = 0;
    has last_measure: int = 0;
}

node NumberingRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has start_measure: int = 0;
    has end_measure: int = 0;
}

edge HostsPage { }
edge CandidateOnPage {
    has bbox: str = "";
}
edge AffectsPlan {
    has reason: str = "";
}
edge ProducesNumber {
    has source: str = "";
}

walker ImpactAuditor {
    has inspected: int = 0;
    has hard_fps: int = 0;
    has current_hard_fp: bool = False;
    has diagnostic_replay: bool = True;

    can start with Root entry {
        print("Starting downstream-impact audit");
        visit [->:HostsPage:->] else {
            disengage;
        }
    }

    can inspect_page with ScorePage entry {
        print(f"Page: {here.title}");
        visit [->:CandidateOnPage:->] else {
            disengage;
        }
    }

    can inspect_candidate with BarlineCandidate entry {
        self.inspected += 1;
        self.current_hard_fp = here.accepted && !here.canonical_barline;

        if self.current_hard_fp {
            self.hard_fps += 1;
            print(f"Hard FP at x={here.x}, bbox=[{here.x}, {here.y_top}, {here.x + 4}, {here.y_bottom}]");
        } else {
            print(f"Accepted canonical barline at x={here.x}");
        }

        visit [->:AffectsPlan:->] else {
            disengage;
        }
    }

    can inspect_plan with MeasurePlan entry {
        if self.current_hard_fp && self.diagnostic_replay {
            print(f"Diagnostic replay removes the false boundary: {here.title}");
            print(f"Intended segmentation: one region for M{here.first_measure}-M{here.last_measure}");
        } else {
            print(f"Production segmentation: {here.region_count} regions for M{here.first_measure}-M{here.last_measure}");
        }

        visit [->:ProducesNumber:->] else {
            disengage;
        }
    }

    can report with NumberingRecord entry {
        if self.current_hard_fp && self.diagnostic_replay {
            print(f"Final numbering replay: M{here.start_measure} remains joined with M{here.end_measure}");
        } else {
            print(f"Final numbering: M{here.start_measure}-M{here.end_measure}");
        }
    }
}

