"""Lifecycle teardown demo with typed ownership edges, invalidation, and cycle detection."""

node RuntimeEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has invalidated: bool = False;
    has visited_epoch: int = 0;

    def teardown() {
        self.available = False;
        self.invalidated = True;
    }
}

node GameplaySession(RuntimeEntity) {
    has episode: int = 1;
    has next_handle: int = 1;

    def allocate_handle() -> int {
        handle_value = self.next_handle;
        self.next_handle += 1;
        return handle_value;
    }

    override def teardown() {
        self.available = False;
        self.invalidated = True;
    }
}

node PhysicsBody(RuntimeEntity) {
    has handle: int = 0;
    has net_id: int = 0;

    override def teardown() {
        self.available = False;
        self.invalidated = True;
        self.handle = -1;
        self.net_id = -1;
    }
}

node Consciousness(RuntimeEntity) {
    has rng_cursor: int = 0;
    has persistent_learning: bool = False;
    has belief_state: str = "";

    override def teardown() {
        self.available = False;
        self.invalidated = True;
        self.rng_cursor = 0;
        self.belief_state = "";
    }
}

edge Contains { }
edge Owns {
    has role: str = "";
}
edge DependsOn { }

walker SessionTeardown {
    has episode: int = 1;
    has visited_count: int = 0;
    has cycle_found: bool = False;
    has report_code: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can invalidate with GameplaySession | PhysicsBody | Consciousness entry {
        if here.visited_epoch == self.episode {
            self.cycle_found = True;
            disengage;
        }

        here.visited_epoch = self.episode;
        here.teardown();
        self.visited_count += 1;

        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        if self.cycle_found {
            self.report_code = 2;
        } else {
            self.report_code = 1;
        }
    }
}

