node ReleaseCandidate {
    has title: str = "";
    has version: str = "";
    has selected: bool = False;
}

node QualificationGate {
    has title: str = "";
    has status: str = "PENDING";
    has required: bool = True;
}

node Artifact {
    has title: str = "";
    has digest: str = "";
    has installed: bool = False;
}

edge Tracks { }
edge Requires {
    has mandatory: bool = True;
}
edge Produces {
    has format: str = "";
}
edge DependsOn {
    has reason: str = "";
}

walker ReleaseQualifier {
    has failures: int = 0;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:Tracks:->] else {
            disengage;
        }
    }

    can inspect_candidate with ReleaseCandidate entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        if here.selected {
            print(f"Selected candidate: {here.title} {here.version}");
        } else {
            print(f"Rejected candidate: {here.title} {here.version}");
            self.failures = self.failures + 1;
        }
        visit [->:Requires:->] else {
            disengage;
        }
    }

    can inspect_gate with QualificationGate entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        print(f"Gate {here.title}: {here.status}");
        if here.required && here.status != "PASS" {
            self.failures = self.failures + 1;
        }
        visit [->:Produces:->] else {
            disengage;
        }
    }

    can inspect_artifact with Artifact entry {
        if here.title in self.seen {
            disengage;
        }
        self.seen.append(here.title);
        print(f"Artifact {here.title}: installed={here.installed}");
        if !here.installed {
            self.failures = self.failures + 1;
        }
    }

    can report with Root exit {
        verdict = "GO" if self.failures == 0 else "NO-GO";
        print(f"Qualification decision: {verdict}");
    }
}

