    can follow_gate with QualificationGate entry {
        if here.title in self.seen {
            print(f"Cycle detected at gate {here.title}");
            disengage;
        }
        self.seen.append(here.title);
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

