"""Saved-work dependency retention with artifact ownership, quotas, and cycle detection."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has artifact_id: str = "";
    has owner_scope: str = "";
    has storage_key: str = "";
    has retention_days: int = 0;
    has is_required: bool = True;
}

node Manifest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has manifest_id: str = "";
    has owner_scope: str = "";
    has recovery_quota: int = 0;
    has saved_work_days: int = 0;
    has published: bool = False;
}

edge Dependency {
    has required: bool = True;
}

walker RecoveryAuditor {
    has scope: str = "";
    has quota_left: int = 0;
    has depth: int = 0;
    has max_depth: int = 4;
    has seen: list[str] = [];
    has reachable: int = 0;
    has rejected: int = 0;
    has cycles: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_manifest with Manifest entry {
        if here.published {
            self.scope = here.owner_scope;
            self.quota_left = here.recovery_quota;
            print(f"Auditing {here.manifest_id} for owner scope {self.scope}");
            visit [->:Dependency:->] else {
                disengage;
            }
        } else {
            print(f"Manifest {here.manifest_id} is not published");
        }
    }

    can inspect_artifact with Artifact entry {
        if here.artifact_id in self.seen {
            self.cycles += 1;
            print(f"Cycle detected at artifact {here.artifact_id}");
        } else {
            self.seen.append(here.artifact_id);
            if here.owner_scope != self.scope {
                self.rejected += 1;
                print(f"Rejected {here.artifact_id}: artifact-owned access denied");
            } else {
                if here.available {
                    if self.quota_left > 0 {
                        self.quota_left -= 1;
                        self.reachable += 1;
                        print(f"Retained {here.artifact_id} for {here.retention_days} days");
                        if self.depth < self.max_depth {
                            self.depth += 1;
                            visit [->:Dependency:->] else {
                                disengage;
                            }
                        } else {
                            print(f"Depth limit reached at {here.artifact_id}");
                        }
                    } else {
                        self.rejected += 1;
                        print(f"Rejected {here.artifact_id}: recovery quota exhausted");
                    }
                } else {
                    self.rejected += 1;
                    print(f"Rejected {here.artifact_id}: bytes unavailable");
                }
            }
        }
    }

    can report with Root exit {
        print(f"reachable={self.reachable}, rejected={self.rejected}, cycles={self.cycles}, quota_left={self.quota_left}");
    }
}

with entry {
