        metadata=response.metadata,
        tool_content=response.tool_content,
        judge_response=evaluation.judge_response,
        failure_reason=evaluation.failure_reason,
        reward=evaluation.reward
    );

    root +>:OwnsRequest:+> request;
    request +>:ReturnsResponse:+> response;
    response +>:ProducesEvaluation:+> evaluation;
    evaluation +>:ProjectsJudgeFields:+> projected;

    sanitizer = JudgeFieldSanitizer();
    root spawn sanitizer;
}

"""Rate-limited follower snapshot traversal with bounded pagination and deduplication."""

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has page_budget: int = 4;
    has item_budget: int = 10;
    has rate_remaining: int = 10;
    has rate_reset_after: int = 30;
    has cancelled: bool = False;
    has baseline_count: int = 0;
    has observed_count: int = 0;
}

node Page {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cursor: str = "";
    has item_count: int = 1;
}

node Follower {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has user_id: str = "";
    has display_name: str = "";
}

edge HasSnapshot { }
edge ContainsPage { }
edge IncludesFollower { }
edge FollowerPage { }

walker FollowerCollector {
    has max_pages: int = 0;
    has max_items: int = 0;
    has rate_remaining: int = 0;
    has rate_reset_after: int = 0;
    has pages_read: int = 0;
    has items_read: int = 0;
    has unique_users: int = 0;
    has cancelled: bool = False;
    has complete: bool = False;
    has reason: str = "";
    has visited_cursors: dict[str, bool] = {};
    has seen_users: dict[str, bool] = {};

    can start with Root entry {
        visit [->:HasSnapshot:->] else {
            self.reason = "no snapshot";
            disengage;
        }
    }

    can begin with Snapshot entry {
        self.max_pages = here.page_budget;
        self.max_items = here.item_budget;
        self.rate_remaining = here.rate_remaining;
        self.rate_reset_after = here.rate_reset_after;
        self.cancelled = here.cancelled;

        if self.cancelled {
            self.reason = "cancelled before retrieval";
            disengage;
        }

        visit [->:ContainsPage:->] else {
            self.reason = "empty snapshot";
            self.complete = True;
            disengage;
        }
    }

    can read_page with Page entry {
        if self.cancelled {
            self.reason = "cancelled";
            disengage;
        }

        if self.pages_read >= self.max_pages {
            self.reason = "page budget exceeded";
            disengage;
        }

        if here.cursor in self.visited_cursors {
            self.reason = "duplicate cursor detected";
            disengage;
        }

        if self.rate_remaining <= 0 {
            self.reason = f"rate limited; reset in {self.rate_reset_after} ticks";
            disengage;
        }

        if self.items_read + here.item_count > self.max_items {
            self.reason = "item budget exceeded";
            disengage;
        }

        self.visited_cursors[here.cursor] = True;
        self.pages_read = self.pages_read + 1;
        self.items_read = self.items_read + here.item_count;
        self.rate_remaining = self.rate_remaining - 1;

        print(f"page {here.cursor}: {self.pages_read} pages, "
              f"{self.items_read} items");

        visit [->:IncludesFollower:->] else {
            self.reason = "snapshot complete";
            self.complete = True;
            disengage;
        }
    }

    can record_follower with Follower entry {
        if here.user_id in self.seen_users {
            print(f"duplicate follower ignored: {here.user_id}");
        } else {
            self.seen_users[here.user_id] = True;
            self.unique_users = self.unique_users + 1;
            print(f"follower accepted: {here.display_name}");
        }

        visit [->:FollowerPage:->] else {
            self.reason = "snapshot complete";
            self.complete = True;
            disengage;
        }
    }

    can report with Root exit {
        print(f"retrieved {self.unique_users} unique followers across "
              f"{self.pages_read} pages; {self.reason}");
    }
}

with entry {
    snapshot = Snapshot(
        title="Channel follower snapshot",
        page_budget=4,
        item_budget=4,
        rate_remaining=5,
        rate_reset_after=30,
        baseline_count=2
    );

    page1 = Page(cursor="cursor-1");
    page2 = Page(cursor="cursor-2");
    page3 = Page(cursor="cursor-3");
    page4 = Page(cursor="cursor-4");

    alice = Follower(user_id="u1", display_name="Alice");
    bob = Follower(user_id="u2", display_name="Bob");
    alice_again = Follower(user_id="u1", display_name="Alice");
    cara = Follower(user_id="u3", display_name="Cara");

    root +>:HasSnapshot:+> snapshot;
    snapshot +>:ContainsPage:+> page1;
    page1 +>:IncludesFollower:+> alice;
    alice +>:FollowerPage:+> page2;
    page2 +>:IncludesFollower:+> bob;
    bob +>:FollowerPage:+> page3;
    page3 +>:IncludesFollower:+> alice_again;
    alice_again +>:FollowerPage:+> page4;
    page4 +>:IncludesFollower:+> cara;
    cara +>:FollowerPage:+> page2;

    root spawn FollowerCollector();
}

"""Native graph demo for bounded interpreter cleanup after NVARC verification failures."""

node VerificationRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mode: str = "inductive";
    has queue_ms: int = 0;
    has execution_ms: int = 0;
    has timeout_ms: int = 0;
    has timed_out: bool = False;
    has cancelled: bool = False;
    has prediction: str = "";
    has reward: int = 1;
}

node InterpreterProcess {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has alive: bool = True;
    has ignores_terminate: bool = False;
    has terminate_sent: bool = False;
    has kill_sent: bool = False;
    has waited: bool = False;
    has reaped: bool = False;
}

node VerificationOutcome {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has exit_code: int = 0;
    has json_valid: bool = True;
    has board_valid: bool = True;
}

edge Spawned {
    has reason: str = "";
}

edge Produces {
    has stream: str = "";
}

walker CleanupAuditor {
    has steps: int = 0;
    has max_steps: int = 32;
    has reaped_count: int = 0;

    can start with Root entry {
        print("auditing inductive verification processes");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with VerificationRequest entry {
        if self.steps >= self.max_steps {
            print("walk stopped at safety depth limit");
            disengage;
        }
        self.steps += 1;

        if here.timed_out || here.cancelled {
            here.prediction = "None";
            here.reward = 0;
            print(f"{here.title}: no prediction and zero reward");
        } else {
            print(f"{here.title}: queued {here.queue_ms}ms, ran {here.execution_ms}ms");
        }

        visit [->:Spawned:->] else {
            disengage;
        }
    }

    can cleanup with InterpreterProcess entry {
        if self.steps >= self.max_steps {
            print("walk stopped at safety depth limit");
            disengage;
        }
        self.steps += 1;

        if here.alive {
            here.terminate_sent = True;
            if here.ignores_terminate {
                here.kill_sent = True;
                print(f"{here.title}: terminate ignored, escalated to kill");
            } else {
                print(f"{here.title}: terminated cleanly");
            }
            here.alive = False;
        }

        here.waited = True;
        here.reaped = True;
        self.reaped_count += 1;

        visit [->:Produces:->] else {
            disengage;
        }
    }

    can validate with VerificationOutcome entry {
        if here.exit_code != 0 || here.json_valid == False || here.board_valid == False {
            print(f"{here.title}: failed validation");
        } else {
            print(f"{here.title}: valid result");
        }
    }
}

with entry {
    timeout_request = VerificationRequest(
        title="timed-out inductive verify",
        queue_ms=14,
        execution_ms=1000,
        timeout_ms=500,
        timed_out=True
    );
    timeout_process = InterpreterProcess(
        title="timeout interpreter",
        pid=4101,
        ignores_terminate=True
    );
    timeout_result = VerificationOutcome(
        title="timeout result",
        exit_code=1,
        json_valid=False
    );

    cancelled_request = VerificationRequest(
        title="cancelled inductive verify",
        queue_ms=7,
        execution_ms=80,
        timeout_ms=500,
        cancelled=True
    );
    cancelled_process = InterpreterProcess(
        title="cancelled interpreter",
        pid=4102
    );
    cancelled_result = VerificationOutcome(
        title="cancelled result",
        exit_code=1,
        board_valid=False
    );

    success_request = VerificationRequest(
        title="successful inductive verify",
        queue_ms=3,
        execution_ms=42,
        timeout_ms=500,
        prediction="accepted"
    );
    success_process = InterpreterProcess(
        title="successful interpreter",
        pid=4103
    );
    success_result = VerificationOutcome(
        title="successful result"
    );

    root ++> timeout_request;
    root ++> cancelled_request;
    root ++> success_request;

    timeout_request +>:Spawned(reason="timeout"):+> timeout_process;
    timeout_process +>:Produces(stream="stdout"):+> timeout_result;

    cancelled_request +>:Spawned(reason="caller cancellation"):+> cancelled_process;
    cancelled_process +>:Produces(stream="stdout"):+> cancelled_result;

    success_request +>:Spawned(reason="completed"):+> success_process;
    success_process +>:Produces(stream="stdout"):+> success_result;

    root spawn CleanupAuditor();
}

