"""Native graph demo of Windows NAR extraction failing on nested directories."""

node RestoreDirectory {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has is_root: bool = False;
    has dir_fd_ready: bool = False;
}

node RestoreFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has kind: str = "regular";
}

edge Contains {
    has relative_path: str = "";
}

walker NarExtractor {
    has windows_mode: bool = True;
    has directories_seen: int = 0;
    has files_seen: int = 0;
    has aborted: bool = False;

    can start with Root entry {
        print("starting NAR extraction");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can restore_directory with RestoreDirectory entry {
        self.directories_seen += 1;

        if here.is_root {
            print(f"create root directory: {here.path}");
            visit [->:Contains:->] else {
                disengage;
            }
        } else {
            if self.windows_mode {
                if !here.dir_fd_ready {
                    print(f"ERROR: missing Windows directory handle for {here.path}");
                    self.aborted = True;
                    disengage;
                }
            }

            print(f"restore nested directory: {here.path}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can restore_file with RestoreFile entry {
        self.files_seen += 1;
        print(f"restore {here.kind} file: {here.path}");
        visit [->:Contains:->] else {
            disengage;
        }
    }
}

