}

edge HasTool {
    has role: str = "";
}

edge ExecutesTask {
    has phase: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker WorkflowProjection {
    has index_builds: int = 0;
    has seen_task_ids: list[str] = [];

    can start with Root entry {
        self.index_builds += 1;
        print(f"built task execution index {self.index_builds} time");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_todo with Todo entry {
        print(f"todo: {here.title}");
        visit [->:HasTool:->] else {
            disengage;
        }
    }

    can inspect_tool with Tool entry {
        print(f"tool: {here.title} for {here.todo_id}");
        visit [->:ExecutesTask:->] else {
            disengage;
        }
    }

    can inspect_task with Task entry {
        if here.task_id in self.seen_task_ids {
            print(f"cycle detected at task {here.task_id}");
            disengage;
        } else {
            self.seen_task_ids.append(here.task_id);
            print(f"task: {here.title} [{here.state}]");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
