"""Bounded distiller walk for coverage, revisit, conflicts, and compaction."""

node DistillerState {
    has title: str = "distiller";
    has year: int = 0;
    has available: bool = True;
    has status: str = "running";
}

node Obligation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has covered: bool = False;
    has revisit_budget: int = 0;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has claim_key: str = "";
    has relation: str = "support";
    has priority: int = 0;
    has protected: bool = False;
    has compacted: bool = False;
    has cold_pointer: str = "";
}

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_key: str = "";
}

edge Tracks { }
edge Satisfies {
    has confidence: float = 0.0;
}
edge SourceLink { }

walker DistillerCycle {
    has compaction_budget: int = 2;
    has max_steps: int = 12;
    has steps: int = 0;
    has revisits: int = 0;
    has retained: int = 0;
    has stop_reason: str = "success";

    can start with Root entry {
        if self.steps >= self.max_steps {
            self.stop_reason = "budget";
            disengage;
        }
        self.steps += 1;
        visit [-->] else {
            self.stop_reason = "no-progress";
            disengage;
        }
    }

    can inspect with DistillerState entry {
        print(f"cycle state: {here.title}");
        if self.steps >= self.max_steps {
            here.status = "budget";
            self.stop_reason = "budget";
            disengage;
        }
        self.steps += 1;
        visit [->:Tracks:->] else {
            here.status = "no-progress";
            self.stop_reason = "no-progress";
            disengage;
        }
    }

    can inspect with Obligation entry {
        print(f"obligation: {here.title}");
        if self.steps >= self.max_steps {
            self.stop_reason = "budget";
            disengage;
        }
        self.steps += 1;

        if !here.covered {
            if here.revisit_budget > 0 {
                here.revisit_budget -= 1;
                here.covered = True;
                self.revisits += 1;
                print(f"targeted revisit completed for {here.title}");
            } else {
                self.stop_reason = "no-progress";
                print(f"no progress for {here.title}");
                disengage;
            }
        }

        visit [->:Satisfies:->] else {
            self.stop_reason = "no-progress";
            disengage;
        }
    }

    can inspect with Evidence entry {
        if self.steps >= self.max_steps {
            self.stop_reason = "budget";
            disengage;
        }
        self.steps += 1;

        if here.relation == "contradiction" {
            print(f"candidate contradiction: {here.claim_key}");
        }
        if here.relation == "supersession" {
            print(f"supersession accepted: {here.claim_key}");
        }
        if here.relation == "scope-difference" {
            print(f"scoped difference retained: {here.claim_key}");
        }

        if here.protected {
            self.retained += 1;
            print(f"protected evidence retained: {here.title}");
        } else {
            if self.retained < self.compaction_budget && here.priority > 0 {
                self.retained += 1;
                print(f"priority evidence retained: {here.title}");
            } else {
                here.compacted = True;
                here.cold_pointer = f"cold://{here.claim_key}";
                print(f"compacted with source pointer: {here.cold_pointer}");
            }
        }

        visit [->:SourceLink:->] else {
            print(f"source pointer missing for {here.title}");
            disengage;
        }
    }

    can inspect with Source entry {
        print(f"source verified: {here.source_key}");
    }

    can report with Root exit {
        print(f"cycle={self.stop_reason}, revisits={self.revisits}, "
              f"retained={self.retained}, steps={self.steps}");
    }
}

