"""Review filter screening with ordered candidates, fail-closed reads, and cycle guards."""

node ReviewScreen {
    has title: str = "";
    has candidate_total: int = 0;
    has max_candidates: int = 4;
    has filter_cap: int = 12;
}

node Candidate {
    has path: str = "";
    has order: int = 0;
    has readable: bool = True;
    has carries_replacement: bool = False;
    has spawn_ms: int = 0;
    has seen: bool = False;
}

node ConfigFile {
    has path: str = "";
    has readable: bool = True;
    has carries_replacement: bool = False;
    has filter_count: int = 0;
}

edge CandidateLink {
    has order: int = 0;
}

edge NextCandidate {
    has order: int = 0;
}

edge ConfigLink {
    has role: str = "";
}

walker ScreenAuditor {
    has max_candidates: int = 4;
    has filter_cap: int = 12;
    has spawn_timeout_ms: int = 20000;
    has checked: int = 0;
    has retained_filters: int = 0;
    has withheld_filters: int = 0;
    has last_order: int = 0;
    has refused: bool = False;
    has reason: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit with ReviewScreen entry {
        self.max_candidates = here.max_candidates;
        self.filter_cap = here.filter_cap;

        if here.candidate_total > self.max_candidates {
            self.refused = True;
            self.reason = "over-cap";
            print(f"{here.title}: refused before candidate reads ({here.candidate_total})");
            disengage;
        }

        visit [->:CandidateLink:->] else {
            self.refused = True;
            self.reason = "no-candidates";
            disengage;
        }
    }

    can inspect with Candidate entry {
        if here.seen {
            self.refused = True;
            self.reason = "cycle";
            print(f"cycle detected at {here.path}");
            disengage;
        }

        here.seen = True;

        if here.carries_replacement {
            self.refused = True;
            self.reason = "replacement-character";
            disengage;
        }

        if !here.readable {
            self.refused = True;
            self.reason = "unreadable-directory";
            disengage;
        }

        if here.spawn_ms > self.spawn_timeout_ms {
            self.refused = True;
            self.reason = "spawn-timeout";
            disengage;
        }

        if here.order <= self.last_order {
            self.refused = True;
            self.reason = "wrong-read-order";
            disengage;
        }

        self.last_order = here.order;
        self.checked += 1;

        visit [->:ConfigLink:->] else {
            self.refused = True;
            self.reason = "missing-config";
            disengage;
        }

        if self.refused {
            disengage;
        }

        visit [->:NextCandidate:->] else {
            disengage;
        }
    }

    can inspect_config with ConfigFile entry {
        if here.carries_replacement {
            self.refused = True;
            self.reason = "replacement-character";
            disengage;
        }

        if !here.readable {
            self.refused = True;
            self.reason = "unreadable-file";
            disengage;
        }

        if here.filter_count > self.filter_cap {
            self.retained_filters = self.filter_cap;
            self.withheld_filters = here.filter_count - self.filter_cap;
        } else {
            self.retained_filters = here.filter_count;
            self.withheld_filters = 0;
        }
    }

    can report with Root exit {
        if self.refused {
            print(f"screen refused: {self.reason}; checked={self.checked}");
        } else {
            print(f"screen clean: checked={self.checked}, "
                  f"retained={self.retained_filters}, "
                  f"withheld={self.withheld_filters}");
        }
    }
}

