        visit [->:CandidateLink:->] else {
            self.refused = True;
            self.reason = "no-candidates";
            disengage;
        }
    }

    can inspect with Candidate entry {
        if here.seen {
            self.refused = True;
            self.reason = "cycle";
            print(f"cycle detected at {here.path}");
            disengage;
        }

        here.seen = True;

        if here.carries_replacement {
            self.refused = True;
            self.reason = "replacement-character";
            disengage;
        }

        if not here.readable {
            self.refused = True;
            self.reason = "unreadable-directory";
            disengage;
        }

        if here.spawn_ms > self.spawn_timeout_ms {
            self.refused = True;
            self.reason = "spawn-timeout";
            disengage;
        }

        if here.order <= self.last_order {
            self.refused = True;
            self.reason = "wrong-read-order";
            disengage;
        }

        self.last_order = here.order;
        self.checked += 1;

        visit [->:ConfigLink:->] else {
            self.refused = True;
            self.reason = "missing-config";
            disengage;
        }

        if self.refused {
            disengage;
        }

        visit [->:NextCandidate:->] else {
            disengage;
        }
    }

    can inspect_config with ConfigFile entry {
        if here.carries_replacement {
            self.refused = True;
            self.reason = "replacement-character";
            disengage;
        }

        if not here.readable {
            self.refused = True;
            self.reason = "unreadable-file";
            disengage;
        }

        if here.filter_count > self.filter_cap {
            self.retained_filters = self.filter_cap;
            self.withheld_filters = here.filter_count - self.filter_cap;
        } else {
            self.retained_filters = here.filter_count;
            self.withheld_filters = 0;
        }
    }

    can summarize with Root exit {
        if self.refused {
            print(f"screen refused: {self.reason}; checked={self.checked}");
        } else {
            print(f"screen clean: checked={self.checked}, "
                  f"retained={self.retained_filters}, "
                  f"withheld={self.withheld_filters}");
        }
    }
}

