"""Native XML graph audit for malformed roots, unsafe detached text, and cycles."""

node XmlDocument {
    has document_id: str = "";
    has root_count: int = 0;
}

node XmlElement {
    has element_id: str = "";
    has tag: str = "";
    has text: str = "";
    has detached: bool = False;
    has escaped: bool = True;
}

edge RootElement {
    has ordinal: int = 0;
}

edge Contains {
    has ordinal: int = 0;
}

walker DomAuditor {
    has valid: bool = True;
    has malformed_documents: int = 0;
    has unsafe_detached_elements: int = 0;
    has cycle_detected: bool = False;
    has seen_ids: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_document with XmlDocument entry {
        if here.root_count != 1 {
            self.valid = False;
            self.malformed_documents += 1;
        }
        visit [->:RootElement:->] else { disengage; }
    }

    can inspect_element with XmlElement entry {
        if here.element_id in self.seen_ids {
            self.valid = False;
            self.cycle_detected = True;
            skip;
        }

        self.seen_ids.append(here.element_id);

        if here.detached and not here.escaped {
            self.valid = False;
            self.unsafe_detached_elements += 1;
        }

        visit [->:Contains:->] else { disengage; }
    }

    can finish with Root exit {
        report self.valid;
    }
}

