    root spawn DomAuditor();
}

"""Deterministic Sentinel reducer with bounded counterfactual replay."""

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
    has hard_failure: bool = False;
    has unsupported_language: bool = False;
    has invalid_input: bool = False;
}

node Replay {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mode: str = "";
    has changed: bool = False;
}

node Action {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path_kind: str = "";
    has dangerous: bool = False;
}

edge Counterfactual {
    has mode: str = "";
}

edge ActionPath {
    has path_kind: str = "";
}

walker SentinelReducer {
    has max_steps: int = 12;
    has steps: int = 0;
    has replay_count: int = 0;
    has invalid_seen: bool = False;
    has unsupported_seen: bool = False;
    has hard_failure_seen: bool = False;
    has original_danger: bool = False;
    has attenuated_danger: bool = False;
    has causal_change: bool = False;
    has limit_hit: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can reduce with Evidence entry {
        if self.steps >= self.max_steps {
            self.limit_hit = True;
            disengage;
        }

        self.steps += 1;

        if here.invalid_input {
            self.invalid_seen = True;
        }

        if here.unsupported_language {
            self.unsupported_seen = True;
        }

        if here.hard_failure {
            self.hard_failure_seen = True;
        }

        visit [-->] else {
            disengage;
        }
    }

    can replay with Replay entry {
        self.replay_count += 1;
        visit [->:ActionPath:->] else {
            disengage;
        }
    }

    can compare with Action entry {
        if here.path_kind == "original" && here.dangerous {
            self.original_danger = True;
        }

        if here.path_kind == "attenuated" && here.dangerous {
            self.attenuated_danger = True;
        }

        if self.original_danger && !self.attenuated_danger {
            self.causal_change = True;
        }
    }

    can report with Root exit {
        verdict = "Clean";

        if self.invalid_seen {
            verdict = "InvalidInput";
        } else {
            if self.unsupported_seen {
                verdict = "UnsupportedLanguage";
            } else {
                if self.hard_failure_seen || self.original_danger {
                    verdict = "Injection";
                } else {
                    if self.causal_change || self.limit_hit {
                        verdict = "Suspicious";
                    }
                }
            }
        }

        print(f"verdict={verdict}");
        print(f"evidence_steps={self.steps}");
        print(f"counterfactual_variants={self.replay_count}");
        print(f"original_danger={self.original_danger}");
        print(f"attenuated_danger={self.attenuated_danger}");
        print(f"causal_change={self.causal_change}");
    }
}

