    has opacity_changed: bool = False;
}

node Drawable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
    has dirty: bool = False;
    has vertex_changed: bool = False;
    has recompute_count: int = 0;
}

edge Contains { }
edge Affects {
    has reason: str = "";
}
edge Invalidates {
    has reason: str = "";
}
edge DependsOn {
    has endpoint: str = "";
}

walker DirtyAuditor {
    has invalidated_count: int = 0;
    has recomputed_count: int = 0;
    has cycle_hits: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_model with Model entry {
        if here.visited {
            self.cycle_hits += 1;
        } else {
            here.visited = True;
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_parameter with Parameter entry {
        if here.visited {
            self.cycle_hits += 1;
        } else {
            here.visited = True;
            if here.changed {
                self.invalidated_count += 1;
            }
            visit [->:Affects:->] else {
                disengage;
            }
        }
    }

    can inspect_part with Part entry {
        if here.visited {
            self.cycle_hits += 1;
        } else {
            here.visited = True;
            if here.opacity_changed {
                self.invalidated_count += 1;
            }
            visit [->:Invalidates:->] else {
                disengage;
            }
        }
