            here.visited = True;
            if here.dirty {
                here.vertex_changed = True;
                here.recompute_count += 1;
                self.recomputed_count += 1;
            } else {
                here.vertex_changed = False;
            }
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
