"""Canonical content identity remains separate from occurrence witness metadata."""

node CanonicalContent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has canonical_key: str = "";
    has physicality_id: str = "";
}

node OccurrenceWitness {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has provider: str = "";
    has byte_offset: int = 0;
    has parser_kind: str = "";
    has depth: int = 0;
}

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_name: str = "";
}

edge Component { }
edge Provides { }
edge WitnessOf { }

walker CanonicalDecomposer {
    has seen_keys: list[str] = [];

    can inspect with CanonicalContent entry {
        if here.canonical_key in self.seen_keys {
            print(f"cycle detected at {here.canonical_key}");
            disengage;
        } else {
            self.seen_keys.append(here.canonical_key);
            print(f"canonical: {here.canonical_key} -> {here.physicality_id}");
            visit [->:Component:->] else {
                disengage;
            }
        }
    }
}

walker WitnessAuditor {
    can inspect_source with Source entry {
        print(f"source: {here.source_name}");
        visit [->:Provides:->] else {
            disengage;
        }
    }

    can inspect_witness with OccurrenceWitness entry {
        print(f"witness: {here.provider} offset={here.byte_offset} "
              f"depth={here.depth} kind={here.parser_kind}");
        visit [->:WitnessOf:->] else {
            disengage;
        }
    }

    can confirm_canonical with CanonicalContent entry {
        print(f"resolves to canonical {here.canonical_key}");
        disengage;
    }
}

