    root spawn DependencyAuditor();
}

"""XML DOM audit: detect multiple document roots and cycles in a typed tree."""

node XmlDocument {
    has label: str = "";
}

node XmlElement {
    has label: str = "";
    has seen: bool = False;
}

node XmlText {
    has label: str = "";
}

edge RootChild { }
edge Contains { }

walker RootScanner {
    has root_count: int = 0;
    has multiple_roots: bool = False;

    can start with Root entry {
        visit [->:RootChild:->] else {
            disengage;
        }
    }

    can count_root with XmlElement entry {
        self.root_count += 1;
        if self.root_count > 1 {
            self.multiple_roots = True;
        }
    }

    can report with Root exit {
        verdict = "REJECT" if self.multiple_roots else "ACCEPT";
        print(f"Document audit: {verdict}; top-level elements={self.root_count}");
    }
}

walker TreeAuditor {
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:RootChild:->] else {
            disengage;
        }
    }

    can inspect with XmlElement entry {
        if here.seen {
            self.cycle_found = True;
            disengage;
        } else {
            here.seen = True;
            print(f"Element: {here.label}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect_text with XmlText entry {
        print(f"Text: {here.label}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can report with Root exit {
        result = "cycle detected" if self.cycle_found else "tree is acyclic";
        print(f"Tree audit: {result}");
    }
}

