}

"""Runtime spawn interception: every kernel event reaches the host classifier."""

node EvalKernel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has language: str = "";
}

node SpawnAttempt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has argv: str = "";
    has source_visible: bool = True;
    has judged: bool = False;
    has approved: bool = False;
}

edge Emits {
    has channel: str = "";
}

walker RuntimeInterceptor {
    has remaining_hops: int = 64;
    has inspected: int = 0;
    has blocked: int = 0;
    has allowed: int = 0;

    can start with Root entry {
        if self.remaining_hops <= 0 {
            disengage;
        }
        self.remaining_hops = self.remaining_hops - 1;
        visit [-->] else {
            disengage;
        }
    }

    can enter_kernel with EvalKernel entry {
        if self.remaining_hops <= 0 {
            disengage;
        }
        self.remaining_hops = self.remaining_hops - 1;
        visit [->:Emits:->] else {
            disengage;
        }
    }

    can intercept with SpawnAttempt entry {
        if self.remaining_hops <= 0 {
            disengage;
        }
        self.remaining_hops = self.remaining_hops - 1;
        self.inspected = self.inspected + 1;

        # The runtime callback uses real argv and ignores source visibility.
        here.judged = True;
        if here.argv == "rm -rf /" {
            here.approved = False;
            self.blocked = self.blocked + 1;
        } else {
            here.approved = True;
            self.allowed = self.allowed + 1;
        }
    }
}

with entry {
    py_kernel = EvalKernel(
