"""Model-agnostic GPTQ demo using typed layer dependencies and cached outputs."""

node Model {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Layer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has quantized: bool = False;
    has execution_count: int = 0;
    has cached_output: str = "";
}

node Cache {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has payload: str = "";
}

edge Contains {
    has order: int = 0;
}

edge Next {
    has order: int = 0;
}

edge CachedAs {
    has order: int = 0;
}

walker ProgressiveQuantizer {
    has seen: list[str] = [];
    has processed: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_model with Model entry {
        print(f"model-agnostic traversal: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can quantize_layer with Layer entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}; stopping safely");
            disengage;
        }

        self.seen.append(here.title);
        print(f"collect Hessian and quantize {here.title}");

        here.quantized = True;
        here.execution_count = here.execution_count + 2;
        here.cached_output = f"post-quantized output of {here.title}";

        cache = Cache(
            title=f"CacheWrapper({here.title})",
            year=here.year,
            payload=here.cached_output
        );
        here +>:CachedAs(order=here.year):+> cache;

        self.processed = self.processed + 1;
        visit [->:Next:->] else {
            disengage;
        }
    }
}

walker CacheReplay {
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_model with Model entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can replay_layer with Layer entry {
        if here.title in self.seen {
            print(f"replay cycle detected at {here.title}; stopping safely");
            disengage;
        }

        self.seen.append(here.title);

        if here.quantized {
            print(f"{here.title} returns cached result: {here.cached_output}");
        } else {
            print(f"{here.title} has no cached result");
        }

        visit [->:Next:->] else {
            disengage;
        }
    }
}

with entry {
    model = Model(title="Transformer", year=0);

    attention = Layer(title="Attention", year=1);
    mlp = Layer(title="MLP", year=2);
    output = Layer(title="OutputProjection", year=3);

    root --> model;
    model +>:Contains(order=0):+> attention;
    attention +>:Next(order=1):+> mlp;
    mlp +>:Next(order=2):+> output;
    output +>:Next(order=3):+> attention;

    root spawn ProgressiveQuantizer();
    root spawn CacheReplay();
}

