"""Interprocedural call summaries with bounded cycle detection and invalidation."""

node ContractFunction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has function_key: str = "";
    has context: str = "";
}

node SummaryRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has summary_key: str = "";
    has reads: str = "";
    has writes: str = "";
    has taint_sources: str = "";
    has taint_sinks: str = "";
    has external_calls: str = "";
    has authorization_checks: str = "";
    has reverts: str = "";
    has value_flow: str = "";
    has return_dependencies: str = "";
    has valid: bool = True;
}

edge StartsAt { }
edge Invalidates { }
edge Calls {
    has context: str = "";
    has argument_mode: str = "";
}
edge Summarizes {
    has version: int = 1;
}
edge DependsOn {
    has reason: str = "";
}

walker InterproceduralAnalyzer {
    has seen: list[str] = [];

    can begin with Root entry {
        print("Starting context-sensitive interprocedural analysis");
        visit [->:StartsAt:->] else {
            disengage;
        }
    }

    can analyze with ContractFunction entry {
        if here.function_key in self.seen {
            print(f"cycle detected at {here.function_key}; stopping this path");
            disengage;
        } else {
            self.seen.append(here.function_key);
            print(f"analyzing {here.function_key} in context {here.context}");
            visit [->:Calls:->] else {
                disengage;
            }
        }
    }
}

walker SummaryInvalidator {
    has seen: list[str] = [];

    can begin with Root entry {
        print("Invalidating dependent summaries");
        visit [->:Invalidates:->] else {
            disengage;
        }
    }

    can invalidate with SummaryRecord entry {
        if here.summary_key in self.seen {
            print(f"dependency cycle detected at {here.summary_key}");
            disengage;
        } else {
            self.seen.append(here.summary_key);
            here.valid = False;
            print(f"invalidated summary {here.summary_key}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
