"""Security audit graph with typed relationships, actor checks, and cycle-safe traversal."""

node Principal {
    has title: str = "";
    has role: str = "viewer";
    has verified: bool = False;
}

node Mission {
    has title: str = "";
    has status: str = "inactive";
    has available: bool = True;
}

node Command {
    has title: str = "";
    has requires_actor: bool = True;
    has admin_only: bool = False;
}

edge Controls {
    has scope: str = "";
}

edge Dispatches {
    has route: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker SecurityAuditor {
    has depth: int = 0;
    has max_depth: int = 3;
    has findings: int = 0;

    can start with Root entry {
        print("Starting security audit");
        visit [-->];
    }

    can inspect with Principal entry {
        verified_label = "verified" if here.verified else "UNVERIFIED";
        print(f"Principal: {here.title} ({verified_label})");
        visit [->:Controls:->] else {
            disengage;
        }
    }

    can inspect with Mission entry {
        print(f"Mission: {here.title} [{here.status}]");
        visit [->:Dispatches:->] else {
            disengage;
        }
    }

    can inspect with Command entry {
        if self.depth >= self.max_depth {
            print(f"Traversal limit reached near {here.title}; possible dependency cycle");
            disengage;
        } else {
            mode = "TRUSTED BYPASS" if here.requires_actor == False else "ACTOR CHECKED";
            print(f"Command: {here.title} ({mode})");
            if here.requires_actor == False {
                self.findings += 1;
                print("  warning: command has no actor requirement");
            }
            self.depth += 1;
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

