walker CoordinateAudit {
    has delta_phi: float = 0.0;
    has plane_offset: float = 0.0;
    has periodic: bool = False;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:ContainsPartition:->] else { disengage; }
    }

    can inspect_partition with XGCPartition entry {
        self.delta_phi = here.delta_phi;
        self.plane_offset = here.plane_offset;
        self.periodic = here.periodic;
        print(f"partition total={here.total_planes} owned={here.owned_planes} "
              f"start={here.plane_start_id} offset={here.plane_offset}");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:OwnsPlane:->] else { disengage; }
    }

    can inspect_plane with ExtrudePlane entry {
        phi = (here.global_index + self.plane_offset) * self.delta_phi;
        print(f"plane local={here.local_index} global={here.global_index} phi={phi}");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:HasPoint:->] else { disengage; }
    }

    can inspect_point with ExtrudePoint entry {
        phi = (here.global_plane + self.plane_offset) * self.delta_phi;
        print(f"point {here.point_id} role={here.role} phi={phi}");
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:IncidentCell:->] else { disengage; }
    }

    can inspect_cell with ExtrudeCell entry {
        phi = (here.global_plane + self.plane_offset) * self.delta_phi;
        print(f"wedge {here.cell_id} plane={here.cell_plane} phi={phi}");
        visit [-->] else { disengage; }
    }
}

walker ReverseConnectivityAudit {
    has periodic: bool = False;
    has depth: int = 0;
    has max_depth: int = 64;

    can start with Root entry {
        if self.depth >= self.max_depth {
            disengage;
        }
