        visit [->:HasPoint:->] else { disengage; }
    }

    can inspect_point with ExtrudePoint entry {
        print(f"{here.role} point expects {here.expected_incident} incident cells");
        if self.periodic {
            print("periodic endpoint wrapping is enabled");
        } else {
            print("nonperiodic endpoint wrapping is disabled");
        }
        if self.depth >= self.max_depth {
            disengage;
        }
        self.depth += 1;
        visit [->:IncidentCell:->] else { disengage; }
    }

    can inspect_cell with ExtrudeCell entry {
        print(f"incident cell {here.cell_id} from cell plane {here.cell_plane}");
        visit [-->] else { disengage; }
    }
}

