"""Trace the expensive upstream expansion behind a Cube view-mart query."""

node QuerySurface {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has query_count: int = 0;
    has average_mib: int = 0;
}

node DataModel {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scan_mib: int = 0;
    has materialized: bool = False;
}

edge Uses {
    has purpose: str = "cube query source";
}

edge DependsOn {
    has purpose: str = "upstream dependency";
}

walker ExpansionAuditor {
    has visited_models: list[str] = [];
    has expanded_mib: int = 0;
    has scanned_models: int = 0;
    has surface_title: str = "";
    has reported_average_mib: int = 0;

    can start with Root entry {
        print("Tracing Cube view-mart expansion");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_surface with QuerySurface entry {
        self.surface_title = here.title;
        self.reported_average_mib = here.average_mib;
        print(f"surface={here.title}, average query={here.average_mib} MiB");
        visit [->:Uses:->] else {
            disengage;
        }
    }

    can expand_model with DataModel entry {
        if here.title in self.visited_models {
            print(f"cycle or repeated dependency ignored: {here.title}");
            disengage;
        }

        self.visited_models.append(here.title);
        self.scanned_models += 1;
        self.expanded_mib += here.scan_mib;
        print(f"reached {here.title}: {here.scan_mib} MiB");

        if here.materialized {
            print(f"materialization boundary at {here.title}");
        } else {
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(
            f"surface={self.surface_title}, "
            f"reported={self.reported_average_mib} MiB, "
            f"expanded={self.expanded_mib} MiB, "
            f"models={self.scanned_models}"
        );
    }
}

