"""Assignment-integrity oracle demo with bounded dependency-cycle auditing."""

node AuditRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Issue(AuditRecord) {
    has number: int = 0;
    has state: str = "";
    has disposition: str = "";
    has superseded: bool = False;
    has unresolved: bool = False;
}

node PullRequest(AuditRecord) {
    has number: int = 0;
    has state: str = "";
    has draft: bool = False;
    has merged: bool = False;
    has repository: str = "";
    has base_sha: str = "";
    has head_sha: str = "";
    has exact_candidate: bool = False;
}

node Assignment(AuditRecord) {
    has owner: str = "";
    has branch: str = "";
    has mutable_scope: str = "";
    has prohibited_scope: str = "";
    has reservation_ok: bool = False;
}

node Proof(AuditRecord) {
    has accepted: bool = False;
    has coverage: str = "";
    has findings: str = "";
}

edge Implements {
    has contract: str = "";
}

edge Claims {
    has reservation: str = "";
}

edge VerifiedBy {
    has basis: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker IntegrityOracle {
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        print("Starting read-only assignment-integrity audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Issue entry {
        print(f"Issue #{here.number}: {here.title}");

        if here.superseded {
            print("  superseded: diagnostic retained");
        }
        if here.unresolved {
            print("  unresolved: BLOCKED");
        }

        if self.depth >= self.max_depth {
            print("  depth/cycle guard stopped traversal");
            disengage;
        }

        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:Implements:->] else {
            disengage;
        }
    }

    can inspect with PullRequest entry {
        base_status = "BASE-MISMATCH";
        if here.base_sha == "base-818" {
            base_status = "BASE-MATCH";
        }

        candidate_status = "CANDIDATE-MISMATCH";
        if here.exact_candidate {
            candidate_status = "CANDIDATE-MATCH";
        }

        print(f"  PR #{here.number}: {base_status}, {candidate_status}");

        if here.draft {
            print("  readiness: DRAFT");
        }
        if here.merged {
            print("  readiness: MERGED");
        }

        if self.depth >= self.max_depth {
            print("  depth/cycle guard stopped traversal");
            disengage;
        }

        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:Claims:->] else {
            disengage;
        }
    }

    can inspect with Assignment entry {
        scope_status = "SCOPE-BLOCKED";
        if here.reservation_ok {
            scope_status = "SCOPE-READY";
        }

        print(f"  owner={here.owner}, branch={here.branch}, {scope_status}");
        print(f"  mutable={here.mutable_scope}");
        print(f"  prohibited={here.prohibited_scope}");

        if self.depth >= self.max_depth {
            print("  depth/cycle guard stopped traversal");
            disengage;
        }

        next_depth = self.depth + 1;
        self.depth = next_depth;
        visit [->:VerifiedBy:->] else {
            disengage;
        }
    }

    can inspect with Proof entry {
        proof_status = "REJECTED";
        if here.accepted {
            proof_status = "ACCEPTED";
        }

        print(f"  proof={proof_status}, coverage={here.coverage}");
        print(f"  findings={here.findings}");
    }
