"""General council stance audit with explicit disagreement and concession handling."""

node GeneralCouncil {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has label: str = "";
}

node Position {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has topic: str = "";
    has statement: str = "";
    has leading_stance: str = "MAINTAIN";
    has concession_target: str = "";
    has concession_valid: bool = False;

    def parsed_stance() -> str {
        if leading_stance == "SUPPORT" {
            return "SUPPORT";
        }
        if leading_stance == "OPPOSE" {
            return "OPPOSE";
        }
        if leading_stance == "MAINTAIN" {
            if statement == "I do not concede" {
                return "MAINTAIN";
            }
            return "MAINTAIN";
        }
        if leading_stance == "CONCEDE" {
            if concession_valid {
                return "CONCEDE";
            }
            return "MAINTAIN";
        }
        return "UNRELATED";
    }
}

edge Convenes { }
edge Presents {
    has order: int = 0;
}

walker StanceAuditor {
    has seen_topic: str = "";
    has prior_effective: str = "";
    has consensus_count: int = 0;
    has disagreement_count: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can inspect_council with GeneralCouncil entry {
        print(f"Auditing {here.label}");
        visit [-->];
    }

    can inspect_position with Position entry {
        stance = here.parsed_stance();
        effective = stance;

        if stance == "CONCEDE" {
            effective = here.concession_target;
        }

        if self.seen_topic == "" {
            self.seen_topic = here.topic;
            self.prior_effective = effective;
            print(f"{here.title}: {effective}");
        } else {
            if here.topic != self.seen_topic {
                print(f"{here.title}: unrelated position, not consensus");
            } else {
                if effective == self.prior_effective {
                    if effective != "MAINTAIN" || here.concession_valid {
                        self.consensus_count += 1;
                        print(f"{here.title}: consensus with the prior position");
                    } else {
                        print(f"{here.title}: maintained disagreement");
                    }
                } else {
                    self.disagreement_count += 1;
                    print(f"{here.title}: disagreement ({self.prior_effective} vs {effective})");
                }
                self.prior_effective = effective;
            }
        }
    }
}

