"""A mutable component tree with typed links, unknown-component fallback, and cycle detection."""

node ComponentTree {
    has tree_id: str = "";
    has surface_id: str = "";
    has invalidated: bool = False;
}

node Component {
    has component_id: str = "";
    has component: str = "";
    has known: bool = True;
    has invalidated: bool = False;
}

node UnknownComponent(Component) {
    has raw_payload: str = "";
}

edge TreeRoot { }
edge RootComponent {
    has slot_name: str = "";
    has position: int = 0;
}
edge ChildSlot {
    has slot_name: str = "";
    has position: int = 0;
}

walker ComponentInspector {
    has visited_ids: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        visit [->:TreeRoot:->] else {
            disengage;
        }
    }

    can inspect_tree with ComponentTree entry {
        visit [->:RootComponent:->] else {
            disengage;
        }
    }

    can inspect_component with Component entry {
        if here.component_id in self.visited_ids {
            here.invalidated = True;
            self.cycle_found = True;
            print(f"cycle detected at component {here.component_id}");
            disengage;
        } else {
            self.visited_ids = self.visited_ids + [here.component_id];
            kind = "known" if here.known else "unknown fallback";
            print(f"visit {here.component_id}: {here.component} ({kind})");
            visit [->:ChildSlot:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"inspected {len(self.visited_ids)} component IDs");
        print(f"cycle found: {self.cycle_found}");
    }
}

