"""Native FileHub smart-paste demo with typed folder traversal and cycle guards."""

node UploadEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has relative_path: str = "";
}

node ClipboardBatch(UploadEntry) {
    has source: str = "";
    has cancelled: bool = False;
}

node Folder(UploadEntry) {
    has child_count: int = 0;
}

node File(UploadEntry) {
    has size_bytes: int = 0;
}

edge Contains {
    has relation: str = "contains";
}

walker ClipboardImporter {
    has seen_paths: list[str] = [];
    has scanned_entries: int = 0;
    has imported_files: int = 0;
    has max_entries: int = 1000;

    can start with Root entry {
        print("Starting Windows Explorer folder paste");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_batch with ClipboardBatch entry {
        if here.cancelled {
            print("Paste cancelled before traversal");
            disengage;
        }
        print(f"Clipboard source: {here.source}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_folder with Folder entry {
        if self.scanned_entries >= self.max_entries {
            print("Traversal limit reached");
            disengage;
        }
        if here.relative_path in self.seen_paths {
            print(f"Cycle or duplicate path skipped: {here.relative_path}");
            disengage;
        }

        self.seen_paths.append(here.relative_path);
        self.scanned_entries = self.scanned_entries + 1;
        print(f"Folder retained: {here.relative_path}");

        visit [->:Contains:->] else {
            print(f"Empty folder retained: {here.relative_path}");
            disengage;
        }
    }

    can import_file with File entry {
        if self.scanned_entries >= self.max_entries {
            print("Traversal limit reached");
            disengage;
        }
        if here.relative_path in self.seen_paths {
            print(f"Cycle or duplicate path skipped: {here.relative_path}");
            disengage;
        }

        self.seen_paths.append(here.relative_path);
        self.scanned_entries = self.scanned_entries + 1;
        self.imported_files = self.imported_files + 1;
        status = "ready" if here.available else "unavailable";
        print(f"File {status}: {here.relative_path} ({here.size_bytes} bytes)");
    }
}

