"""Tenancy, Journey ownership, and a guarded descendant re-parenting walk."""

node Tenant {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
}

node Holon {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tenant_scope: str = "";
    has domain_version: int = 1;
}

node Journey {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner: str = "";
    has config_version: int = 1;
}

edge Contains {
    has relation: str = "domain";
}

edge ParentOf {
    has reason: str = "hierarchy";
}

edge OwnsJourney {
    has role: str = "owner";
}

walker ReparentAuditor {
    has superuser: bool = False;
    has destination_tenant: str = "";
    has seen: list[str] = [];
    has moved: int = 0;

    can start with Root entry {
        if self.superuser == False {
            print("re-parent denied: superuser approval is required");
            disengage;
        }
        print(f"approved re-parent to {self.destination_tenant}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_tenant with Tenant entry {
        print(f"tenant scope: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can reparent_holon with Holon entry {
        if here.title in self.seen {
            print(f"cycle guard stopped at {here.title}");
            disengage;
        }

        self.seen.append(here.title);
        here.tenant_scope = self.destination_tenant;
        here.domain_version = here.domain_version + 1;
        self.moved = self.moved + 1;

        print(
            f"re-parented {here.title} to {here.tenant_scope}, "
            f"domain_version={here.domain_version}"
        );

        visit [-->] else {
            disengage;
        }
    }

    can report_journey with Journey entry {
        owner_label = "platform" if here.owner == "" else here.owner;
        print(
            f"Journey {here.title}: owner={owner_label}, "
            f"config_version={here.config_version}"
        );
    }
}

with entry {
    tenant_a = Tenant(title="Tenant-A", slug="tenant-a");
    tenant_b = Tenant(title="Tenant-B", slug="tenant-b");

    parent = Holon(
        title="Account Root",
        tenant_scope="Tenant-A",
        domain_version=1
    );
    child = Holon(
        title="Account Child",
        tenant_scope="Tenant-A",
        domain_version=1
    );
    journey = Journey(
        title="Onboarding Journey",
        owner="Account Root",
        config_version=3
    );

    root ++> tenant_a;
    root ++> tenant_b;
    tenant_a +>:Contains(relation="tenant hierarchy"):+> parent;
    parent +>:ParentOf(reason="descendant"):+> child;
    parent +>:OwnsJourney(role="journey owner"):+> journey;

    root spawn ReparentAuditor(
        superuser=True,
        destination_tenant="Tenant-B"
    );
    root spawn ReparentAuditor(
        superuser=False,
        destination_tenant="Tenant-C"
    );
}

