walker ConfigResolver {
    has expected_version: int = 0;
    has visited_count: int = 0;
    has invalidation_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Starting Janus configuration resolution");
        visit [-->] else {
            disengage;
        }
    }

    can resolve with Journey entry {
        if here.visited {
            self.cycle_found = True;
            print(f"Cycle detected at {here.title}");
            disengage;
        } else {
            here.visited = True;
            self.visited_count += 1;
            self.expected_version = here.config_version;
            print(f"Journey boundary: version {self.expected_version}");
            visit [->:OwnsExperience:->] else {
                disengage;
            }
        }
    }

    can resolve with JanusExperience entry {
        if here.visited {
            self.cycle_found = True;
            print(f"Cycle detected at {here.title}");
            disengage;
        } else {
            here.visited = True;
            self.visited_count += 1;
            if here.config_present {
                if here.config_version != self.expected_version {
                    here.invalidated = True;
                    self.invalidation_count += 1;
                    print(f"Invalidated {here.title}: version {here.config_version}");
                } else {
                    print(f"Resolved {here.title}: {here.config}");
                }
                visit [->:UsesPlay:->] else {
                    disengage;
                }
            } else {
                here.invalidated = True;
                print(f"Missing configuration row for {here.title}");
                disengage;
            }
        }
    }

    can resolve with JanusPlay entry {
        if here.visited {
            self.cycle_found = True;
            print(f"Cycle detected at {here.title}");
            disengage;
        } else {
            here.visited = True;
            self.visited_count += 1;
            if here.config_present {
                if here.config_version != self.expected_version {
                    here.invalidated = True;
                    self.invalidation_count += 1;
