walker ReparentAuditor {
    has superuser: bool = False;
    has destination_tenant: str = "";
    has moved: int = 0;
    has denied: int = 0;

    can start with Root entry {
        if self.superuser {
            print(f"approved re-parent to {self.destination_tenant}");
        } else {
            print("re-parent denied: superuser approval is required");
        }
        visit [-->] else {
            disengage;
        }
    }

    can inspect_tenant with Tenant entry {
        print(f"tenant scope: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can reparent_holon with Holon entry {
        if self.superuser {
            here.tenant_scope = self.destination_tenant;
            here.domain_version = here.domain_version + 1;
            self.moved = self.moved + 1;
            print(
                f"re-parented {here.title} to {here.tenant_scope}, "
                f"domain_version={here.domain_version}"
            );
        } else {
            self.denied = self.denied + 1;
            print(f"re-parent skipped for {here.title}");
        }
        visit [-->] else {
            disengage;
        }
    }

    can report_journey with Journey entry {
        owner_label = "platform" if here.owner == "" else here.owner;
        print(
            f"Journey {here.title}: owner={owner_label}, "
            f"config_version={here.config_version}"
        );
        visit [-->] else {
            disengage;
        }
    }
}

