"""Full-auto state updates with bounded lock contention and cycle-safe auditing."""

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has process_id: str = "";
    has requested_delta: int = 0;
    has operation_status: str = "";
    has lock_option_status: str = "";
    has storage_status: str = "";
}

node StateRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has counter_before: int = 0;
    has counter_after: int = 0;
    has successful_updates: int = 0;
    has update_status: str = "";
}

node Lock {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner_id: str = "";
    has held: bool = False;
    has max_wait_ms: int = 0;
    has acquisition_status: str = "";
}

edge Contains {
    has label: str = "";
}

edge Updates {
    has delta: int = 0;
}

edge ProtectedBy {
    has mode: str = "";
}

edge HeldBy {
    has owner: str = "";
}

walker TransactionAudit {
    has seen: list[str] = [];
    has visited_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Auditing serialized full-auto state transaction");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_process with Process entry {
        if here.title in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at {here.process_id}; audit stopped");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count = self.visited_count + 1;
            print(f"{here.process_id}: {here.operation_status}; "
                  f"lock={here.lock_option_status}; storage={here.storage_status}");
            visit [->:Updates:->] else {
                disengage;
            }
        }
    }

    can inspect_state with StateRecord entry {
        if here.title in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}; audit stopped");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count = self.visited_count + 1;
            if here.counter_after == here.counter_before + here.successful_updates {
                print(f"{here.title}: both updates retained; "
                      f"counter={here.counter_after}; status={here.update_status}");
            } else {
                print(f"{here.title}: counter invariant failed");
            }
            visit [->:ProtectedBy:->] else {
                disengage;
            }
        }
    }

    can inspect_lock with Lock entry {
        if here.title in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at {here.title}; audit stopped");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count = self.visited_count + 1;
            if here.held {
                print(f"{here.title}: live lock held by {here.owner_id}; "
                      f"bounded wait={here.max_wait_ms} ms");
            } else {
                print(f"{here.title}: lock released; {here.acquisition_status}");
            }
            visit [->:HeldBy:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"audit visited {self.visited_count} records; "
              f"cycle_guard={self.cycle_found}");
    }
}

