"""Native graph ratchet for reachable repo_map workflow consumers."""

node RepoAction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has advertised: bool = True;
}

node WorkflowConsumer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has channel: str = "";
    has reachable: bool = True;
    has bounded_fallback: str = "";
}

edge ActionUse {
    has producer: str = "";
    has scenario: str = "";
    has bounded_fallback: str = "";
}

walker ActionRatchet {
    has advertised_seen: int = 0;
    has consumer_links: int = 0;
    has unwired: int = 0;

    can start with Root entry {
        print("Checking reachable repo_map actions");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with RepoAction entry {
        if here.advertised {
            self.advertised_seen = self.advertised_seen + 1;
            print(f"action: {here.title}");
        }

        visit [->:ActionUse:->] else {
            if here.advertised {
                self.unwired = self.unwired + 1;
                print(f"unwired: {here.title}");
            }
        }
    }

    can verify with WorkflowConsumer entry {
        if here.available && here.reachable {
            self.consumer_links = self.consumer_links + 1;
            print(f"consumer: {here.title} via {here.channel}");
        } else {
            print(f"fallback: {here.bounded_fallback}");
        }
    }

    can finish with Root exit {
        print(f"advertised={self.advertised_seen}, "
            f"runtime_consumers={self.consumer_links}, "
            f"unwired={self.unwired}");
    }
}

