"""Plan-cursor controls propagated through normal and scoring context paths."""

node ContextConfig {
    has title: str = "";
    has enabled: bool = True;
    has lookahead: int = 1;
    has token_budget: int = 4;
}

node ContextPath {
    has title: str = "";
    has path_name: str = "";
    has available: bool = True;
}

node PlanChunk {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has rank: int = 0;
    has tokens: int = 0;

    def canonical_token_count() -> int {
        return self.tokens;
    }
}

edge Configures { }
edge Offers { }
edge Candidate { }

walker PlanCursor {
    has enabled: bool = True;
    has lookahead: int = 1;
    has token_budget: int = 4;
    has control_name: str = "";
    has active_path: str = "";
    has used_tokens: int = 0;
    has selected_chunks: int = 0;
    has total_tokens: int = 0;

    can start with Root entry {
        visit [->:Configures:->] else {
            disengage;
        }
    }

    can load with ContextConfig entry {
        self.enabled = here.enabled;
        self.lookahead = here.lookahead;
        self.token_budget = here.token_budget;
        self.control_name = here.title;
        visit [->:Offers:->] else {
            disengage;
        }
    }

    can extract with ContextPath entry {
        self.active_path = here.path_name;
        self.used_tokens = 0;
        self.selected_chunks = 0;
        print(f"{self.control_name}/{self.active_path}: "
              f"enabled={self.enabled}, lookahead={self.lookahead}, "
              f"budget={self.token_budget}");
        visit [->:Candidate:->] else {
            disengage;
        }
    }

    can consider with PlanChunk entry {
        if self.enabled {
            if here.available {
                if here.rank <= self.lookahead {
                    candidate_total = self.used_tokens
                        + here.canonical_token_count();
                    if candidate_total <= self.token_budget {
                        self.used_tokens = candidate_total;
                        self.selected_chunks += 1;
                        self.total_tokens += here.canonical_token_count();
                        print(f"  selected {here.title} "
                              f"({here.canonical_token_count()} tokens)");
                    }
                }
            }
        }
    }

    can report with Root exit {
        print(f"canonical tokens selected: {self.total_tokens}");
    }
}

with entry {
    default_controls = ContextConfig(title="default", enabled=True);
    explicit_controls = ContextConfig(
        title="explicit",
