    explicit_scoring +>:Candidate:+> third;
    disabled_normal +>:Candidate:+> first;
    disabled_normal +>:Candidate:+> second;
    disabled_normal +>:Candidate:+> third;
    disabled_scoring +>:Candidate:+> first;
    disabled_scoring +>:Candidate:+> second;
    disabled_scoring +>:Candidate:+> third;

    root spawn PlanCursor();
}

"""Installer lifecycle demo with string-safe config normalization and plugin cleanup."""

node HostConfig {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has present: bool = False;
    has original_bytes: str = "";
    has backup_bytes: str = "";
    has normalized_bytes: str = "";
    has plugin_reference: bool = False;
}

node Plugin {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cleanup_authorized: bool = True;
}

node PluginFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has plugin_owned: bool = False;
    has removed: bool = False;
}

edge OwnsPlugin { }
edge OwnsFile { }

walker Installer {
    has cleaned_files: int = 0;
    has configs_seen: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with HostConfig entry {
        self.configs_seen += 1;
        if here.present {
            here.backup_bytes = here.original_bytes;
            here.normalized_bytes = "{\"pattern\":\"comma,}\",\"bracket\":\"comma,]\"}";
            here.plugin_reference = False;
        }
        visit [-->] else {
            disengage;
        }
    }

    can authorize with Plugin entry {
        if here.cleanup_authorized {
            visit [->:OwnsFile:->] else {
                disengage;
            }
        } else {
            disengage;
        }
    }

    can remove with PluginFile entry {
        if here.plugin_owned {
            here.removed = True;
            self.cleaned_files += 1;
        }
    }
}

with entry {
    existing = HostConfig(
        title="host-config",
        present=True,
        original_bytes="{\"pattern\":\"comma,}\",\"bracket\":\"comma,]\",}"
    );
    absent = HostConfig(
        title="missing-host-config",
        present=False
    );

    active_plugin = Plugin(title="swarm-plugin", cleanup_authorized=True);
    orphaned_plugin = Plugin(title="orphaned-plugin", cleanup_authorized=True);

    active_cache = PluginFile(
        title="active-cache",
