    active_plugin +>:OwnsFile:+> active_cache;
    active_plugin +>:OwnsFile:+> active_shared;
    orphaned_plugin +>:OwnsFile:+> orphaned_cache;

    root spawn Installer();
}

"""Recursive policy-object merge audit with typed strategy delegation, provenance, limits, and cycle safety."""

node Entity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node PolicyObject(Entity) {
    has pointer: str = "/";
    has strategy_id: str = "object-v1";
    has source_layer: str = "base";
    has depth: int = 0;
    has plain_fragment: bool = True;
    has explicit_empty: bool = False;
    has valid: bool = True;
    has registry_name: str = "policy-fields";
}

node PolicyField(Entity) {
    has key: str = "";
    has pointer: str = "";
    has strategy_id: str = "scalar-v1";
    has executor_kind: str = "scalar";
    has value_kind: str = "string";
    has source_layer: str = "base";
    has before_digest: str = "";
    has after_digest: str = "";
    has change_category: str = "inherited";
    has present: bool = True;
    has registered: bool = True;
    has invalid: bool = False;
    has undefined_value: bool = False;
    has accessor_detected: bool = False;
    has proxy_detected: bool = False;
    has unsafe_value: bool = False;
    has shared_reference: bool = False;
    has bool_value: bool = False;
    has int_value: int = 0;
    has text_value: str = "";
}

node StrategyRegistry(Entity) {
    has registry_name: str = "policy-fields";
    has object_executor: str = "object-v1";
    has scalar_executor: str = "scalar-v1";
    has collection_executor: str = "unsupported-until-v2";
    has canonical_order: list[str] = [];
    has frozen: bool = True;
}

edge ChildField {
    has key: str = "";
    has strategy_id: str = "";
    has source_layer: str = "";
}

edge TargetsObject { }

edge RegistryOf { }

walker MergeAudit {
    has seen_pointers: list[str] = [];
    has provenance_entries: list[str] = [];
    has diagnostics: list[str] = [];
    has result: list[str] = [];
    has operations: int = 0;
    has max_operations: int = 32;
    has max_depth: int = 4;
    has max_provenance_entries: int = 32;
    has failed: bool = False;
    has status: str = "resolved";

    can start with Root entry {
        visit [-->];
    }

    can merge_object with PolicyObject entry {
        if self.failed {
            disengage;
        }

        if self.operations >= self.max_operations {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + ["aggregate operation budget exceeded"];
            disengage;
        }

        self.operations += 1;

        if here.depth > self.max_depth {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"depth limit at {here.pointer}"];
            disengage;
        }

        if not here.plain_fragment or not here.valid {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"invalid plain fragment at {here.pointer}"];
            disengage;
        }

        if here.strategy_id != "object-v1" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"object strategy conflict at {here.pointer}"];
            disengage;
        }

        if here.pointer in self.seen_pointers {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"cycle detected at {here.pointer}"];
            disengage;
        }

        self.seen_pointers = self.seen_pointers + [here.pointer];

        if len(self.provenance_entries) >= self.max_provenance_entries {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + ["provenance budget exceeded"];
            disengage;
        }

        object_marker = "empty-explicit" if here.explicit_empty else "fields";
        object_record = f"object|pointer={here.pointer}|source={here.source_layer}|strategy={here.strategy_id}|marker={object_marker}";
        self.provenance_entries = self.provenance_entries + [object_record];

        visit [->:ChildField:->] else {
            skip;
        }
    }

    can merge_field with PolicyField entry {
        if self.failed {
            disengage;
        }

        if self.operations >= self.max_operations {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + ["aggregate operation budget exceeded"];
            disengage;
        }

        self.operations += 1;

        if here.key == "__proto__" or here.key == "prototype" or here.key == "constructor" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"unsafe key rejected at {here.pointer}"];
            disengage;
        }

        if here.accessor_detected or here.proxy_detected or here.unsafe_value or here.shared_reference or here.undefined_value {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"unsafe fragment rejected at {here.pointer}"];
            disengage;
        }

        if not here.registered {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"unknown child key at {here.pointer}"];
            disengage;
        }

        if here.invalid or here.value_kind == "null" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"invalid child value at {here.pointer}"];
            disengage;
        }

        if here.value_kind == "object" and here.executor_kind == "scalar" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"type conflict at {here.pointer}"];
            disengage;
        }

        if here.value_kind == "array" and here.executor_kind == "object" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"type conflict at {here.pointer}"];
            disengage;
        }

        if here.executor_kind == "collection" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"unsupported collection executor at {here.pointer}"];
            disengage;
        }

        if here.executor_kind != "scalar" and here.executor_kind != "object" {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + [f"missing executor at {here.pointer}"];
            disengage;
        }

        if len(self.provenance_entries) >= self.max_provenance_entries {
            self.failed = True;
            self.status = "failed";
            self.diagnostics = self.diagnostics + ["provenance budget exceeded"];
            disengage;
        }

        change = "overridden" if here.change_category == "overridden" else "inherited";
        field_record = f"field|pointer={here.pointer}|source={here.source_layer}|strategy={here.strategy_id}|before={here.before_digest}|after={here.after_digest}|change={change}";
        self.provenance_entries = self.provenance_entries + [field_record];

        print(f"delegated {here.pointer} to {here.strategy_id}; present={here.present}");
        visit [->:TargetsObject:->] else {
            skip;
        }
    }

    can finish with exit {
        if self.failed {
            self.result = self.diagnostics;
            print(f"merge failed after {self.operations} operations");
        } else {
            self.result = self.provenance_entries;
            print(f"merge resolved with {len(self.provenance_entries)} provenance entries");
        }
        report self.result;
    }
}

