"""Native graph demo of bounded variant clustering and deterministic alias merging."""

node Catalog {
    has name: str = "";
    has variant_to_canonical: dict[str, str] = {};
    has aliases: int = 0;
}

node Partition {
    has shard_id: str = "";
    has variant_to_canonical: dict[str, str] = {};
    has aliases: int = 0;
}

node Phrase {
    has text: str = "";
    has doc_freq: int = 0;
    has resolved_to: str = "";
    has is_variant: bool = False;
}

node Concept {
    has phrase: str = "";
    has doc_freq: int = 0;
    has stable_rank: int = 0;
    has is_canonical: bool = True;
}

edge Owns { }
edge Contains { }
edge CandidateOf {
    has similarity: float = 0.0;
}

walker Clusterer {
    has local_map: dict[str, str] = {};
    has merged_map: dict[str, str] = {};
    has current_variant: str = "";
    has selected_canonical: str = "";
    has selected_rank: int = 2147483647;
    has canonical_phrases: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 64;

    can start with Root entry {
        self.hops += 1;
        if self.hops > self.max_hops { disengage; }
        visit [->:Owns:->] else { disengage; }
    }

    can open_catalog with Catalog entry {
        self.hops += 1;
        if self.hops > self.max_hops { disengage; }
        self.merged_map = {};
        visit [->:Owns:->] else { disengage; }
    }

    can open_partition with Partition entry {
        self.hops += 1;
        if self.hops > self.max_hops { disengage; }
        self.local_map = {};
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_phrase with Phrase entry {
        self.hops += 1;
        if self.hops > self.max_hops { disengage; }
        self.current_variant = here.text;
        self.selected_canonical = "";
        self.selected_rank = 2147483647;
        visit [->:CandidateOf:->] else { disengage; }
    }

    can rank_candidate with Concept entry {
        self.hops += 1;
        if self.hops > self.max_hops { disengage; }

        if here.is_canonical {
            if here.phrase not in self.canonical_phrases {
                self.canonical_phrases.append(here.phrase);
            }
        }

        if self.selected_canonical == "" {
            self.selected_canonical = here.phrase;
            self.selected_rank = here.stable_rank;
        } else {
            if here.phrase == self.current_variant {
                self.selected_canonical = here.phrase;
                self.selected_rank = here.stable_rank;
            } else {
                if self.selected_canonical != self.current_variant {
                    if here.stable_rank < self.selected_rank {
                        self.selected_canonical = here.phrase;
                        self.selected_rank = here.stable_rank;
                    } else {
                        if here.stable_rank == self.selected_rank {
                            if here.phrase < self.selected_canonical {
                                self.selected_canonical = here.phrase;
                                self.selected_rank = here.stable_rank;
                            }
                        }
                    }
                }
            }
        }
    }

    can finish_phrase with Phrase exit {
        here.resolved_to = self.selected_canonical;
        here.is_variant = self.selected_canonical != here.text;

        if here.is_variant {
            self.local_map[here.text] = self.selected_canonical;
        }

        print(f"{here.text} -> {here.resolved_to}");
    }

    can finish_partition with Partition exit {
        here.variant_to_canonical = self.local_map;
        here.aliases = len(here.variant_to_canonical);
        assert here.aliases == len(here.variant_to_canonical);

        for key in here.variant_to_canonical {
            assert key not in self.canonical_phrases;

            if key not in self.merged_map {
                self.merged_map[key] = here.variant_to_canonical[key];
            } else {
                if here.variant_to_canonical[key] < self.merged_map[key] {
                    self.merged_map[key] = here.variant_to_canonical[key];
                }
            }
        }
    }

    can finish_catalog with Catalog exit {
        here.variant_to_canonical = self.merged_map;
        here.aliases = len(here.variant_to_canonical);
        assert here.aliases == len(here.variant_to_canonical);

        for key in here.variant_to_canonical {
            assert key not in self.canonical_phrases;
        }

        resolved_models = here.variant_to_canonical["models"];
        print(f"{here.name}: {here.aliases} aliases, models -> {resolved_models}");
    }
}

with entry {
    catalog = Catalog(name="PatternRank");
    shard_a = Partition(shard_id="A");
    shard_b = Partition(shard_id="B");

    variant = Phrase(text="models", doc_freq=7);
    canonical = Phrase(text="model", doc_freq=14);

    model = Concept(phrase="model", doc_freq=14, stable_rank=1);
    modeling = Concept(phrase="modeling", doc_freq=5, stable_rank=2);

    root +>:Owns:+> catalog;
    catalog +>:Owns:+> shard_a;
    catalog +>:Owns:+> shard_b;

    shard_a +>:Contains:+> variant;
    shard_b +>:Contains:+> variant;
    shard_a +>:Contains:+> canonical;

    variant +>:CandidateOf(similarity=0.91):+> model;
    variant +>:CandidateOf(similarity=0.89):+> modeling;
    canonical +>:CandidateOf(similarity=1.0):+> model;
    canonical +>:CandidateOf(similarity=0.72):+> modeling;

    root spawn Clusterer();
}

