    has canonical: bool = True;
}

edge DependsOn {
    has reason: str = "";
}

walker RegistryAuditor {
    has seen_ids: list[str] = [];

    can begin with Root entry {
        print("Auditing the canonical workflow registry");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_registry with Registry entry {
        print(f"Registry {here.registry_id}: {here.authority}");
        visit [->:Registered:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        if here.workflow_id in self.seen_ids {
            print(f"Cycle detected at workflow {here.workflow_id}");
            disengage;
        } else {
            self.seen_ids.append(here.workflow_id);
            print(f"{here.workflow_id} | {here.path} | {here.version} | {here.category}");

            if here.path == "" {
                print(f"Invalid path for {here.workflow_id}");
            }
            if here.version == "" {
                print(f"Invalid version for {here.workflow_id}");
            }
            if here.category == "" {
                print(f"Invalid category for {here.workflow_id}");
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

