        if here.title in self.seen {
            self.cycle_count += 1;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count += 1;
            print(f"solver: mode={here.mode}, action={here.action}");
            print(f"residual={here.residual}, merit={here.merit}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

