        if here.title in self.seen {
            self.cycle_count += 1;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count += 1;
            print(f"geometry: coordinates={here.coordinates}");
            print(f"multiplicative update: {here.update_rule}");
            visit [->:Carries:->] else {
                disengage;
            }
        }
    }

    can inspect with CarriedState entry {
        if here.title in self.seen {
            self.cycle_count += 1;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count += 1;
            if here.mode == "strict" {
                print("strict mode: carried state is solver-blind");
            } else {
                print(f"mean-field mode: using {here.algebraic_density}");
            }
            visit [->:Reads:->] else {
                disengage;
            }
        }
    }

    can inspect with DownstreamRead entry {
        if here.title in self.seen {
