            disengage;
        } else {
            self.seen = self.seen + [here.title];
            self.visited_count += 1;
            if here.downstream_only && !here.reads_solver {
                print("downstream read cannot reach the solver graph");
            }
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

