"""Deterministic security placement plan with typed execution dependencies and cycle detection."""

node PlacementPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has graph_version: str = "";
    has provider: str = "";
}

node SecurityIntent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has intent_id: str = "";
    has required: bool = False;
}

node ProviderCapability {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has capability_id: str = "";
    has support: str = "unsupported";
    has semantic_mapping: str = "";
}

node ProviderPhase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has phase_id: str = "";
    has order: int = 0;
}

edge Selects {
    has intent_pointer: str = "";
}

edge EnforcedAt {
    has placement_id: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker PlannerAudit {
    has seen: list[str] = [];
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_plan with PlacementPlan entry {
        print(f"plan {here.title}: {here.provider} graph {here.graph_version}");
        visit [->:Selects:->] else {
            disengage;
        }
    }

    can inspect_intent with SecurityIntent entry {
        if here.intent_id in self.seen {
            self.cycle_detected = True;
            print(f"cycle detected at intent {here.intent_id}");
            disengage;
        } else {
            self.seen.append(here.intent_id);
            requirement = "required" if here.required else "optional";
            print(f"intent {here.intent_id}: {here.title} ({requirement})");
            visit [->:Candidate:->] else {
                disengage;
            }
        }
    }

    can inspect_capability with ProviderCapability entry {
        if here.capability_id in self.seen {
            self.cycle_detected = True;
            print(f"cycle detected at capability {here.capability_id}");
            disengage;
        } else {
            self.seen.append(here.capability_id);
            print(f"capability {here.capability_id}: {here.support}");
            print(f"mapping: {here.semantic_mapping}");
            visit [->:EnforcedAt:->] else {
                disengage;
            }
        }
    }

    can inspect_phase with ProviderPhase entry {
        if here.phase_id in self.seen {
            self.cycle_detected = True;
            print(f"cycle detected at phase {here.phase_id}");
            disengage;
        } else {
            self.seen.append(here.phase_id);
            print(f"phase {here.order}: {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

