"""Impact analysis over documented asset relations with cycle-safe walkers."""

node Asset {
    has asset_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Relation {
    has relation_id: str = "";
    has relation_type: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge Documents {
    has relation_type: str = "";
}

edge LeadsTo { }

walker DownstreamImpact {
    has source_asset_id: str = "";
    has direction: str = "downstream";
    has relation_filter: str = "";
    has seen_asset_ids: list[str] = [];
    has trail: str = "";
    has depth: int = 0;

    can start with Root entry {
        print(f"impact source={self.source_asset_id} direction={self.direction}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_asset with Asset entry {
        if here.asset_id in self.seen_asset_ids {
            print(f"cycle guard stopped at {here.asset_id}");
        } else {
            self.seen_asset_ids.append(here.asset_id);
            print(f"hit asset={here.asset_id} depth={self.depth} path={self.trail}{here.asset_id}");
            visit [->:Documents:->] else {
                disengage;
            }
        }
    }

    can inspect_relation with Relation entry {
        if self.relation_filter == "" or here.relation_type == self.relation_filter {
            self.trail = self.trail + " --[" + here.relation_type + "]--> ";
            self.depth = self.depth + 1;
            visit [->:LeadsTo:->] else {
                disengage;
            }
        } else {
            print(f"filtered relation={here.relation_type}");
        }
    }
}

walker UpstreamImpact {
    has source_asset_id: str = "";
    has direction: str = "upstream";
    has relation_filter: str = "";
    has seen_asset_ids: list[str] = [];
    has trail: str = "";
    has depth: int = 0;

    can start with Root entry {
        print(f"impact source={self.source_asset_id} direction={self.direction}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_asset with Asset entry {
        if here.asset_id in self.seen_asset_ids {
            print(f"cycle guard stopped at {here.asset_id}");
        } else {
            self.seen_asset_ids.append(here.asset_id);
            print(f"hit asset={here.asset_id} depth={self.depth} path={self.trail}{here.asset_id}");
            visit [<--:LeadsTo:--] else {
                disengage;
            }
        }
    }

    can inspect_relation with Relation entry {
        if self.relation_filter == "" or here.relation_type == self.relation_filter {
            self.trail = self.trail + " <--[" + here.relation_type + "]-- ";
            self.depth = self.depth + 1;
            visit [<--:Documents:--] else {
                disengage;
            }
        } else {
            print(f"filtered relation={here.relation_type}");
        }
    }
}

