"""Sandbox cleanup audit showing an empty temporary path resolving to the workspace."""

node WorkflowRun {
    has record_id: str = "";
    has run_name: str = "";
    has read_only: bool = True;
}

node ScratchArea {
    has record_id: str = "";
    has requested_path: str = "";
    has path_value: str = "";
    has created: bool = True;
}

node CleanupAction {
    has record_id: str = "";
    has command_text: str = "";
    has variable_value: str = "";
    has resolved_path: str = "";
    has target_is_workspace: bool = False;
    has critical_path_prompted: bool = False;
}

node Workspace {
    has record_id: str = "";
    has absolute_path: str = "";
    has is_working_directory: bool = True;
    has intact: bool = True;
}

edge Starts { }
edge UsesScratch {
    has purpose: str = "";
}
edge PlansCleanup {
    has phase: str = "";
}
edge ResolvesTo {
    has reason: str = "";
}
edge ContainsRun { }

walker CleanupAuditor {
    has seen: list[str] = [];
    has depth: int = 0;
    has max_depth: int = 8;
    has findings: int = 0;

    can begin with Root entry {
        self.depth = 0;
        visit [->:Starts:->] else { disengage; }
    }

    can inspect_run with WorkflowRun entry {
        if here.record_id in self.seen {
            print(f"cycle detected at {here.run_name}");
            disengage;
        }
        self.seen.append(here.record_id);
        print(f"workflow: {here.run_name}");
        if self.depth >= self.max_depth {
            print("maximum traversal depth reached");
            disengage;
        }
        self.depth += 1;
        visit [->:UsesScratch:->] else { disengage; }
    }

    can inspect_scratch with ScratchArea entry {
        if here.record_id in self.seen {
            print(f"cycle detected at {here.record_id}");
            disengage;
        }
        self.seen.append(here.record_id);
        print(f"scratch request: {here.requested_path}");
        if here.created == False {
            print("mktemp failed; scratch variable remained empty");
        }
        if self.depth >= self.max_depth {
            print("maximum traversal depth reached");
            disengage;
        }
        self.depth += 1;
        visit [->:PlansCleanup:->] else { disengage; }
    }

    can inspect_cleanup with CleanupAction entry {
        if here.record_id in self.seen {
            print(f"cycle detected at {here.record_id}");
            disengage;
        }
        self.seen.append(here.record_id);
        if here.variable_value == "" {
            print(f"empty variable in command: {here.command_text}");
        }
        if here.target_is_workspace {
            self.findings += 1;
            print(f"[UNSAFE] resolved target is {here.resolved_path}");
            if here.critical_path_prompted == False {
                print("no critical-path prompt was raised");
            }
        }
        if self.depth >= self.max_depth {
            print("maximum traversal depth reached");
            disengage;
        }
        self.depth += 1;
        visit [->:ResolvesTo:->] else { disengage; }
    }

    can inspect_workspace with Workspace entry {
        if here.record_id in self.seen {
            print(f"cycle detected at {here.absolute_path}");
            disengage;
        }
        self.seen.append(here.record_id);
        print(f"workspace reached: {here.absolute_path}");
        if self.depth >= self.max_depth {
            print("maximum traversal depth reached");
            disengage;
        }
        self.depth += 1;
        visit [->:ContainsRun:->] else { disengage; }
    }

    can report with Root exit {
        print(f"audit findings: {self.findings}");
    }
}

with entry {
    run = WorkflowRun(
