"""Native OSP audit of preset drift, template knowledge, and descendant traversal."""

node ConfigItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has preset_value: str = "";
    has profile_value: str = "";
    has differs: bool = False;
    has template_known: bool = False;
    has reportable: bool = False;
}

node Profile(ConfigItem) {
    has checkout_name: str = "";
}

node Setting(ConfigItem) {
    has depth: int = 0;
}

node Server(ConfigItem) {
    has framework_name: str = "";
    has enabled: bool = False;
}

edge Contains {
    has relation: str = "";
}

walker DriftAuditor {
    has findings: int = 0;

    can start with Root entry {
        print("Auditing the ALS deployment graph");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Profile | Setting | Server entry {
        if (here.template_known) {
            print(f"template-known path: {here.key}; descendants remain eligible");
        }

        if (here.differs) {
            if (here.reportable) {
                self.findings = self.findings + 1;
                print(f"deviation: {here.key} = {here.profile_value}");
            }
        }

        visit [->:Contains:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"reportable deviations: {self.findings}");
    }
}

