"""Cache-coherence cascade closure for a nested Post, Comment, and Like graph."""

node Post {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Comment {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Like {
    has record_id: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DestroyCascade { }
edge RestrictCascade { }
edge CacheCoverage { }

walker CascadeAudit {
    has covered_models: list[str] = [];
    has visited_ids: list[str] = [];
    has mutated_models: list[str] = [];
    has missing_models: list[str] = [];

    can start with Root entry {
        covered_nodes = [candidate for candidate in [here ->:CacheCoverage:->]];
        for candidate in covered_nodes {
            self.covered_models.append(candidate.title);
        }
        visit [->:DestroyCascade:->] else { disengage; }
    }

    can collect with Post | Comment | Like entry {
        if here.record_id in self.visited_ids {
            skip;
        }

        self.visited_ids.append(here.record_id);
        self.mutated_models.append(here.title);

        if here.title not in self.covered_models {
            self.missing_models.append(here.title);
        }

        visit [->:DestroyCascade:->] else { disengage; }
    }

    can finish with exit {
        report self.missing_models;
    }
}

