"""Production readiness ledger modeled as a graph of gates, checks, and dependencies."""

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slug: str = "";
    has release_ready: bool = False;
}

node ReleaseGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has gate_id: str = "";
    has passed: bool = False;
}

node Check {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has result: str = "missing";
}

edge HasGate {
    has required: bool = True;
}

edge Evaluates {
    has evidence: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker ReleaseAuditor {
    has inspected: int = 0;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_repository with Repository entry {
        self.inspected += 1;
        print(f"Repository: {here.title}");
        visit [->:HasGate:->] else { disengage; }
    }

    can inspect_gate with ReleaseGate entry {
        self.inspected += 1;
        gate_status = "PASS" if here.passed else "FAIL";
        print(f"Gate {here.title}: {gate_status}");
        visit [->:Evaluates:->] else { disengage; }
    }

    can inspect_check with Check entry {
        self.inspected += 1;
