        visit [-->] else { disengage; }
    }

    can report with Root exit {
        print(f"Release audit inspected {self.inspected} records");
    }
}

walker DependencyAuditor {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        self.seen = [];
        self.cycle_found = False;
        visit [-->] else { disengage; }
