        }
        self.seen.append(here.gate_id);
        print(f"Dependency check: {here.title}");
        visit [->:DependsOn:->] else { disengage; }
    }

    can report with Root exit {
        if self.cycle_found {
            print("Dependency audit: cycle found");
        } else {
            print("Dependency audit: no cycle found");
        }
    }
}

