"""Topology-aware session recovery with root selection, suppression, promotion, and cycle guards."""

node RecoveryPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has live: bool = False;
    has recoverable: bool = False;
    has recovered: bool = False;
    has ancestor_blocked: bool = False;
    has ambiguous: bool = False;
    has selected: bool = False;
    has suppressed: bool = False;
    has promoted: bool = False;
    has unknown: bool = False;
    has visited: bool = False;
}

edge Contains {
    has label: str = "recovery plan";
}

edge Candidate {
    has evidence: str = "session inventory";
}

edge Owns {
    has authoritative: bool = True;
}

walker CohortRecovery {
    has roots_selected: int = 0;
    has descendants_suppressed: int = 0;
    has orphan_children_promoted: int = 0;
    has unknown_components: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_plan with RecoveryPlan entry {
        print(f"recovery plan: {here.title}");
        visit [->:Candidate:->] else {
            disengage;
        }
    }

    can inspect_session with Session entry {
        if here.visited {
            here.ambiguous = True;
            here.unknown = True;
            self.unknown_components += 1;
            print(f"UNKNOWN cycle detected at {here.title}");
        } elif here.ambiguous {
            here.unknown = True;
            self.unknown_components += 1;
            print(f"UNKNOWN ambiguous ancestry: {here.title}");
        } else {
            here.visited = True;

            if here.live {
                here.suppressed = True;
                self.descendants_suppressed += 1;
                print(f"SUPPRESSED {here.title}: parent is live");
                visit [->:Owns:->];
            } elif here.recovered {
                here.suppressed = True;
                self.descendants_suppressed += 1;
                print(f"SUPPRESSED {here.title}: parent was recovered");
                visit [->:Owns:->];
            } elif here.ancestor_blocked {
                here.suppressed = True;
                self.descendants_suppressed += 1;
                print(f"SUPPRESSED {here.title}: owned by selected cohort");
                visit [->:Owns:->];
            } elif here.recoverable {
                here.selected = True;
                self.roots_selected += 1;
                print(f"ROOT SELECTED {here.title}");
                visit [->:Owns:->];
            } else {
                here.promoted = True;
                self.orphan_children_promoted += 1;
                print(f"ORPHAN PROMOTED {here.title}");
                visit [->:Owns:->];
            }
        }
    }

    can report with Root exit {
        print(f"summary: roots selected={self.roots_selected}, "
              f"descendants suppressed={self.descendants_suppressed}, "
              f"orphan children promoted={self.orphan_children_promoted}, "
              f"unknown components={self.unknown_components}");
    }
}

with entry {
    plan = RecoveryPlan(title="Coordinator recovery", year=2025);

    parent = Session(
        title="coordinator-A",
