    cycle_a +>:Owns:+> cycle_b;
    cycle_b +>:Owns:+> cycle_a;

    root spawn CohortRecovery();
}

"""SoundWave release-readiness ledger with typed dependency traversal."""

node Release {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "AT RISK";
}

node Gate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has audit_state: str = "unseen";
}

edge HasGate { }
edge DependsOn { }

walker ReadinessAuditor {
    has seen_gates: list[str] = [];
    has blocked_count: int = 0;
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Auditing SoundWave production readiness");
        visit [-->] else {
            disengage;
        }
    }

    can audit with Release entry {
        print(f"Release: {here.title} [{here.status}]");
        visit [->:HasGate:->] else {
            disengage;
        }
    }

    can inspect with Gate entry {
        if here.title in self.seen_gates {
            self.cycle_found = True;
            print(f"[CYCLE] dependency revisited: {here.title}");
            disengage;
        } else {
            self.seen_gates.append(here.title);
            gate_status = "PASS" if here.available else "BLOCKED";
            if here.available == False {
                self.blocked_count = self.blocked_count + 1;
            }
            print(f"[{gate_status}] {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Summary: {self.blocked_count} blocked gate(s), cycle={self.cycle_found}");
    }
}

