"""Cache-coherence cascade closure with cycle-safe mutation auditing."""

node Post {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Comment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Like {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge DestroyCascade { }
edge RestrictCascade { }
edge CacheCoverage { }

walker CascadeAudit {
    has covered_models: list[str] = [];
    has visited_models: list[str] = [];
    has missing_models: list[str] = [];

    can start with Root entry {
        for candidate in [here ->:CacheCoverage:->] {
            self.covered_models.append(candidate.title);
        }
        visit [->:DestroyCascade:->] else {
            disengage;
        }
    }

    can collect with Post | Comment | Like entry {
        if here.title in self.visited_models {
            skip;
        }

        self.visited_models.append(here.title);

        if here.title not in self.covered_models {
            self.missing_models.append(here.title);
            print(f"MISSING cache coverage: {here.title}");
        } else {
            print(f"mutation covered: {here.title}");
        }

        visit [->:DestroyCascade:->] else {
            disengage;
        }
    }

    can finish with exit {
        report self.missing_models;
    }
}

