"""Process blast-radius audit with typed containment and explicit cycle detection."""

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has process_class: str = "";
    has domain: str = "";
    has generation: int = 1;
    has heartbeat: int = 0;
    has checkpoint: int = 0;
    has disposition: str = "running";
}

node Fault {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has disposition: str = "injected";
}

edge Contains {
    has relationship: str = "owns";
}

edge Targets {
    has reason: str = "fault victim";
}

walker BlastRadiusAudit {
    has victim_title: str = "";
    has fault_kind: str = "";
    has expected_restart: list[str] = [];
    has seen_titles: list[str] = [];
    has observed_stopped: list[str] = [];
    has observed_restarted: list[str] = [];
    has cycle_detected: bool = False;
    has schema_violation: bool = False;
    has under_recovery: bool = False;
    has root_identity: str = "root";

    can begin with Root entry {
        print(f"root={self.root_identity}:alive");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Process entry {
        if here.title in self.seen_titles {
            self.cycle_detected = True;
            print(f"cycle detected at {here.title}");
        } else {
            self.seen_titles.append(here.title);
            here.heartbeat = here.heartbeat + 1;
            here.checkpoint = here.checkpoint + 1;

            if self.fault_kind == "panic" {
                if here.title == self.victim_title {
                    here.available = False;
                    here.disposition = "stopped";
                    self.observed_stopped.append(here.title);

                    if here.title not in self.expected_restart {
                        self.schema_violation = True;
                    }

                    here.generation = here.generation + 1;
                    here.available = True;
                    here.disposition = "restarted";
                    self.observed_restarted.append(here.title);
                    print(f"restarted leaf={here.title} generation={here.generation}");
                }
            }
        }

        visit [->:Contains:->] else {
            disengage;
        }
    }

    can summarize with Root exit {
        if self.victim_title not in self.observed_restarted {
            self.under_recovery = True;
        }

        print(f"expected_restart={self.expected_restart}");
        print(f"observed_stopped={self.observed_stopped}");
        print(f"observed_restarted={self.observed_restarted}");
        print(f"schema_violation={self.schema_violation}");
        print(f"under_recovery={self.under_recovery}");
        print(f"cycle_detected={self.cycle_detected}");
    }
}

