node Payload {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has view_storage: str = "Inline";
    has scalar_fields: int = 0;
}

node Metadata {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has view_storage: str = "Inline";
    has entry_count: int = 0;
}

edge NestedMessage {
    has field_name: str = "";
    has owned_storage: str = "Inline";
    has view_storage: str = "Inline";
}

walker ViewDecoder {
    has seen: list[str] = [];
    has visited_count: int = 0;
    has allocations: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Message | Payload | Metadata entry {
        if here.title in self.seen {
        } else {
            self.seen.append(here.title);
            self.visited_count += 1;

            if here.title != "BenchRequest" {
                if here.view_storage == "Boxed" {
                    self.allocations += 1;
                }
            }

            visit [->:NestedMessage:->] else {
                disengage;
            }
        }
    }
}

