    has transcript: str = "";
    has first_pass_note: str = "";
    has metadata_valid: bool = True;
    has state: str = "pending";
}

node EnrichedRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_id: str = "";
    has transcript: str = "";
    has first_pass_note: str = "";
    has model_config: str = "gpt-5.6-luna:low";
    has store_responses: bool = False;
    has tools_enabled: bool = False;
    has schema_version: str = "record-v1";
    has workflow_version: str = "intake-v1";
    has prompt_version: str = "prompt-v1";
    has approval_state: str = "not_requested";
    has written: bool = False;
    has model_title: str = "";
    has summary: str = "";
    has project: str = "";
    has urgency: str = "normal";
    has confidence: float = 0.0;
}

node QuarantineRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_id: str = "";
    has reason: str = "";
}

edge Produces { }
edge QuarantinedAs { }

walker IntakeAuditor {
    has completing: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can scan with IntakeBatch entry {
        print(f"Scanning batch {here.batch_id}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with IntakeItem entry {
        if self.completing {
            here.state = "succeeded";
            self.completing = False;
            print(f"{here.source_id}: processing completed exactly once");
        } else if here.state == "succeeded" || here.state == "quarantined" {
            print(f"{here.source_id}: duplicate delivery ignored ({here.state})");
        } else if !here.metadata_valid || here.mode != "Idea Inbox" ||
                  here.transcript == "" || here.first_pass_note == "" {
            here.state = "quarantined";
            print(f"{here.source_id}: routed to quarantine");
            visit [->:QuarantinedAs:->] else {
                disengage;
            }
        } else {
            here.state = "processing";
            print(f"{here.source_id}: state is processing");
            visit [->:Produces:->] else {
                disengage;
            }
        }
    }

    can persist with EnrichedRecord entry {
        if !here.written {
            here.written = True;
            here.model_title = "Captured idea";
            here.summary = "Structured enrichment created without external actions";
            here.project = "voice-note-inbox";
            here.urgency = "normal";
            here.confidence = 0.91;
            self.completing = True;
            print(f"{here.source_id}: durable record written with store=false");
        } else {
            self.completing = True;
            print(f"{here.source_id}: existing durable record reused");
        }
        visit [<--:Produces:--] else {
            disengage;
        }
    }

    can quarantine with QuarantineRecord entry {
        print(f"{here.source_id}: quarantine reason = {here.reason}");
    }
}

