}

edge Tracks {
    has g_spi: float = 0.0;
}

edge DependsOn { }
edge Wraps { }
edge Sources { }
edge SendsTo { }

walker FunnelAuditor {
    has max_depth: int = 8;
    has depth: int = 0;
    has visited_count: int = 0;

    can start with Root entry {
        print("Auditing the growth-funnel dependency graph");
        visit [->:Tracks:->] else {
            disengage;
        }
    }

    can inspect with SprintTask entry {
        if self.depth >= self.max_depth {
            print(f"depth limit reached at {here.title}");
            disengage;
        } else {
            self.depth = self.depth + 1;
            visit [->:DependsOn:->] else {
                print(f"no dependency for {here.title}");
            };
            visit [->:Wraps:->] else {
                print(f"no wrapped workflow for {here.title}");
            };
            visit [->:Sources:->] else {
                print(f"no source highlight for {here.title}");
            };
            self.depth = self.depth - 1;
            self.visited_count = self.visited_count + 1;
            print(f"task: {here.title}, G-SPI={here.g_spi}");
        }
    }

    can inspect with DigestWorkflow entry {
        self.visited_count = self.visited_count + 1;
        print(f"workflow: {here.title}, dry_run={here.dry_run}, "
              f"single_path={here.single_send_path}");
        visit [->:SendsTo:->] else {
            print("workflow has no send target");
        };
    }

    can inspect with AuctionHighlight entry {
        self.visited_count = self.visited_count + 1;
        print(f"highlight: {here.title}, amount={here.amount}, "
              f"source_mca_id={here.mca_id}");
        visit [->:SendsTo:->] else {
            print("highlight lineage endpoint reached");
        };
    }

    can report with Root exit {
        print(f"funnel audit visited {self.visited_count} records");
    }
}

