"""Native graph walk for deterministic, cycle-safe social proof extraction."""

node GraphEntity {
    has title: str = "";
    has kind: str = "";
    has year: int = 0;
    has available: bool = True;
    has incoming_edge_type: str = "";
}

node SocialProofStep {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: GraphEntity | None = None;
    has source_title: str = "";
    has edge_type: str = "";
    has verb: str = "";
    has target: GraphEntity | None = None;
    has target_title: str = "";
}

edge SocialLink {
    has edge_type: str = "";
}

walker SocialProofWalker {
    has candidate_title: str = "";
    has anchor_title: str = "";
    has edge_verbs: dict[str, str] = {};
    has seen_titles: list[str] = [];
    has steps: list[SocialProofStep] = [];
    has description: str = "";
    has previous_node: GraphEntity | None = None;
    has previous_title: str = "";
    has stopped_on_cycle: bool = False;
    has confidence: float = 0.85;

    def resolve_verb(edge_name: str) -> str {
        mapped = self.edge_verbs.get(edge_name);
        if mapped is None {
            return edge_name;
        }
        return mapped;
    }

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can extract with GraphEntity entry {
        if here.title in self.seen_titles {
            self.description = self.description + " -> [...]";
            self.stopped_on_cycle = True;
            disengage;
        }

        self.seen_titles.append(here.title);
        if self.anchor_title == "" {
            self.anchor_title = here.title;
        }

        if here.title == self.candidate_title {
            if len(self.steps) == 0 {
                self.description = "directly related";
            }
            disengage;
        }

        if self.previous_title != "" and here.incoming_edge_type != "" {
            verb = self.resolve_verb(here.incoming_edge_type);
            step = SocialProofStep(
                source=self.previous_node,
                source_title=self.previous_title,
                edge_type=here.incoming_edge_type,
                verb=verb,
                target=here,
                target_title=here.title
            );
            self.steps.append(step);

            if self.description == "" {
                self.description = self.previous_title + " " + verb + " " + here.title;
            } else {
                self.description = self.description + ", then " + self.previous_title + " " + verb + " " + here.title;
            }
        }

        self.previous_node = here;
        self.previous_title = here.title;
        visit [->:SocialLink:->] else { disengage; }
    }

    can finish with exit {
        print("Social proof: " + self.description);
        print("Anchor=" + self.anchor_title + ", Candidate=" + self.candidate_title);
        print("Steps=" + str(len(self.steps)));
        print("Confidence=" + str(self.confidence));

        for step in self.steps {
            print(step.source_title + " --[" + step.edge_type + "/" + step.verb + "]--> " + step.target_title);
        }

        if self.stopped_on_cycle {
            print("Cycle policy: truncated with [...]");
        }
    }
}

