"""Static verification graph: audit dependencies for dead code, cycles, and boundary violations."""

node Workspace {
    has name: str = "";
}

node Module {
    has name: str = "";
    has zone: str = "";
    has used: bool = True;
    has boundary_ok: bool = True;
    has baseline_known: bool = False;
    has suppressed: bool = False;
    has suppression_reason: str = "";
}

edge Contains { }

edge DependsOn {
    has relation: str = "runtime";
}

walker StaticAuditor {
    has seen: list[str] = [];
    has cycle_count: int = 0;
    has dead_count: int = 0;
    has boundary_count: int = 0;
    has new_findings: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_workspace with Workspace entry {
        print(f"Auditing workspace: {here.name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_module with Module entry {
        if here.name in self.seen {
            if here.baseline_known == False {
                if here.suppressed == False {
                    self.cycle_count += 1;
                    self.new_findings += 1;
                    print(f"[NEW CYCLE] dependency returns to {here.name}");
                }
            }
        } else {
            self.seen.append(here.name);

            if here.baseline_known == False {
                if here.suppressed == True {
                    print(f"[SUPPRESSED] {here.name}: {here.suppression_reason}");
                } else {
                    if here.used == False {
                        self.dead_count += 1;
                        self.new_findings += 1;
                        print(f"[NEW DEAD CODE] {here.name}");
                    }

                    if here.boundary_ok == False {
                        self.boundary_count += 1;
                        self.new_findings += 1;
                        print(f"[NEW BOUNDARY VIOLATION] {here.name} in {here.zone}");
                    }
                }
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"New findings: {self.new_findings}");
        print(f"Dead modules: {self.dead_count}");
        print(f"Boundary violations: {self.boundary_count}");
        print(f"Cycles: {self.cycle_count}");
    }
}

