"""Native reachability demo with typed call edges and explicit cycle pruning."""

node CallGraph {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FunctionNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has signature: str = "";
    has distance: int = 0;
    has scanned: bool = False;
}

edge Contains {
    has label: str = "";
}

edge Calls {
    has call_kind: str = "";
}

walker Reachability {
    has target_signature: str = "";
    has depth_limit: int = 0;
    has reached: bool = False;
    has visited_count: int = 0;
    has pruned_count: int = 0;

    can start with Root entry {
        visit [->:Contains:->];
    }

    can enter_graph with CallGraph entry {
        visit [->:Contains:->];
    }

    can inspect with FunctionNode entry {
        if here.scanned {
            self.pruned_count += 1;
        } else {
            here.scanned = True;
            self.visited_count += 1;

            if here.signature == self.target_signature {
                self.reached = True;
                disengage;
            } else {
                if self.depth_limit > 0 {
                    if here.distance < self.depth_limit {
                        visit [->:Calls:->] else {
                            disengage;
                        }
                    }
                } else {
                    visit [->:Calls:->] else {
                        disengage;
                    }
                }
            }
        }
    }
}

