"""Incremental relowering: attribute deferred caller edges and recheck impact."""

node Workspace {
    has title: str = "";
}

node Define {
    has title: str = "";
    has block_count: int = 0;
    has dirty_block_count: int = 0;
    has impact_upper_bound: int = 0;
    has dirty: bool = False;
    has want_partial: bool = True;
    has restamped: bool = False;

    def mark_all_blocks_dirty() {
        self.dirty_block_count = self.block_count;
        self.dirty = True;
    }

    def mark_caller_body_dirty() {
        if self.dirty_block_count < 1 {
            self.dirty_block_count = 1;
        }
        self.dirty = True;
    }

    def reconsult_partial_impact() {
        self.want_partial = self.dirty_block_count < self.impact_upper_bound;
    }
}

edge DeferredCall {
    has generation: int = 0;
    has deferred: bool = True;
}

walker IncrementalAuditor {
    has target_name: str = "f";
    has peel_names: list[str] = [];
    has seen_names: list[str] = [];
    has partial_forced_full_by_impact_total: int = 0;
    has cascade_rearm_new_edge_only_total: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can enter_workspace with Workspace entry {
        visit [-->];
    }

    can attribute with Define entry {
        if here.title in self.seen_names {
            disengage;
        }
        self.seen_names.append(here.title);
        self.peel_names.append(here.title);

        if here.title == self.target_name {
            here.mark_all_blocks_dirty();
            self.cascade_rearm_new_edge_only_total += 1;
        } else {
            here.mark_caller_body_dirty();
        }

        here.reconsult_partial_impact();
        if here.want_partial == False {
            here.mark_all_blocks_dirty();
            self.partial_forced_full_by_impact_total += 1;
        }

        visit [->:DeferredCall:->] else {
            disengage;
        }
    }
}

