walker DependencyAuditor {
    has seen: list[str] = [];
    has last_rank: int = -1;
    has cycle_found: bool = False;
    has layering_violation: bool = False;

    can start with Root entry {
        print("Auditing core/lib dependency layers");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Module entry {
        if (here.name in self.seen) {
            self.cycle_found = True;
            print(f"[CYCLE] dependency revisits {here.name}");
            disengage;
        } else {
            if (self.last_rank >= 0 && here.module_rank < self.last_rank) {
                self.layering_violation = True;
                print(f"[LAYERING] reverse dependency enters {here.layer}");
            }
            self.seen.append(here.name);
            self.last_rank = here.module_rank;
            print(f"[CHECK] {here.name} ({here.layer})");
            visit [->:Imports:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        cycle_result = "cycle found" if self.cycle_found else "no cycle";
        layer_result = "layering violation found"
            if self.layering_violation
            else "layering direction is valid";
        print(f"Audit complete: {cycle_result}; {layer_result}");
    }
}

