"""Cycle-aware, stack-safe value conversion modeled with typed graph traversal."""

node Boundary {
    has boundary_name: str = "";
}

node Value {
    has value_id: str = "";
    has path_label: str = "";
}

node ListValue(Value) {
    has container_kind: str = "list";
}

node MapValue(Value) {
    has container_kind: str = "mapping";
}

edge Contains {
    has slot: str = "";
}

walker Converter {
    has seen_ids: list[str] = [];
    has path_text: str = "";
    has converted_count: int = 0;
    has max_nodes: int = 10000;
    has cycle_found: bool = False;
    has limit_hit: bool = False;
    has failure_path: str = "";

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can open with Boundary entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can convert with ListValue | MapValue entry {
        if self.converted_count >= self.max_nodes {
            self.limit_hit = True;
            self.failure_path = f"{self.path_text} -> conversion limit";
            disengage;
        }

        if here.value_id in self.seen_ids {
            self.cycle_found = True;
            self.failure_path = f"{self.path_text} -> {here.path_label}";
            disengage;
        }

        self.seen_ids.append(here.value_id);
        self.converted_count += 1;

        if self.path_text == "" {
            next_path = here.path_label;
        } else {
            next_path = f"{self.path_text} -> {here.path_label}";
        }
        self.path_text = next_path;

        visit [->:Contains:->] else {
            disengage;
        }
    }
}

