"""Cycle-safe recursive resolution of nested skills with deduplication."""

node Manifest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has transitive_enabled: bool = True;
}

node Skill {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has git: str = "";
    has commit: str = "";
    has path: str = "";
}

edge Includes { }
edge DependsOn { }

walker Resolver {
    has seen: list[str] = [];
    has active: list[str] = [];
    has resolved: int = 0;
    has cycle_errors: int = 0;
    has transitive_enabled: bool = False;

    can start with Root entry {
        visit [->:Includes:->];
    }

    can read_manifest with Manifest entry {
        self.transitive_enabled = here.transitive_enabled;
        print(f"manifest: {here.title}");
        visit [->:Includes:->];
    }

    can resolve_skill with Skill entry {
        key = f"{here.git}|{here.commit}|{here.path}";

        if not self.transitive_enabled {
            print(f"transitive resolution disabled: {here.title}");
        } elif key in self.active {
            self.cycle_errors += 1;
            print(f"ERROR: dependency cycle detected at {key}");
        } elif key in self.seen {
            print(f"deduplicated: {key}");
        } else {
            self.seen.append(key);
            self.active.append(key);
            self.resolved += 1;
            print(f"resolved: {here.title} from {key}");

            visit [->:DependsOn:->] else {
                print(f"no nested ai.json skills in {here.path}");
