"""Native OSP demo for ordered pipeline deployment with cycle detection."""

node Bundle {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Pipeline {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has deployed: bool = False;
}

edge Contains { }

edge ControlDependency {
    has caller_pipeline: str = "";
    has callee_pipeline: str = "";
    has activity_name: str = "";
    has wait_on_completion: bool = True;
}

walker DeploymentPlanner {
    has visited: list[str] = [];
    has deploy_order: list[str] = [];
    has warnings: list[str] = [];
    has hops: int = 0;
    has max_hops: int = 32;

    can start with Root entry {
        print("Planning ordered deployment");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Bundle entry {
        print(f"Bundle: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can schedule with Pipeline entry {
        if here.title in self.visited {
            warning = f"cycle detected at {here.title}; back-edge omitted";
            self.warnings.append(warning);
            print(f"WARN: {warning}");
        } else {
            if self.hops >= self.max_hops {
                warning = f"depth limit reached at {here.title}";
                self.warnings.append(warning);
                print(f"WARN: {warning}");
            } else {
                self.visited.append(here.title);
                self.hops += 1;
                visit [->:ControlDependency:->];
                self.deploy_order.append(here.title);
                here.deployed = True;
                print(f"deploy {here.title}");
            }
        }
    }
}

