}

"""Cycle-aware, stack-safe conversion modeled with typed graph traversal."""

node Boundary {
    has boundary_name: str = "";
}

node Value {
    has value_id: str = "";
    has path_label: str = "";
}

node ListValue(Value) {
}

node MapValue(Value) {
}

edge Contains {
    has slot: str = "";
}

walker ConversionAudit {
    has seen_ids: list[str] = [];
    has converted_count: int = 0;
    has max_nodes: int = 10000;
    has cycle_found: bool = False;
    has failure_path: str = "";

    can start with Root entry {
        print("conversion audit started at root");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can open with Boundary entry {
        print(f"converting {here.boundary_name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can convert with ListValue | MapValue entry {
        if self.converted_count >= self.max_nodes {
            self.failure_path = here.path_label;
            print(f"bounded conversion stop at {self.failure_path}");
            disengage;
        }

        if here.value_id in self.seen_ids {
            self.cycle_found = True;
            self.failure_path = here.path_label;
            print(f"cycle detected at {self.failure_path}");
            disengage;
        }

        self.seen_ids.append(here.value_id);
        self.converted_count += 1;
        print(f"converted value at {here.path_label}");

        visit [->:Contains:->] else {
            disengage;
        }
    }
}

