            self.inspected = self.inspected + 1;
            if here.active {
                self.cycle_count = self.cycle_count + 1;
                self.failure_path = here.path_label;
            } else {
                here.active = True;
                visit [->:Contains:->] else {
                    disengage;
                }
            }
        }
    }
}

