"""Cbranch-style repository graph with guarded commit-history auditing."""

node Repository {
    has name: str = "";
    has busy: bool = False;
}

node Branch {
    has name: str = "";
    has current: bool = False;
    has protected: bool = False;
    has enabled: bool = True;
}

node Commit {
    has hash: str = "";
    has message: str = "";
    has author: str = "";
    has archived: bool = False;
}

node Tag {
    has name: str = "";
    has protected: bool = False;
    has enabled: bool = True;
}

edge Contains {
    has role: str = "";
}

edge PointsTo {
    has reason: str = "";
}

edge Parent {
    has ordinal: int = 0;
}

walker HistoryAuditor {
    has seen_hashes: list[str] = [];
    has commit_count: int = 0;
    has reference_count: int = 0;
    has revisit_count: int = 0;
    has cycle_guard_triggered: bool = False;
    has blocked: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit_repository with Repository entry {
        if here.busy {
            self.blocked = True;
            disengage;
        } else {
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can audit_reference with Branch | Tag entry {
        self.reference_count += 1;
        visit [->:PointsTo:->] else {
            disengage;
        }
    }

    can audit_commit with Commit entry {
        if here.hash in self.seen_hashes {
            self.revisit_count += 1;
            self.cycle_guard_triggered = True;
        } else {
            self.seen_hashes.append(here.hash);
            self.commit_count += 1;
            visit [->:Parent:->] else {
                disengage;
            }
        }
    }
}

