    has reason: str = "";
}

walker ReportSweep {
    has answer_budget: int = 12;
    has visited_items: int = 0;
    has findings: int = 0;
    has checkpoints: int = 0;
    has complete: bool = True;
    has seen_titles: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Issue | PullRequest entry {
        if self.visited_items >= self.answer_budget {
            self.complete = False;
            print("answer budget reached before complete coverage");
            disengage;
        }

        if here.title in self.seen_titles {
            print(f"cycle or duplicate guarded: {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.visited_items += 1;
        self.checkpoints += 1;

        status = "available" if here.available else "unavailable";
        print(f"{here.kind} #{here.title} from {here.origin}: {status}");

        if not here.available {
            self.findings += 1;
        }

        visit [-->] else {
            disengage;
        }
    }

    can inspect_comment with Comment entry {
        if self.visited_items >= self.answer_budget {
            self.complete = False;
            print("answer budget reached before comment-tail completion");
            disengage;
        }

        if here.title in self.seen_titles {
            print(f"cycle or duplicate guarded: {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.visited_items += 1;
        self.checkpoints += 1;

        print(f"comment tail {here.sequence} for {here.origin}: {here.body}");

        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(
            f"final authority refresh: complete={self.complete}, "
            f"items={self.visited_items}, checkpoints={self.checkpoints}, "
            f"findings={self.findings}"
        );
    }
}

