"""Dependency graph rules with partial evaluation and cycle protection."""

node Ruleset {
    has title: str = "";
    has resolved_report: str = "";
    has missing_report: str = "";
    has error_report: str = "";
}

node Fact {
    has name: str = "";
    has path: str = "";
    has expression: str = "";
    has is_input: bool = False;
    has is_output: bool = False;
    has available: bool = True;
    has number_value: float = 0.0;
    has boolean_value: bool = False;
    has resolved: bool = False;
    has missing: str = "";
    has error: str = "";
}

edge Publishes { }
edge DependsOn { has rationale: str = ""; }

walker Evaluator {
    has seen: list[str] = [];
    has age_ready: bool = False;
    has income_ready: bool = False;
    has household_ready: bool = False;
    has threshold_ready: bool = False;
    has age_value: float = 0.0;
    has income_value: float = 0.0;
    has threshold_value: float = 0.0;
    has age_verified_ready: bool = False;
    has age_verified_value: bool = False;
    has resolved_report: str = "";
    has missing_report: str = "";
    has error_report: str = "";
    has cycle_detected: bool = False;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can open with Ruleset entry {
        print(f"Evaluating ruleset: {here.title}");
        visit [->:Publishes:->] else { disengage; }
    }

    can resolve with Fact entry {
        if here.name in self.seen {
            self.cycle_detected = True;
            print(f"cycle detected at {here.name}; evaluation stopped");
            disengage;
        } else {
            self.seen = self.seen + [here.name];
            if here.is_input {
                if here.name == "age" {
                    self.age_ready = here.available;
                    self.age_value = here.number_value;
                }
                if here.name == "income" {
                    self.income_ready = here.available;
                    self.income_value = here.number_value;
                }
                if here.name == "householdSize" {
                    self.household_ready = here.available;
                }
                if here.name == "incomeThreshold" {
                    self.threshold_ready = here.available;
                    self.threshold_value = here.number_value;
                }
            } else {
                visit [->:DependsOn:->] else { disengage; }
            }
        }
    }

    can complete with Fact exit {
        if here.name == "ageVerified" {
            if self.age_ready {
                here.resolved = True;
                self.age_verified_ready = True;
                self.age_verified_value = self.age_value >= 18.0;
                here.boolean_value = self.age_verified_value;
                self.resolved_report = self.resolved_report
                    + f"ageVerified={self.age_verified_value}; ";
            } else {
                here.missing = "$.person.age";
                self.missing_report = self.missing_report
                    + f"ageVerified: {here.missing}; ";
            }
        }

        if here.name == "eligible" {
            if self.age_verified_ready
                && self.income_ready
                && self.household_ready
                && self.threshold_ready {
                here.resolved = True;
                here.boolean_value = self.age_verified_value
                    && (self.income_value < self.threshold_value);
                self.resolved_report = self.resolved_report
                    + f"eligible={here.boolean_value}; ";
            } else {
                missing_paths = "";

                if not self.age_verified_ready {
                    missing_paths = missing_paths + "$.person.age, ";
                }
                if not self.income_ready {
                    missing_paths = missing_paths + "$.person.income, ";
                }
                if not self.household_ready {
                    missing_paths = missing_paths
                        + "$.person.householdSize, ";
                }
                if not self.threshold_ready {
                    missing_paths = missing_paths
                        + "$.policy.incomeThreshold, ";
                }

                here.missing = missing_paths;
                self.missing_report = self.missing_report
                    + f"eligible: {here.missing}";
            }
        }
    }

    can finish with Ruleset exit {
        here.resolved_report = self.resolved_report;
        here.missing_report = self.missing_report;
        here.error_report = self.error_report;

        print(f"resolved: {here.resolved_report}");
        print(f"missing: {here.missing_report}");
        print(f"errors: {here.error_report}");

        if self.cycle_detected {
            print("cycle policy: explicit guard set");
        }
    }
}

