    has source_kind: str = "";
    has command: str = "";

    override def describe() -> str {
        return self.title + " [" + self.source_kind + "]";
    }
}

node EvidenceSource(SurveySubject) {
    has capability: str = "";
    has privilege: str = "standard user";

    override def describe() -> str {
        return self.title + " [" + self.capability + "]";
    }
}

