walker StartupImpactAuditor {
    has seen_titles: list[str] = [];
    has conclusions: list[str] = [];
    has evidence_notes: list[str] = [];
    has revisits_blocked: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect with StartupEntry entry {
        if here.title in self.seen_titles {
            self.revisits_blocked += 1;
            print(f"revisit blocked: {here.title}");
            skip;
        }

        self.seen_titles.append(here.title);
        self.conclusions.append(
            here.title + ": Unknown — Windows exposes no per-entry impact metric"
        );
        print(f"{here.describe()} => {here.finding}");
        visit [-->] else { skip; }
    }

    can review with EvidenceSource entry {
        if here.title in self.seen_titles {
            self.revisits_blocked += 1;
            print(f"revisit blocked: {here.title}");
            skip;
        }

        self.seen_titles.append(here.title);
        self.evidence_notes.append(here.describe());
        print(f"evidence: {here.describe()} requires {here.privilege}");
    }

    can summarize with Root exit {
        print(f"audited {len(self.conclusions)} startup entries; impact remains Unknown");
        report self.conclusions;
    }
}

