walker Planner {
    has depth: int = 0;
    has depth_limit: int = 6;

    can start with Root entry {
        print("planner: inspect query graph");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_query with Query entry {
        print(f"query: {here.title} ({here.arm_count} arms)");
        visit [->:References:->] else {
            disengage;
        }
    }

    can inspect_cte with Cte entry {
        if here.is_recursive && !here.stage_ready {
            print(f"recursive CTE {here.title} has no stage lowering");
            print("route refusal to the local output instead of failing the DAG");
            visit [->:RoutesTo:->] else {
                disengage;
            }
        } else {
            print(f"CTE {here.title} has a lowered stage");
            visit [->:LowersTo:->] else {
                disengage;
            }
        }
    }

    can inspect_output with Output entry {
        print(f"output: {here.title} routed through {here.route}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect_stage with Stage entry {
        if self.depth >= self.depth_limit {
            print(f"dependency cycle guarded at {here.title}");
            disengage;
        } else {
            self.depth = self.depth + 1;
            print(f"stage: {here.title} (depth {self.depth})");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

