    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "function";
    has visited: bool = False;
}

edge Contains { }
edge Calls { }

walker DependencyAuditor {
    has max_steps: int = 12;

    can start with Root entry {
        print("Starting analyzer call-graph audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_package with Package entry {
        print(f"Package: {here.title} {here.release}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_module with Module entry {
        print(f"Module: {here.path}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_callable with Callable entry {
        if self.max_steps <= 0 {
            print("Traversal limit reached");
            disengage;
        }

        if here.visited {
            print(f"Cycle detected at {here.title}");
            disengage;
        }

        here.visited = True;
        self.max_steps = self.max_steps - 1;
        print(f"Callable: {here.title}");
        visit [->:Calls:->] else {
            disengage;
        }
    }
}

