"""Witness-based extension interface resolution over a cyclic type graph."""

node ReceiverType {
    has type_name: str = "";
    has nominal_match: bool = False;
}

node Contract {
    has interface_name: str = "";
    has requires_witness: bool = True;
}

node Witness {
    has witness_name: str = "";
    has valid: bool = True;
}

edge Candidate { }
edge Implements { }
edge AppliesTo { }

walker WitnessResolver {
    has seen_types: list[str] = [];
    has cycle_detected: bool = False;
    has witnesses_checked: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can resolve with ReceiverType entry {
        if here.type_name in self.seen_types {
            self.cycle_detected = True;
            disengage;
        }
        self.seen_types.append(here.type_name);
        visit [->:Candidate:->] else {
            disengage;
        }
    }

    can inspect with Witness entry {
        if here.valid {
            self.witnesses_checked += 1;
        }
        visit [->:Implements:->] else {
            disengage;
        }
    }

    can verify with Contract entry {
        visit [->:AppliesTo:->] else {
            disengage;
        }
    }
}

