node ProductionGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has monitoring_ready: bool = False;
    has recovery_ready: bool = False;
    has authorization_clear: bool = False;
}

node Canary {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has issue_number: int = 0;
    has status: str = "bounded";
    has owner_decision: str = "defer";
    has private_state_preserved: bool = True;
    has signed_delivery: bool = False;
    has stable_identity: bool = False;
    has idempotent_delivery: bool = False;
    has rollback_ready: bool = False;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_revision: str = "";
    has accepted_count: int = 0;
    has deduplicated_count: int = 0;
    has coverage_percent: float = 0.0;
    has delivery_verified: bool = False;
    has target_cycle_visible: bool = False;
    has rollback_verified: bool = False;
}

edge Requires { }
edge Enables { }
edge ProducesEvidence { }

walker Coordinator {
    has hops_left: int = 8;
    has audited_canaries: int = 0;

    can start with Root entry {
        if self.hops_left <= 0 {
            disengage;
        }
        self.hops_left = self.hops_left - 1;
        visit [->:Requires:->] else {
            disengage;
        }
    }

    can check_gate with ProductionGate entry {
        if here.monitoring_ready {
            if here.recovery_ready {
                if here.authorization_clear {
                    print(f"Production gate ready: {here.title}");
                    if self.hops_left <= 0 {
                        disengage;
                    }
                    self.hops_left = self.hops_left - 1;
                    visit [->:Enables:->] else {
                        disengage;
                    }
                } else {
                    print("Gate blocked by unresolved authorization evidence");
                    disengage;
                }
            } else {
                print("Gate blocked: recovery boundary is missing");
                disengage;
            }
        } else {
            print("Gate blocked: monitoring evidence is missing");
            disengage;
        }
    }

