"""A graph-native model of deeply nested recursive CTE query nodes."""

node QueryNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has depth: int = 0;
    has marked: bool = False;
}

node RecursiveCTENode(QueryNode) {
    has cte_name: str = "";
    has operation: str = "WITH RECURSIVE";
}

node SelectQuery(QueryNode) {
    has projection: str = "*";
}

edge QueryChild {
    has role: str = "child";
}

walker QueryAuditor {
    has max_depth: int = 6;
    has visited_count: int = 0;
    has copy_count: int = 0;
    has render_count: int = 0;
    has bind_count: int = 0;

    can start with Root entry {
        print(f"auditing nested recursive query graph (limit={self.max_depth})");
        visit [->:QueryChild:->] else { disengage; }
    }

    can inspect with RecursiveCTENode | SelectQuery entry {
        if here.marked {
            print(f"cycle guard stopped at {here.title}");
            disengage;
        }

        if here.depth >= self.max_depth {
            print(f"depth guard stopped expansion at {here.title}");
            disengage;
        }

        here.marked = True;
        self.visited_count += 1;
        self.copy_count += 1;
        self.render_count += 1;
        self.bind_count += 1;
        print(f"copy/toString/bind: {here.title} depth={here.depth}");
        visit [->:QueryChild:->] else { disengage; }
    }

    can summarize with Root exit {
        print(f"visited={self.visited_count}, copy={self.copy_count}, "
              f"toString={self.render_count}, bind={self.bind_count}");
    }
}

