"""Fail-closed local mission lookahead and dependency-cycle audit."""

node GovernanceRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has audit_mark: str = "UNSEEN";
    has cycle_mark: str = "UNSEEN";
}

node Mission(GovernanceRecord) {
    has pre_execution_closure: str = "";
    has expected_n1_binding: str = "";
    has expected_n2_binding: str = "";
    has lookahead_binding: str = "";
    has control_snapshot_id: str = "";
    has control_seq: str = "";
}

node Lookahead(GovernanceRecord) {
    has slot: str = "";
    has status: str = "";
    has summary: str = "";
    has source_ref: str = "";
}

node Evidence(GovernanceRecord) {
    has evidence_status: str = "NOT_RUN";
    has source_ref: str = "";
    has reused: bool = False;
}

node ControlSnapshot(GovernanceRecord) {
    has snapshot_id: str = "";
    has control_seq: str = "";
    has is_current: bool = False;
}

edge HasCheckpoint { }
edge NextCheckpoint { }
edge UsesEvidence { }
edge BindsSnapshot { }
edge DependsOn { }

walker GateAuditor {
    has gate_valid: bool = True;
    has expected_n1_binding: str = "";
    has expected_n2_binding: str = "";
    has expected_lookahead_binding: str = "";
    has expected_snapshot_id: str = "";
    has expected_control_seq: str = "";
    has observed_n1_binding: str = "";
    has observed_n2_binding: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_mission with Mission entry {
        if here.audit_mark == "SEEN" {
            print("FAIL: repeated mission encountered; walk stopped");
            self.gate_valid = False;
            disengage;
        }

        here.audit_mark = "SEEN";
        self.expected_n1_binding = here.expected_n1_binding;
        self.expected_n2_binding = here.expected_n2_binding;
        self.expected_lookahead_binding = here.lookahead_binding;
        self.expected_snapshot_id = here.control_snapshot_id;
        self.expected_control_seq = here.control_seq;

        if here.pre_execution_closure == ""
            || here.pre_execution_closure == "UNKNOWN"
            || here.pre_execution_closure == "NOT_RUN" {
            print("FAIL: pre-execution closure is missing or a placeholder");
            self.gate_valid = False;
        }

        visit [->:HasCheckpoint:->] else {
            print("FAIL: N+1/N+2 lookahead is absent");
            self.gate_valid = False;
            disengage;
        }
    }

    can inspect_lookahead with Lookahead entry {
        if here.audit_mark == "SEEN" {
            print("FAIL: repeated lookahead encountered; walk stopped");
            self.gate_valid = False;
            disengage;
        }

        here.audit_mark = "SEEN";
        binding = f"{here.slot}|{here.status}|{here.summary}|{here.source_ref}";

        if here.status == "PREPARED" {
            if here.summary == ""
                || here.summary == "UNKNOWN"
                || here.source_ref == ""
                || here.source_ref == "UNKNOWN" {
                print(f"FAIL: {here.slot} PREPARED record is incomplete");
                self.gate_valid = False;
            }
        } else if here.status == "BLOCKED_BY_DEPENDENCY" {
            if here.summary == ""
                || here.summary == "UNKNOWN"
                || here.source_ref == ""
                || here.source_ref == "UNKNOWN" {
                print(f"FAIL: {here.slot} blocker or source reference is missing");
                self.gate_valid = False;
            }
        } else {
            print(f"FAIL: {here.slot} has a closed-vocabulary violation");
            self.gate_valid = False;
        }

        if here.slot == "N+1" {
            self.observed_n1_binding = binding;
            if binding != self.expected_n1_binding {
                print("FAIL: N+1 lookahead binding is stale");
                self.gate_valid = False;
            }
            visit [->:NextCheckpoint:->] else {
                print("FAIL: N+2 lookahead is absent");
                self.gate_valid = False;
                disengage;
            }
        } else if here.slot == "N+2" {
            self.observed_n2_binding = binding;
            if binding != self.expected_n2_binding {
                print("FAIL: N+2 lookahead binding is stale");
                self.gate_valid = False;
            }
            visit [->:UsesEvidence:->] else {
                print("FAIL: accepted or reused PASS evidence is absent");
                self.gate_valid = False;
                disengage;
            }
        } else {
            print("FAIL: unknown lookahead slot");
            self.gate_valid = False;
            disengage;
        }
    }

    can inspect_evidence with Evidence entry {
        if here.audit_mark == "SEEN" {
            print("FAIL: repeated evidence encountered; walk stopped");
            self.gate_valid = False;
            disengage;
        }

        here.audit_mark = "SEEN";

        if here.evidence_status != "PASS" || here.source_ref == "" {
            print("FAIL: evidence is not an accepted or reused PASS");
            self.gate_valid = False;
        }

        visit [->:BindsSnapshot:->] else {
            print("FAIL: exact current control snapshot is absent");
            self.gate_valid = False;
            disengage;
        }
    }

    can inspect_snapshot with ControlSnapshot entry {
        if here.audit_mark == "SEEN" {
            print("FAIL: repeated control snapshot encountered");
            self.gate_valid = False;
            disengage;
        }

        here.audit_mark = "SEEN";

        if here.snapshot_id != self.expected_snapshot_id
            || here.control_seq != self.expected_control_seq
            || here.is_current == False {
            print("FAIL: control snapshot binding is stale or not current");
            self.gate_valid = False;
        }

        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        actual_binding = f"{self.observed_n1_binding}||{self.observed_n2_binding}";

        if self.observed_n1_binding == ""
            || self.observed_n2_binding == "" {
            print("FAIL: complete N+1/N+2 lookahead was not materialized");
            self.gate_valid = False;
        }

        if actual_binding != self.expected_lookahead_binding {
            print("FAIL: compiled lookahead binding does not match observed content");
            self.gate_valid = False;
        }

        if self.gate_valid {
            print("PASS: mission is fail-closed and ready for local validation");
        } else {
            print("BLOCKED: local execution authority was not granted");
        }
    }
}

walker CycleDetector {
    has cycle_found: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can follow with Mission entry {
        if here.cycle_mark == "SEEN" {
            self.cycle_found = True;
            print(f"FAIL: dependency cycle returns to {here.title}");
            disengage;
        }

        here.cycle_mark = "SEEN";
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can report with Root exit {
        if self.cycle_found {
            print("Dependency audit: cycle detected");
        } else {
            print("Dependency audit: no cycle detected");
        }
    }
}

