    customer +>:Hosts(purpose="runs customer application"):+> app;
    app +>:Implements(mode="bespoke"):+> custom_feature;
    custom_feature +>:PromotedTo(decision="generalize into core"):+> core_feature;
    app +>:UsesCore(version="1.0.0"):+> core_feature;
    core +>:Owns(library="datex-core"):+> core_feature;

    core_feature +>:DependsOn(reason="loads claims data"):+> dependency;
    dependency +>:DependsOn(reason="illustrates invalid dependency cycle"):+> core_feature;

    root spawn ProductizationAudit();
}

"""Targeted LSX provenance indexes with loose-definition precedence."""

node Resource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has record_id: str = "";
    has resource_name: str = "";
    has source_kind: str = "";
    has definition_path: str = "";
    has configured: bool = False;
    has supported: bool = True;
    has precedence: int = 0;
}

node Index(Resource) {
    has index_name: str = "";
}

node LooseDefinition(Resource) {
}

node PackagedRecord(Resource) {
}

edge Contains {
}

edge References {
    has relation: str = "";
}

walker ProvenanceResolver {
    has target_name: str = "";
    has seen: list[str] = [];
    has selected_id: str = "";
    has selected_source: str = "";
    has selected_path: str = "";
    has selected_rank: int = -1;
    has candidate_count: int = 0;
    has ambiguous: bool = False;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter with Index entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with LooseDefinition | PackagedRecord entry {
        if here.record_id in self.seen {
            print(f"cycle detected at {here.record_id}");
            disengage;
        } else {
            self.seen.append(here.record_id);

            if here.resource_name == self.target_name {
                if here.supported {
                    if here.source_kind == "package" {
                        self.candidate_count += 1;
                        if here.precedence > self.selected_rank {
                            self.selected_id = here.record_id;
                            self.selected_source = here.source_kind;
                            self.selected_path = here.definition_path;
                            self.selected_rank = here.precedence;
                            self.ambiguous = False;
                        } elif here.precedence == self.selected_rank {
                            self.ambiguous = True;
                        }
                    } elif here.configured {
                        self.candidate_count += 1;
                        if here.precedence > self.selected_rank {
                            self.selected_id = here.record_id;
                            self.selected_source = here.source_kind;
                            self.selected_path = here.definition_path;
                            self.selected_rank = here.precedence;
                            self.ambiguous = False;
                        } elif here.precedence == self.selected_rank {
                            self.ambiguous = True;
                        }
                    }
                }
            }

            visit [->:References:->] else {
                disengage;
            }
        }
    }

    can summarize with Root exit {
        if self.candidate_count == 0 {
            print(f"{self.target_name}: no visible supported definition");
        } elif self.ambiguous {
            print(f"{self.target_name}: same-rank ambiguity");
        } elif self.selected_source == "package" {
            print(f"{self.target_name}: packaged-only provenance at {self.selected_path}");
        } else {
            print(f"{self.target_name}: loose definition at {self.selected_path}");
        }
    }
}

