walker DependencyAuditor {
    has seen_packages: list[str] = [];
    has findings: int = 0;

    can begin with Root entry {
        print("Scanning production dependencies at high severity");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_workspace with Workspace entry {
        print(f"Workspace: {here.title} (audit level: {here.audit_level})");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_package with Package entry {
        if here.title in self.seen_packages {
            print(f"[cycle/revisit] {here.title}");
            disengage;
        } else {
            self.seen_packages.append(here.title);
            state = "patched" if here.available else "VULNERABLE";
