                print(f"  high findings: {here.high_findings}, patched: {here.patched_version}");
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Audit complete: {self.findings} high transitive findings observed");
    }
}

