"""Read-only workspace-agent callback verification with bounded cycle traversal."""

node ApprovalRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "DD-2026-008";
    has revision: int = 1;
    has approved: bool = True;
}

node SpecialistResult {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "PASS";
    has read_only: bool = True;
    has preserved_separately: bool = True;
}

node CallbackAttempt {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has conversation_key: str = "dd-2026-008";
    has idempotency_key: str = "DD-2026-008-r1-callback";
    has status: str = "BLOCKED";
    has terminal_success: bool = False;
}

edge Contains { }
edge Produces { }
edge Attempts { }
edge ReturnsTo { }

walker CallbackAuditor {
    has traversal_budget: int = 0;
    has specialist_passed: bool = False;
    has callback_blocked: bool = False;
    has callback_succeeded: bool = False;

    can start with Root entry {
        self.traversal_budget = 6;
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_approval with ApprovalRecord entry {
        if here.approved {
            visit [->:Produces:->] else {
                disengage;
            }
        } else {
            disengage;
        }
    }

    can inspect_specialist with SpecialistResult entry {
        if here.status == "PASS" {
            if here.read_only {
                if here.preserved_separately {
                    self.specialist_passed = True;
                }
            }
        }
        self.traversal_budget = self.traversal_budget - 1;
        if self.traversal_budget <= 0 {
            disengage;
        } else {
            visit [->:Attempts:->] else {
                disengage;
            }
        }
    }

    can inspect_callback with CallbackAttempt entry {
        if here.status == "BLOCKED" {
            self.callback_blocked = True;
        }
        if here.terminal_success {
            self.callback_succeeded = True;
        }
        self.traversal_budget = self.traversal_budget - 1;
        if self.traversal_budget <= 0 {
            disengage;
        } else {
            visit [->:ReturnsTo:->] else {
                disengage;
            }
        }
    }
}

