"""Story categorisation demo with typed topic edges and mute-aware traversal."""

node Story {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Topic {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has muted: bool = False;
}

edge StoryCategory {
    has confidence: float = 0.0;
}

edge ParentTopic {
    has relation: str = "";
}

walker CategoryFilter {
    has story_blocked: bool = False;
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->];
    }

    can inspect_story with Story entry {
        self.story_blocked = False;
        self.depth = 0;
        print(f"Story: {here.title}");
        visit [->:StoryCategory:->] else {
            disengage;
        }
    }

    can inspect_topic with Topic entry {
        state = "MUTED" if here.muted else "active";
        print(f"  topic: {here.title} [{state}]");

        if here.muted {
            self.story_blocked = True;
        }

        self.depth = self.depth + 1;
        if self.depth >= self.max_depth {
            print("  traversal stopped by depth guard");
            disengage;
        }

        visit [->:ParentTopic:->] else {
            disengage;
        }
    }

    can report with Story exit {
        result = "MUTED" if self.story_blocked else "VISIBLE";
        print(f"  decision: {result}");
    }
}

