    }

    can follow_live_boundary with TranscriptSnapshot entry {
        visit [->:LiveBoundary:->] else {
            disengage;
        }
    }

    can apply_event with RpcEvent entry {
        if (here.event_id in self.seen_event_ids) {
            self.cycle_detected = True;
            disengage;
        } else {
            self.seen_event_ids.append(here.event_id);
            here.processed = True;
            self.processed_events += 1;

            if (here.neutral) {
                self.neutral_events += 1;
            } else {
                self.folded_delta += here.delta;
            }

            if (here.rebuild_required) {
                self.rebuild_required = True;
            }

            visit [->:NextEvent:->] else {
                disengage;
            }
        }
    }

    can finalize with TranscriptSnapshot exit {
        here.folded_delta = self.folded_delta;
        here.processed_events = self.processed_events;
        here.neutral_events = self.neutral_events;
        here.cycle_detected = self.cycle_detected;
        here.rebuild_required = self.rebuild_required;
    }
}

