"""Evidence-driven cleanup audit for completed download-client entries."""

node Download {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has download_key: str = "";
    has category: str = "";
    has completed: bool = False;
}

node ImportEvidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has is_imported: bool = False;
    has library_exists: bool = False;
    has active: bool = False;
    has same_location: bool = False;
    has ambiguous: bool = False;
    has uncertain: bool = False;
}

node LibraryFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has library_ref: str = "";
    has exists: bool = False;
    has size_bytes: int = 0;
}

node ActiveOperation {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has operation_ref: str = "";
    has active: bool = False;
}

edge ImportProof { }
edge LibraryRepresentation { }
edge ActiveReference { }

walker CleanupAuditor {
    has verified_count: int = 0;
    has skipped_count: int = 0;
    has remaining_steps: int = 20;

    can start with Root entry {
        if self.remaining_steps <= 0 {
            print("audit stopped: traversal budget exhausted");
            disengage;
        } else {
            self.remaining_steps -= 1;
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect with Download entry {
        print(f"completed download {here.download_key}: {here.completed}");
        if self.remaining_steps <= 0 {
            print("audit stopped: traversal budget exhausted");
            disengage;
        } else {
            self.remaining_steps -= 1;
            visit [->:ImportProof:->] else {
                self.skipped += 1;
                disengage;
            }
        }
    }

    can inspect with ImportEvidence entry {
        decision = "insufficient_evidence";

        if here.ambiguous {
            decision = "ambiguous_match";
        } else {
            if here.uncertain {
                decision = "same_path_or_hardlink_uncertain";
            } else {
                if here.active {
                    decision = "still_active";
                } else {
                    if here.is_imported {
                        if here.library_exists {
                            if here.same_location {
                                decision = "same_path_or_hardlink_uncertain";
                            } else {
                                decision = "import_verified";
                                self.verified_count += 1;
                            }
                        } else {
                            decision = "library_file_missing";
                        }
                    } else {
                        decision = "not_imported";
                    }
                }
            }
        }

        if decision != "import_verified" {
            self.skipped += 1;
        }
        print(f"cleanup decision: {decision}");

        if self.remaining_steps <= 0 {
            print("audit stopped: traversal budget exhausted");
            disengage;
        } else {
            self.remaining_steps -= 1;
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect with LibraryFile entry {
        print(f"library proof {here.library_ref}: exists={here.exists}, "
              f"size={here.size_bytes}");
    }

    can inspect with ActiveOperation entry {
        print(f"active reference {here.operation_ref}: active={here.active}");
    }
}

