"""Preserve nullable response-schema branches before flattening for Gemini."""

node ResponseSchema {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source: str = "";
}

node SchemaProperty {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has spelling: str = "";
    has base_type: str = "";
    has has_null_branch: bool = False;
    has nullable: bool = False;
    has flattened_type: str = "";
    has result: str = "";
}

node UnionBranch {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has branch_type: str = "";
    has is_null: bool = False;
}

edge Contains { }
edge HasProperty { }
edge HasBranch {
    has role: str = "";
}

walker ResponseSanitizer {
    has preserve_nullable: bool = True;
    has nullable_fields: int = 0;

    can begin with Root entry {
        print("Inspecting response schema before Gemini flattening");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter with ResponseSchema entry {
        print(f"schema source: {here.source}");
        visit [->:HasProperty:->] else {
            disengage;
        }
    }

    can clean with SchemaProperty entry {
        if self.preserve_nullable {
            if here.has_null_branch {
                here.nullable = True;
                self.nullable_fields += 1;
            }
        }

        here.flattened_type = here.base_type;
        result_value = "null" if here.nullable else "fabricated value";
        here.result = result_value;

        print(f"{here.title}: {here.spelling} -> nullable={here.nullable}, "
              f"result={here.result}");

        visit [->:HasBranch:->] else {
            disengage;
        }
    }

    can inspect with UnionBranch entry {
        branch_label = "null branch" if here.is_null else here.branch_type;
        print(f"  branch: {branch_label}");
    }

    can report with Root exit {
        print(f"preserved nullable fields: {self.nullable_fields}");
    }
}

with entry {
    response = ResponseSchema(
        title="Gemini response",
        source="OpenAI response_format"
    );

    type_array = SchemaProperty(
        title="value from type array",
        spelling="type: [string, null]",
        base_type="string",
        has_null_branch=True
    );
    type_string = UnionBranch(
        title="string alternative",
        branch_type="string"
    );
    type_null = UnionBranch(
        title="null alternative",
        branch_type="null",
        is_null=True
    );

    any_of = SchemaProperty(
        title="value from anyOf",
        spelling="anyOf: [string, null]",
        base_type="string",
        has_null_branch=True
    );
    any_string = UnionBranch(
        title="string alternative",
        branch_type="string"
    );
    any_null = UnionBranch(
        title="null alternative",
        branch_type="null",
        is_null=True
    );

    one_of = SchemaProperty(
        title="value from oneOf",
        spelling="oneOf: [string, null]",
        base_type="string",
        has_null_branch=True
    );
    one_string = UnionBranch(
        title="string alternative",
        branch_type="string"
    );
    one_null = UnionBranch(
        title="null alternative",
        branch_type="null",
        is_null=True
    );

    root +>:Contains:+> response;
    response +>:HasProperty:+> type_array;
    response +>:HasProperty:+> any_of;
    response +>:HasProperty:+> one_of;

    type_array +>:HasBranch(role="type alternative"):+> type_string;
    type_array +>:HasBranch(role="type alternative"):+> type_null;
    any_of +>:HasBranch(role="union alternative"):+> any_string;
    any_of +>:HasBranch(role="union alternative"):+> any_null;
    one_of +>:HasBranch(role="union alternative"):+> one_string;
    one_of +>:HasBranch(role="union alternative"):+> one_null;

    root spawn ResponseSanitizer();
}

