"""Reverse-order document patching preserves every paragraph between placeholders."""

node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has patch_key: str = "";
    has replacement_lines: int = 0;
    has patched_occurrences: int = 0;
    has deleted_elements: int = 0;
}

node Paragraph {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has position: int = 0;
    has placeholder_count: int = 0;
    has rendered_lines: int = 1;
}

edge ReversePatchOrder {
    has rank: int = 0;
}

edge PreviousParagraph {
    has rank: int = 0;
}

walker ReversePatcher {
    has replacement_lines: int = 0;
    has applied: int = 0;
    has deleted_elements: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can open with Document entry {
        self.replacement_lines = here.replacement_lines;
        visit [->:ReversePatchOrder:->] else {
            disengage;
        }
    }

    can patch with Paragraph entry {
        if here.placeholder_count > 0 {
            here.rendered_lines = self.replacement_lines;
            here.placeholder_count = 0;
            self.applied += 1;
        }
        visit [->:PreviousParagraph:->] else {
            disengage;
        }
    }
}

