    document = Document(
        title="Patchable document",
        patch_key="ph",
        replacement_lines=2
    );

    heading_one = Paragraph(
        title="HEADING ONE",
        position=1,
        rendered_lines=1
    );
    first_placeholder = Paragraph(
        title="{{ph}}",
        position=2,
        placeholder_count=1,
        rendered_lines=0
    );
    heading_two = Paragraph(
        title="HEADING TWO",
        position=3,
        rendered_lines=1
    );
    second_placeholder = Paragraph(
        title="{{ph}}",
        position=4,
        placeholder_count=1,
        rendered_lines=0
    );

    root ++> document;
    document +>:ReversePatchOrder(rank=4):+> second_placeholder;
    second_placeholder +>:PreviousParagraph(rank=3):+> heading_two;
    heading_two +>:PreviousParagraph(rank=2):+> first_placeholder;
    first_placeholder +>:PreviousParagraph(rank=1):+> heading_one;

    patcher = ReversePatcher();
    root spawn patcher;

    document.patched_occurrences = patcher.applied;
    document.deleted_elements = patcher.deleted_elements;
}

"""Native reactive sizing demo with typed dependencies and guarded invalidation."""

node SizingInput {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has kind: str = "";
    has disposed: bool = False;

    def measure() -> int {
        return 0;
    }
}

node Scale(SizingInput) {
    has domain_count: int = 0;
    has step: int = 0;
    has offset: int = 0;

    override def measure() -> int {
        return self.domain_count * self.step + self.offset;
    }
}

node SizeExpression(SizingInput) {
    has multiplier: int = 1;

    override def measure() -> int {
        return self.multiplier;
    }
}

node View {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has visible: bool = True;
    has topology_count: int = 0;
    has last_demand: int = -1;
    has reflow_requests: int = 0;
}

node LayoutBoundary {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has reflow_requests: int = 0;
    has allocated_size: int = 0;
}

edge Contains { }
edge Dependency {
    has reason: str = "";
}
edge ChildOf {
    has slot: str = "";
}
edge ReportsTo { }

walker SizeInvalidator {
    has step_demand: int = 0;
    has expression_factor: int = 1;
    has child_demand: int = 0;
    has pending_demand: int = 0;
    has pending_reflow: bool = False;
    has seen: list[str] = [];

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Scale | SizeExpression entry {
        if here.disposed {
            disengage;
        }

        if here.key in self.seen {
            print(f"cycle ignored at {here.key}");
            disengage;
        }

        self.seen.append(here.key);

        if here.kind == "scale" {
            self.step_demand = here.measure();
        } else {
            self.expression_factor = here.measure();
        }

        visit [->:Dependency:->] else {
            disengage;
        }
    }

    can invalidate with View entry {
        if here.key in self.seen {
            print(f"cycle ignored at {here.key}");
            disengage;
        }

        self.seen.append(here.key);

        demand: int = 0;
        if here.visible {
            demand = self.step_demand * self.expression_factor
                + here.topology_count + self.child_demand;
        }

        changed: bool = demand != here.last_demand;
        if changed {
            here.last_demand = demand;
            here.reflow_requests += 1;
        }

        self.pending_demand = demand;
        self.pending_reflow = changed;
        self.child_demand = demand;

        visit [->:ChildOf:->] else {
            visit [->:ReportsTo:->] else {
                disengage;
            }
        }
    }

    can report with LayoutBoundary entry {
        if self.pending_reflow {
            here.reflow_requests += 1;
            print(f"reflow requested for demand {self.pending_demand}");
        } else {
            print("unchanged demand; no reflow requested");
        }

        disengage;
    }
}

with entry {
    boundary = LayoutBoundary(title="layout boundary");

    scale = Scale(
        title="positional scale",
        key="scale",
        kind="scale",
        domain_count=3,
        step=10,
        offset=2
    );

    old_expr = SizeExpression(
        title="retired step expression",
        key="old-expression",
        kind="expression",
        multiplier=1
    );

    child = View(
        title="hidden concat child",
        key="child",
        visible=False,
        topology_count=2
    );

    parent = View(
        title="grid parent",
        key="parent",
        topology_count=1
    );

    root +>:Contains:+> scale;
    scale +>:Dependency(reason="domain feeds step expression"):+> old_expr;
    old_expr +>:Dependency(reason="expression feeds intrinsic demand"):+> child;
    child +>:ChildOf(slot="concat child"):+> parent;
    parent +>:ReportsTo:+> boundary;

    root spawn SizeInvalidator();

    scale del ->:Dependency:-> old_expr;
    old_expr.disposed = True;

    new_expr = SizeExpression(
        title="replacement step expression",
        key="new-expression",
        kind="expression",
        multiplier=2
    );

    scale +>:Dependency(reason="replacement expression"):+> new_expr;
    new_expr +>:Dependency(reason="expression feeds intrinsic demand"):+> child;

    child.visible = True;
    scale.domain_count = 4;

    root spawn SizeInvalidator();
    root spawn SizeInvalidator();

    print(f"boundary reflows: {boundary.reflow_requests}");
}

"""Reverse-order document patching preserves every paragraph between placeholders."""

node Document {
    has title: str = "";
