    has replacement_lines: int = 0;
    has applied_occurrences: int = 0;
}

node Paragraph {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has is_placeholder: bool = False;
    has rendered_lines: int = 1;
}

edge ContainsDocument { }

edge StartsAt {
    has order: int = 0;
}

edge PreviousElement {
    has order: int = 0;
}

walker ReversePatcher {
    has replacement_lines: int = 0;

    can start with Root entry {
        visit [->:ContainsDocument:->] else {
            disengage;
        }
    }

    can open with Document entry {
        self.replacement_lines = here.replacement_lines;
        visit [->:StartsAt:->] else {
            disengage;
        }
    }

    can patch with Paragraph entry {
        if here.is_placeholder {
            here.rendered_lines = self.replacement_lines;
            here.is_placeholder = False;
            here.parent_document.applied_occurrences += 1;
            print(f"patched {here.title} with {self.replacement_lines} lines");
        } else {
            print(f"preserved {here.title}");
        }

        visit [->:PreviousElement:->] else {
