}

"""Follow-up repository graph query demo."""

node Repository {
    has title: str = "";
    has snapshot_id: str = "";
    has delivery_paused: bool = False;
}

node Artifact {
    has title: str = "";
    has stable_id: str = "";
    has path: str = "";
    has snapshot_id: str = "";
    has source: str = "";
    has coverage: str = "";
    has delivered: bool = False;
    has fresh: bool = True;
    has approved: bool = True;
    has excluded: bool = False;
}

node Evidence {
    has title: str = "";
    has stable_id: str = "";
    has snapshot_id: str = "";
    has coverage: str = "";
    has fresh: bool = True;
}

edge Snapshot: Repository --> Artifact {
    has snapshot_id: str = "";
}

edge DependsOn: Artifact --> Artifact {
    has relation: str = "runtime";
}

edge Supports: Artifact --> Evidence {
    has relation: str = "test";
}

walker FollowUpQuery {
    has start_path: str = "";
    has snapshot_id: str = "";
    has relationship: str = "DependsOn";
    has direction: str = "out";
    has max_depth: int = 2;
    has depth: int = 0;
    has visited_paths: list[str] = [];
    has active_paths: list[str] = [];
    has results: list[str] = [];
    has reports: list[list[str]] = [];
    has blocked: bool = False;

    can start with Root entry {
        visit [-->[?:Repository]] else {
            print("No repository is attached to root");
            disengage;
        }
    }

    can open_snapshot with Repository entry {
        if here.delivery_paused {
            print(f"Query paused by owner policy for {here.title}");
            self.blocked = True;
            disengage;
        }
        if here.snapshot_id != self.snapshot_id {
            print(f"Invalid snapshot request: {self.snapshot_id}");
            self.blocked = True;
            disengage;
        }
        if (self.relationship != "DependsOn" and self.relationship != "Supports") {
            print(f"Invalid relationship filter: {self.relationship}");
            self.blocked = True;
            disengage;
        }
        if (self.direction != "out" and self.direction != "in") {
            print(f"Invalid direction filter: {self.direction}");
            self.blocked = True;
            disengage;
        }
        visit [->:Snapshot:->[?:Artifact, path == self.start_path]] else {
            print(f"Unknown artifact path: {self.start_path}");
            disengage;
        }
    }

    can follow_artifact with Artifact entry {
        if here.snapshot_id != self.snapshot_id {
            print(f"Stale artifact ignored: {here.path}");
            disengage;
        }
        if here.excluded or not here.approved {
            print(f"Delivery excluded or approval paused: {here.path}");
            self.blocked = True;
            disengage;
        }
        if here.path in self.visited_paths {
            print(f"Cycle detected at {here.path}");
            skip;
        }
        self.visited_paths.append(here.path);
        self.active_paths.append(here.path);
        self.depth = self.depth + 1;
        self.results.append(f"{here.stable_id} {here.path} | source={here.source} | coverage={here.coverage} | delivered={here.delivered} | fresh={here.fresh}");
        if self.depth >= self.max_depth {
            print(f"Depth limit reached at {here.path}");
            skip;
        }
        if self.relationship == "DependsOn" {
            if self.direction == "out" {
                visit [->:DependsOn:->] else {
                    print(f"No recorded DependsOn edge from {here.path}; coverage is not proof of absence");
                    disengage;
                }
            } else {
                visit [<-:DependsOn:<-] else {
                    print(f"No recorded DependsOn edge from {here.path}; coverage is not proof of absence");
                    disengage;
                }
            }
        } else {
            if self.direction == "out" {
                visit [->:Supports:->] else {
                    print(f"No recorded Supports edge from {here.path}; coverage is not proof of absence");
                    disengage;
                }
            } else {
                visit [<-:Supports:<-] else {
                    print(f"No recorded Supports edge from {here.path}; coverage is not proof of absence");
                    disengage;
                }
            }
        }
    }

    can close_artifact with Artifact exit {
        if self.active_paths and self.active_paths[-1] == here.path {
            self.active_paths.pop();
            self.depth = self.depth - 1;
        }
    }

    can collect_evidence with Evidence entry {
        if here.snapshot_id != self.snapshot_id {
            print(f"Stale evidence ignored: {here.stable_id}");
            disengage;
        }
        self.results.append(f"{here.stable_id} evidence={here.title} | coverage={here.coverage} | fresh={here.fresh}");
    }

    can finish with Root exit {
        report self.results;
    }
}

with entry {
    repo = Repository(title="knowledge-graph-kit", snapshot_id="snap-42");
    root ++> repo;

