    has metadata_applied: bool = False;
}

node Page {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has refused: bool = False;
    has hydrated: bool = False;
}

node Port {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has channel: str = "";
    has validated: bool = False;
}

edge OwnsDocument { }
edge ContainsPage { }
edge DependsOn { }
edge HostPort { }

walker HydrationAudit {
    has seen_titles: list[str] = [];
    has document_count: int = 0;
    has page_count: int = 0;
    has refused_count: int = 0;
    has cycle_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Runtime entry {
        visit [->:OwnsDocument:->] else {
            disengage;
        }
    }

    can observe with Document entry {
        self.document_count += 1;
        here.observed = True;
        here.metadata_applied = True;
        visit [->:ContainsPage:->] else {
            disengage;
        }
    }

    can hydrate with Page entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.page_count += 1;

            if here.refused {
                self.refused_count += 1;
            } else {
                here.hydrated = True;
                visit [->:DependsOn:->] else {
                    disengage;
                }
            }
        }
    }
}

walker PortAudit {
    has valid_count: int = 0;
    has invalid_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Runtime entry {
        visit [->:HostPort:->] else {
            disengage;
        }
    }

    can validate with Port entry {
        here.validated = True;

        if here.available {
            self.valid_count += 1;
        } else {
            self.invalid_count += 1;
        }
    }
}

