}

edge DependsOn {
    has relation: str = "";
}

walker ArchitectureAuditor {
    has visited: list[str] = [];
    has baseline_total: int = 0;
    has new_total: int = 0;
    has resolved_total: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_repository with Repository entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_module with Module entry {
        if here.title in self.visited {
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.visited.append(here.title);
            self.baseline_total += here.baseline_violations;
            self.new_total += here.new_violations;
            self.resolved_total += here.resolved_violations;
            print(f"audit {here.title}: baseline={here.baseline_violations}, "
                  f"new={here.new_violations}, resolved={here.resolved_violations}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"architecture evidence: baseline={self.baseline_total}, "
              f"new={self.new_total}, resolved={self.resolved_total}");
    }
}

walker ImpactAnalyzer {
    has visited: list[str] = [];
    has affected_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_repository with Repository entry {
        visit [-->] else {
            disengage;
        }
    }

    can trace_module with Module entry {
        if here.title in self.visited {
            print(f"impact traversal cycle at {here.title}");
            disengage;
        } else {
            self.visited.append(here.title);
            self.affected_count += 1;
            impact_kind = "direct" if here.changed else "transitive";
            hotspot_label = " HOTSPOT" if here.hotspot else "";
            print(f"{impact_kind} impact: {here.title}{hotspot_label}");
            visit [<--:DependsOn:--] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"change impact surface: {self.affected_count} modules");
    }
}

