"""Model a native validation dependency audit and explicit cycle detection."""

node ValidationJob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has job_id: str = "";
}

node ValidationDependency {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has role: str = "";
    has language: str = "Rust";
    has oracle_only: bool = False;
    has kernel_fallback: bool = False;
}

edge Requires {
    has purpose: str = "";
}

walker DependencyAudit {
    has seen: list[str] = [];
    has strict_claim: bool = True;

    can start with Root entry {
        print("Auditing the prepared validation dependency graph");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_job with ValidationJob entry {
        print(f"prepared job: {here.job_id}");
        visit [->:Requires:->] else {
            disengage;
        }
    }

    can inspect_dependency with ValidationDependency entry {
        if here.name in self.seen {
            print(f"cycle detected at {here.name}");
            disengage;
        } else {
            self.seen.append(here.name);

            if here.oracle_only {
                print(f"[ORACLE] {here.name} remains opt-in and independent");
            } else {
                if here.language == "C" {
                    self.strict_claim = False;
                    print(f"[REJECTED] C verification backend: {here.name}");
                }
                if here.language == "C++" {
                    self.strict_claim = False;
                    print(f"[REJECTED] C++ verification backend: {here.name}");
                }
                if here.kernel_fallback {
                    self.strict_claim = False;
                    print(f"[REJECTED] silent kernel fallback: {here.name}");
                }
                if here.language == "Rust" {
                    print(f"[RUST] {here.role}: {here.name}");
                }
            }

            visit [->:Requires:->] else {
                disengage;
