        if here.name in self.seen {
            self.cycle_detected = True;
            print(f"[CYCLE] dependency loop returns to {here.name}");
            disengage;
        } else {
            self.seen.append(here.name);
            visit [->:Requires:->] else {
                disengage;
            }
        }
    }
}

