"""Stable region identities, membership audits, and guarded dependency ordering."""

node LogicalNode {
    has logical_name: str = "";
    has canonical_region_id: str = "";
    has membership_count: int = 1;
}

node Region {
    has region_id: str = "";
    has member_signature: str = "";
    has placement_target: str = "";
    has execution_mode: str = "";
    has security_domain: str = "";
    has policy: str = "";
    has strategy_version: str = "";

    def stable_id() -> str {
        return f"{self.member_signature}|target={self.placement_target}|mode={self.execution_mode}|security={self.security_domain}|policy={self.policy}|strategy={self.strategy_version}";
    }
}

edge Owns {
    has slot: int = 0;
}

edge Contains {
    has channel: str = "";
}

edge MemberOf {
    has membership_role: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker MembershipAudit {
    has expected_region_id: str = "";
    has mapping_valid: bool = True;
    has duplicate_membership: bool = False;

    can start with Root entry {
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect with LogicalNode entry {
        self.expected_region_id = here.canonical_region_id;
        if here.membership_count != 1 {
            self.mapping_valid = False;
            self.duplicate_membership = True;
            print(f"FAIL CLOSED: {here.logical_name} has {here.membership_count} region memberships");
            disengage;
        } else {
            visit [->:MemberOf:->] else {
                self.mapping_valid = False;
                print(f"FAIL CLOSED: {here.logical_name} has no region edge");
                disengage;
            }
        }
    }

    can confirm with Region entry {
        if here.region_id != self.expected_region_id {
            self.mapping_valid = False;
            print(f"FAIL CLOSED: mapping points to unexpected region {here.region_id}");
            disengage;
        }
    }

    can report with Root exit {
        if self.mapping_valid {
            print("membership audit: every logical node maps exactly once");
        } else {
            print("membership audit: invalid mapping rejected");
        }
    }
}

walker TopologyWalker {
    has seen_region_ids: list[str] = [];
    has ordered_region_ids: list[str] = [];
    has cycle_detected: bool = False;
    has topology_valid: bool = True;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Region entry {
        if here.region_id in self.seen_region_ids {
            self.cycle_detected = True;
            self.topology_valid = False;
            print(f"FAIL CLOSED: dependency cycle reaches {here.region_id}");
            disengage;
        } else {
            self.seen_region_ids = self.seen_region_ids + [here.region_id];
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can record with Region exit {
        if self.topology_valid {
            self.ordered_region_ids = self.ordered_region_ids + [here.region_id];
        }
    }

    can report with Root exit {
        if self.cycle_detected {
            print("dependency audit: cyclic topology rejected");
        } else {
            print(f"dependency order: {self.ordered_region_ids}");
        }
    }
}

with entry {
    region_a = Region(
        member_signature="orders",
        placement_target="warehouse-east",
        execution_mode="batch",
        security_domain="internal",
        policy="strict",
        strategy_version="v1"
    );
    region_a.region_id = region_a.stable_id();

    region_b = Region(
        member_signature="inventory",
        placement_target="warehouse-east",
        execution_mode="batch",
        security_domain="internal",
        policy="strict",
        strategy_version="v1"
    );
    region_b.region_id = region_b.stable_id();

    region_c = Region(
        member_signature="billing",
        placement_target="payments-east",
        execution_mode="stream",
        security_domain="restricted",
        policy="strict",
        strategy_version="v1"
    );
    region_c.region_id = region_c.stable_id();

    logical_a = LogicalNode(
        logical_name="orders-source",
        canonical_region_id=region_a.region_id
    );
    logical_b = LogicalNode(
        logical_name="inventory-source",
        canonical_region_id=region_b.region_id
    );
    logical_c = LogicalNode(
        logical_name="billing-source",
        canonical_region_id=region_c.region_id,
        membership_count=2
    );

    root +>:Contains(channel="execution-plan"):+> region_a;
    region_a +>:DependsOn(reason="orders reads inventory"):+> region_b;
    region_b +>:DependsOn(reason="billing reconciliation"):+> region_c;
    region_c +>:DependsOn(reason="tampered cycle"):+> region_a;

    root +>:Owns(slot=1):+> logical_a;
    root +>:Owns(slot=2):+> logical_b;
    root +>:Owns(slot=3):+> logical_c;

    logical_a +>:MemberOf(membership_role="canonical"):+> region_a;
    logical_b +>:MemberOf(membership_role="canonical"):+> region_b;
    logical_c +>:MemberOf(membership_role="canonical"):+> region_c;
    logical_c +>:MemberOf(membership_role="tampered-duplicate"):+> region_a;

    print(f"stable region identity: {region_a.region_id}");
    print("region identity alone is not a reusable cache identity");

    root spawn MembershipAudit();
    root spawn TopologyWalker();
}

"""Review lane demo: split rule globs and filter large artifacts before diff materialization."""

node ReviewLane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has rule_patterns: str = "";
    has comma_separated: bool = True;
    has target_path: str = "";
}

node RuleFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has glob: str = "";
}

node ReviewTarget {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
}

node ReviewArtifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has size_bytes: int = 0;
    has untracked: bool = False;
}

edge LaneRule {
    has ordinal: int = 0;
}

edge NextRule {
    has ordinal: int = 0;
}

edge Targets {
    has selected: bool = False;
}

edge DiffCandidate {
    has candidate_kind: str = "";
}

walker ReviewAuditor {
    has target_path: str = "";
    has max_diff_bytes: int = 1000000;
    has loaded_rules: int = 0;
    has materialized_artifacts: int = 0;
    has skipped_artifacts: int = 0;
    has lane_status: str = "NOT_STARTED";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_lane with ReviewLane entry {
        self.lane_status = "REVIEW_LANE_STARTED";
        print(f"status={self.lane_status}");
        if here.comma_separated {
            print(f"split --rules into rule globs: {here.rule_patterns}");
        }
        visit [->:LaneRule:->] else {
            disengage;
        }
    }

    can inspect_rule with RuleFile entry {
        self.loaded_rules += 1;
        print(f"loaded rule glob: {here.glob}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_target with ReviewTarget entry {
        print(f"path filter active: {here.path}");
        visit [->:DiffCandidate:->] else {
            disengage;
        }
    }

    can inspect_artifact with ReviewArtifact entry {
        if here.path == self.target_path {
            if here.size_bytes > self.max_diff_bytes {
                self.skipped_artifacts += 1;
                print(f"DIFF_SKIPPED_LARGE path={here.path} bytes={here.size_bytes}");
            } else {
                self.materialized_artifacts += 1;
                print(f"DIFF_MATERIALIZED path={here.path}");
            }
        } else {
            self.skipped_artifacts += 1;
            print(f"DIFF_PREFILTERED path={here.path}");
        }
        visit [->:DiffCandidate:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"rules={self.loaded_rules}");
        print(f"materialized={self.materialized_artifacts}");
        print(f"skipped={self.skipped_artifacts}");
        print("review_lane_status=STARTED_NOT_MALFUNCTION");
    }
}

