"""Deduplicated traversal of a duplicated session-message graph."""

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has session_id: str = "";
}

node Message {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has uuid: str = "";
    has role: str = "";
}

edge Contains { }
edge Reply { }

walker SyncAuditor {
    has seen_uuids: list[str] = [];
    has unique_messages: int = 0;
    has duplicate_entries: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can open_session with Session entry {
        print(f"Scanning session {here.session_id}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_message with Message entry {
        if here.uuid in self.seen_uuids {
            self.duplicate_entries += 1;
            print(f"Skipping duplicate entry {here.uuid}");
        } else {
            self.seen_uuids.append(here.uuid);
            self.unique_messages += 1;
            print(f"Visiting {here.uuid} ({here.role})");
            visit [->:Reply:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Unique UUIDs: {self.unique_messages}");
        print(f"Duplicate entries skipped: {self.duplicate_entries}");
    }
}

with entry {
    session = Session(
        title="Affected transcript",
        session_id="session-81"
    );
    root +>:Contains:+> session;

    first = Message(
        title="Turn 1",
        uuid="m-1",
        role="user"
    );
    second_a = Message(
        title="Turn 2",
        uuid="m-2",
        role="assistant"
    );
    second_b = Message(
        title="Turn 2 duplicate",
        uuid="m-2",
        role="assistant"
    );
    third_a = Message(
        title="Turn 3",
        uuid="m-3",
        role="user"
    );
    third_b = Message(
        title="Turn 3 duplicate",
        uuid="m-3",
        role="user"
    );

    session +>:Contains:+> first;
    first +>:Reply:+> second_a;
    first +>:Reply:+> second_b;
    second_a +>:Reply:+> third_a;
    second_a +>:Reply:+> third_b;
    second_b +>:Reply:+> third_a;
    second_b +>:Reply:+> third_b;

    root spawn SyncAuditor();
}

