"""Single-pass reachability over shared Git-like object history."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has object_id: str = "";
}

node Ref(GraphItem) {
    has ref_name: str = "";
}

node Commit(GraphItem) {
    has generation: int = 0;
}

node GitObject(GraphItem) {
    has size: int = 0;
}

edge RefTarget {
    has label: str = "";
}

edge Parent {
    has ordinal: int = 0;
}

edge Contains {
    has entry_name: str = "";
}

walker ReachabilityWalker {
    has seen: list[str] = [];
    has reachable_count: int = 0;
    has ref_count: int = 0;
    has walk_count: int = 0;

    can begin with Root entry {
        self.walk_count += 1;
        visit [-->] else {
            disengage;
        }
    }

    can follow_ref with Ref entry {
        self.ref_count += 1;
        visit [->:RefTarget:->] else {
            disengage;
        }
    }

    can follow_commit with Commit entry {
        if here.object_id in self.seen {
            disengage;
        } else {
            self.seen.append(here.object_id);
            self.reachable_count += 1;
            visit [-->] else {
                disengage;
            }
        }
    }

    can follow_object with GitObject entry {
        if here.object_id in self.seen {
            disengage;
        } else {
            self.seen.append(here.object_id);
            self.reachable_count += 1;
        }
    }
}

with entry {
    base = Commit(
        title="shared base",
        year=2020,
        object_id="c0",
        generation=0
    );
    main_tip = Commit(
        title="main tip",
        year=2024,
        object_id="c1",
        generation=1
    );
    feature_tip = Commit(
        title="feature tip",
        year=2024,
        object_id="c2",
        generation=1
    );

    tree = GitObject(
        title="shared tree",
        object_id="t0",
        size=4096
    );
    blob = GitObject(
        title="README",
        object_id="b0",
        size=128
    );

    main = Ref(
        title="main ref",
        ref_name="refs/heads/main",
        object_id="r-main"
    );
    feature = Ref(
        title="feature ref",
        ref_name="refs/heads/feature",
        object_id="r-feature"
    );

    root ++> main ++> feature;

    main +>:RefTarget(label="want"):+> main_tip;
    feature +>:RefTarget(label="want"):+> feature_tip;

    main_tip +>:Parent(ordinal=1):+> base;
    feature_tip +>:Parent(ordinal=1):+> base;

    base +>:Contains(entry_name="tree"):+> tree;
    tree +>:Contains(entry_name="README"):+> blob;

    root spawn ReachabilityWalker();
}

"""Native graph demo for dependency ordering and mainline traversal."""

node Event {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has event_id: str = "";
    has origin_server_ts: int = 0;
    has sender_power: int = 0;
}

node PowerLevelsEvent {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has event_id: str = "";
    has origin_server_ts: int = 0;
    has sender_power: int = 0;
    has mainline_position: int = 0;
}

edge AuthEvent {
    has relation: str = "auth ancestor";
    has sender_power: int = 0;
}

edge MainlineStep {
    has position: int = 0;
}

walker DependencyAuditor {
    has visited_ids: list[str] = [];
    has revisit_detected: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Event | PowerLevelsEvent entry {
        if here.event_id in self.visited_ids {
            self.revisit_detected = True;
            print(f"revisit guarded at {here.event_id}");
            disengage;
        } else {
            self.visited_ids.append(here.event_id);
            print(
                f"ordered {here.event_id}: "
                f"power={here.sender_power}, "
                f"ts={here.origin_server_ts}"
            );
            visit [->:AuthEvent:->] else {
                disengage;
            }
        }
    }
}

walker MainlineWalker {
    has mainline_ids: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can collect with PowerLevelsEvent entry {
        if here.event_id in self.mainline_ids {
            disengage;
        } else {
            self.mainline_ids.append(here.event_id);
            print(
                f"mainline[{here.mainline_position}] = "
                f"{here.event_id}"
            );
            visit [->:MainlineStep:->] else {
                disengage;
            }
        }
    }
}

with entry {
    pl0 = PowerLevelsEvent(
        title="initial power levels",
        year=2020,
        event_id="$pl0",
        origin_server_ts=100,
        sender_power=100,
        mainline_position=0
    );
    pl1 = PowerLevelsEvent(
        title="updated power levels",
        year=2020,
        event_id="$pl1",
        origin_server_ts=200,
        sender_power=80,
        mainline_position=1
    );
    branch = Event(
        title="branch event",
        year=2020,
        event_id="$branch",
        origin_server_ts=210,
        sender_power=50
    );
    final_event = Event(
        title="final event",
        year=2020,
        event_id="$final",
        origin_server_ts=300,
        sender_power=40
    );

    root ++> pl0 ++> pl1;

    pl0 +>:AuthEvent(
        relation="power-levels successor",
        sender_power=100
    ): +> pl1;
    pl0 +>:AuthEvent(
        relation="branch dependency",
        sender_power=100
    ): +> branch;
    pl1 +>:AuthEvent(
        relation="final dependency",
        sender_power=80
    ): +> final_event;
    branch +>:AuthEvent(
        relation="shared dependency",
        sender_power=50
    ): +> final_event;

    pl0 +>:MainlineStep(position=0):+> pl1;

    root spawn DependencyAuditor();
    root spawn MainlineWalker();
}

"""Issue #9 demo: conformance proves behavior while benchmark speed remains unmeasured."""

node ConformanceSuite {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has wait_mode: bool = True;
}

node Backend {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has semantics_equivalent: bool = True;
    has measured: bool = False;
    has throughput: int = 0;
}

node BenchmarkTier {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has refresh_mode: bool = False;
}

edge ConformanceCoverage {
    has wait_mode: bool = True;
}

edge EvaluationOrder {
    has sequence: int = 0;
}

edge BenchmarkCoverage {
    has refresh_mode: bool = False;
}

walker OrderAuditor {
    has steps: int = 0;
    has max_steps: int = 20;

    can start with Root entry {
        if self.steps >= self.max_steps {
            print("Traversal bound reached; cycle policy stopped the walk");
            disengage;
        } else {
            self.steps = self.steps + 1;
            visit [-->] else { disengage; }
        }
    }

    can inspect_suite with ConformanceSuite entry {
        print(f"Conformance: {here.title}, wait={here.wait_mode}");
        if self.steps >= self.max_steps {
            print("Traversal bound reached; cycle policy stopped the walk");
            disengage;
        } else {
            self.steps = self.steps + 1;
            visit [->:ConformanceCoverage:->] else { disengage; }
        }
    }

    can inspect_backend with Backend entry {
        if here.measured {
            print(f"{here.title}: equivalent behavior, measured throughput={here.throughput}");
        } else {
            print(f"{here.title}: equivalent behavior, speed unmeasured");
        }
        if self.steps >= self.max_steps {
            print("Traversal bound reached; cycle policy stopped the walk");
            disengage;
        } else {
            self.steps = self.steps + 1;
            visit [->:EvaluationOrder:->] else { disengage; }
        }
    }

    can inspect_benchmark with BenchmarkTier entry {
        print(f"Benchmark tier: {here.title}, refresh={here.refresh_mode}");
        if self.steps >= self.max_steps {
            print("Traversal bound reached; cycle policy stopped the walk");
            disengage;
        } else {
            self.steps = self.steps + 1;
            visit [->:BenchmarkCoverage:->] else { disengage; }
        }
    }
}

