walker PackageAuditor {
    has visited: list[str] = [];
    has sources_found: int = 0;
    has steps_checked: int = 0;
    has smoke_checks: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit_package with Package entry {
        if here.title in self.visited {
            self.cycle_count += 1;
            print(f"cycle detected at package {here.title}");
        } else {
            self.visited.append(here.title);
            print(f"package: {here.title} ({here.license})");
