"""Cross-folder email threads modeled with typed edges and a cycle-safe walker."""

node Account {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has account_id: str = "";
}

node Folder {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has folder_name: str = "";
}

node Email {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has message_id: str = "";
    has thread_id: str = "";
    has in_reply_to: str = "";
    has folder_name: str = "";
    has depth: int = 0;
}

edge Stores {
    has mailbox_path: str = "";
}

edge Contains {
    has label: str = "";
}

edge Reply {
    has relation: str = "reply";
}

walker ThreadWalker {
    has target_thread_id: str = "";
    has max_depth: int = 8;
    has visited_ids: set[str] = set();

    can start with Root entry {
        print(f"Gathering thread {self.target_thread_id} across folders");
        visit [-->] else {
            disengage;
        }
    }

    can enter_account with Account entry {
        print(f"Account: {here.account_id}");
        visit [->:Stores:->] else {
            disengage;
        }
    }

    can enter_folder with Folder entry {
        print(f"Folder: {here.folder_name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Email entry {
        if here.thread_id != self.target_thread_id {
            return;
        }

        if here.message_id in self.visited_ids {
            print(f"Cycle guard stopped at {here.message_id}");
            return;
        }

        self.visited_ids.add(here.message_id);
        print(f"{'  ' * here.depth}[{here.folder_name}] {here.title} ({here.year})");

        if here.depth >= self.max_depth {
            print(f"Depth limit reached at {here.message_id}");
            return;
        }

        visit [->:Reply:->] else {
            disengage;
        }
    }
}

