"""Fail-safe updater demo: typed Git operations stop on verified failure."""

node UpdatePlan {
    has plan_name: str = "";
}

node Repository {
    has name: str = "";
    has state: str = "unknown";
    has update_verified: bool = False;
}

node GitOperation {
    has command: str = "";
    has mutating: bool = False;
    has succeeded: bool = False;
    has stderr: str = "";
    has sanitized_stderr: str = "";
}

edge Runs {
    has purpose: str = "";
}

edge Next {
    has sequence: int = 0;
}

walker Updater {
    has success: bool = True;
    has checked_operations: int = 0;
    has failed_operation: str = "";
    has failure_detail: str = "";
    has max_steps: int = 8;

    can start with Root entry {
        visit [-->[?:UpdatePlan]] else { disengage; }
    }

    can enter with UpdatePlan entry {
        if here.plan_name == "issue-65-demo" {
            visit [-->[?:Repository]] else { disengage; }
        } else {
            disengage;
        }
    }

    can inspect with Repository entry {
        print(f"Checking repository {here.name} ({here.state})");
        visit [->:Runs:->] else { disengage; }
    }

    can verify with GitOperation entry {
        self.checked_operations += 1;
        if self.checked_operations > self.max_steps {
            self.success = False;
            self.failed_operation = "operation traversal";
            self.failure_detail = "cycle or depth limit reached";
            disengage;
        } elif here.succeeded {
            print(f"verified: {here.command}");
            visit [->:Next:->] else { disengage; }
        } else {
            self.success = False;
            self.failed_operation = here.command;
            self.failure_detail = here.sanitized_stderr;
            print(f"stopped: {here.command} -- {here.sanitized_stderr}");
        }
    }

    can report_result with exit {
        if self.success {
            print("UPDATE VERIFIED");
        } else {
            print(f"UPDATE FAILED at {self.failed_operation}: {self.failure_detail}");
        }
    }
}

with entry {
    plan = UpdatePlan(plan_name="issue-65-demo");
    repository = Repository(name="agentic-workflow", state="dirty");
    pull = GitOperation(
        command="git pull",
        mutating=True,
        succeeded=False,
        stderr="fatal: authentication failed for https://token@remote.invalid/repo.git",
        sanitized_stderr="fatal: authentication failed for <redacted-remote>/repo.git"
    );
    reset = GitOperation(
        command="git reset --hard HEAD",
        mutating=True,
        succeeded=True,
        stderr="",
        sanitized_stderr=""
    );

    root ++> plan ++> repository;
    repository +>:Runs(purpose="update"):+> pull;
    pull +>:Next(sequence=1):+> reset;

    root spawn Updater();
}

