"""Results revision lineage demo with typed edges and deterministic child conflicts."""

node SimulationRun {
    has run_id: str = "";
    has result_key: str = "";
}

node ResultRevision {
    has result_key: str = "";
    has revision_id: str = "";
    has base_revision_id: str = "";
    has digest: str = "";
    has current_leaf: bool = True;
    has immutable: bool = True;

    def reserve_child() -> bool {
        if self.current_leaf {
            self.current_leaf = False;
            return True;
        }
        return False;
    }
}

edge HasRevision {
    has role: str = "";
}

edge RevisionChild {
    has relation: str = "";
}

walker RevisionWriter {
    has result_key: str = "";
    has base_revision_id: str = "";
    has candidate_digest: str = "";
    has outcome: str = "";
    has visited_ids: list[str] = [];
    has outcomes: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_run with SimulationRun entry {
        visit [->:HasRevision:->] else {
            disengage;
        }
    }

    can inspect_revision with ResultRevision entry {
        if here.revision_id in self.visited_ids {
            self.outcome = "CYCLE_DETECTED";
            disengage;
        } else {
            self.visited_ids.append(here.revision_id);

            if here.revision_id == self.base_revision_id {
                if here.result_key != self.result_key {
                    self.outcome = "REJECTED_DIFFERENT_RESULT";
                } else if here.reserve_child() {
                    candidate = ResultRevision(
                        result_key=self.result_key,
                        revision_id=self.candidate_digest,
                        base_revision_id=here.revision_id,
                        digest=self.candidate_digest
                    );
                    here +>:RevisionChild(relation="correction"):+> candidate;
                    self.outcome = f"ACCEPTED_CHILD:{self.candidate_digest}";
                } else {
                    self.outcome = "CONFLICT_CURRENT_BASE_ALREADY_CLOSED";
                }
            }

            visit [->:RevisionChild:->] else {
                disengage;
            }
        }
    }

    can finish with exit {
        self.outcomes.append(self.outcome);
        report self.outcomes;
    }
}

with entry {
    run = SimulationRun(run_id="RUN-6568", result_key="RESULT-R11");
    base = ResultRevision(
        result_key="RESULT-R11",
        revision_id="REV-BASE",
        digest="digest-base"
    );

    root ++> run;
    run +>:HasRevision(role="canonical revision"):+> base;

    first = RevisionWriter(
        result_key="RESULT-R11",
        base_revision_id="REV-BASE",
        candidate_digest="digest-correction-a"
    );
    root spawn first;

    second = RevisionWriter(
        result_key="RESULT-R11",
        base_revision_id="REV-BASE",
        candidate_digest="digest-correction-b"
    );
    root spawn second;

    print(first.outcome);
    print(second.outcome);
}

