"""Reverse integrity audit for InfiniDysk-owned library references."""

node Library {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has current_dav_item_ids: list[str] = [];
    has census_trustworthy: bool = True;
}

node DavItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has dav_id: str = "";
}

node LibraryReference {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has target_id: str = "";
    has recognized_infini: bool = True;
    has generated_output: bool = False;
    has owner: str = "";
    has repair_queued: bool = False;
}

edge LibraryRoot { }
edge CurrentDavItem { }
edge LibraryReferenceLink { }
edge ReferenceTarget {
    has relation: str = "resolved";
}

walker LibraryReferenceIntegrity {
    has current_dav_item_ids: list[str] = [];
    has inspected: int = 0;
    has stale: int = 0;
    has repair_candidates: int = 0;
    has steps: int = 0;
    has max_steps: int = 32;
    has seen_paths: list[str] = [];

    can start with Root entry {
        if self.steps >= self.max_steps {
            print("Traversal limit reached; stopping safely");
            disengage;
        }
        self.steps += 1;
        visit [->:LibraryRoot:->] else { disengage; }
    }

    can scan with Library entry {
        if not here.census_trustworthy {
            print("Library census is not trustworthy; failed closed");
            disengage;
        }
        if self.steps >= self.max_steps {
            print("Traversal limit reached; stopping safely");
            disengage;
        }
        self.steps += 1;
        visit [->:LibraryReferenceLink:->] else { disengage; }
    }

    can inspect with LibraryReference entry {
        if self.steps >= self.max_steps {
            print("Traversal limit reached; stopping safely");
            disengage;
        }
        self.steps += 1;

        if here.path in self.seen_paths {
            print(f"Cycle detected at {here.path}; stopping this walk");
            disengage;
        }
        self.seen_paths.append(here.path);

        if not here.recognized_infini or here.generated_output {
            print(f"SKIP non-owned/generated reference {here.path}");
        } else {
            self.inspected += 1;
            is_live: bool = here.target_id in self.current_dav_item_ids;

            if not is_live {
                self.stale += 1;
                here.repair_queued = True;
                self.repair_candidates += 1;

                if here.owner != "" {
