"""Safe BSON traversal demo with an explicit nesting cap and cycle guard."""

node Command {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has kind: str = "command";
    has payload: str = "";
    has walked: bool = False;
}

node BsonValue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has kind: str = "scalar";
    has payload: str = "";
    has walked: bool = False;
}

edge Contains {
    has slot: str = "";
}

walker SafeRenderer {
    has max_depth: int = 4;
    has current_depth: int = 0;

    can start with Root entry {
        print("starting bounded bulkWrite validation");
        visit [-->];
    }

    can inspect with Command | BsonValue entry {
        if here.walked {
            print(f"[cycle/repeat] stopped at {here.key}");
            disengage;
        }

        here.walked = True;

        if self.current_depth >= self.max_depth {
            print(f"[rejected] BSON nesting cap reached at {here.key}");
            disengage;
        }

        print(f"render {here.kind} key={here.title} payload={here.payload}");
        self.current_depth += 1;
        visit [->:Contains:->] else {
            self.current_depth -= 1;
        }
        self.current_depth -= 1;
    }
}

