}

walker RemovalCoordinator {
    has mode: str = "application";
    has confirmation: str = "";
    has plan_digest: str = "";
    has expected_digest: str = "inventory-v1-application-7f3a";
    has generation: int = 0;
    has plan_generation: int = 0;
    has max_depth: int = 8;
    has planned: int = 0;
    has removed_count: int = 0;
    has preserved_count: int = 0;
    has journal_phase: str = "new";

    can start with Root entry {
        if self.confirmation != "REMOVE" {
            print("Refusing uninstall: exact REMOVE confirmation is required");
            disengage;
        } else {
            if self.plan_digest != self.expected_digest {
                print("Refusing uninstall: plan digest mismatch");
                disengage;
            } else {
                if self.generation != self.plan_generation {
                    print("Refusing uninstall: inventory generation drifted");
                    disengage;
                } else {
                    self.journal_phase = "planned";
                    print(f"Planning {self.mode} removal with digest {self.plan_digest}");
                    visit [-->] else {
                        disengage;
                    }
                }
            }
        }
    }

