"""Live workflow reachability with separate visited and live sets."""

node DeploymentGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has requested_id: str = "";
}

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has workflow_id: str = "";
    has floor_label: bool = False;
}

edge Targets { }
edge Executes {
    has relation: str = "";
}

walker LiveClosure {
    has floor_seed_id: str = "";
    has target_id: str = "";
    has visited_ids: list[str] = [];
    has live_ids: list[str] = [];

    can begin with Root entry {
        self.live_ids.append(self.floor_seed_id);
        visit [-->] else {
            disengage;
        }
    }

    can open_gate with DeploymentGate entry {
        print(f"gate target: {here.requested_id}");
        self.target_id = here.requested_id;
        visit [->:Targets:->] else {
            disengage;
        }
    }

    can inspect with Workflow entry {
        if here.workflow_id in self.visited_ids {
            skip;
        }

        self.visited_ids.append(here.workflow_id);
        if here.workflow_id not in self.live_ids {
            self.live_ids.append(here.workflow_id);
        }

        print(f"visited {here.title} ({here.workflow_id})");
        visit [->:Executes:->] else {
            disengage;
        }
    }

    can report with exit {
        print(f"target {self.target_id} live: {self.target_id in self.live_ids}");
        print(f"visited independently: {self.visited_ids}");
        print(f"live closure: {self.live_ids}");
    }
}

