"""Source-aware release pipeline with typed dependencies and guarded traversal."""

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_id: str = "";
    has approved: bool = False;
    has license_name: str = "";
}

node LockedInput {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has input_hash: str = "";
    has source_date: str = "";
    has locked: bool = False;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has payload_hash: str = "";
    has deterministic: bool = False;
    has synthetic: bool = False;
    has secret_leaked: bool = False;
}

node Release {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has release_id: str = "";
    has published: bool = False;
    has last_known_good: bool = False;
    has payload_hash: str = "";
}

edge SourceInput {
    has ordinal: int = 0;
}

edge InputArtifact {
    has transform: str = "";
}

edge ArtifactRelease {
    has partition: str = "";
}

walker PipelineAuditor {
    has steps: int = 0;
    has max_steps: int = 12;

    can report with Source | LockedInput | Artifact | Release entry {
        print(f"record {here.title} ({here.year})");
    }

    can start with Root entry {
        print("auditing locked inputs and published artifacts");
        self.steps += 1;
        visit [-->] else {
            disengage;
        }
    }

    can inspect_source with Source entry {
        self.steps += 1;
        if here.approved {
            print(f"source {here.source_id} approved under {here.license_name}");
        } else {
            print(f"source {here.source_id} rejected");
        }
        if self.steps >= self.max_steps {
            print("cycle guard: traversal depth limit reached");
            disengage;
        } else {
            visit [->:SourceInput:->] else {
                disengage;
            }
        }
    }

    can inspect_input with LockedInput entry {
        self.steps += 1;
        if here.locked {
            print(f"locked input {here.input_hash} dated {here.source_date}");
        } else {
            print(f"refresh failed for {here.title}; existing release remains untouched");
        }
        if self.steps >= self.max_steps {
            print("cycle guard: traversal depth limit reached");
            disengage;
        } else {
            visit [->:InputArtifact:->] else {
                disengage;
            }
        }
    }

    can inspect_artifact with Artifact entry {
        self.steps += 1;
        if here.deterministic {
            if here.synthetic {
                print(f"artifact {here.title} rejected: synthetic record");
            } else {
                if here.secret_leaked {
                    print(f"artifact {here.title} rejected: secret detected");
                } else {
                    print(f"artifact {here.payload_hash} is deterministic and valid");
                }
            }
        } else {
            print(f"artifact {here.title} rejected: nondeterministic transformation");
        }
        if self.steps >= self.max_steps {
            print("cycle guard: traversal depth limit reached");
            disengage;
        } else {
            visit [->:ArtifactRelease:->] else {
                disengage;
            }
        }
    }

    can inspect_release with Release entry {
        self.steps += 1;
        if here.last_known_good {
            print(f"published release {here.release_id} is last-known-good");
        } else {
            print(f"candidate release {here.release_id} was not published");
        }
        disengage;
    }
}

