"""ADR task dependency audit with typed edges, ordering checks, and cycle detection."""

node Spec {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_key: str = "";
    has document_index: int = 0;
}

edge Contains { }
edge DependsOn {
    has reason: str = "";
}
edge CycleStart { }

walker OrderAuditor {
    has expected_index: int = 0;
    has violations: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with Spec entry {
        print(f"Auditing {here.name}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with Task entry {
        if self.expected_index == 0 {
            self.expected_index = here.document_index;
            print(f"Starting at {here.task_key}: {here.title}");
        } else {
            if here.document_index >= self.expected_index {
                self.violations += 1;
                print(f"ORDER ERROR: {here.task_key} depends on a later task");
            } else {
                print(f"valid dependency: {here.task_key}");
            }
            self.expected_index = here.document_index;
        }

        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker CycleDetector {
    has origin_key: str = "";
    has steps: int = 0;
    has max_steps: int = 8;

    can start with Root entry {
        self.origin_key = "ADR-401";
        visit [->:CycleStart:->] else {
            disengage;
        }
    }

    can inspect with Task entry {
        self.steps += 1;

        if self.steps > self.max_steps {
            print("cycle guard stopped the dependency walk");
            disengage;
        } else {
            if here.task_key == self.origin_key && self.steps > 1 {
                print(f"CYCLE DETECTED at {here.task_key}");
                disengage;
            } else {
                print(f"cycle scan: {here.task_key}");
                visit [->:DependsOn:->] else {
                    disengage;
                }
            }
        }
    }
}

