"""Persistent orphan confirmation with safe mutation-time revalidation."""

node DavFile {
    has title: str = "";
    has created_at: int = 0;
    has history_item_id: int = 0;
    has linked: bool = True;
    has deleted: bool = False;
}

node Scan {
    has generation: int = 0;
    has observed_at: int = 0;
    has healthy: bool = True;
    has library_available: bool = True;
    has inside_mount: bool = False;
    has linked_ids: int = 0;
    has extreme_unlinked_ratio: bool = False;
}

node OrphanEvidence {
    has first_seen: int = -1;
    has last_seen: int = -1;
    has observations: int = 0;
    has last_successful_generation: int = 0;
}

edge ScannedFile {
    has observed_generation: int = 0;
}

edge HasEvidence { }

edge CurrentScan {
    has authoritative: bool = True;
}

walker OrphanConfirmer {
    has grace_hours: int = 24;
    has scan_healthy: bool = False;
    has scan_time: int = 0;
    has scan_generation: int = 0;
    has current_title: str = "";
    has current_linked: bool = True;
    has current_history: int = 0;
    has current_created: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Scan entry {
        self.scan_healthy = here.healthy;
        self.scan_time = here.observed_at;
        self.scan_generation = here.generation;

        if here.library_available == False {
            self.scan_healthy = False;
        }
        if here.inside_mount {
            self.scan_healthy = False;
        }
        if here.linked_ids < 5 {
            self.scan_healthy = False;
        }
        if here.extreme_unlinked_ratio {
            self.scan_healthy = False;
        }

        visit [-->] else {
            disengage;
        }
    }

    can inspect with DavFile entry {
        self.current_title = here.title;
        self.current_linked = here.linked;
        self.current_history = here.history_item_id;
        self.current_created = here.created_at;

        visit [->:HasEvidence:->] else {
            disengage;
        }
    }

    can record with OrphanEvidence entry {
        if self.scan_healthy {
            if self.current_linked {
                here.first_seen = -1;
                here.last_seen = -1;
                here.observations = 0;
                here.last_successful_generation = self.scan_generation;
                print(f"reset orphan evidence for {self.current_title}");
            } else {
                if here.observations == 0 {
                    here.first_seen = self.scan_time;
                }
                here.last_seen = self.scan_time;
                here.observations += 1;
                here.last_successful_generation = self.scan_generation;
                print(f"confirmed unlinked observation {here.observations} for {self.current_title}");
            }
        } else {
            print(f"ignored unhealthy scan evidence for {self.current_title}");
        }
    }
}

walker MutationRevalidator {
    has grace_hours: int = 24;
    has scan_healthy: bool = False;
    has scan_time: int = 0;
    has current_title: str = "";
    has current_linked: bool = True;
    has current_history: int = 0;
    has current_created: int = 0;

    can begin with Root entry {
        visit [->:CurrentScan:->] else {
            disengage;
        }
    }

    can inspect with Scan entry {
        self.scan_healthy = here.healthy;
        self.scan_time = here.observed_at;

        if here.library_available == False {
            self.scan_healthy = False;
        }
        if here.inside_mount {
            self.scan_healthy = False;
        }
        if here.linked_ids < 5 {
            self.scan_healthy = False;
        }
        if here.extreme_unlinked_ratio {
            self.scan_healthy = False;
        }

        visit [-->] else {
            disengage;
        }
    }

    can revalidate with DavFile entry {
        self.current_title = here.title;
        self.current_linked = here.linked;
        self.current_history = here.history_item_id;
        self.current_created = here.created_at;

        visit [->:HasEvidence:->] else {
            disengage;
        }
    }

    can delete with OrphanEvidence entry {
        if self.scan_healthy {
            if self.current_linked {
                print(f"kept {self.current_title}: linked again");
            } else {
                if self.current_history != 0 {
                    print(f"kept {self.current_title}: protected by history");
                } else {
                    if self.current_created >= self.scan_time {
                        print(f"kept {self.current_title}: created after scan start");
                    } else {
                        if here.observations >= 2 {
                            if self.scan_time - here.first_seen >= self.grace_hours {
                                print(f"DELETE {self.current_title}: revalidation passed");
                            } else {
                                print(f"kept {self.current_title}: grace period not elapsed");
                            }
                        } else {
                            print(f"kept {self.current_title}: confirmation incomplete");
                        }
                    }
                }
            }
        } else {
            print(f"kept {self.current_title}: current scan is unhealthy");
        }
    }
}

