"""Native OpenSpec dependency audit with cycle detection and decision escalation."""

edge DependsOn {
    has reason: str = "";
}

edge UsesEvidence {
    has source_note: str = "";
}

edge Escalates {
    has severity: str = "material";
}

node GraphRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has schema_name: str = "openspec";
    has approved: bool = False;
    has material_decision: str = "";
}

node PlannerPrompt(GraphRecord) {
    has role_contract: str = "";
}

node DesignerPrompt(GraphRecord) {
    has design_scope: str = "";
}

node TaskPlan(GraphRecord) {
    has dependency_note: str = "";
}

node RepositoryEvidence(GraphRecord) {
    has source: str = "";
    has excerpt: str = "";
}

walker DependencyAuditor {
    has seen_paths: list[str] = [];
    has cycle_detected: bool = False;
    has unresolved_decisions: int = 0;

    can begin with Root entry {
        print("Auditing dispatched OpenSpec artifacts");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with PlannerPrompt | DesignerPrompt | TaskPlan | RepositoryEvidence entry {
        if here.path in self.seen_paths {
            self.cycle_detected = True;
            print(f"cycle detected at {here.path}");
            disengage;
        } else {
            self.seen_paths.append(here.path);
            print(f"checking {here.title} from {here.path}");

            if not here.approved {
                print(f"not yet approved: {here.title}");
            }

            if here.material_decision != "" {
                self.unresolved_decisions += 1;
                print(f"escalate material decision: {here.material_decision}");
            }

            visit [-->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"audited {len(self.seen_paths)} records");
        print(f"material decisions: {self.unresolved_decisions}");
        print(f"cycle detected: {self.cycle_detected}");
    }
}

