}

"""Native parser-performance graph demo with shared DFA state and cycle guards."""

node InputFile {
    has path: str = "";
    has token_count: int = 0;
}

node ParserAtn {
    has grammar_name: str = "";
    has cache_ready: bool = False;
}

node Decision {
    has decision_id: int = 0;
    has ll1: bool = False;
    has adaptive_calls: int = 0;
}

node DfaState {
    has state_id: int = 0;
    has learned: bool = False;
    has seen: bool = False;
}

edge ContainsInput {
    has ordinal: int = 0;
}

edge UsesAtn {
    has cacheable: bool = True;
}

edge HasDecision {
    has index: int = 0;
}

edge CachedDfa {
    has learned_for: str = "";
}

edge NextState {
    has token_kind: int = 0;
}

walker PerformanceAuditor {
    has files_seen: int = 0;
    has ll1_bypasses: int = 0;
    has adaptive_predictions: int = 0;
    has dfa_states_seen: int = 0;

    can begin with Root entry {
        print("auditing interpreted parser graph");
        visit [->:ContainsInput:->] else {
            disengage;
        }
    }

    can inspect_file with InputFile entry {
        self.files_seen += 1;
        print(f"file {here.path}: {here.token_count} tokens");
        visit [->:UsesAtn:->] else {
            disengage;
        }
    }

    can inspect_atn with ParserAtn entry {
        if here.cache_ready {
            print(f"shared ATN cache reused for {here.grammar_name}");
        } else {
            here.cache_ready = True;
            print(f"cold ATN cache initialized for {here.grammar_name}");
        }
        visit [->:HasDecision:->] else {
            disengage;
        }
    }

    can inspect_decision with Decision entry {
        if here.ll1 {
            self.ll1_bypasses += 1;
            print(f"decision {here.decision_id}: LL(1) fast path");
        } else {
            here.adaptive_calls += 1;
            self.adaptive_predictions += 1;
            print(f"decision {here.decision_id}: adaptive prediction");
        }
        visit [->:CachedDfa:->] else {
            disengage;
        }
    }

    can inspect_state with DfaState entry {
        if here.seen {
            print(f"DFA state {here.state_id}: cycle/revisit guard stopped walk");
        } else {
            here.seen = True;
            self.dfa_states_seen += 1;
            if here.learned {
                print(f"DFA state {here.state_id}: learned transition reused");
            } else {
                print(f"DFA state {here.state_id}: transition discovered");
            }
            visit [->:NextState:->] else {
                disengage;
            }
        }
    }
}

with entry {
    atn = ParserAtn(grammar_name="DOT");

    file_a = InputFile(path="graph_a.dot", token_count=420);
    file_b = InputFile(path="graph_b.dot", token_count=315);

    decision_ll1 = Decision(decision_id=1, ll1=True);
    decision_adaptive = Decision(decision_id=2, ll1=False);

    state_a = DfaState(state_id=10, learned=True);
    state_b = DfaState(state_id=11, learned=True);
    state_c = DfaState(state_id=12, learned=False);

    root +>:ContainsInput(ordinal=1):+> file_a;
    root +>:ContainsInput(ordinal=2):+> file_b;
    file_a +>:UsesAtn(cacheable=True):+> atn;
    file_b +>:UsesAtn(cacheable=True):+> atn;

    atn +>:HasDecision(index=0):+> decision_ll1;
    atn +>:HasDecision(index=1):+> decision_adaptive;
    decision_ll1 +>:CachedDfa(learned_for="DOT"): +> state_a;
    decision_adaptive +>:CachedDfa(learned_for="DOT"): +> state_b;

    state_a +>:NextState(token_kind=1):+> state_b;
    state_b +>:NextState(token_kind=2):+> state_c;
    state_c +>:NextState(token_kind=3):+> state_a;

    root spawn PerformanceAuditor();
}

"""Demonstrate running a flow from a selected task with cycle protection."""

node Flow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has needs_skipped_output: bool = False;
    has output_ready: bool = False;
}

edge NextTask {
    has ordinal: int = 0;
}

walker RunFromHere {
    has visited_ids: list[str] = [];
    has started: bool = False;

    can execute with Task entry {
        if not self.started {
            print(f"Run from here: {here.title}");
            self.started = True;
        }

        if here.task_id in self.visited_ids {
            print(f"Cycle detected at {here.title}; stopping");
            disengage;
        }

        self.visited_ids.append(here.task_id);

        if here.needs_skipped_output and not here.output_ready {
            print(f"Warning: {here.title} expects output from skipped upstream tasks");
        }

        if not here.available {
            print(f"Skipped unavailable task: {here.title}");
        } else {
            print(f"Executing {here.title}");
            here.output_ready = True;
        }

        visit [->:NextTask:->] else {
            print("Downstream traversal complete");
            disengage;
        }
    }
}

with entry {
