    task_a = Task(task_id="A", title="Task A");
    task_b = Task(task_id="B", title="Task B");
    task_c = Task(
        task_id="C",
        title="Task C",
        needs_skipped_output=True
    );
    task_d = Task(task_id="D", title="Task D");
    cycle_a = Task(task_id="X", title="Cycle X");
    cycle_b = Task(task_id="Y", title="Cycle Y");

    root ++> pipeline ++> task_a;
    task_a +>:NextTask(ordinal=1):+> task_b;
    task_b +>:NextTask(ordinal=2):+> task_c;
    task_c +>:NextTask(ordinal=3):+> task_d;
    cycle_a +>:NextTask(ordinal=1):+> cycle_b;
    cycle_b +>:NextTask(ordinal=2):+> cycle_a;

    task_c spawn RunFromHere();
    cycle_a spawn RunFromHere();
}

