"""CAP-01 support audit: walk capability, profile, route, and bounded evidence links."""

node Capability {
    has title: str = "";
    has feature_id: str = "";
    has profile_id: str = "";
    has route_id: str = "";
    has activity_id: str = "";
    has fixture_id: str = "";
}

node SupportProfile {
    has title: str = "";
    has profile_id: str = "";
    has parser_mode: str = "deferred";
    has explicitly_opted_in: bool = False;
}

node PublicRoute {
    has title: str = "";
    has route_id: str = "";
    has profile_id: str = "";
    has activity_id: str = "";
    has fixture_id: str = "";
    has route_kind: str = "deferred";
    has implementation_supported: bool = False;
    has documented_support: bool = False;
}

node EvidenceFixture {
    has title: str = "";
    has fixture_id: str = "";
    has profile_id: str = "";
    has route_id: str = "";
    has activity_id: str = "";
    has artifact_id: str = "";
    has bounded: bool = False;
}

edge ProfileBinding {
    has profile_id: str = "";
}

edge RouteBinding {
    has route_id: str = "";
}

edge EvidenceBinding {
    has fixture_id: str = "";
}

walker SupportAuditor {
    has steps: int = 0;
    has max_steps: int = 32;
    has accepted: int = 0;
    has rejected: int = 0;
    has candidate: bool = False;
    has expected_profile_id: str = "";
    has expected_route_id: str = "";
    has expected_activity_id: str = "";
    has expected_fixture_id: str = "";

    can start with Root entry {
        print("CAP-01 support audit");
        visit [-->] else { disengage; }
    }

    can inspect_capability with Capability entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the cycle/depth guard");
            disengage;
        } else {
            self.steps += 1;
            self.expected_profile_id = here.profile_id;
            self.expected_route_id = here.route_id;
            self.expected_activity_id = here.activity_id;
            self.expected_fixture_id = here.fixture_id;
            print(f"feature {here.feature_id}: checking route {here.route_id}");
            visit [->:ProfileBinding:->] else { disengage; }
        }
    }

    can inspect_profile with SupportProfile entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the cycle/depth guard");
            disengage;
        } else {
            self.steps += 1;
            if here.explicitly_opted_in and here.parser_mode == "v1" {
                print(f"profile {here.profile_id}: explicitly opted-in V1 route");
            } else {
                print(f"profile {here.profile_id}: ordinary deferred parser");
            }
            visit [->:RouteBinding:->] else { disengage; }
        }
    }

    can inspect_route with PublicRoute entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the cycle/depth guard");
            disengage;
        } else {
            self.steps += 1;
            self.candidate = here.route_kind == "v1"
                and here.implementation_supported
                and here.documented_support
                and here.profile_id == self.expected_profile_id
                and here.route_id == self.expected_route_id
                and here.activity_id == self.expected_activity_id
                and here.fixture_id == self.expected_fixture_id;

            if self.candidate {
                print(f"route {here.route_id}: profile and activity bindings match");
            } else {
                self.rejected += 1;
                if here.route_kind == "deferred" {
                    print(f"REJECT {here.route_id}: documentation is overbroad");
                } else {
                    print(f"REJECT {here.route_id}: support documentation is stale");
                }
            }
            visit [->:EvidenceBinding:->] else { disengage; }
        }
    }

    can inspect_fixture with EvidenceFixture entry {
        if self.steps >= self.max_steps {
            print("Traversal stopped at the cycle/depth guard");
            disengage;
        } else {
            self.steps += 1;
            if self.candidate
                and here.bounded
                and here.fixture_id == self.expected_fixture_id
                and here.profile_id == self.expected_profile_id
                and here.route_id == self.expected_route_id
                and here.activity_id == self.expected_activity_id {
                self.accepted += 1;
                print(f"ACCEPT {here.artifact_id}: bounded evidence identity confirmed");
            } else {
                if self.candidate {
                    self.rejected += 1;
                }
                print(f"REJECT {here.artifact_id}: evidence is not an exact bounded fixture");
            }
            self.candidate = False;
        }
    }

    can report with Root exit {
        print(f"support result: {self.accepted} accepted, {self.rejected} rejected");
    }
}

