        }
    }

    can inspect_session with Session entry {
        if here.session_id == self.completion_session_id {
            if self.completion_session_id != self.current_session_id {
                self.stale_completion_blocked = True;
                print(f"blocked stale {self.operation} completion from "
                      f"session {here.session_id}");
            }
        }

        if here.session_id == self.current_session_id {
            self.successor_session_seen = True;
        }

        visit [-->] else {
            disengage;
        }
    }

    can inspect_resource with Runtime | Invite | Peer entry {
        if self.operation == "accept" {
            if here.resource_kind == "invite" {
                if here.owner_session_id == self.current_session_id {
                    if here.resource_id == self.current_pending_invite_id {
                        if here.pending == True {
                            self.successor_invite_preserved = True;
                            print(f"pending invite {here.resource_id} remains "
                                  f"owned by successor");
                        }
                    }
                }
            }
        }

        if self.operation == "leave" {
            if here.resource_kind == "runtime" {
                if here.owner_session_id == self.current_session_id {
                    if here.resource_id == self.current_manager_id {
                        if here.cleaned == False {
                            self.successor_runtime_preserved = True;
                            print(f"successor runtime {here.resource_id} "
                                  f"was not cleaned");
                        }
                    }
                }
            }
        }

        visit [-->] else {
            disengage;
        }
    }
}

