"""BELIEF R4/R5 closeout: preserve evidence while auditing dependencies safely."""

node ExperimentLane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has route: str = "";
    has retired: bool = False;
}

node ArchiveArtifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has immutable: bool = True;
}

node PullRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has number: int = 0;
    has disposition: str = "";
}

edge Preserves {
    has manifest_ref: str = "";
}

edge Reviews {
    has disposition: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker EvidenceAuditor {
    can begin with Root entry {
        print("Auditing preserved BELIEF evidence");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_lane with ExperimentLane entry {
        print(f"lane: {here.title} route={here.route}");
        visit [->:Preserves:->] else {
            disengage;
        }
    }

    can inspect_artifact with ArchiveArtifact entry {
        print(f"artifact: {here.title} kind={here.kind} immutable={here.immutable}");
    }
}

walker DependencyAuditor {
    has depth: int = 0;
    has max_depth: int = 4;

    can begin with Root entry {
        print("Auditing reusable engineering and dependency safety");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_lane with ExperimentLane entry {
        print(f"reviewing retired lane: {here.title}");
        visit [->:Reviews:->] else {
            disengage;
        }
    }

    can inspect_request with PullRequest entry {
        if self.depth >= self.max_depth {
            print(f"cycle/depth guard stopped at PR #{here.number}");
            disengage;
        } else {
            print(f"PR #{here.number}: {here.disposition}");
            prior_depth = self.depth;
            self.depth = prior_depth + 1;
            visit [->:DependsOn:->] else {
                print(f"PR #{here.number} has no further dependency");
            }
            self.depth = prior_depth;
        }
    }
}

