    );

    root ++> lane;

    lane +>:Preserves(manifest_ref="r4-terminal-manifest"):+> result;
    lane +>:Preserves(manifest_ref="r5-recovery-logs"):+> measurements;

    lane +>:Reviews(disposition="close unless policy question remains"):+> pr179;
    lane +>:Reviews(disposition="replace with compact closeout"):+> pr125;

    pr179 +>:DependsOn(reason="historical documentation context"):+> pr125;
    pr125 +>:DependsOn(reason="legacy stack dependency cycle"):+> pr179;

    root spawn EvidenceAuditor();
    root spawn DependencyAuditor(max_depth=4);
}

