    has work_type: str = "";
    has product_impact: bool = False;
    has phase: str = "TERMINAL";
    has work_digest: str = "";
    has provider_claimed: bool = False;

    def reconcile() -> bool {
        if self.phase != "CREATED" { return False; }
        self.phase = "RECONCILE";
        return True;
    }

    def authorize() -> bool {
        if self.phase != "RECONCILE" { return False; }
        self.phase = "AUTHORIZE";
        return True;
    }

    def claim_executor() -> bool {
        if self.phase != "AUTHORIZE" or not self.available { return False; }
        self.provider_claimed = True;
        self.phase = "CLAIMED";
        return True;
    }

    def complete() -> bool {
        if self.phase != "CLAIMED" { return False; }
        self.phase = "TERMINAL";
        return True;
    }
}

node ControlPlane {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has active_runs: int = 0;
    has broken_runs: int = 0;
    has multiple_active: bool = False;
    has exact_main: str = "";
    has refreshed_main: str = "";
    has refresh_ok: bool = True;
    has provider_refreshed: bool = False;
    has queue_valid: bool = True;
    has policy_allows: bool = True;
    has health_ok: bool = True;
    has cost_ok: bool = True;
    has created_runs: int = 0;
    has selected_issue: int = 0;
    has selected_roadmap: str = "";
    has bootstrap_result: str = "IDLE";
    has successor_phase: str = "NONE";
    has provider_write_authorized: bool = False;
    has ci_authority: bool = False;
    has merge_authority: bool = False;

    def force_refresh() -> bool {
        if not self.refresh_ok { return False; }
        self.refreshed_main = self.exact_main;
        self.provider_refreshed = self.refreshed_main == self.exact_main;
        return self.provider_refreshed;
    }

    def new_run_allowed() -> bool {
        return self.active_runs == 0 and self.broken_runs == 0
            and not self.multiple_active and self.created_runs == 0;
    }

    def authorize_next_action(item: RoadmapItem) -> bool {
        if not self.new_run_allowed() or not self.provider_refreshed {
            return False;
        }
        if not self.queue_valid or not self.policy_allows
            or not self.health_ok or not self.cost_ok {
            return False;
        }
        if not item.ready or not item.claimable or item.human_required
            or not item.conflict_clear or not item.dependencies_satisfied {
            return False;
        }
        return item.roadmap_id != "" and item.issue_number > 0;
    }
}

edge RoadmapSlot {
    has roadmap_order: int = 0;
}

edge DependsOn {
    has satisfied: bool = True;
}

edge Materializes {
    has issue_number: int = 0;
}

edge History { }

walker IdleBootstrap {
    has controller: ControlPlane;
    has created: bool = False;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can refresh with ControlPlane entry {
        if not here.new_run_allowed() {
            here.bootstrap_result = "IDLE_FAIL_CLOSED";
            disengage;
        }
        if not here.force_refresh() {
            here.bootstrap_result = "IDLE_FAIL_CLOSED";
            disengage;
        }
        visit [->:RoadmapSlot:->] else {
            here.bootstrap_result = "ROADMAP_COMPLETE_OR_EMPTY";
            disengage;
        }
    }

    can authorize with RoadmapItem entry {
        if not self.created and self.controller.authorize_next_action(here) {
            fresh_run = DurableRun(
                title=here.title,
                roadmap_id=here.roadmap_id,
                issue_number=here.issue_number,
                risk=here.risk,
                work_type=here.work_type,
                product_impact=here.product_impact,
                phase="CREATED",
                work_digest=f"digest:{here.roadmap_id}:{here.issue_number}:{here.title}"
            );
            here +>:Materializes(issue_number=here.issue_number):+> fresh_run;
            here.selected = True;
            self.created = True;
            self.controller.created_runs = self.controller.created_runs + 1;
            self.controller.active_runs = 1;
            self.controller.selected_issue = here.issue_number;
            self.controller.selected_roadmap = here.roadmap_id;
            self.controller.bootstrap_result = "CLAIM_ONE_READY_ALLOW";
        }
    }
}

walker RuntimeSupervisor {
    has controller: ControlPlane;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect with ControlPlane entry {
        visit [->:RoadmapSlot:->] else { disengage; }
    }

    can handoff with RoadmapItem entry {
        visit [->:Materializes:->] else { skip; }
    }

    can advance with DurableRun entry {
        if here.reconcile() { print("phase=RECONCILE"); }
        if here.authorize() { print("phase=AUTHORIZE"); }
        if here.claim_executor() { print("phase=CLAIM via existing executor"); }
        if here.complete() {
            self.controller.active_runs = 0;
            self.controller.successor_phase = here.phase;
            print("phase=TERMINAL");
        }
    }
}

walker DependencyGuard {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can inspect with RoadmapItem entry {
        if here.key in self.seen {
            self.cycle_found = True;
            print(f"cycle blocked at {here.key}");
            disengage;
        }
        self.seen.append(here.key);
        visit [->:DependsOn:->] else { disengage; }
    }
}

