"""Queue closure audit with typed predecessor edges and explicit cycle detection."""

node Queue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has inspected: bool = False;
}

node Fact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fact_key: str = "";
    has queued: bool = False;
    has seen: bool = False;
    has cycle_hits: int = 0;
}

edge Contains {
    has queued_at: int = 0;
}

edge DependsOn {
    has relation: str = "";
}

walker QueueAuditor {
    has discovered_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Queue entry {
        here.inspected = True;
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can collect with Fact entry {
        if here.seen {
            here.cycle_hits = here.cycle_hits + 1;
            here.available = False;
            disengage;
        } else {
            here.seen = True;
            self.discovered_count = self.discovered_count + 1;
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

