    has declared_type: str = "";
}

edge Declares { }
edge DefaultsTo { }
edge HasField { }
edge FieldType { }

walker TypeResolver {
    has resolved_path: str = "";
    has field_count: int = 0;
    has unresolved_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_module with DesignModule entry {
        visit [->:Declares:->] else {
            disengage;
