    can inspect_struct with StructType entry {
        visit [->:HasField:->] else {
            disengage;
        }
    }

    can inspect_field with MemberField entry {
        self.field_count += 1;
        self.resolved_path = self.resolved_path + "." + here.field_name;
        visit [->:FieldType:->] else {
            disengage;
        }
    }
}

