"""Request-aware ALIAS traversal with explicit cycle detection."""

node InboundRequest {
    has inbound_host: str = "";
    has configured_host: str = "";
}

node LightningAddress {
    has username: str = "";
    has host: str = "";
    has mode: str = "DIRECT";
}

edge AliasTo { }

walker AliasCycleGuard {
    has request_host: str = "";
    has configured_host: str = "";
    has seen_usernames: list[str] = [];
    has hops: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter with InboundRequest entry {
        self.request_host = here.inbound_host;
        self.configured_host = here.configured_host;
        print(f"request arrived through {self.request_host}");
        visit [-->] else {
            disengage;
        }
    }

    can follow with LightningAddress entry {
        if here.username in self.seen_usernames {
            print(f"cycle detected at {here.username} after {self.hops} hops");
            disengage;
        } else {
            self.seen_usernames.append(here.username);
            self.hops = self.hops + 1;

            if here.host != self.configured_host && here.host != self.request_host {
                print(f"off-instance hop: {here.username}@{here.host}");
                disengage;
            } else {
                print(f"local hop: {here.username}@{here.host}");

                if here.mode == "ALIAS" {
                    visit [->:AliasTo:->] else {
                        disengage;
                    }
                } else {
                    print(f"final destination: {here.username}@{here.host}");
                    disengage;
                }
            }
        }
    }
}

