    has status: str = "unknown";
    has structured_content: str = "";
    has text_output: str = "";
}

edge UsesClient { }
edge ReturnsHealth { }

walker HealthCheck {
    has status: str = "unknown";
    has structured_content: str = "";
    has text_output: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can invoke with AllotMintHealthTool entry {
        print(f"Calling {here.name}");
        visit [->:UsesClient:->] else {
            disengage;
        }
