"""Bounded StarLang-style orchestration with typed providers, outcomes, budgets, and cycle detection."""

node Orchestration {
    has orchestration_id: str = "";
    has max_branches: int = 0;
    has max_depth: int = 0;
}

node Provider {
    has provider_id: str = "";
    has authorized: bool = False;
    has outcome: str = "unavailable";
    has depth: int = 1;
}

node Observation {
    has provider_id: str = "";
    has outcome: str = "failed";
    has item_count: int = 0;
    has provenance: str = "";
}

edge Candidate { }
edge Produced { }
edge Causal {
    has cause: str = "";
}

walker BoundedOrchestrator {
    has max_branches: int = 0;
    has max_depth: int = 0;
    has branches: int = 0;
    has success_count: int = 0;
    has partial_count: int = 0;
    has blocked_count: int = 0;
    has failed_count: int = 0;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can plan with Orchestration entry {
        if here.orchestration_id in self.visited {
            print(f"cycle blocked at orchestration {here.orchestration_id}");
            disengage;
        } else {
            self.visited.append(here.orchestration_id);
            self.max_branches = here.max_branches;
            self.max_depth = here.max_depth;
            visit [->:Candidate:->] else {
                disengage;
            }
        }
    }

    can invoke with Provider entry {
        if self.branches >= self.max_branches {
            print("branch budget exhausted");
            disengage;
        } else {
            self.branches += 1;

            if here.authorized {
                print(f"invoking authorized provider {here.provider_id}");

                if here.depth > self.max_depth {
                    print(f"depth budget blocked provider {here.provider_id}");
                    self.blocked_count += 1;
                    disengage;
                } else {
                    visit [->:Produced:->] else {
                        self.failed_count += 1;
                        disengage;
                    }
                }
            } else {
                print(f"provider {here.provider_id} is blocked");
                self.blocked_count += 1;
            }
        }
    }

    can collect with Observation entry {
        if here.outcome == "success" {
            self.success_count += 1;
        } else if here.outcome == "partial" {
            self.partial_count += 1;
            print(f"partial coverage from {here.provider_id}");
        } else if here.outcome == "blocked" {
            self.blocked_count += 1;
        } else {
            self.failed_count += 1;
        }

        print(f"{here.provider_id}: {here.outcome}, {here.item_count} items from {here.provenance}");
    }

    can report with Root exit {
        print(f"branches={self.branches}, success={self.success_count}, "
              f"partial={self.partial_count}, blocked={self.blocked_count}, "
              f"failed={self.failed_count}");
    }
}

walker CycleGuard {
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Orchestration entry {
        if here.orchestration_id in self.visited {
            print(f"cycle detected at {here.orchestration_id}");
            disengage;
        } else {
            self.visited.append(here.orchestration_id);
            visit [->:Candidate:->] else {
                disengage;
            }
        }
    }

    can follow with Provider entry {
        if here.provider_id in self.visited {
            print(f"provider cycle detected at {here.provider_id}");
            disengage;
        } else {
            self.visited.append(here.provider_id);
            visit [->:Causal:->] else {
                disengage;
            }
        }
    }
}

with entry {
    plan = Orchestration(
        orchestration_id="identity-enumeration-v1",
        max_branches=2,
        max_depth=2
    );

    provider_a = Provider(
        provider_id="identity-alpha",
        authorized=True,
        outcome="success",
        depth=1
    );
    provider_b = Provider(
        provider_id="identity-beta",
        authorized=True,
        outcome="partial",
        depth=1
    );
    provider_c = Provider(
        provider_id="identity-gamma",
        authorized=False,
        outcome="blocked",
        depth=1
    );

    observation_a = Observation(
        provider_id="identity-alpha",
        outcome="success",
        item_count=4,
        provenance="alpha-response"
    );
    observation_b = Observation(
        provider_id="identity-beta",
        outcome="partial",
        item_count=1,
        provenance="beta-response"
    );

    root ++> plan;
    plan +>:Candidate:+> provider_a;
    plan +>:Candidate:+> provider_b;
    plan +>:Candidate:+> provider_c;
    provider_a +>:Produced:+> observation_a;
    provider_b +>:Produced:+> observation_b;
    provider_a +>:Causal(cause="retry-link"):+> plan;

    root spawn BoundedOrchestrator();
    root spawn CycleGuard();
}

"""Benchmark graph demo with workload metadata, dependency traversal, and cycle detection."""

node BenchmarkWorkload {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has size: int = 0;
    has density: float = 0.0;
    has width: int = 0;
    has depth: int = 0;
    has critical_path: int = 0;
    has contention: int = 0;
    has heterogeneity: int = 0;
    has work_lower_bound: int = 0;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has work: int = 0;
}

node SchedulerPolicy {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has strategy: str = "";
    has deterministic: bool = True;
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has environment_digest: str = "";
    has source_identity: str = "";
    has comparable: bool = False;
}

edge Contains {
    has relation: str = "";
}

edge DependsOn {
    has cost: int = 1;
}

walker BenchmarkWalker {
    has seen_ids: list[str] = [];
    has visited_tasks: int = 0;
    has total_work: int = 0;
    has critical_path: int = 0;
    has work_lower_bound: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_workload with BenchmarkWorkload entry {
        self.critical_path = here.critical_path;
        self.work_lower_bound = here.work_lower_bound;
        print(f"workload {here.title}: size={here.size}, density={here.density}, "
              f"width={here.width}, depth={here.depth}, contention={here.contention}, "
              f"heterogeneity={here.heterogeneity}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with Task entry {
        if here.task_id in self.seen_ids {
            print(f"cycle detected; blocked dependency {here.task_id}");
        } else {
            self.seen_ids.append(here.task_id);
            self.visited_tasks += 1;
            self.total_work += here.work;
            print(f"task {here.task_id}: work={here.work}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect_metadata with SchedulerPolicy | Evidence entry {
        print(f"metadata {here.title}: available={here.available}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"tasks={self.visited_tasks}, total_work={self.total_work}, "
              f"critical_path={self.critical_path}, "
              f"work_lower_bound={self.work_lower_bound}");
    }
}

