    has seen: list[str] = [];

    can start with Root entry {
        print("Starting dependency audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Surface entry {
        print(f"Surface: {here.title}");
        visit [->:Uses:->] else {
            disengage;
