"""Two-sweep evaluation planning with dependency traversal and admission checks."""

node Package {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Criterion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has evaluation_mode: str = "scored";
    has extraction_ready: bool = False;
}

node Submission {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has ingest_status: str = "ok";
}

node WorkUnit {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stage: str = "";
    has judge_id: str | None = None;
    has judge_model: str = "";
    has question: str = "";
    has criterion_title: str = "";
    has submission_title: str = "";
    has done: bool = False;
}

edge Includes { }
edge PrerequisiteFor {
    has reason: str = "";
}
edge HasSubmission { }
edge PlanHead { }
edge NextUnit {
    has sequence: int = 0;
}

walker SweepPlanner {
    has seen: list[str] = [];

    can start with Root entry {
        print("Sweep 1: judged criteria in dependency order");
        visit [-->] else { disengage; }
    }

    can inspect with Package entry {
        print(f"package: {here.title}");
        visit [->:Includes:->] else { disengage; }
    }

    can order with Criterion entry {
        if here.title in self.seen {
            print(f"cycle detected at criterion {here.title}");
            disengage;
        } else {
            self.seen.append(here.title);
            if here.evaluation_mode == "deterministic" {
                print(f"admitted deterministic criterion: {here.title}");
            } else {
                if here.extraction_ready {
                    print(f"admitted scored criterion: {here.title}");
                } else {
                    print(f"blocked criterion: {here.title}");
                }
            }
            visit [->:PrerequisiteFor:->] else { disengage; }
        }
    }
}

walker PlanAuditor {
    can start with Root entry {
        print("Sweep 2: fixed judge, question, criterion, submission order");
        visit [-->] else { disengage; }
    }

    can inspect with Package entry {
        visit [->:PlanHead:->] else { disengage; }
    }

    can audit with WorkUnit entry {
        if here.stage == "extraction" {
            if here.done {
                print(f"[extraction done] {here.criterion_title} / {here.submission_title}");
            } else {
                print(f"[extraction blocked] {here.criterion_title} / {here.submission_title}");
            }
        } else if here.stage == "deterministic" {
            if here.judge_id is None {
                print(f"[deterministic only] {here.criterion_title} / judge=None");
            }
        } else {
            print(f"[scoring] {here.judge_model} -> {here.question} -> "
                  f"{here.criterion_title} -> {here.submission_title}");
        }
        visit [->:NextUnit:->] else { disengage; }
    }
}

walker AdmissionAuditor {
    can start with Root entry {
        print("Sweep 1 admission: accepted submissions only");
        visit [-->] else { disengage; }
    }

    can inspect with Package entry {
        visit [->:HasSubmission:->] else { disengage; }
    }

    can admit with Submission entry {
        if here.ingest_status == "ok" {
            print(f"admitted: {here.title}");
        } else if here.ingest_status == "low_confidence_ocr" {
            print(f"admitted with OCR warning: {here.title}");
        } else {
            print(f"quarantined; no scoring work: {here.title}");
        }
        visit [-->] else { disengage; }
    }
}

