"""Semantic code-intelligence graph with dependency cycle detection and reachability walks."""

node Artifact {
    has label: str = "";
    has state: str = "active";
}

node SourceFile(Artifact) {
    has language: str = "";
}

node Symbol(Artifact) {
    has kind: str = "";
}

edge Contains {
    has role: str = "";
}

edge Imports {
    has version: str = "";
}

walker DependencyAuditor {
    has seen: list[str] = [];
    has cycle_count: int = 0;
    has visited_count: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else { disengage; };
    }

    can inspect with SourceFile entry {
        if here.label in self.seen {
            self.cycle_count += 1;
            print(f"dependency cycle detected at {here.label}");
            disengage;
        } else {
            self.seen.append(here.label);
            self.visited_count += 1;
            print(f"auditing {here.label} ({here.language})");
            visit [->:Imports:->] else { disengage; };
        }
    }

    can summarize with Root exit {
        print(f"dependency audit visited {self.visited_count} files");
        print(f"dependency cycles found: {self.cycle_count}");
    }
}

walker DefinitionExplorer {
    has found: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else { disengage; };
    }

    can inspect with SourceFile entry {
        visit [->:Contains:->] else { disengage; };
    }

    can inspect with Symbol entry {
        self.found += 1;
        print(f"reachable symbol: {here.label} ({here.kind})");
        visit [->:Contains:->] else { disengage; };
    }

    can summarize with Root exit {
        print(f"definition walk found {self.found} symbols");
    }
}

with entry {
    parser = SourceFile(
        label="parser.py",
        state="indexed",
        language="Python"
    );
    graph = SourceFile(
        label="graph.ts",
        state="indexed",
        language="TypeScript"
    );
    parser_symbol = Symbol(
        label="parse_graph",
        state="indexed",
        kind="function"
    );
    graph_symbol = Symbol(
        label="build_index",
        state="indexed",
        kind="function"
    );

    root +>:Contains(role="entry source"):+> parser;
    parser +>:Contains(role="defines"):+> parser_symbol;
    parser +>:Imports(version="1.0"):+> graph;
    graph +>:Contains(role="defines"):+> graph_symbol;
    graph +>:Imports(version="1.0"):+> parser;

    root spawn DependencyAuditor();
    root spawn DefinitionExplorer();
}

"""Safe reconciliation of a live authoritative project graph."""

node Project {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has authoritative_revision: int = 0;
    has amendment_note: str = "";
}

node GraphRevision {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has revision: int = 0;
    has definition_digest: str = "";
}

node Transition {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has transition_id: str = "";
    has semantic_digest: str = "";
    has dependency_digest: str = "";
    has mutation_scope: str = "";
    has required_authority: str = "";
    has confirmed: bool = False;
    has executing: bool = False;
    has prerequisites_satisfied: bool = True;
    has historical_digest: str = "";
    has historical_revision: int = 0;
    has frontier_state: str = "WAITING";
}

node TargetedRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_id: str = "";
    has observed_revision: int = 0;
    has reconciled_revision: int = 0;
    has active_transition_id: str = "";
    has authority_digest: str = "";
    has authority_scope: str = "";
    has authority_kind: str = "";
    has confirmed_ids: list[str] = [];
    has checkpoint_evidence: str = "";
    has state: str = "WAITING";
}

edge OwnsRun { }
edge ObservesRevision { }
edge ContainsTransition { }
edge Supersedes { }
edge PrerequisiteFor {
    has relation: str = "";
}

walker Reconciler {
    has current_revision: int = 0;
    has observed_revision: int = 0;
    has active_transition_id: str = "";
    has authority_digest: str = "";
    has authority_scope: str = "";
    has authority_kind: str = "";
    has confirmed_ids: list[str] = [];
    has seen_ids: list[str] = [];
    has ready_count: int = 0;
    has waiting_count: int = 0;
    has cycle_detected: bool = False;
    has failed_closed: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Project entry {
        self.current_revision = here.authoritative_revision;
        print(f"authoritative graph@{self.current_revision}: {here.amendment_note}");
        visit [->:OwnsRun:->] else {
            disengage;
        }
    }

    can inspect with TargetedRun entry {
        self.observed_revision = here.observed_revision;
        self.active_transition_id = here.active_transition_id;
        self.authority_digest = here.authority_digest;
        self.authority_scope = here.authority_scope;
        self.authority_kind = here.authority_kind;
        self.confirmed_ids = here.confirmed_ids;

        if here.observed_revision != self.current_revision {
            here.reconciled_revision = self.current_revision;
            here.checkpoint_evidence =
                f"graph changed from @{here.observed_revision} to "
                f"authoritative @{self.current_revision}";
            print(here.checkpoint_evidence);
        }

        visit [->:ObservesRevision:->] else {
            disengage;
        }
    }

    can inspect with GraphRevision entry {
        if here.revision != self.current_revision {
            print(f"ignoring stale graph@{here.revision}");
            disengage;
        }

        print(f"recomputing frontier from graph@{here.revision}");
        visit [->:ContainsTransition:->] else {
            disengage;
        }
    }

    can inspect with Transition entry {
        if here.transition_id in self.seen_ids {
            self.cycle_detected = True;
            print(f"cycle detected at transition {here.transition_id}");
            disengage;
        }

        self.seen_ids = self.seen_ids + [here.transition_id];

        if here.transition_id == self.active_transition_id {
            if here.executing {
                if here.semantic_digest == self.authority_digest
                    and here.mutation_scope == self.authority_scope
                    and here.required_authority == self.authority_kind {
                    print(f"active authority remains valid for {here.transition_id}");
                } else {
                    self.failed_closed = True;
                    here.frontier_state = "BLOCKED";
                    print(f"failed closed: stale authority for {here.transition_id}");
                    disengage;
                }
            }
        }

        if here.transition_id in self.confirmed_ids {
            if here.semantic_digest == here.historical_digest {
                here.confirmed = True;
                here.frontier_state = "CONFIRMED";
                print(
                    f"preserved confirmed evidence for {here.transition_id} "
                    f"from graph@{here.historical_revision}"
                );
            } else {
                self.failed_closed = True;
                here.frontier_state = "BLOCKED";
                print(
                    f"rejected material redefinition of confirmed "
                    f"transition {here.transition_id}"
                );
                disengage;
            }
        }

        if here.confirmed {
            here.frontier_state = "CONFIRMED";
        } else {
            state_label = "READY" if here.prerequisites_satisfied else "WAITING";
            here.frontier_state = state_label;

            if here.prerequisites_satisfied {
                self.ready_count += 1;
                print(f"{here.transition_id}: READY");
            } else {
                self.waiting_count += 1;
                print(f"{here.transition_id}: WAITING for prerequisite");
            }
        }

        visit [->:PrerequisiteFor:->] else {
            disengage;
        }
    }
}

with entry {
    project = Project(
        title="Overcenter",
        authoritative_revision=2,
        amendment_note="inserted B before C and added independent D"
    );

    old_revision = GraphRevision(
