"""Recursive projection graph with typed mounts, remapped paths, and hidden members."""

node ProjectionItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has segment: str = "";
    has effective_path: str = "";
    has state_key: str = "";
    has exposed: bool = True;
    has terminal: bool = False;
}

node Plugin(ProjectionItem) {
    has kernel_name: str = "plugin-kernel";
}

node ProjectionGroup(ProjectionItem) {
    has relative: bool = True;
}

node ProjectedCall(ProjectionItem) {
    has route: str = "kernel-dispatch";
}

edge Contains { }

edge Exposes {
    has mount_segment: str = "";
    has root_patch: str = "";
}

walker ProjectionWalker {
    has steps: int = 0;
    has max_steps: int = 32;

    can start with Root entry {
        print("Walking recursively exposed members");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Plugin | ProjectionGroup | ProjectedCall entry {
        self.steps += 1;
        if self.steps >= self.max_steps {
            print("Traversal budget reached; cycle safety stops the walk");
            disengage;
        } else {
            if here.exposed {
                kind_label = "projection";
                if here.terminal {
                    kind_label = "callable";
                }
                print(f"{kind_label}: {here.effective_path}");
                if here.terminal {
                    print(f"  dispatch through shared state: {here.state_key}");
                }
                visit [->:Exposes:->] else {
                    disengage;
                }
            } else {
                print(f"hidden: {here.title}");
                disengage;
            }
        }
    }
}

