"""Dependency graph demo with typed edges, traversal, and cycle detection."""

node Design {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Signal {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has width: int = 1;
    has value: int = 0;
}

node Assignment {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has expression: str = "";
}

edge Contains { }
edge DependsOn {
    has reason: str = "";
}
edge Drives {
    has reason: str = "";
}

walker DependencyAudit {
    has seen_titles: list[str] = [];
    has steps: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Auditing design dependencies");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_design with Design entry {
        print(f"Design: {here.title}");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_assignment with Assignment entry {
        if here.title in self.seen_titles {
            self.cycle_found = True;
            print(f"Cycle detected at assignment {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.steps += 1;
            print(f"Evaluate {here.title}: {here.expression}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect_signal with Signal entry {
        if here.title in self.seen_titles {
            self.cycle_found = True;
            print(f"Cycle detected at signal {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.steps += 1;
            print(f"Read {here.title}, width={here.width}, value={here.value}");
            visit [->:Drives:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Audit steps: {self.steps}");
        print(f"Cycle found: {self.cycle_found}");
    }
}

with entry {
    design = Design(title="counter.v", year=2024);
    assignment = Assignment(
        title="next_state",
        expression="state + 1"
    );
    signal = Signal(
