    );

    root +>:Contains:+> design;
    design +>:Contains:+> assignment;
    assignment +>:DependsOn(reason="expression reads state"):+> signal;
    signal +>:Drives(reason="state update feeds expression"):+> assignment;

    root spawn DependencyAudit();
}

"""TaskSmack performance dependencies modeled as a typed graph."""

node WorkItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has invalidated: bool = False;
}

node Process(WorkItem) {
    has pid: int = 0;
}

node Chart(WorkItem) {
    has sample_period_ms: int = 1000;
}

node GpuProbe(WorkItem) {
    has vendor: str = "";
}

edge Contains { }

edge DependsOn {
    has reason: str = "";
}

walker InvalidationAudit {
    has seen_titles: list[str] = [];
    has visited_count: int = 0;
    has invalidated_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        visit [->:Contains:->] else { disengage; }
    }

    can inspect with Process | Chart | GpuProbe entry {
        if here.title in self.seen_titles {
            self.cycle_found = True;
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.visited_count += 1;
            here.invalidated = True;
            self.invalidated_count += 1;
            visit [->:DependsOn:->] else { disengage; }
        }
    }
}

