"""Failure propagation through shared dependencies and resources."""

node Service {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has bot: str = "";
    has feature: str = "";
}

node Dependency {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has failure_mode: str = "";
    has shared_bots: str = "";
}

node Resource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scope: str = "";
}

edge FailurePath {
    has shared: bool = False;
    has relation: str = "";
}

edge HoldsResource {
    has shared: bool = False;
    has relation: str = "";
}

walker FailurePropagator {
    has seen: list[str] = [];
    has impacted: list[str] = [];

    can start with Root entry {
        print("Tracing failure propagation from the selected dependency");
        visit [-->] else { disengage; }
    }

    can inspect_dependency with Dependency entry {
        if here.title in self.seen {
            print(f"cycle guard stopped at {here.title}");
            disengage;
        } else {
            self.seen.append(here.title);
            if here.available {
                print(f"dependency healthy: {here.title}");
            } else {
                print(f"failed dependency: {here.title} ({here.failure_mode})");
                visit [<--:FailurePath:--] else { disengage; }
            }
        }
    }

    can inspect_service with Service entry {
        if here.title in self.seen {
