    has available: bool = True;
}

node Artifact {
    has path: str = "";
    has size: int = 0;
    has sha256: str = "";
    has available: bool = True;
}

node ValidationGate {
    has name: str = "";
    has passed: bool = False;
    has required: bool = True;
    has available: bool = True;
}

edge Contains {
    has purpose: str = "";
}

edge Verifies {
    has expected: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker RecoveryAuditor {
    has seen: list[str] = [];
    has blocked: bool = False;

    can start with Root entry {
        print("Starting isolated checkout recovery audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with CheckoutAttempt entry {
        if here.attempt_id in self.seen {
            print(f"Cycle detected at attempt {here.attempt_id}; stopping safely");
            disengage;
        } else {
            self.seen.append(here.attempt_id);
            print(f"Attempt {here.attempt_id}: {here.state}");
            print(f"Expected commit: {here.expected_commit}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can inspect with Artifact entry {
        key = "artifact:" + here.path;
        if key in self.seen {
            print(f"Cycle detected at artifact {here.path}; stopping safely");
            disengage;
        } else {
            self.seen.append(key);
            print(f"Checking {here.path}: {here.size} bytes, SHA-256 {here.sha256}");
            visit [->:Verifies:->] else {
                disengage;
            }
        }
    }

    can inspect with ValidationGate entry {
        key = "gate:" + here.name;
        if key in self.seen {
            print(f"Cycle detected at gate {here.name}; stopping safely");
            disengage;
        } else {
            self.seen.append(key);
            if here.passed {
                print(f"[PASS] {here.name}");
            } else {
                print(f"[BLOCKED] {here.name}");
                self.blocked = True;
            }
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

