    has fresh: bool = True;
    has policy_prechecked: bool = False;
}

node Snapshot {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tenant_id: str = "";
    has fresh: bool = True;
    has trusted: bool = True;
}

node CacheEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tenant_id: str = "";
    has source_tenant_id: str = "";
    has cache_key: str = "";
    has fresh: bool = True;
    has authority: bool = False;
    has tenant_scoped: bool = True;
}

edge Owns {
    has relation: str = "context";
}

edge Produces { }

edge Invalidates { }

walker ContextAuditor {
    has examined: int = 0;
    has findings: int = 0;
    has max_examined: int = 32;
    has active_tenant: str = "";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_tenant with Tenant entry {
        self.examined += 1;
        self.active_tenant = here.tenant_id;
        print(f"tenant scope: {here.tenant_id}");

        if self.examined >= self.max_examined {
            print("walk stopped at the safety depth cap");
            disengage;
        } else {
            visit [->:Owns:->] else {
                disengage;
            }
        }
    }

    can inspect_context with Context entry {
        self.examined += 1;

        if here.tenant_id != self.active_tenant {
            self.findings += 1;
            print(f"[FINDING] context crosses tenant boundary: {here.title}");
        }

        if here.fresh == False and here.policy_prechecked == True {
            self.findings += 1;
            print(f"[FINDING] stale precheck cannot be authority: {here.title}");
        }

        if self.examined >= self.max_examined {
            print("walk stopped at the safety depth cap");
            disengage;
        } else {
            visit [->:Produces:->] else {
                disengage;
            }
        }
    }

    can inspect_snapshot with Snapshot entry {
        self.examined += 1;

        if here.fresh == False or here.trusted == False {
            self.findings += 1;
            print(f"[FINDING] unusable snapshot: {here.title}");
        }

        if self.examined >= self.max_examined {
            print("walk stopped at the safety depth cap");
            disengage;
        } else {
            visit [->:Invalidates:->] else {
                disengage;
            }
        }
    }

    can inspect_cache with CacheEntry entry {
        self.examined += 1;

        if here.tenant_id != here.source_tenant_id {
            self.findings += 1;
            print(f"[FINDING] cross-tenant cache poisoning: {here.cache_key}");
        }

        if here.tenant_scoped == False {
            self.findings += 1;
            print(f"[FINDING] cache-key collision risk: {here.cache_key}");
        }

        if here.fresh == False and here.authority == True {
            self.findings += 1;
            print(f"[FINDING] stale cache marked authoritative: {here.cache_key}");
        }
    }

    can report with Root exit {
        print(f"Audit complete: {self.examined} records, {self.findings} findings");
    }
}

