}

"""Bounded recursive template references with explicit validation state."""

node Template {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has reference_name: str = "";
    has is_reference: bool = False;
    has has_children: bool = False;
    has resolved: bool = False;
}

node DataValue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "$";
    has text: str = "";
}

edge Contains {
    has field_name: str = "";
}

edge UsesTemplate {
    has path: str = "";
}

edge NamedReference {
    has reference_name: str = "";
}

walker TemplateValidator {
    has label: str = "validator";
    has known_names: list[str] = [];
    has max_depth: int = 8;
    has steps: int = 0;
    has unresolved_count: int = 0;
    has cycle_count: int = 0;
    has limit_count: int = 0;
    has seen_names: list[str] = [];
    has path: str = "$";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can validate with DataValue entry {
        print(f"{self.label}: validating value at {here.path}");
        visit [->:UsesTemplate:->] else {
            disengage;
        }
    }

    can inspect with Template entry {
        next_path = f"{self.path} -> {here.name}";
        self.path = next_path;

        if here.name in self.seen_names {
            self.cycle_count += 1;
            print(f"{self.label}: recursive cycle at {self.path}");
            disengage;
        }

        if self.steps >= self.max_depth {
            self.limit_count += 1;
            print(f"{self.label}: depth limit {self.max_depth} at {self.path}");
            disengage;
        }

        self.seen_names.append(here.name);
        self.steps += 1;

        if here.is_reference {
            if here.reference_name in self.known_names {
                here.resolved = True;
                print(f"{self.label}: resolved '{here.reference_name}' at {self.path}");
            } else {
                self.unresolved_count += 1;
                print(f"{self.label}: unresolved '{here.reference_name}' at {self.path}");
            }
        }

        if here.has_children {
            visit [->:Contains:->] else {
                disengage;
            }
        }

        if here.is_reference {
            visit [->:NamedReference:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"{self.label}: unresolved={self.unresolved_count}, "
              f"cycles={self.cycle_count}, limits={self.limit_count}");
    }
}

