"""Evidence-grounded regression impact analysis with typed graph traversal."""

node ChangeSet {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has change_id: str = "";
    has summary: str = "";
    has diff: str = "";
    has requirements: str = "";
    has api_changes: str = "";
    has configuration_changes: str = "";
    has source_ref: str = "";
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_kind: str = "";
    has source_ref: str = "";
    has excerpt: str = "";
    has confidence: str = "unknown";
    has contradictory: bool = False;
}

node ProjectItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has item_kind: str = "";
    has item_name: str = "";
    has affected: bool = False;
    has impact_reason: str = "";
    has confidence: str = "unknown";
    has supporting_refs: str = "";
    has existing_tests: str = "";
    has recommended_scope: str = "";
    has coverage_gaps: str = "";
    has unknowns: str = "";
}

node ImpactReport {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has change_summary: str = "";
    has affected_items: str = "";
    has impact_reasons: str = "";
    has confidence: str = "unknown";
    has supporting_references: str = "";
    has recommended_regression_scope: str = "";
    has coverage_gaps: str = "";
    has unknowns: str = "";
}

edge ContainsChange {
    has relation: str = "change under analysis";
}

edge ContainsReport {
    has relation: str = "analysis result";
}

edge UsesEvidence {
    has relation: str = "retrieved evidence";
}

edge IgnoredEvidence {
    has relation: str = "unrelated evidence";
}

edge SupportsItem {
    has relation: str = "evidence-backed relationship";
}

edge RelatedItem {
    has relation: str = "dependency or workflow relationship";
}

walker ImpactAnalyzer {
    has remaining_depth: int = 4;
    has affected_count: int = 0;
    has unknown_count: int = 0;

    can start with Root entry {
        print("Starting regression-impact analysis");
        visit [-->] else { disengage; }
    }

    can inspect_change with ChangeSet entry {
        print(f"Change {here.change_id}: {here.summary}");
        print(f"Change provenance: {here.source_ref}");
        visit [->:UsesEvidence:->] else { disengage; }
    }

    can inspect_evidence with Evidence entry {
        print(f"Evidence [{here.source_kind}] {here.source_ref}");
        if here.confidence == "unknown" {
            print("Evidence confidence is unknown");
        }
        if here.contradictory {
            print("Conflicting evidence preserved as uncertainty");
        }
        visit [->:SupportsItem:->] else { disengage; }
    }

    can assess_item with ProjectItem entry {
        if here.affected {
            self.affected_count = self.affected_count + 1;
            print(f"AFFECTED {here.item_kind}: {here.item_name}");
            print(f"Reason: {here.impact_reason}");
            print(f"Confidence: {here.confidence}");
            print(f"Supporting references: {here.supporting_refs}");
            print(f"Recommended tests: {here.recommended_scope}");
            print(f"Existing tests: {here.existing_tests}");
            print(f"Coverage gaps: {here.coverage_gaps}");
        }
        if here.confidence == "unknown" {
            self.unknown_count = self.unknown_count + 1;
            print(f"Unknowns: {here.unknowns}");
        }

        if self.remaining_depth <= 0 {
            print("Cycle/depth guard stopped further dependency traversal");
        } else {
            self.remaining_depth = self.remaining_depth - 1;
            visit [->:RelatedItem:->] else { disengage; }
        }
    }

    can publish_report with ImpactReport entry {
        print("=== Regression Impact Report ===");
        print(f"Change summary: {here.change_summary}");
        print(f"Affected items: {here.affected_items}");
        print(f"Impact reasons: {here.impact_reasons}");
        print(f"Confidence: {here.confidence}");
        print(f"Supporting references: {here.supporting_references}");
        print(f"Recommended regression scope: {here.recommended_regression_scope}");
        print(f"Coverage gaps: {here.coverage_gaps}");
        print(f"Unknowns: {here.unknowns}");
    }

    can finish with Root exit {
        print(f"Analyzed affected items: {self.affected_count}");
        print(f"Items requiring uncertainty review: {self.unknown_count}");
    }
}

