"""WASM drawing pipeline stages modeled as a typed dependency graph."""

node Stage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge PipelineMember { }
edge DependsOn { }
edge Produces { }

walker DependencyPlanner {
    has steps: int = 0;
    has max_steps: int = 8;

    can start with Root entry {
        visit [->:PipelineMember:->] else {
            disengage;
        }
    }

    can plan with Stage entry {
        status = "ready" if here.available else "blocked";
        self.steps += 1;
        print(f"{self.steps}: {here.title} ({status})");

        if here.available && self.steps < self.max_steps {
            visit [->:DependsOn:->] else {
                disengage;
            }
        } else {
            print(f"stopped at {here.title}");
            disengage;
        }
    }
}

walker ArtifactAuditor {
    can start with Root entry {
        visit [->:PipelineMember:->] else {
            disengage;
        }
    }

    can inspect with Stage entry {
        visit [->:Produces:->] else {
            disengage;
        }
    }

    can report with Artifact entry {
        status = "usable" if here.available else "invalid";
        print(f"artifact {here.title} ({here.year}): {status}");
        disengage;
    }
}

