walker PromotionAuditor {
    has seen_ids: list[str] = [];
    has checked_packages: int = 0;
    has promotion_allowed: bool = True;

    can begin with Root entry {
        print("Auditing the tested candidate and its immutable dependencies");
        visit [-->] else { disengage; }
    }

    can inspect with FlowPackage entry {
        if here.package_id in self.seen_ids {
            self.promotion_allowed = False;
            print(f"Cycle detected at package {here.package_id}; promotion rejected");
            print("Audit result: REJECT; cycle guard stopped the walk");
            disengage;
        } else {
            self.seen_ids.append(here.package_id);
            self.checked_packages += 1;
            if (not here.immutable) or (not here.tested) or (not here.approved) or
               (not here.provenance_complete) or (not here.registered_graph) or
               (not here.tools_compatible) or (not here.jurisdiction_compatible) or
               here.review_expired or (not here.configuration_only) {
                self.promotion_allowed = False;
                print(f"Package {here.flow_version} failed fail-closed promotion checks");
            } else {
                print(f"Verified {here.package_id}: hash {here.definition_hash}, suite {here.suite_version}");
