"""Dependency-aware page-cache invalidation for custom and shared sources."""

node Project {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node CacheEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has recorded_revision: int = 0;
    has invalidated: bool = False;
}

node Source {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has revision: int = 0;
    has is_directory: bool = False;
}

edge Fingerprints {
    has reason: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker CacheAuditor {
    has newest_revision: int = 0;
    has cache_title: str = "";
    has cycle_found: bool = False;
    has visited_paths: list[str] = [];
    has cache_entry: CacheEntry | None = None;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_project with Project entry {
        visit [-->];
    }

    can inspect_cache with CacheEntry entry {
        self.cache_title = here.title;
        self.cache_entry = here;
        visit [->:Fingerprints:->];
    }

    can inspect_source with Source entry {
        if here.path in self.visited_paths {
            self.cycle_found = True;
            print(f"cycle guarded at {here.path}");
        } else {
            self.visited_paths.append(here.path);
            if here.revision > self.newest_revision {
                self.newest_revision = here.revision;
            }
            kind = "directory" if here.is_directory else "file";
            print(f"fingerprint {kind} {here.path} at revision {here.revision}");
            visit [->:DependsOn:->];
        }
    }

    can `report with exit {
        if self.cache_entry is not None {
            if self.newest_revision > self.cache_entry.recorded_revision {
                self.cache_entry.invalidated = True;
            }
            status = "INVALIDATED" if self.cache_entry.invalidated else "VALID";
            print(f"{status}: {self.cache_title}, newest revision {self.newest_revision}");
            print(f"cycle detected: {self.cycle_found}");
            report {
                "cache": self.cache_title,
                "status": status,
                "newest_revision": self.newest_revision,
                "cycle_detected": self.cycle_found
            };
        }
    }
}

