"""Audited promotion demo for immutable flow packages."""

node FlowPackage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has package_id: str = "";
    has flow_version: str = "";
    has definition_hash: str = "";
    has suite_version: str = "";
    has immutable: bool = True;
    has tested: bool = False;
    has approved: bool = False;
    has provenance_complete: bool = False;
    has registered_graph: bool = False;
    has tools_compatible: bool = False;
    has jurisdiction_compatible: bool = False;
    has review_expired: bool = False;
    has configuration_only: bool = True;

    def is_promotable() -> bool {
        return self.immutable and self.tested and self.approved and
            self.provenance_complete and self.registered_graph and
            self.tools_compatible and self.jurisdiction_compatible and
            (not self.review_expired) and self.configuration_only;
    }
}

