    has available: bool = True;
    has assignment_id: str = "";
    has jurisdiction: str = "";
    has case_type: str = "";
    has flow_version: str = "";
    has active: bool = False;
    has closed: bool = False;
    has rollback_target: str = "";
    has transaction_id: str = "";
    has approver: str = "";
