edge UsesFlow { }
edge PinnedTo { }

walker PromotionAuditor {
    has seen_ids: list[str] = [];
    has checked_packages: int = 0;
    has promotion_allowed: bool = True;

    can begin with Root entry {
        print("Auditing candidate and immutable dependencies");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with FlowPackage entry {
        if here.package_id in self.seen_ids {
            self.promotion_allowed = False;
            print(f"Cycle detected at package {here.package_id}; rejected");
            disengage;
        }

        self.seen_ids.append(here.package_id);
        self.checked_packages += 1;

        if here.is_promotable() {
            print(f"Verified {here.package_id}: {here.definition_hash}");
        } else {
            self.promotion_allowed = False;
            print(f"Package {here.package_id} failed fail-closed checks");
        }

        visit [->:DependsOn:->] else {
            decision = "PROMOTE" if self.promotion_allowed else "REJECT";
            print(f"Audit result: {decision}; checked {self.checked_packages} package(s)");
            disengage;
        }
    }
}

