"""Curation coverage demo: walk MONDO parents to find exact and ancestor coverage."""

node Concept {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mondo_id: str = "";
    has curated_by: str = "";
}

node QueueStub {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has stub_id: str = "";
}

node CurationEntry {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has entry_name: str = "";
    has anchor_mondo: str = "";
}

edge Targets {
    has relation: str = "queue target";
}

edge SubClassOf {
    has relation: str = "MONDO subClassOf";
}

edge Covers {
    has mapping_note: str = "";
}

walker CoveragePreflight {
    has origin_mondo: str = "";
    has visited_ids: list[str] = [];
    has exact_hits: int = 0;
    has ancestor_hits: int = 0;
    has cycle_hits: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_stub with QueueStub entry {
        self.origin_mondo = here.stub_id;
        self.visited_ids = [];
        print(f"checking queue stub {here.title}");
        visit [->:Targets:->] else {
            disengage;
        }
    }

    can inspect_concept with Concept entry {
        if here.mondo_id in self.visited_ids {
            self.cycle_hits += 1;
            print(f"cycle guard stopped at {here.mondo_id}");
            disengage;
        }

        self.visited_ids.append(here.mondo_id);

        if here.curated_by != "" {
            if here.mondo_id == self.origin_mondo {
                self.exact_hits += 1;
                print(f"exact coverage: {here.mondo_id} via {here.curated_by}");
            } else {
                self.ancestor_hits += 1;
                print(f"ancestor coverage: {here.mondo_id} via {here.curated_by}");
            }
        } else {
            print(f"not yet covered: {here.mondo_id}");
        }

        visit [->:SubClassOf:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"preflight summary: exact={self.exact_hits}, "
              f"ancestor={self.ancestor_hits}, cycles={self.cycle_hits}");
    }
}

