"""Bounded predictive COPC prefetch with separate visible and cache state."""

node CameraView {
    has motion_magnitude: float = 0.0;
    has motion_threshold: float = 0.05;
    has generation: int = 0;
    has stationary: bool = True;
    has visible_work_pending: bool = False;
}

node PrefetchPlan {
    has generation: int = 0;
    has direction: str = "";
    has active: bool = True;
    has queued: bool = True;
}

node CopcNode {
    has label: str = "";
    has side: str = "";
    has depth: int = 0;
    has points: int = 0;
    has selected: bool = False;
    has rendered: bool = False;
    has decoded: bool = False;
    has queued: bool = False;
    has prefetch_generation: int = 0;
    has cache_priority: str = "normal";
}

edge Visible { }
edge Predicts { has generation: int = 0; }
edge NextPlan { has reason: str = ""; }
edge Targets { has expected_points: int = 0; }
edge Hierarchy { has relation: str = "child"; }

walker PredictivePrefetcher {
    has active_generation: int = 0;
    has predicted_direction: str = "";
    has visible_work_waiting: bool = False;
    has stationary: bool = False;
    has queued_nodes: int = 0;
    has prefetch_points: int = 0;
    has queue_limit: int = 3;
    has prefetch_point_limit: int = 1200;
    has depth_limit: int = 3;
    has stale_dropped: int = 0;
    has skipped_current: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_view with CameraView entry {
        self.active_generation = here.generation;
        self.visible_work_waiting = here.visible_work_pending;
        if here.stationary == True {
            self.stationary = True;
            disengage;
        }
        if here.motion_magnitude <= here.motion_threshold {
            self.stationary = True;
            disengage;
        }
        visit [->:Predicts:->] else { disengage; }
    }

    can inspect_plan with PrefetchPlan entry {
        self.predicted_direction = here.direction;
        if here.active == False {
            self.stale_dropped += 1;
            visit [->:NextPlan:->] else { disengage; }
        } else {
            if here.generation != self.active_generation {
                self.stale_dropped += 1;
                visit [->:NextPlan:->] else { disengage; }
            } else {
                visit [->:Targets:->] else { disengage; }
            }
        }
    }

    can inspect_node with CopcNode entry {
        eligible = True;
        if here.selected == True {
            eligible = False;
            self.skipped_current += 1;
        }
        if here.rendered == True {
            eligible = False;
            self.skipped_current += 1;
        }
        if here.decoded == True {
            eligible = False;
            self.skipped_current += 1;
        }
        if self.visible_work_waiting == True {
            eligible = False;
            self.skipped_current += 1;
        }
        if here.side != self.predicted_direction {
            eligible = False;
        }
        if eligible == False {
            if here.depth < self.depth_limit {
                visit [->:Hierarchy:->] else { disengage; }
            } else {
                disengage;
            }
        } else {
            if self.queued_nodes >= self.queue_limit {
                disengage;
            } else {
                if self.prefetch_points + here.points > self.prefetch_point_limit {
                    disengage;
                } else {
                    here.queued = True;
                    here.prefetch_generation = self.active_generation;
                    here.cache_priority = "speculative";
                    self.queued_nodes += 1;
                    self.prefetch_points += here.points;
                    if here.depth < self.depth_limit {
                        visit [->:Hierarchy:->] else { disengage; }
                    } else {
                        disengage;
                    }
                }
            }
        }
    }
}

with entry {
    view = CameraView(
        motion_magnitude=1.0,
