"""Bounded predictive COPC prefetch with stale-plan suppression and cache-safe traversal."""

node CameraView {
    has title: str = "";
    has motion_magnitude: float = 0.0;
    has motion_threshold: float = 0.05;
    has generation: int = 0;
    has stationary: bool = True;
    has visible_work_pending: bool = False;
    has predicted_direction: str = "";
}

node PrefetchPlan {
    has title: str = "";
    has generation: int = 0;
    has direction: str = "";
    has active: bool = True;
    has queued: bool = True;
}

node CopcNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has side: str = "";
    has depth: int = 0;
    has points: int = 0;
    has selected: bool = False;
    has rendered: bool = False;
    has decoded: bool = False;
    has queued: bool = False;
    has plan_generation: int = 0;
    has cache_priority: str = "normal";
}

edge Predicts {
    has generation: int = 0;
}

edge Targets {
    has expected_points: int = 0;
}

edge Hierarchy {
    has relation: str = "child";
}

edge Visible {
}

walker PredictivePrefetcher {
    has active_generation: int = 0;
    has predicted_direction: str = "";
    has stationary: bool = False;
    has visible_work_waiting: bool = False;
    has queued_nodes: int = 0;
    has prefetch_points: int = 0;
    has queue_limit: int = 3;
    has prefetch_point_limit: int = 1200;
    has depth_limit: int = 3;
    has stale_dropped: int = 0;
    has skipped_current: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_view with CameraView entry {
        self.active_generation = here.generation;
        self.predicted_direction = here.predicted_direction;
        self.visible_work_waiting = here.visible_work_pending;

        if here.stationary {
            self.stationary = True;
            print("stationary camera: predictive queue drained");
            disengage;
        }

        if here.motion_magnitude <= here.motion_threshold {
            self.stationary = True;
            print("motion below threshold: no future region");
            disengage;
        }

        if self.visible_work_waiting {
            print("visible work has priority over predictive work");
            disengage;
        }

        print(f"predicting generation {self.active_generation} toward {self.predicted_direction}");
        visit [->:Predicts:->] else {
            disengage;
        }
    }

    can inspect_plan with PrefetchPlan entry {
        if here.active == False {
            self.stale_dropped += 1;
            print(f"dropping inactive prefetch plan {here.title}");
        } elif here.generation != self.active_generation {
            self.stale_dropped += 1;
            print(f"dropping stale prefetch plan {here.title}");
        } elif here.direction != self.predicted_direction {
            self.stale_dropped += 1;
            print(f"dropping superseded direction {here.direction}");
        } else {
            print(f"examining bounded prefetch plan {here.title}");
        }

        visit [->:Targets:->] else {
            print(f"prefetch plan {here.title} has no candidates");
        }
    }

    can inspect_node with CopcNode entry {
        if here.plan_generation != self.active_generation {
            self.stale_dropped += 1;
            print(f"ignoring stale candidate {here.title}");
        } elif here.selected {
            self.skipped_current += 1;
            print(f"current selected node stays outside prefetch queue: {here.title}");
        } elif here.rendered {
            self.skipped_current += 1;
            print(f"current rendered node stays outside prefetch queue: {here.title}");
        } elif here.decoded {
            self.skipped_current += 1;
            print(f"decoded cache hit avoids prefetch: {here.title}");
        } elif self.queued_nodes >= self.queue_limit {
            print(f"queue limit keeps {here.title} out of speculative work");
        } elif self.prefetch_points + here.points > self.prefetch_point_limit {
            print(f"point budget keeps {here.title} out of speculative work");
        } else {
            here.queued = True;
            here.cache_priority = "speculative";
            self.queued_nodes += 1;
            self.prefetch_points += here.points;
            print(f"queued speculative node {here.title} ({here.points} points)");
        }

        if here.depth < self.depth_limit {
            visit [->:Hierarchy:->] else {
                print(f"no deeper hierarchy below {here.title}");
            }
        }
    }

    can report with Root exit {
        print(f"prefetch summary: queued={self.queued_nodes}, points={self.prefetch_points}, stale={self.stale_dropped}");
    }
}

