"""Recursive registry revalidation with typed retained references."""

node RegistryRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has code: str = "";
    has state: str = "valid";
    has audit_seen: bool = False;
    has projection: str = "";

    def locally_valid() -> bool {
        if self.state != "valid" {
            return False;
        }
        return True;
    }

    def revalidate() -> bool {
        return self.locally_valid();
    }

    def logical_values() -> str {
        if self.revalidate() {
            return self.code;
        }
        return "<rejected>";
    }
}

