"""Candidate-bound workflow validation with parent reuse, invalidation, and cycle detection."""

node Candidate {
    has candidate_id: str = "";
    has engineering_digest: str = "";
    has command_set: str = "";
    has validator: str = "";
    has platform: str = "";
    has target_revision: int = 0;
}

node Delivery {
    has delivery_id: str = "";
    has target_revision: int = 0;
    has source_changed: bool = False;
    has evidence_only: bool = False;
    has receipt_stale: bool = False;
    has invalidated: bool = False;
}

node Proof {
    has proof_id: str = "";
    has candidate_digest: str = "";
    has command_set: str = "";
    has validator: str = "";
    has platform: str = "";
    has valid: bool = True;
    has use_count: int = 0;
    has reused: bool = False;
}

edge CandidateDelivery { }
edge ParentDelivery {
    has reason: str = "";
}
edge UsesProof {
    has mode: str = "";
}

walker DeliveryValidator {
    has expected_target: int = 0;
    has seen_deliveries: list[str] = [];

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can select with Candidate entry {
        self.expected_target = here.target_revision;
        print(f"candidate {here.candidate_id} is bound to revision {here.target_revision}");
        visit [->:CandidateDelivery:->] else {
            disengage;
        }
    }

    can validate with Delivery entry {
        if here.delivery_id in self.seen_deliveries {
            print(f"cycle detected at delivery {here.delivery_id}; stopping safely");
            disengage;
        } else {
            self.seen_deliveries.append(here.delivery_id);

            if here.invalidated {
                print(f"{here.delivery_id}: proof invalidated");
            } else {
                if here.source_changed {
                    print(f"{here.delivery_id}: product change invalidates engineering proof");
                } else {
                    if here.receipt_stale {
                        print(f"{here.delivery_id}: stale receipt rejected before commands");
                    } else {
                        if here.target_revision != self.expected_target {
                            print(f"{here.delivery_id}: target moved; revalidation required");
                        } else {
                            print(f"{here.delivery_id}: parent delivery structurally validated");
                        }
                    }
                }
            }

            visit [->:ParentDelivery:->] else {
                disengage;
            }
        }
    }
}

walker ProofAuditor {
    has expected_digest: str = "";
    has expected_command_set: str = "";
    has expected_validator: str = "";
    has expected_platform: str = "";
    has proof_allowed: bool = True;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Candidate entry {
        self.expected_digest = here.engineering_digest;
        self.expected_command_set = here.command_set;
        self.expected_validator = here.validator;
        self.expected_platform = here.platform;
        visit [->:CandidateDelivery:->] else {
            disengage;
        }
    }

    can prepare with Delivery entry {
        self.proof_allowed = True;

        if here.source_changed {
            self.proof_allowed = False;
        } else {
            if here.receipt_stale {
                self.proof_allowed = False;
            } else {
                if here.invalidated {
                    self.proof_allowed = False;
                }
            }
        }

        if here.evidence_only {
            print(f"{here.delivery_id}: evidence-only change uses structural validation");
        }

        visit [->:UsesProof:->] else {
            disengage;
        }
    }

    can audit with Proof entry {
        if self.proof_allowed {
            if here.valid {
                if here.candidate_digest == self.expected_digest {
                    if here.command_set == self.expected_command_set {
                        if here.validator == self.expected_validator {
                            if here.platform == self.expected_platform {
                                if here.use_count > 0 {
                                    here.reused = True;
                                    print(f"{here.proof_id}: reusable proof observed again");
                                } else {
                                    print(f"{here.proof_id}: exact product proof accepted");
                                }
                                here.use_count = here.use_count + 1;
                            } else {
                                print(f"{here.proof_id}: validator mismatch; fail closed");
                            }
                        } else {
                            print(f"{here.proof_id}: validator mismatch; fail closed");
                        }
                    } else {
                        print(f"{here.proof_id}: command-set mismatch; fail closed");
                    }
                } else {
                    print(f"{here.proof_id}: candidate digest mismatch; fail closed");
                }
            } else {
                print(f"{here.proof_id}: poisoned proof rejected");
            }
        } else {
            print(f"{here.proof_id}: delivery state forbids proof reuse");
        }
    }
}

with entry {
    candidate = Candidate(
        candidate_id="candidate-107",
        engineering_digest="eng-abc",
        command_set="app+server",
