    has directory: str = "";
    has dependency: bool = True;
    has inspected: bool = False;
}

node SearchRequest {
    has pattern: str = "";
    has package_path: str = "";
    has resolved_dir: str = "";
    has broad_scan_blocked: bool = True;
}

edge CacheCatalog { }
edge CacheEntry { }
edge ContainsPackage { }
edge RequestLink { }
edge RequestTarget { }
edge PackageImport { }

walker DependencyResolver {
    has scan_label: str = "exact-directory search";

    can begin with Root entry {
        print(f"Starting {self.scan_label}; broad cache scans are blocked");
        visit [->:RequestLink:->];
    }

    can resolve with SearchRequest entry {
        print(f"Resolving package {here.package_path}");
        print(f"Search directory: {here.resolved_dir}");
        if here.broad_scan_blocked {
            print("Safety rule: GOMODCACHE and GOPATH are not searched recursively");
