    can inspect with GoPackage entry {
        if here.inspected {
            print(f"Cycle detected at {here.package_path}; stopping this branch");
            disengage;
        } else {
            here.inspected = True;
            print(f"Inspecting {here.package_path} only in {here.directory}");
            visit [->:PackageImport:->] else {
                print(f"Finished dependency walk at {here.package_path}");
                disengage;
            }
        }
    }
}

