    has title: str = "";
    has rule_number: int = 0;
    has outcome: str = "";
    has seen: bool = False;
}

edge Tracks {
    has evidence: str = "";
}

edge Covers {
    has evidence: str = "";
}

edge AcceleratedBy {
    has mode: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker RuntimeAuditor {
    has visited_count: int = 0;

    can start with Root entry {
        print("Runtime optimization audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Audit entry {
        if here.seen {
            print("[guard] audit already inspected");
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"scope: {here.scope}");
            visit [->:Tracks:->] else {
                disengage;
            }
        }
    }

    can inspect with HotPath entry {
        if here.seen {
            print(f"[guard] hot path already inspected: {here.title}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"rank {here.rank}: {here.title} ({here.measured_seconds} seconds)");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect with Kernel entry {
        if here.seen {
            print(f"[cycle guard] dependency revisited: {here.title}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            pin = "exact" if here.exact_pin else "distributional";
            print(f"kernel {here.title}: {here.backend}, {pin} pin");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect with OptimizationRule entry {
        if here.seen {
            print(f"[guard] rule already recorded: {here.rule_number}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"rule {here.rule_number}: {here.title} - {here.outcome}");
        }
    }
}

