    }

    can inspect_kernel with Kernel entry {
        if here.seen {
            self.cycle_count += 1;
            print(f"Cycle detected at kernel: {here.title}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"Kernel: {here.title} via {here.backend}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect_rule with OptimizationRule entry {
        if here.seen {
            self.cycle_count += 1;
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"Rule {here.rule_number}: {here.title} — {here.outcome}");
        }
    }
}

