"""Dependency graph demo with typed edges, cycle detection, and cascade invalidation."""

node Artifact {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has category: str = "";
}

node Library(Artifact) {
    has release_count: int = 0;
}

node Service(Artifact) {
    has replicas: int = 1;
}

edge DependsOn {
    has reason: str = "";
}

walker DependencyAudit {
    has seen: list[str] = [];

    can start with Root entry {
        print("Auditing dependency graph");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Artifact entry {
        if here.title in self.seen {
            print(f"cycle detected at {here.title}");
            disengage;
        }

        self.seen.append(here.title);
        print(f"visiting {here.category}: {here.title}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker CascadeInvalidator {
    has seen: list[str] = [];

    can invalidate with Artifact entry {
        if here.title in self.seen {
            disengage;
        }

        self.seen.append(here.title);
        if here.available {
            here.available = False;
        }
        print(f"invalidated {here.title}");
        visit [<--:DependsOn:--] else {
            disengage;
        }
    }
}

