}

node Checkpoint {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has checkpoint_id: str = "";
    has completed_steps: int = 0;
    has preserved: bool = False;
}

edge DependsOn {
    has reason: str = "";
}

edge HasCheckpoint {
    has created_after_attempt: int = 0;
}

walker ConvergenceAudit {
    has seen_task_ids: list[str] = [];
    has cycle_found: bool = False;
    has repeated_work: bool = False;
    has visited_tasks: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit_task with Task entry {
        if here.task_id in self.seen_task_ids {
            self.cycle_found = True;
            disengage;
        }
        self.seen_task_ids.append(here.task_id);
        self.visited_tasks += 1;
        if here.attempts > 2 and here.progress == 0 {
            self.repeated_work = True;
        }
        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

walker CheckpointKeeper {
    has preserved_checkpoints: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can find_checkpoint with Task entry {
        visit [->:HasCheckpoint:->] else {
            disengage;
        }
    }

    can preserve with Checkpoint entry {
        if here.available {
            here.preserved = True;
            self.preserved_checkpoints += 1;
        }
    }
