"""Fail-closed EGRUL authority audit with immutable subject lineage and cycle detection."""

node SourcePackage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has package_key: str = "";
    has formation_date: str = "";
    has acquisition_ready: bool = False;
    has baseline_covered: bool = False;
    has continuity_ok: bool = False;
    has source_finality: bool = False;
}

node EntityVersion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version_key: str = "";
    has inn: str = "";
    has ogrn: str = "";
    has record_as_of: str = "";
    has source_hash: str = "";
    has invalidated: bool = False;
}

node LegalEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has inn: str = "";
    has current_ogrn: str = "";
    has status: str = "";
    has authoritative_current: bool = False;
}

edge Contains { }

edge Supersedes {
    has reason: str = "";
}

edge SelectsCurrent {
    has selected_at: str = "";
}

walker AuthorityAuditor {
    has seen_versions: list[str] = [];
    has verified_records: int = 0;
    has rejected_records: int = 0;
    has cycle_count: int = 0;

    can start with Root entry {
        print("Starting EGRUL authority audit");
        visit [-->] else { disengage; }
    }

    can inspect_package with SourcePackage entry {
        if here.acquisition_ready and here.baseline_covered and here.continuity_ok and here.source_finality {
            print(f"authoritative package: {here.package_key}");
        } else {
            print(f"shadow-only package: {here.package_key}");
        }
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_current with LegalEntity entry {
        print(f"INN {here.inn} -> OGRN {here.current_ogrn}, status={here.status}");
        if here.authoritative_current {
            print("current pointer is authoritative for this positive fact");
        } else {
            print("current pointer is not authoritative");
        }
        visit [->:SelectsCurrent:->] else { disengage; }
    }

    can inspect_version with EntityVersion entry {
        if here.version_key in self.seen_versions {
            self.cycle_count += 1;
            print(f"cycle blocked at immutable version {here.version_key}");
        } else {
            self.seen_versions.append(here.version_key);
            if here.invalidated {
                self.rejected_records += 1;
                print(f"invalidated version: {here.version_key}");
            } else {
                self.verified_records += 1;
                print(f"verified {here.inn}/{here.ogrn} as of {here.record_as_of}");
                print(f"provenance hash: {here.source_hash}");
            }
            visit [->:Supersedes:->] else { disengage; }
        }
    }

    can report with Root exit {
        print(f"verified={self.verified_records}, rejected={self.rejected_records}, cycles={self.cycle_count}");
    }
}

