"""Native SID-style causal impact audit for a reversed root edge."""

node CausalVariable {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has true_impacted: bool = False;
    has estimated_impacted: bool = False;
    has sid_mismatch: bool = False;
}

node InterventionCase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has origin: str = "";
}

edge TrueCause {
    has note: str = "";
}

edge EstimatedCause {
    has note: str = "";
}

walker ImpactTracer {
    has origin_label: str = "";
    has use_estimated: bool = False;
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can select with InterventionCase entry {
        visit [-->] else {
            disengage;
        }
    }

    can trace with CausalVariable entry {
        if self.depth >= self.max_depth {
            print(f"depth limit reached while tracing from {self.origin_label}");
            disengage;
        } else {
            if here.title != self.origin_label {
                if self.use_estimated {
                    here.estimated_impacted = True;
                } else {
                    here.true_impacted = True;
                }
                print(f"traced {here.title} from {self.origin_label}");
            }

            self.depth += 1;
            if self.use_estimated {
                visit [->:EstimatedCause:->] else {
                    disengage;
                }
            } else {
                visit [->:TrueCause:->] else {
                    disengage;
                }
            }
        }
    }
}

walker SidReporter {
    has origin_label: str = "X";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_case with InterventionCase entry {
        visit [-->] else {
            disengage;
        }
    }

    can report with CausalVariable entry {
        if here.title != self.origin_label {
            if here.true_impacted && !here.estimated_impacted {
                here.sid_mismatch = True;
                print(f"SID mismatch: do({self.origin_label}) -> {here.title}");
            } else {
                print(f"intervention agrees for do({self.origin_label}) -> {here.title}");
            }
        }
        visit [-->] else {
            disengage;
        }
    }
}

with entry {
    query = InterventionCase(title="Evaluate do(X)", origin="X");
    x = CausalVariable(title="X");
    y = CausalVariable(title="Y");
    z = CausalVariable(title="Z");

    root ++> query ++> x ++> y ++> z;

    x +>:TrueCause(note="ground truth"): +> y;
    y +>:TrueCause(note="ground truth"): +> z;

    y +>:EstimatedCause(note="reversed root edge"): +> x;
    y +>:EstimatedCause(note="learned downstream edge"): +> z;

    true_trace = ImpactTracer(origin_label="X", use_estimated=False);
    root spawn true_trace;

    estimated_trace = ImpactTracer(origin_label="X", use_estimated=True);
    root spawn estimated_trace;

    root spawn SidReporter(origin_label="X");
}

"""Source-only delivery handoff without requiring shared-target integration."""

node Plan {
    has title: str = "";
    has delivery_target_branch: str = "";
    has source_only: bool = True;
    has available: bool = True;
}

node Work {
    has title: str = "";
    has source_branch: str = "";
    has candidate_commit: str = "";
    has reviewed: bool = False;
    has integrated: bool = False;
    has available: bool = True;
}

node SourceHandoff {
    has title: str = "";
    has isolated_ref: str = "";
    has exact_commit: str = "";
    has reviewed: bool = False;
    has published: bool = False;
    has integrated: bool = False;
    has available: bool = True;
}

node IntegrationAuthority {
    has title: str = "";
    has owner: str = "";
    has integrated_commit: str = "";
    has reconciled: bool = False;
    has available: bool = True;
}

edge PlanWork { }
edge Publishes { }
edge AwaitsIntegration { }

walker DeliveryAuditor {
    has target_branch: str = "";
    has expected_commit: str = "";
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        if self.depth >= self.max_depth {
            print("cycle guard stopped the delivery walk");
            disengage;
        }
        self.depth += 1;
        visit [-->] else {
            disengage;
        }
    }

    can inspect_plan with Plan entry {
        self.target_branch = here.delivery_target_branch;
        print(f"Plan: {here.title}");
        print(f"source-only mode: {here.source_only}");
        visit [->:PlanWork:->] else {
            disengage;
        }
    }

    can inspect_work with Work entry {
        self.expected_commit = here.candidate_commit;
        print(f"Work: {here.title}");
        print(f"reviewed candidate: {here.candidate_commit}");
        print(f"shared-target integration already complete: {here.integrated}");
        visit [->:Publishes:->] else {
            disengage;
        }
    }

    can inspect_handoff with SourceHandoff entry {
        commit_matches = here.exact_commit == self.expected_commit;
        isolated = here.isolated_ref != self.target_branch;
        valid = commit_matches and isolated and here.reviewed and here.published and not here.integrated;

        if valid {
