"""A distance-aware electrical grid with explicit cycle-safe voltage auditing."""

node GridNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node PowerPlant(GridNode) {
    has generated_voltage: float = 240.0;
    has output_power: float = 10000.0;
}

node Transformer(GridNode) {
    has ratio: float = 1.0;
}

node CableSegment(GridNode) {
    has material: str = "copper";
    has length: float = 1.0;
    has resistivity: float = 0.00188;
}

node Load(GridNode) {
    has required_voltage: float = 240.0;
    has demand_power: float = 1000.0;
    has delivered_voltage: float = 0.0;
}

edge Supplies { }

walker VoltageAuditor {
    has path_voltage: float = 0.0;
    has path_current: float = 0.0;
    has total_loss: float = 0.0;
    has seen: list[str] = [];
    has readings: list[str] = [];
    has cycle_count: int = 0;

    def mark_seen(label: str) -> bool {
        if label in self.seen {
            self.cycle_count += 1;
            return False;
        }
        self.seen = self.seen + [label];
        return True;
    }

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_plant with PowerPlant entry {
        if (not self.mark_seen(here.title)) { disengage; }
        self.path_voltage = here.generated_voltage;
        self.path_current = here.output_power / here.generated_voltage;
        self.readings = self.readings + [f"{here.title}: {self.path_voltage} V, {self.path_current} A"];
        visit [->:Supplies:->] else { disengage; }
    }

    can inspect_transformer with Transformer entry {
        if (not self.mark_seen(here.title)) { disengage; }
        self.path_voltage = self.path_voltage * here.ratio;
        self.path_current = self.path_current / here.ratio;
        self.readings = self.readings + [f"{here.title}: ratio {here.ratio}, {self.path_voltage} V, {self.path_current} A"];
        visit [->:Supplies:->] else { disengage; }
    }

    can inspect_cable with CableSegment entry {
        if (not self.mark_seen(here.title)) { disengage; }
        resistance = here.resistivity * here.length;
        voltage_drop = self.path_current * resistance;
        line_loss = self.path_current * self.path_current * resistance;
        self.path_voltage = self.path_voltage - voltage_drop;
        self.total_loss = self.total_loss + line_loss;
        self.readings = self.readings + [f"{here.title}: {here.material} {here.length} blocks, drop {voltage_drop} V"];
        visit [->:Supplies:->] else { disengage; }
    }

    can inspect_load with Load entry {
        if (not self.mark_seen(here.title)) { disengage; }
        here.delivered_voltage = self.path_voltage;
        load_state = "POWERED" if here.available and self.path_voltage >= here.required_voltage else "UNDER-VOLTAGE";
        self.readings = self.readings + [f"{here.title}: {load_state} at {here.delivered_voltage} V"];
        visit [->:Supplies:->] else { disengage; }
    }

    can finish with Root exit {
        self.readings = self.readings + [f"line loss: {self.total_loss} W", f"cycles guarded: {self.cycle_count}"];
        report self.readings;
    }
}

