    plant = PowerPlant(title="Plant", generated_voltage=240.0, output_power=10000.0);
    step_up = Transformer(title="Step-up", ratio=10.0);
    line = CableSegment(title="Aluminium long-haul", material="aluminium", length=400.0, resistivity=0.0027);
    service = CableSegment(title="Copper service", material="copper", length=30.0, resistivity=0.00188);
