node BipartiteVertex {
    has vertex_id: int = 0;
    has label: str = "";
    has side: str = "";
    has matched: bool = False;
}

node LeftVertex(BipartiteVertex) {
    has partition_note: str = "left side";
}

node RightVertex(BipartiteVertex) {
    has partition_note: str = "right side";
}

node Region {
    has region_id: int = 0;
    has label: str = "";
    has kind: str = "";
    has members: list[str] = [];
    has rank: int = 0;
}

edge FreeLink {
    has witness: str = "";
}

edge MatchLink {
    has pair_id: int = 0;
}

edge Membership {
    has role: str = "";
}

edge BlockDependency {
    has reason: str = "";
}

walker AlternatingReachability {
    has seen_ids: list[int] = [];
    has discovered: list[str] = [];
    has step_limit: int = 20;

    can start with Root entry {
        print("alternating reachability from source-bound seeds");
        visit [-->] else { disengage; }
    }

    can alternate with LeftVertex | RightVertex entry {
        if self.step_limit <= 0 {
            print("alternating walk stopped at its depth bound");
            disengage;
        } elif here.vertex_id in self.seen_ids {
            print(f"cycle guard retained {here.label} without revisiting it");
        } else {
            self.seen_ids.append(here.vertex_id);
            self.discovered.append(here.label);
            self.step_limit = self.step_limit - 1;
            print(f"reached {here.side} vertex {here.label});

            if here.side == "left" {
                visit [->:FreeLink:->] else {
                    print(f"no free edge leaves {here.label}");
                }
            } else {
                visit [->:MatchLink:->] else {
                    print(f"no matched edge returns from {here.label}");
                }
            }
        }
    }
}

walker OrderAuditor {
    has seen_regions: list[int] = [];
    has order: list[str] = [];

    can start with Root entry {
        print("fine-block condensation order");
        visit [-->] else { disengage; }
    }

    can inspect with Region entry {
        if here.region_id in self.seen_regions {
            print(f"region cycle or merge ignored at {here.label}");
        } else {
            self.seen_regions.append(here.region_id);
            self.order.append(here.label);
            print(f"{here.kind}: {here.label} contains {here.members}");
            visit [->:BlockDependency:->] else {
                print(f"{here.label} has no outgoing dependency");
            }
        }
    }
}

with entry {
    source_left = LeftVertex(
        vertex_id=1,
        label="L-source",
        side="left",
        matched=False
    );
    matched_left = LeftVertex(
        vertex_id=2,
        label="L-matched",
        side="left",
        matched=True
    );
    shared_right = RightVertex(
        vertex_id=3,
        label="R-shared",
        side="right",
        matched=True
    );

    source_left +>:FreeLink(witness="unmatched-left alternating edge"):+> shared_right;
    shared_right +>:MatchLink(pair_id=1):+> matched_left;

    triangular_left = LeftVertex(
        vertex_id=4,
        label="L-tri-1",
        side="left",
        matched=True
    );
    triangular_other = LeftVertex(
        vertex_id=5,
        label="L-tri-2",
        side="left",
        matched=True
    );
    triangular_right = RightVertex(
        vertex_id=6,
        label="R-tri-1",
        side="right",
        matched=True
    );
    triangular_last = RightVertex(
        vertex_id=7,
        label="R-tri-2",
        side="right",
        matched=True
    );

    triangular_right +>:MatchLink(pair_id=2):+> triangular_left;
    triangular_last +>:MatchLink(pair_id=3):+> triangular_other;
    triangular_left +>:FreeLink(witness="triangular off-diagonal"):+> triangular_last;

    deficient = Region(
        region_id=10,
        label="D-left",
        kind="coarse deficient region",
        members=["L-source", "L-matched", "R-shared"],
        rank=0
    );
    block_a = Region(
        region_id=11,
        label="B1",
        kind="balanced fine block",
        members=["L-tri-1", "R-tri-1"],
        rank=1
    );
    block_b = Region(
        region_id=12,
        label="B2",
        kind="balanced fine block",
        members=["L-tri-2", "R-tri-2"],
        rank=2
    );

    deficient +>:Membership(role="source-bound deficient partition"):+> source_left;
    deficient +>:Membership(role="source-bound deficient partition"):+> matched_left;
    deficient +>:Membership(role="source-bound deficient partition"):+> shared_right;
    block_a +>:Membership(role="balanced block member"):+> triangular_left;
    block_a +>:Membership(role="balanced block member"):+> triangular_right;
    block_b +>:Membership(role="balanced block member"):+> triangular_other;
    block_b +>:Membership(role="balanced block member"):+> triangular_last;
    block_a +>:BlockDependency(reason="off-diagonal triangular dependency"):+> block_b;

    root ++> source_left;
    root ++> triangular_left;
    root ++> deficient;
    root ++> block_a;
    root ++> block_b;

    reach = AlternatingReachability(step_limit=20);
    root spawn reach;
    print(f"source-bound vertices: {reach.discovered}");

    auditor = OrderAuditor();
    root spawn auditor;
    print(f"canonical region order: {auditor.order}");
}

