node TestRun(RuntimeRecord) {
    has runner_alive: bool = False;
}

node FixtureProcess(RuntimeRecord) {
    has pid: int = 0;
    has orphaned: bool = True;
    has terminated: bool = False;
    has listeners: int = 0;
}

edge LaunchesRun {
    has relation: str = "";
}

edge OwnsProcess {
    has relation: str = "";
}

edge ChildProcess {
    has relation: str = "";
}

walker Cleanup {
    has depth: int = 0;
    has max_depth: int = 12;
    has cleaned_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_run with TestRun entry {
        print(f"Inspecting test run: {here.title}");
        visit [->:OwnsProcess:->] else {
            disengage;
        }
    }

    can terminate with FixtureProcess entry {
        if self.depth >= self.max_depth {
            print(f"Depth limit stopped possible cycle at PID {here.pid}");
            disengage;
        } else {
            self.depth += 1;
            if here.orphaned {
                here.available = False;
                here.terminated = True;
                self.cleaned_count += 1;
                print(f"Terminating orphaned PID {here.pid} ({here.title})");
            }
            visit [->:ChildProcess:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Cleanup marked {self.cleaned_count} fixture leaders or children");
    }
}

