"""Validate task prerequisites with a cycle-detecting depth-first walker."""

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_key: str = "";
}

edge Contains {
    has label: str = "";
}

edge Prerequisite {
    has reason: str = "";
}

walker DependencyValidator {
    has active_path: list[Task] = [];
    has cycle_found: bool = False;
    has blocked_update: bool = False;
    has cycle_note: str = "";

    can start with Root entry {
        visit :0: [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        print(f"Checking workflow: {here.title}");
        visit :0: [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_task with Task entry {
        if here in self.active_path {
            self.cycle_found = True;
            self.blocked_update = True;
            self.cycle_note = f"circular prerequisite at {here.task_key}";
            print(f"UPDATE BLOCKED: {self.cycle_note}");
            disengage;
        }

        self.active_path.append(here);
        print(f"Visiting task {here.task_key}");
        visit :0: [->:Prerequisite:->] else {
            disengage;
        }
    }

    can leave_task with Task exit {
        if self.active_path {
            self.active_path.pop();
        }
    }
}

