    task_b +>:Prerequisite(reason="A must be completed first"):+> task_a;

    validator = DependencyValidator();
    root spawn validator;

    print(f"Cycle found: {validator.cycle_found}");
    print(f"Update blocked: {validator.blocked_update}");
}

