    can start with Root entry {
        print("Auditing additive integration dependencies");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can inspect with PipelineEntity entry {
        if here.auditing {
            self.cycle_count += 1;
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            here.auditing = True;

            if not here.available {
                here.invalidated = True;
                self.invalid_count += 1;
                print(f"invalidated unavailable component: {here.title}");
            } else {
                print(f"preserved component: {here.title}");
            }

            if self.depth >= self.max_depth {
                here.invalidated = True;
                self.invalid_count += 1;
                print(f"depth limit reached at {here.title}");
                here.auditing = False;
                here.audited = True;
                disengage;
            } else {
                self.depth += 1;
                visit [->:DependsOn:->] else {
                    disengage;
                }
                self.depth -= 1;
                here.auditing = False;
                here.audited = True;
            }
        }
    }
}

