"""Offline chess recognition lineage demo using typed graph relationships and a cycle-safe walker."""

node DatasetSlice {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_kind: str = "printed";
    has coverage: str = "clean";
}

node EvaluationRun {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has recipe: str = "frozen";
    has status: str = "planned";
}

node ModelCandidate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has detector: str = "";
    has kind: str = "candidate";
}

edge UsesData {
    has role: str = "";
}

edge ProducesModel {
    has path: str = "";
}

edge DependsOn {
    has reason: str = "";
}

edge Invalidates {
    has reason: str = "";
}

walker DependencyAuditor {
    has current_chain: list[str] = [];
    has audited: int = 0;

    can start with Root entry {
        print("Auditing frozen chess-recognition lineage");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with EvaluationRun | DatasetSlice | ModelCandidate entry {
        already_seen = False;
        for seen_title in self.current_chain {
            if seen_title == here.title {
                already_seen = True;
                break;
            }
        }

        if already_seen {
            print(f"cycle prevented at {here.title}");
            disengage;
        }

        self.current_chain.append(here.title);
        self.audited += 1;
        availability = "available" if here.available else "unavailable";
        print(f"{here.title} ({here.year}) [{availability}]");
        visit [-->] else {
            disengage;
        }
        self.current_chain.pop();
    }

    can report with Root exit {
        print(f"Audited {self.audited} graph records");
    }
}

