walker KotlinVerifier {
    has checked_hosts: int = 0;
    has blocked_hosts: int = 0;
    has hops: int = 0;
    has hop_limit: int = 16;
    has cycle_detected: bool = False;

    can start with Root entry {
        if self.hops >= self.hop_limit {
            self.cycle_detected = True;
            disengage;
        }
        self.hops += 1;
        visit [-->] else {
            disengage;
        }
    }

    can dispatch with BuildJob entry {
        if self.hops >= self.hop_limit {
            self.cycle_detected = True;
            disengage;
        }
        self.hops += 1;
        visit [->:RunsLane:->] else {
            disengage;
        }
    }

    can select_policy with KotlinLane entry {
        if self.hops >= self.hop_limit {
            self.cycle_detected = True;
            disengage;
        }
        self.hops += 1;
        visit [->:UsesPolicy:->] else {
            disengage;
        }
    }

    can probe with EgressPolicy entry {
        if self.hops >= self.hop_limit {
            self.cycle_detected = True;
            disengage;
        }
        self.hops += 1;
        visit [->:AllowsEgress:->] else {
            disengage;
        }
    }

    can record with DependencyHost entry {
        self.checked_hosts += 1;
        here.probed = True;
        here.reachable = here.available;
        if here.available == False {
            self.blocked_hosts += 1;
        }
    }
}

