"""A shared-subtree DAG demo for memoized tree-node remapping."""

node GraphItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has nodeid: int = 0;
    has remapped: bool = False;
}

node TreeNode(GraphItem) {
    has split_kind: str = "";
}

node CategoryEntry(GraphItem) {
    has category: int = 0;
}

edge Child {
    has slot: int = 0;
}

edge CategoryChoice {
    has category: int = 0;
}

walker NaiveExpander {
    has calls: int = 0;
    has limit: int = 40;

    can start with Root entry {
        visit [->:Child:->] else {
            disengage;
        }
    }

    can expand with TreeNode entry {
        if self.calls >= self.limit {
            print("naive traversal budget reached");
            disengage;
        } else {
            self.calls += 1;
            print(f"naive visit {here.nodeid}: {here.title}");
            visit [->:CategoryChoice:->] else {
                visit [->:Child:->] else {
                    disengage;
                }
            }
        }
    }

    can expand with CategoryEntry entry {
        if self.calls >= self.limit {
            print("naive traversal budget reached");
            disengage;
        } else {
            self.calls += 1;
            print(f"naive visit category {here.category}");
            visit [->:Child:->] else {
                disengage;
            }
        }
    }
}

walker MemoizedRemapper {
    has calls: int = 0;

    can start with Root entry {
        visit [->:Child:->] else {
            disengage;
        }
    }

    can remap with TreeNode entry {
        if here.remapped {
            print(f"memo skip {here.nodeid}: {here.title}");
        } else {
            here.remapped = True;
            self.calls += 1;
            print(f"memo visit {here.nodeid}: {here.title}");
            visit [->:CategoryChoice:->] else {
                visit [->:Child:->] else {
                    disengage;
                }
            }
        }
    }

    can remap with CategoryEntry entry {
        if here.remapped {
            print(f"memo skip category {here.category}");
        } else {
            here.remapped = True;
            self.calls += 1;
            print(f"memo visit category {here.category}");
            visit [->:Child:->] else {
                disengage;
            }
        }
    }
}

