"""Model a Codex tool call that recursively spawns shell processes."""

node ToolCall {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has request: str = "";
    has tool_name: str = "";
}

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has command: str = "";
    has shell: bool = False;
    has suspicious: bool = False;
}

edge BeginsCall { }

edge Executes {
    has mode: str = "";
}

edge Spawned {
    has reason: str = "";
}

walker ProcessAudit {
    has visited_count: int = 0;
    has depth: int = 0;
    has max_depth: int = 4;

    can start with Root entry {
        print("audit: following one tool call into its process tree");
        visit [->:BeginsCall:->] else { disengage; }
    }

    can inspect_call with ToolCall entry {
        print(f"tool={here.tool_name} request={here.request}");
        visit [->:Executes:->] else { disengage; }
    }

    can inspect_process with Process entry {
        self.visited_count += 1;
        print(f"pid={here.pid} command={here.command}");

        if (here.suspicious) {
            print("warning: recursive shell growth detected");
        }

        if (self.depth >= self.max_depth) {
            print("depth guard stopped further spawning");
        } else {
            self.depth += 1;
            visit [->:Spawned:->];
        }
    }

    can finish with Root exit {
        print(f"audit complete: {self.visited_count} processes reached");
        report self.visited_count;
    }
}

with entry {
    call = ToolCall(
        title="shell tool call",
        request="run git status",
        tool_name="bash"
    );
    root +>:BeginsCall:+> call;

    first = Process(
        title="bash",
        pid=100,
        command="bash -lc git status",
        shell=True
    );
    call +>:Executes(mode="fork"):+> first;

    second = Process(
        title="bash",
        pid=101,
        command="bash -lc bash -lc git status",
        shell=True
    );
    first +>:Spawned(reason="tool wrapper"):+> second;

    third = Process(
        title="bash",
        pid=102,
        command="bash -lc bash -lc bash",
        shell=True,
        suspicious=True
    );
    second +>:Spawned(reason="recursive child"):+> third;

    fourth = Process(
        title="bash",
        pid=103,
        command="bash -lc bash",
        shell=True,
        suspicious=True
    );
    third +>:Spawned(reason="recursive child"):+> fourth;

    fifth = Process(
        title="bash",
        pid=104,
        command="bash -lc bash",
        shell=True,
        suspicious=True
    );
    fourth +>:Spawned(reason="recursive child"):+> fifth;

    leaf = Process(title="git", pid=105, command="git status");
    fifth +>:Spawned(reason="leaf command"):+> leaf;

    root spawn ProcessAudit(max_depth=4);
}

