    has available: bool = True;
    has bundle_id: str = "";
}

node Batch {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has batch_id: str = "";
}

node BatchItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has entry_id: str = "";
    has outcome: str = "";
}

edge Contains { }

edge Reference {
    has source_site: str = "";
}

edge SplitFrom { }

edge Link {
    has profile: str = "";
    has rm_code: str = "";
}

edge Entry { }
edge Request { }

walker ReferenceResolver {
    has depth: int = 0;
    has max_depth: int = 4;

    can start with Root entry {
        visit [-->];
    }

    can resolve with Resource entry {
        if here.visited {
            print(f"cycle detected at {here.resource_id}");
            disengage;
        } else {
            here.visited = True;
            if here.kind == "$reference" {
                if here.coding_use != "" {
                    print(f"reference preserves worked example {here.coding_use}");
                }
                if here.available == False {
                    print(f"request refused: cannot fetch {here.reference_url}");
                    disengage;
                } else {
                    if self.depth >= self.max_depth {
                        print(f"request refused: reference depth limit at {here.resource_id}");
                        disengage;
                    } else {
                        self.depth += 1;
                        visit [->:Reference:->] else { disengage; }
                        self.depth -= 1;
                    }
                }
            }
        }
    }
}

walker BundleRouter {
    can start with Root entry {
        visit [-->];
    }

    can split with Bundle entry {
        print(f"bundle {here.bundle_id}: split by meta.profile membership");
        visit [->:Contains:->] else { disengage; }
    }

    can route with Resource entry {
        if "profile/alpha" in here.profiles {
            print(f"{here.resource_id} routed to profile/alpha");
        }
        if "profile/beta" in here.profiles {
            print(f"{here.resource_id} routed to profile/beta");
        }
    }
}

walker HierarchySplitter {
    can start with Root entry {
        visit [-->];
    }

    can split with Resource entry {
        if here.kind == "hierarchy" {
            print(f"hierarchy {here.resource_id}: split occurrence enters deterministic id");
            visit [->:SplitFrom:->] else { disengage; }
        }
        if here.kind == "event" {
            print(f"split resource {here.resource_id} for dosage {here.split_key}");
        }
    }
}

walker LinkFollower {
    can start with Root entry {
        visit [-->];
    }

    can follow with Resource entry {
        if here.kind == "LINKED" {
            print(f"LINKED: trigger context by profile from {here.resource_id}");
            visit [->:Link:->] else { disengage; }
        }
    }

    can inspect with Resource entry {
        if here.kind == "context" {
            print(f"RM LINK context reached: {here.resource_id}");
        }
    }
}

walker BatchAuditor {
    has failures: int = 0;

    can start with Batch entry {
        visit [->:Entry:->] else { disengage; }
    }

    can inspect with BatchItem entry {
        if here.outcome == "failure" {
            self.failures += 1;
        }
        print(f"batch entry {here.entry_id}: {here.outcome}");
        if here.outcome == "failure" {
            print(f"batch response: HTTP 200, failures={self.failures}");
        }
        visit [->:Request:->] else { disengage; }
    }

    can target with Resource entry {
        print(f"batch request target: {here.resource_id}");
    }
}

