"""Proof approval workflow with exact rendered-version binding and revision return paths."""

node MockupVersion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has version_label: str = "";
    has render_hash: str = "";
    has locked: bool = False;
}

node ProofRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has request_id: str = "";
    has target_hash: str = "";
    has status: str = "open";
    has expires_at: str = "";
}

node ApprovalDecision {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has actor: str = "";
    has decided_at: str = "";
    has comments: str = "";
    has target_hash: str = "";
    has outcome: str = "";
    has audit_id: str = "";
}

node WorkOrder {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has order_id: str = "";
    has art_gate: str = "open";
    has evidence_locked: bool = False;
    has revision_task_status: str = "none";
}

edge Contains { }

edge Presents {
    has issued_at: str = "";
    has expires_at: str = "";
}

edge Records { }

edge Controls {
    has relation: str = "";
}

walker ProofAuditor {
    has presented_hash: str = "";
    has mockup_locked: bool = False;
    has approved: bool = False;

    can start with Root entry {
        print("Auditing proof approval graph");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_request with ProofRequest entry {
        print(f"Proof request {here.request_id} targets {here.target_hash}");
        visit [->:Presents:->] else {
            disengage;
        }
    }

    can inspect_mockup with MockupVersion entry {
        self.presented_hash = here.render_hash;
        self.mockup_locked = here.locked;
        print(f"Presented {here.version_label} with render {here.render_hash}");
        visit [->:Records:->] else {
            disengage;
        }
    }

    can inspect_decision with ApprovalDecision entry {
        exact_target = here.target_hash == self.presented_hash;
        self.approved = False;

        if exact_target {
            if here.outcome == "approve" {
                if self.mockup_locked {
                    self.approved = True;
                }
            }
        }

        if self.approved {
            print(f"Approved by {here.actor}: exact locked proof {here.target_hash}");
        } else {
            if here.outcome == "request_changes" {
                print(f"Changes requested by {here.actor}; history kept in {here.audit_id}");
            } else {
                print(f"Rejected stale or unlocked target {here.target_hash}");
            }
        }

        visit [->:Controls:->] else {
            disengage;
        }
    }

    can finalize_order with WorkOrder entry {
        if self.approved {
            here.art_gate = "cleared";
            here.evidence_locked = True;
            here.revision_task_status = "none";
            print(f"Work order {here.order_id}: evidence locked and art gate cleared");
        } else {
            here.art_gate = "open";
            here.evidence_locked = False;
            here.revision_task_status = "draft";
            print(f"Work order {here.order_id}: new draft revision task created");
        }

        visit [-->] else {
            disengage;
        }
    }
}

