"""Native graph model for an overflow-aware dashboard."""

node Record {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has category: str = "";
}

node Dashboard {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_limit: int = 3;
    has job_limit: int = 2;
}

node Run(Record) {
    has profile: str = "";
    has status: str = "";
}

node QueueJob(Record) {
    has profile: str = "";
    has task: str = "";
}

edge HasDashboard { }

edge ContainsRecord {
    has lane: str = "";
}

walker DashboardAudit {
    has show_all: bool = False;
    has run_limit: int = 0;
    has job_limit: int = 0;
    has run_total: int = 0;
    has job_total: int = 0;
    has run_overflow: int = 0;
    has job_overflow: int = 0;

    can start with Root entry {
        visit [->:HasDashboard:->] else { disengage; }
    }

    can inspect_dashboard with Dashboard entry {
        self.run_limit = here.run_limit;
        self.job_limit = here.job_limit;
        print(f"Dashboard limits: runs {self.run_limit}, jobs {self.job_limit}");
        visit [->:ContainsRecord:->] else { disengage; }
        print(f"Runs total={self.run_total}, omitted={self.run_overflow}; Jobs total={self.job_total}, omitted={self.job_overflow}");
    }

    can inspect_record with Run | QueueJob entry {
        if here.category == "run" {
            self.run_total += 1;
            if self.show_all {
                print(f"RUN {here.title} [{here.status}] profile={here.profile}");
            } else {
                if self.run_total <= self.run_limit {
                    print(f"RUN {here.title} [{here.status}] profile={here.profile}");
                } else {
                    self.run_overflow += 1;
                }
            }
        } else {
            self.job_total += 1;
            if self.show_all {
                print(f"JOB {here.title} task={here.task} profile={here.profile}");
            } else {
                if self.job_total <= self.job_limit {
                    print(f"JOB {here.title} task={here.task} profile={here.profile}");
                } else {
                    self.job_overflow += 1;
                }
            }
        }
    }
}

