"""Symlink-safe directory scanning with explicit canonical-path cycle detection."""

node Directory {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has canonical_path: str = "";
    has is_link: bool = False;
}

node SourceFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has extension: str = "";
}

edge Contains {
    has kind: str = "";
}

walker TypeScanner {
    has visited_paths: list[str] = [];
    has discovered_files: list[str] = [];

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can scan with Directory entry {
        if here.canonical_path in self.visited_paths {
            print(f"[cycle] skipped {here.title} at {here.canonical_path}");
        } else {
            self.visited_paths.append(here.canonical_path);
            print(f"[directory] scanning {here.title} at {here.canonical_path}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can report with SourceFile entry {
        self.discovered_files.append(here.title);
        print(f"[file] discovered {here.title}{here.extension}");
    }
}

