    subdir +>:Contains(kind="symlink"):+> loop;
    loop +>:Contains(kind="resolved child directory"):+> subdir;

    root spawn TypeScanner();
}

"""AI-OS Context Package Layer: resolve pinned packages and detect dependency cycles."""

node ContextPackage {
    has package_name: str = "";
    has package_type: str = "project";
    has owner: str = "";
    has source_path: str = "";
    has source_revision: str = "";
    has content_hash: str = "";
    has pinned_hash: str = "";
    has target_name: str = "codex";
    has eligible: bool = True;
}

node ContextTarget {
    has target_name: str = "";
    has compiler_version: str = "";
}

edge DependsOn {
    has requirement: str = "";
}

edge CompilesFor {
    has adapter: str = "";
}

walker DependencyResolver {
    has target_name: str = "codex";
    has visited_packages: list[str] = [];

    can start with Root entry {
        print(f"Resolving AI-OS context for {self.target_name}");
        visit [-->] else {
            disengage;
        }
    }

    can resolve with ContextPackage entry {
        if here.package_name in self.visited_packages {
            print(f"ERROR: dependency cycle detected at {here.package_name}");
            disengage;
        }

        if here.owner == "" {
            print(f"ERROR: unknown owner for {here.package_name}");
            disengage;
        }

        if here.source_path == "" {
            print(f"ERROR: missing canonical source for {here.package_name}");
            disengage;
        }

        if here.content_hash == "" {
            print(f"ERROR: missing source hash for {here.package_name}");
            disengage;
        }

        if here.content_hash != here.pinned_hash {
            print(f"ERROR: hash mismatch for {here.package_name}");
            disengage;
        }

        if not here.eligible {
            print(f"ERROR: governance rejected {here.package_name}");
            disengage;
        }

        if here.target_name != self.target_name {
            print(f"ERROR: {here.package_name} is incompatible with {self.target_name}");
            disengage;
        }

        self.visited_packages = self.visited_packages + [here.package_name];
        print(f"LOCKED {here.package_name} from {here.source_path}");
        visit [->:DependsOn:->] else {
            print(f"Resolved dependency leaf {here.package_name}");
            disengage;
        }
    }

    can inspect with ContextTarget entry {
        print(f"Using {here.target_name} adapter version {here.compiler_version}");
    }
}

