node ModelSpace {
    has title: str = "";
    has space: str = "MODEL";
    has geometry_count: int = 0;
    has source_revision: int = 0;
}

node Layout {
    has title: str = "";
    has layout_id: int = 0;
    has space: str = "PAPER";
    has active: bool = False;
}

node Viewport {
    has title: str = "";
    has viewport_id: int = 0;
    has center_x: float = 0.0;
    has center_y: float = 0.0;
    has scale: float = 1.0;
    has rotation: float = 0.0;
    has locked: bool = False;
}

node PageSetup {
    has title: str = "";
    has setup_id: int = 0;
    has paper_size: str = "A3";
    has orientation: str = "LANDSCAPE";
    has margin: float = 10.0;
    has plot_scale: float = 1.0;
}

edge LayoutContains {
    has role: str = "";
}

edge ViewportDisplays {
    has layer_override: str = "";
}

edge RootModel { }

edge RelatedModel {
    has relation: str = "";
}

walker LayoutPublisher {
    has visited_layouts: list[int] = [];
    has visited_viewports: list[int] = [];
    has visited_models: list[int] = [];

    can begin with Root entry {
        print("PLOT PREVIEW");
        visit [-->];
    }

    can inspect with Layout entry {
        if here.layout_id in self.visited_layouts {
            print(f"Skipping repeated layout {here.title}");
        } else {
            self.visited_layouts.append(here.layout_id);
            print(f"Layout {here.layout_id}: {here.title} [{here.space}]");
            visit [->:LayoutContains:->] else { disengage; };
        }
    }

    can inspect with Viewport entry {
        if here.viewport_id in self.visited_viewports {
            print(f"Skipping repeated viewport {here.title}");
        } else {
            self.visited_viewports.append(here.viewport_id);
            lock_state = "LOCKED" if here.locked else "OPEN";
            print(f"Viewport {here.viewport_id}: scale {here.scale} {lock_state}");
            visit [->:ViewportDisplays:->] else { disengage; };
        }
    }

    can inspect with PageSetup entry {
        print(f"Page setup {here.setup_id}: {here.paper_size} "
              f"{here.orientation}, scale {here.plot_scale}");
    }

    can inspect with ModelSpace entry {
        if here.source_revision in self.visited_models {
            print(f"Skipping repeated model reference {here.title}");
        } else {
            self.visited_models.append(here.source_revision);
            print(f"Model geometry: {here.geometry_count} entities, "
                  f"revision {here.source_revision}");
        }
    }
}

walker CycleAuditor {
    has visited_revisions: list[int] = [];

    can begin with Root entry {
        visit [->:RootModel:->] else { disengage; };
    }

    can inspect with ModelSpace entry {
        if here.source_revision in self.visited_revisions {
            print(f"Cycle detected at {here.title}");
            disengage;
        } else {
            self.visited_revisions.append(here.source_revision);
            print(f"Auditing model dependency {here.title}");
            visit [->:RelatedModel:->] else { disengage; };
        }
    }
}

