    has reason: str = "";
}

walker AssetInvalidator {
    has run_id: int = 1;
    has visited_count: int = 0;
    has cycle_found: bool = False;

    can start with Root entry {
        print("Starting asset invalidation walk");
        visit [-->] else {
            disengage;
        }
    }

