            print(f"Invalidated {here.asset_id}: {here.title}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Visited assets: {self.visited_count}");
        print(f"Cycle found: {self.cycle_found}");
    }
}

