"""Audit representation benchmark evidence through typed dependency edges."""

node Benchmark {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has audited_cases: int = 0;
    has invalidated_cases: int = 0;
}

node Method {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fit_regime: str = "";
    has evaluation_scope: str = "";
    has audited: bool = False;
}

node EvidenceCase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has sequence_id: str = "";
    has status: str = "ok";
    has metric_n: int = 0;
    has invalidated: bool = False;
    has audited: bool = False;
}

edge Runs {
    has scope: str = "";
}

edge Produces {
    has fit_regime: str = "";
}

edge DependsOn { }

walker EvidenceAuditor {
    has seen_cases: int = 0;
    has invalidated_cases: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_benchmark with Benchmark entry {
        print(f"Auditing benchmark: {here.title}");
        visit [->:Runs:->] else {
            disengage;
        }
    }

    can inspect_method with Method entry {
        here.audited = True;
        print(f"Method: {here.title} | regime={here.fit_regime} | "
              f"scope={here.evaluation_scope}");
        if here.available {
            print("  dependency available");
        } else {
            print("  dependency unavailable");
        }
        visit [->:Produces:->] else {
            disengage;
        }
    }

    can inspect_case with EvidenceCase entry {
        if here.audited {
            print(f"Cycle detected at case {here.sequence_id}");
            disengage;
        } else {
            here.audited = True;
            self.seen_cases = self.seen_cases + 1;

            if here.status == "ok" {
                if here.metric_n > 0 {
                    print(f"Case {here.sequence_id}: ok, metric_n={here.metric_n}");
                } else {
                    here.invalidated = True;
                    self.invalidated_cases = self.invalidated_cases + 1;
                    print(f"Case {here.sequence_id}: invalid metric schema");
                }
            } else {
                here.invalidated = True;
                self.invalidated_cases = self.invalidated_cases + 1;
                print(f"Case {here.sequence_id}: {here.status}, no promoted metrics");
            }

            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can report with Root exit {
        print(f"Audit complete: {self.seen_cases} cases inspected, "
              f"{self.invalidated_cases} invalidated");
    }
}

