"""Recon scan graph that rejects wildcard DNS, catch-all ports, and soft 404s."""

node ScanTarget {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mode: str = "";
    has baseline_signature: str = "";
}

node Probe {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has signature: str = "";
    has status: int = 0;
    has body_size: int = 0;
    has is_baseline: bool = False;
    has allows_recursion: bool = False;
}

node Finding {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has validated: bool = False;
    has allows_recursion: bool = False;
}

edge Contains {
    has phase: str = "";
}

edge Probes {
    has purpose: str = "";
}

edge Produces {
    has confidence: int = 0;
}

walker BlackHoleGuard {
    has accepted: int = 0;
    has rejected: int = 0;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect with ScanTarget entry {
        print(f"preflight {here.title}: {here.mode}, baseline={here.baseline_signature}");
        visit [->:Probes:->] else {
            disengage;
        }
    }

    can filter with Probe entry {
        if here.is_baseline {
            self.rejected += 1;
            print(f"discarded catch-all response {here.title}: {here.signature}");
        } else {
            self.accepted += 1;
            print(f"accepted distinct response {here.title}: {here.signature}");
            visit [->:Produces:->] else {
                disengage;
            }
        }
    }

    can report with Finding entry {
        if here.validated {
            print(f"kept finding {here.title}; recursive fuzzing={here.allows_recursion}");
        } else {
            print(f"discarded unvalidated finding {here.title}");
        }
    }

    can summarize with exit {
        print(f"scan guard summary: accepted={self.accepted}, rejected={self.rejected}");
    }
}

with entry {
