"""Quarantine intake audit with provenance, independent gates, and bounded cycle-safe traversal."""

node SourceArtifact {
    has label: str = "";
    has immutable_hash: str = "";
    has triangle_count: int = 0;
    has untouched: bool = True;
}

node Candidate {
    has label: str = "";
    has derivative_hash: str = "";
    has triangle_count: int = 0;
    has quarantined: bool = True;
}

node ReviewGate {
    has label: str = "";
    has passed: bool = False;
    has independent: bool = True;
}

edge DerivedFrom {
    has evidence_hash: str = "";
}

edge GateFor {
    has gate_kind: str = "";
}

edge DependsOn { }

walker IntakeAuditor {
    has max_depth: int = 4;
    has depth: int = 0;
    has inspected: int = 0;
    has depth_stops: int = 0;

    can start with Root entry {
        print("starting quarantine intake audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_candidate with Candidate entry {
        if self.depth >= self.max_depth {
            self.depth_stops += 1;
            print(f"depth limit reached at {here.label}");
            disengage;
        } else {
            self.depth += 1;
            self.inspected += 1;
            state = "QUARANTINED" if here.quarantined else "READY";
            print(f"{state}: {here.label} ({here.triangle_count} triangles)");
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect_related with SourceArtifact | ReviewGate entry {
        print(f"related record: {here.label}");
        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"audit complete: {self.inspected} candidates inspected, "
              f"{self.depth_stops} bounded cycle/depth stops");
    }
}

