"""Audit graph demo for forecasts, game state, settlement, and cycle detection."""

node AuditRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
}

node Forecast(AuditRecord) {
    has model_id: str = "";
    has probability: float = 0.0;
    has eligible: bool = True;
}

node Game(AuditRecord) {
    has latest_state: str = "";
}

node LedgerEntry(AuditRecord) {
    has stake: float = 0.0;
    has settled: bool = False;
}

edge AuditLink {
    has reason: str = "";
}

walker AuditTrail {
    can start with Root entry {
        print("Starting audit traversal");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Forecast entry {
        if here.visited {
            print(f"Cycle detected at forecast {here.title}");
            disengage;
        } else {
            here.visited = True;
            eligibility = "ELIGIBLE" if here.eligible else "INVALID";
            print(f"Forecast {here.model_id}: {eligibility}");
            visit [->:AuditLink:->] else {
                disengage;
            }
        }
    }

    can inspect with Game entry {
        if here.visited {
            print(f"Cycle detected at game {here.title}");
            disengage;
        } else {
            here.visited = True;
            state = "LIVE" if here.available else "STALE";
            print(f"Game {here.title}: {state} ({here.latest_state})");
            visit [->:AuditLink:->] else {
                disengage;
            }
        }
    }

    can inspect with LedgerEntry entry {
        if here.visited {
