"""Validate task prerequisites with a native Jac depth-first graph walk."""

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has blocked: bool = False;
}

edge Contains { }

edge Requires {
    has reason: str = "";
}

walker CycleDetector {
    has active_ids: list[str] = [];
    has inspected_ids: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        visit [-->] else { disengage; }
    }

    can enter_workflow with Workflow entry {
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_task with Task entry {
        if here.task_id in self.active_ids {
            self.cycle_found = True;
            here.blocked = True;
            disengage;
        } else {
            self.active_ids.append(here.task_id);
            self.inspected_ids.append(here.task_id);
            visit [->:Requires:->] else { disengage; }
        }
    }

    can leave_task with Task exit {
        if len(self.active_ids) > 0 {
            current_id = self.active_ids[len(self.active_ids) - 1];
            if current_id == here.task_id {
                self.active_ids.pop();
            }
        }
    }
}

