    }
}

"""Calyx-style fixture planning for accounts, assets, and dependent contracts."""

node Account {
    has account_id: str = "";
    has funded: bool = False;
}

node Asset {
    has symbol: str = "";
    has issuer: str = "";
}

node Contract {
    has name: str = "";
    has wasm: str = "";
    has address: str = "";
    has initialized: bool = False;
}

edge Funds: Account --> Asset {
    has amount: int = 0;
}

edge Deploys: Account --> Contract { }

edge DependsOn: Contract --> Contract {
    has parameter: str = "";
}

walker FixturePlanner {
    has active_contracts: list[str] = [];
    has seen_contracts: list[str] = [];
    has completed_contracts: list[str] = [];
    has cycle_nodes: list[str] = [];
    has initialization_order: list[str] = [];
    has cycle_count: int = 0;

    can start with Root entry {
        print("planning declarative fixture");
        visit [-->] else { disengage; }
    }

    can order_contract with Contract entry {
        if here.name in self.completed_contracts {
            skip;
        }
        if here.name in self.cycle_nodes {
            print(f"skipping cyclic contract {here.name}");
            disengage;
        }
        if here.name in self.seen_contracts {
            self.cycle_count += 1;
            self.cycle_nodes.append(here.name);
            print(f"cycle or repeated dependency detected at {here.name}");
            disengage;
        }

        self.seen_contracts.append(here.name);
        self.active_contracts.append(here.name);
        dependencies = [here ->:DependsOn:->];

        for dependency in dependencies {
            if dependency.name in self.active_contracts {
                self.cycle_count += 1;
                self.cycle_nodes.append(here.name);
