"""Audit dispatch board with typed relationships and cycle-safe traversal."""

node WorkItem {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Lane(WorkItem) {
    has owner: str = "";
}

node Issue(WorkItem) {
    has state: str = "";
}

node Evidence(WorkItem) {
    has kind: str = "";
}

edge Dispatch {
    has owner: str = "";
}

edge Dependency {
    has reason: str = "";
}

edge EvidenceLink {
    has kind: str = "";
}

walker AuditBoard {
    has seen: list[str] = [];
    has cycle_found: bool = False;

    can begin with Root entry {
        print("Auditing the current-main dispatch board");
        visit [->:Dispatch:->] else { disengage; }
    }

    can inspect with Lane entry {
        print(f"lane {here.title} owned by {here.owner}");
        visit [->:Dispatch:->] else { disengage; }
    }

    can inspect with Issue entry {
        if here.key in self.seen {
            self.cycle_found = True;
            print(f"cycle detected at {here.key}");
        } else {
            self.seen.append(here.key);
            print(f"issue {here.key}: {here.title} [{here.state}]");
            visit [->:Dependency:->] else {
                print(f"no dependencies for {here.key}");
            }
            visit [->:EvidenceLink:->] else {
                print(f"no evidence attached to {here.key}");
            }
        }
    }

    can inspect with Evidence entry {
        print(f"evidence {here.key}: {here.kind}");
    }
}

