"""Native OSP model of a cron lifecycle walker with phase and skill limits."""

node CronJob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has timeout_minutes: int = 45;
}

node Phase {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has order: int = 0;
}

node Issue {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has priority: int = 0;
}

node Skill {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has payload_bytes: int = 0;
}

edge Schedules { }
edge RunsPhase {
    has ordinal: int = 0;
}
edge TracksIssue {
    has priority: int = 0;
}
edge ReadsSkill {
    has payload_bytes: int = 0;
}

walker LifecycleAuditor {
    has skill_budget: int = 2;
    has skills_read: int = 0;
    has hops: int = 0;
    has hop_limit: int = 12;

    can start with Root entry {
        visit [->:Schedules:->] else {
            disengage;
        }
    }

    can inspect with CronJob entry {
        if self.hops >= self.hop_limit {
            print("Traversal stopped at the hop limit");
            disengage;
        }
        self.hops += 1;
        print(f"Cron job: {here.title}, timeout={here.timeout_minutes} minutes");
        visit [->:RunsPhase:->] else {
            disengage;
        }
    }

    can inspect with Phase entry {
        if self.hops >= self.hop_limit {
            print("Traversal stopped at the hop limit");
            disengage;
        }
        self.hops += 1;
        print(f"Phase {here.order}: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Issue entry {
        print(f"Issue: [{here.priority}] {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Skill entry {
        if self.skills_read >= self.skill_budget {
            print("Early exit: skill-read budget reached");
            disengage;
        }
        self.skills_read += 1;
        print(f"Read skill {self.skills_read}: {here.title} ({here.payload_bytes} bytes)");
        visit [-->] else {
            disengage;
        }
    }
}

