"""Creative Partner lens audit with provenance, role canonicalization, and topic normalization."""

node Record {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
}

node RoomTopic(Record) {
    has topic_id: str = "";
    has context_id: str = "";
    has observed_audience: bool = False;
    has simulated_audience: bool = False;
    has disagreement: bool = False;
    has unique_concern: bool = False;
    has unresolved: bool = True;
    has invalidated: bool = False;
    has cycle_detected: bool = False;

    has evidence_origin: str = "none";
    has evidence_basis: str = "insufficient";
    has derived_sufficient: bool = False;
    has derived_basis: str = "insufficient";
    has canonical_evidence_count: int = 0;
    has inferred_evidence_count: int = 0;
    has sufficient_evidence_count: int = 0;

    has canonical_roles: list[str] = [];
    has duplicate_roles: int = 0;

    def recompute() {
        origin_value = "none";
        if self.canonical_evidence_count > 0
            and self.inferred_evidence_count > 0 {
            origin_value = "canonical+bounded-inference";
        } else {
            if self.canonical_evidence_count > 0 {
                origin_value = "canonical";
            } else {
                if self.inferred_evidence_count > 0 {
                    origin_value = "bounded-inference";
                }
            }
        }

        sufficient_value = self.sufficient_evidence_count > 0;
        basis_value = "sufficient" if sufficient_value else "insufficient";

        self.evidence_origin = origin_value;
        self.evidence_basis = basis_value;
        self.derived_sufficient = sufficient_value;
        self.derived_basis = basis_value;
    }
}

node CreativeLens(Record) {
    has lens_id: str = "";
    has policy: str = "";
    has context_id: str = "";
    has audience_truth: str = "observed";
    has decision_authority: bool = False;
}

node Evidence(Record) {
    has origin: str = "canonical";
    has sufficiency: str = "insufficient";
    has statement: str = "";
}

node ProfessionalRole(Record) {
    has alias: str = "";
    has canonical_id: str = "";
    has ontology_only: bool = True;

    def resolved_id() -> str {
        return self.canonical_id;
    }
}

edge Contains {
    has relation: str = "contains";
}

edge TopicLens {
    has relation: str = "evaluated-by";
}

edge TopicEvidence {
    has relation: str = "supported-by";
}

edge TopicRole {
    has relation: str = "linked-role";
}

walker EvidenceAuditor {
    has seen_keys: list[str] = [];
    has current_topic: RoomTopic | None = None;
    has audited_topics: list[RoomTopic] = [];
    has reported: bool = False;

    can begin with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_topic with RoomTopic entry {
        if here.key in self.seen_keys {
            here.cycle_detected = True;
            disengage;
        }

        self.seen_keys.append(here.key);
        self.current_topic = here;
        self.audited_topics.append(here);

        here.canonical_evidence_count = 0;
        here.inferred_evidence_count = 0;
        here.sufficient_evidence_count = 0;
        here.canonical_roles = [];
        here.duplicate_roles = 0;
        here.invalidated = False;
        here.recompute();

        visit [-->] else {
            disengage;
        }
    }

    can inspect_lens with CreativeLens entry {
        if here.key in self.seen_keys {
            if self.current_topic is not None {
                self.current_topic.cycle_detected = True;
            }
            disengage;
        }

        self.seen_keys.append(here.key);

        if self.current_topic is None {
            disengage;
        } else {
            if here.context_id != self.current_topic.context_id {
                self.current_topic.invalidated = True;
            }
            if here.decision_authority {
                self.current_topic.invalidated = True;
            }
        }
    }

    can inspect_evidence with Evidence entry {
        if here.key in self.seen_keys {
            if self.current_topic is not None {
                self.current_topic.cycle_detected = True;
            }
            disengage;
        }

        self.seen_keys.append(here.key);

        if self.current_topic is None {
            disengage;
        } else {
            if here.origin == "canonical" {
                self.current_topic.canonical_evidence_count += 1;
            }
            if here.origin == "bounded-inference" {
                self.current_topic.inferred_evidence_count += 1;
            }
            if here.sufficiency == "sufficient" {
                self.current_topic.sufficient_evidence_count += 1;
            }
            self.current_topic.recompute();
        }
    }

    can inspect_role with ProfessionalRole entry {
        if here.key in self.seen_keys {
            if self.current_topic is not None {
                self.current_topic.cycle_detected = True;
            }
            disengage;
        }

        self.seen_keys.append(here.key);

        if self.current_topic is None {
            disengage;
        } else {
            canonical_role = here.resolved_id();
            if canonical_role in self.current_topic.canonical_roles {
                self.current_topic.duplicate_roles += 1;
            } else {
                self.current_topic.canonical_roles.append(canonical_role);
            }
        }
    }

    can report with Root exit {
        for topic in self.audited_topics {
            topic.recompute();
        }
        self.reported = True;
    }
}

