                self.current_topic.sufficient_evidence_count += 1;
            }
            self.current_topic.recompute();
        }
    }

    can inspect_role with ProfessionalRole entry {
        if here.key in self.seen_keys {
            if self.current_topic is not None {
                self.current_topic.cycle_detected = True;
            }
            disengage;
        }

        self.seen_keys.append(here.key);

        if self.current_topic is None {
            disengage;
        } else {
            canonical_role = here.resolved_id();
            if canonical_role in self.current_topic.canonical_roles {
                self.current_topic.duplicate_roles += 1;
            } else {
                self.current_topic.canonical_roles.append(canonical_role);
            }
        }
    }

    can finalize with Root exit {
        for topic in self.audited_topics {
            topic.recompute();
        }
        self.reported = True;
    }
}

