"""Sync-loop maintenance demo with authentication, prechecks, watches, and cycle detection."""

node SyncSession {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has authenticated: bool = False;
    has waiting_for_two_factor: bool = False;
    has reauth_required: bool = False;
}

node ChangeSet {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has scoped_token: bool = False;
    has precheck_passed: bool = True;
    has invalidated: bool = False;
}

node WatchPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cadence_seconds: int = 30;
    has reconciliation_due: bool = True;
}

edge Authenticates {
    has channel: str = "";
}

edge Precedes { }

edge Monitors {
    has interval_seconds: int = 30;
}

edge DependsOn { }

walker SyncAuditor {
    has seen_titles: list[str] = [];
    has cycle_count: int = 0;
    has inspected_count: int = 0;

    can start with Root entry {
        print("Starting sync-loop audit");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_session with SyncSession entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
            print(f"cycle detected at session {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.inspected_count += 1;

        if here.reauth_required {
            print(f"reauthenticating {here.title}");
            here.reauth_required = False;
            here.authenticated = True;
        } else {
            if here.waiting_for_two_factor {
                print(f"waiting for two-factor recovery for {here.title}");
                here.waiting_for_two_factor = False;
            }

            if not here.authenticated {
                print(f"authenticating {here.title}");
                here.authenticated = True;
            }
        }

        print(f"session ready: {here.title}");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_changes with ChangeSet entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
            print(f"dependency cycle detected at {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.inspected_count += 1;

        if here.scoped_token and not here.precheck_passed {
            here.invalidated = True;
            print(f"invalidating scoped-token change set {here.title}");
        } else {
            print(f"prechecks passed for {here.title}");
        }

        visit [-->] else {
            disengage;
        }
    }

    can inspect_watch with WatchPlan entry {
        if here.title in self.seen_titles {
            self.cycle_count += 1;
            print(f"watch dependency cycle detected at {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.inspected_count += 1;

        cadence_label = "due" if here.reconciliation_due else "waiting";
        availability_label = "active" if here.available else "paused";
        print(f"watch {here.title}: {availability_label}, "
              f"reconciliation {cadence_label} every "
              f"{here.cadence_seconds}s");

        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"audit inspected {self.inspected_count} records and found "
              f"{self.cycle_count} cycle(s)");
    }
}

with entry {
    session = SyncSession(
