    root spawn SyncAuditor();
}

"""In-process session verification cache with burst deduplication and invalidation."""

node PreviewBatch {
    has label: str = "";
    has request_count: int = 0;
}

node Session {
    has cookie_hash: str = "";
    has seen: bool = False;
}

node CacheEntry {
    has cookie_hash: str = "";
    has verified: bool = False;
    has valid: bool = False;
    has age_seconds: int = 0;
    has ttl_seconds: int = 10;
    has cache_hits: int = 0;
    has backend_calls: int = 0;
    has deduplicated_calls: int = 0;
    has invalidation_count: int = 0;
}

node AuthResponse {
    has ok: bool = False;
    has status_code: int = 0;
}

edge Contains { }
edge UsesSession { }
edge Caches { }
edge AuthResult { }

walker SessionCacheVerifier {
    has pending_requests: int = 0;
    has current_entry: CacheEntry | None = None;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_batch with PreviewBatch entry {
        self.pending_requests = here.request_count;
        visit [->:UsesSession:->] else { disengage; }
    }

    can inspect_session with Session entry {
        if here.seen {
            disengage;
        }
        here.seen = True;
        visit [->:Caches:->] else { disengage; }
    }

    can check_cache with CacheEntry entry {
        fresh = here.valid && here.age_seconds <= here.ttl_seconds;
        if fresh {
            here.cache_hits = here.cache_hits + self.pending_requests;
        } else {
            here.backend_calls = here.backend_calls + 1;
            deduped = self.pending_requests - 1 if self.pending_requests > 0 else 0;
            here.deduplicated_calls = here.deduplicated_calls + deduped;
            self.current_entry = here;
            visit [->:AuthResult:->] else { disengage; }
        }
    }

    can apply_auth_result with AuthResponse entry {
        if self.current_entry is not None {
            if here.ok {
                self.current_entry.verified = True;
                self.current_entry.valid = True;
                self.current_entry.age_seconds = 0;
            } else {
                self.current_entry.verified = False;
                self.current_entry.valid = False;
                self.current_entry.invalidation_count =
                    self.current_entry.invalidation_count + 1;
            }
            self.current_entry = None;
        }
    }
}

