}

node Session {
    has cookie_hash: str = "";
}

node CacheEntry {
    has cookie_hash: str = "";
    has verified: bool = False;
    has valid: bool = False;
    has age_seconds: int = 0;
    has ttl_seconds: int = 10;
    has cache_hits: int = 0;
    has backend_calls: int = 0;
    has deduplicated_calls: int = 0;
    has invalidation_count: int = 0;
    has requests_to_serve: int = 0;
    has backend_status_code: int = 200;
}

node AuthResponse {
    has ok: bool = False;
    has status_code: int = 0;
}

edge Contains { }
edge UsesSession { }
edge Caches { }
edge AuthResult { }

walker CacheAuditor {
    has hop_budget: int = 16;

    can start with Root entry {
        if self.hop_budget <= 0 {
            disengage;
        }
        self.hop_budget = self.hop_budget - 1;
        visit [->:Contains:->] else { disengage; }
    }

    can inspect_batch with PreviewBatch entry {
        print(f"burst: {here.label} ({here.request_count} requests)");
        if self.hop_budget <= 0 {
            disengage;
        }
        self.hop_budget = self.hop_budget - 1;
        visit [->:UsesSession:->] else { disengage; }
    }

    can inspect_session with Session entry {
        print(f"session key: {here.cookie_hash}");
        if self.hop_budget <= 0 {
            disengage;
        }
        self.hop_budget = self.hop_budget - 1;
        visit [->:Caches:->] else { disengage; }
    }

    can inspect_cache with CacheEntry entry {
        fresh: bool = here.valid;
        if here.age_seconds > here.ttl_seconds {
            fresh = False;
        }

        if fresh {
            here.cache_hits = here.cache_hits + here.requests_to_serve;
            print(f"cache hit: {here.cookie_hash}, served {here.requests_to_serve} previews");
        } else {
            here.backend_calls = here.backend_calls + 1;
            deduplicated: int = here.requests_to_serve - 1 if here.requests_to_serve > 0 else 0;
            here.deduplicated_calls = here.deduplicated_calls + deduplicated;

            if here.backend_status_code == 200 {
                here.verified = True;
                here.valid = True;
                here.age_seconds = 0;
            } else {
                here.verified = False;
                here.valid = False;
                here.invalidation_count = here.invalidation_count + 1;
            }

            print(f"cache miss: one backend call, {deduplicated} requests deduplicated");

            if self.hop_budget <= 0 {
                disengage;
            }
            self.hop_budget = self.hop_budget - 1;
            visit [->:AuthResult:->] else { disengage; }
        }
    }

    can apply_auth with AuthResponse entry {
        if here.ok {
            print(f"auth {here.status_code}: cache refreshed and verified");
        } else {
            print(f"auth {here.status_code}: cached session invalidated");
        }
    }
}

