"""Native restored-project dependency graph with typed identity and cycle-safe walking."""

node RestoredProject {
    has target_identity: str = "";
    has locator: str = "";
    has restored: bool = False;
    has completion_state: str = "incomplete";
}

node RestoredPackage {
    has identity: str = "";
    has version: str = "";
    has declaration_identity: str = "";
    has evidence_identity: str = "";
}

edge RestoredRoot {
    has target_identity: str = "";
}

edge ProjectReference {
    has source_identity: str = "";
    has target_identity: str = "";
}

edge PackageDependency {
    has declaration_identity: str = "";
    has evidence_identity: str = "";
}

walker DependencyTraversal {
    has selected_target: str = "";
    has visited_keys: list[str] = [];
    has discovered: list[str] = [];
    has project_count: int = 0;
    has package_count: int = 0;
    has revisit_count: int = 0;
    has failed_project_count: int = 0;
    has cycle_detected: bool = False;
    has maximum_depth: int = 0;
    has current_depth: int = 0;
    has completed: bool = False;

    can start with Root entry {
        visit [->:RestoredRoot:->] else { disengage; }
    }

    can inspect_project with RestoredProject entry {
        project_key = "project:" + here.target_identity;
        if len(self.visited_keys) == 0 and here.target_identity != self.selected_target {
            self.failed_project_count += 1;
        } else {
            if project_key in self.visited_keys {
                self.revisit_count += 1;
                self.cycle_detected = True;
            } else {
                self.visited_keys.append(project_key);
                if here.restored {
                    self.project_count += 1;
                    self.discovered.append(project_key + "@" + here.completion_state);
                    if self.current_depth > self.maximum_depth {
                        self.maximum_depth = self.current_depth;
                    }
                    self.current_depth += 1;
                    visit [-->] else { disengage; }
                } else {
                    self.failed_project_count += 1;
                    self.discovered.append(project_key + "@failed");
                }
            }
        }
    }

    can inspect_package with RestoredPackage entry {
        package_key = "package:" + here.identity;
        if package_key in self.visited_keys {
            self.revisit_count += 1;
            self.cycle_detected = True;
        } else {
            self.visited_keys.append(package_key);
            self.package_count += 1;
            self.discovered.append(package_key + "@" + here.evidence_identity);
            if self.current_depth > self.maximum_depth {
                self.maximum_depth = self.current_depth;
            }
            self.current_depth += 1;
            visit [-->] else { disengage; }
        }
    }

    can finish with Root exit {
        self.completed = True;
        report self.discovered;
    }
}

