"""Two-core scheduler demo with typed execution and worklist edges."""

node Core {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cpu_id: int = 0;
    has scheduler_runs: int = 0;
}

node Process {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has progress: int = 0;
    has target: int = 0;
    has quantum: int = 1;
}

node ExecutionState {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slot: int = 0;
    has owner_cpu: int = 0;
    has valid: bool = True;
}

node WorkItem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has units: int = 0;
    has completed: bool = False;
}

edge Runs {
    has dispatches: int = 0;
}

edge StateLink {
    has slot: int = 0;
}

edge PendingWork {
    has sequence: int = 0;
}

walker Scheduler {
    has kernel_core_count: int = 1;
    has active_cores: int = 0;
    has idle_cores: int = 0;
    has valid_slots: int = 0;
    has invalid_slots: int = 0;
    has completed_units: int = 0;
    has combined_progress: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can dispatch with Core entry {
        if here.available {
            self.active_cores += 1;
            here.scheduler_runs += 1;
        }
        visit [->:Runs:->] else {
            self.idle_cores += 1;
        }
    }

    can run with Process entry {
        if here.available {
            previous_progress = here.progress;
            if here.progress < here.target {
                here.progress += here.quantum;
                if here.progress > here.target {
                    here.progress = here.target;
                }
            }
            delta = here.progress - previous_progress;
            self.combined_progress += delta;
        }
        visit [->:StateLink:->] else {
            self.invalid_slots += 1;
        }
    }

    can inspect with ExecutionState entry {
        if here.valid and here.slot >= 0 and here.slot < self.kernel_core_count {
            self.valid_slots += 1;
            visit [->:PendingWork:->] else {
                self.idle_cores += 1;
            }
        } else {
            self.invalid_slots += 1;
        }
    }

    can complete with WorkItem entry {
        if here.available {
            if here.completed == False {
                here.completed = True;
                self.completed_units += here.units;
            }
        }
    }

    can report with Root exit {
        print(f"active cores: {self.active_cores}");
        print(f"valid execution slots: {self.valid_slots}");
        print(f"completed work units: {self.completed_units}");
        print(f"combined busy-loop progress: {self.combined_progress}");
    }
}

