"""Model a control-flow graph with typed edges and cycle-safe cleanup traversal."""

node Program {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has cleanup_rounds: int = 3;
}

node BasicBlock {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has visited: bool = False;
    has simplified: bool = False;
}

edge Contains {
}

edge Branch {
    has kind: str = "";
}

walker CFGReachabilityAudit {
    has reachable_count: int = 0;
    has cycle_count: int = 0;
    has cleanup_rounds_seen: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can enter_program with Program entry {
        self.cleanup_rounds_seen = here.cleanup_rounds;
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_block with BasicBlock entry {
        if here.visited {
            self.cycle_count += 1;
        } else {
            here.visited = True;
            self.reachable_count += 1;
            if here.available {
                here.simplified = True;
            }
            visit [->:Branch:->] else {
                disengage;
            }
        }
    }
}

with entry {
    program = Program(
        title="rucc control-flow optimizer",
        year=2025,
        available=True,
        cleanup_rounds=3
    );

    entry_block = BasicBlock(title="entry", year=0, available=True);
    diamond_block = BasicBlock(title="diamond", year=0, available=True);
    exit_block = BasicBlock(title="exit", year=0, available=True);
    dead_block = BasicBlock(title="dead", year=0, available=False);

    root +>:Contains:+> program;
    program +>:Contains:+> entry_block;
    program +>:Contains:+> diamond_block;
    program +>:Contains:+> exit_block;
    program +>:Contains:+> dead_block;

    entry_block +>:Branch(kind="true"):+> diamond_block;
    entry_block +>:Branch(kind="false"):+> exit_block;
    diamond_block +>:Branch(kind="loop"):+> entry_block;
    diamond_block +>:Branch(kind="continue"):+> exit_block;

    root spawn CFGReachabilityAudit();
}

