"""Bounded browser trace replay with project, locator, fixture, and drift checks."""

node Project {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has project_name: str = "";
    has git_root: str = "";
    has allowed_hostname: str = "";
}

node BrowserTrace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has trace_id: str = "";
    has hostname: str = "";
    has allowed_hostname: str = "";
    has parser_version: str = "";
    has expected_parser_version: str = "";
    has selected_success: bool = False;
    has status: str = "draft";
    has fixture_digest: str = "";
    has revision: int = 0;
}

node TraceStep {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has action: str = "";
    has locator_kind: str = "";
    has locator_value: str = "";
    has locator_matches: int = 0;
    has schema_matches: bool = False;
    has mutating: bool = False;
    has retry_used: bool = False;
    has transient_failures: int = 0;
}

node Fixture {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has fixture_id: str = "";
    has fixture_digest: str = "";
    has positive: bool = False;
    has redacted: bool = False;
}

edge ContainsProject { }
edge OwnsTrace { }
edge ContainsStep { }
edge UsesFixture { }

walker ReplayAuditor {
    has lifecycle: str = "active";
    has steps_seen: int = 0;

    can begin with Root entry {
        visit [->:ContainsProject:->] else {
            disengage;
        }
    }

    can inspect_project with Project entry {
        print(f"Project: {here.project_name} at {here.git_root}");
        visit [->:OwnsTrace:->] else {
            disengage;
        }
    }

    can inspect_trace with BrowserTrace entry {
        if here.selected_success == False {
            self.lifecycle = "stale";
        }
        if here.hostname != here.allowed_hostname {
            self.lifecycle = "stale";
        }
        if here.parser_version != here.expected_parser_version {
            self.lifecycle = "stale";
        }
        if here.status != "approved" {
            self.lifecycle = "stale";
        }

        print(f"Trace {here.trace_id} revision {here.revision}: {self.lifecycle}");
        visit [->:ContainsStep:->] else {
            disengage;
        }
    }

    can replay_step with TraceStep entry {
        self.steps_seen += 1;

        if here.transient_failures > 0 {
            if here.mutating == False && here.retry_used == False {
                print(f"One bounded retry allowed for {here.action}");
            } else {
                self.lifecycle = "stale";
            }
        }

        if here.locator_matches == 0 {
            self.lifecycle = "stale";
        }

        if here.locator_matches > 1 {
            self.lifecycle = "stale";
            if here.mutating == True {
                self.lifecycle = "quarantined";
            }
        }

        if here.schema_matches == False {
            if here.mutating == True && here.locator_matches > 1 {
                self.lifecycle = "quarantined";
            } else {
                self.lifecycle = "stale";
            }
        }

        print(f"Replay {here.action} via {here.locator_kind}: {self.lifecycle}");
        visit [->:UsesFixture:->] else {
            disengage;
        }
    }

    can validate_fixture with Fixture entry {
        if here.redacted == False {
            self.lifecycle = "stale";
        }

        if here.positive == True {
            print(f"Positive redacted fixture {here.fixture_id} checked");
        } else {
            print(f"Negative redacted fixture {here.fixture_id} checked");
        }

        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"Replay finished: {self.lifecycle}, steps={self.steps_seen}");
    }
}

