"""Native cache invalidation demo for recursively included bludfiles."""

node SourceFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has modified_at: int = 0;
    has exists: bool = True;
    has required: bool = True;
}

node BytecodeCache {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has built_at: int = 0;
    has expected_sources: int = 0;
}

edge CompiledFrom {
    has recorded_at: int = 0;
}

edge Includes {
    has wildcard: bool = False;
}

walker CacheAuditor {
    has snapshot_at: int = 0;
    has checked_sources: int = 0;
    has invalidated: bool = False;
    has depth: int = 0;
    has max_depth: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit with BytecodeCache entry {
        self.snapshot_at = here.built_at;
        self.checked_sources = 0;
        self.invalidated = False;
        self.depth = 0;
        visit [->:CompiledFrom:->] else {
            disengage;
        }
    }

    can inspect with SourceFile entry {
        self.checked_sources += 1;

        if not here.exists {
            if here.required {
                self.invalidated = True;
                print(f"missing required source: {here.path}");
            } else {
                print(f"optional source absent: {here.path}");
            }
        } else {
            if here.modified_at > self.snapshot_at {
                self.invalidated = True;
                print(f"changed source: {here.path}");
            } else {
                print(f"unchanged source: {here.path}");
            }
        }

        if self.depth >= self.max_depth {
            self.invalidated = True;
            print(f"dependency depth limit reached at {here.path}");
        } else {
            self.depth += 1;
            visit [->:Includes:->] else {
                disengage;
            }
            self.depth -= 1;
        }
    }

    can report with BytecodeCache exit {
        if self.checked_sources != here.expected_sources {
            self.invalidated = True;
            print("dependency manifest changed");
        }

        status = "REBUILD" if self.invalidated else "REUSE";
        print(f"cache decision: {status}");
    }
}

