}

edge HasStream { }
edge OwnsBuffer { }
edge CarriesFrame { }

walker BorrowedStreamAudit {
    can start with Root entry {
        visit [->:HasStream:->] else {
            disengage;
        }
    }

    can borrow_stream with StreamOwner entry {
        if here.visited {
            disengage;
