        here.visited = True;
        here.borrow_count += 1;

        if here.writer_present == False {
            disengage;
        }

        here.write_count += 1;
        visit [->:OwnsBuffer:->] else {
            disengage;
        }
    }

    can update_buffer with ByteBuffer entry {
        if here.visited {
            disengage;
        }
        here.visited = True;
        here.header_generation += 1;
        here.payload_bytes += 16;
        visit [->:CarriesFrame:->] else {
            disengage;
        }
    }

    can commit_frame with Frame entry {
        if here.visited {
            disengage;
        }
        here.visited = True;
        here.available = False;
    }
}

