    has reason: str = "";
}

walker ResolutionImpact {
    has changed_sheet: str = "";
    has mode: str = "remove";
    has seen: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can enter_workbook with Workbook entry {
        visit [-->] else {
            disengage;
        }
