    can inspect_sheet with Sheet entry {
        if here.title == self.changed_sheet {
            print(f"{self.mode}: scanning references to sheet {here.title}");
            visit [<--:ReferencesSheet:--] else {
                disengage;
            }
        } else {
            disengage;
        }
