            self.seen.append(here.key);
            here.needs_recalc = True;
            if self.mode == "remove" {
                here.resolved = False;
                print(f"unresolved: {here.title} -> {self.changed_sheet}");
            } else {
                here.resolved = True;
                here.needs_recalc = False;
                print(f"resolved: {here.title} -> {self.changed_sheet}");
            }
            visit [<--:DependsOn:--] else {
                disengage;
            }
        }
    }
}

