"""Evidence-group traversal for identity and release accountability proofs."""

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has passage: str = "";
    has kind: str = "";
    has selected: bool = False;
}

node Person {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has nickname: str = "";
}

node Release {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "";
}

edge ProofDependency {
    has rationale: str = "";
}

edge Mentions {
    has rationale: str = "";
}

walker EvidenceSelector {
    has seen: list[str] = [];
    has selected_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can collect with Evidence entry {
        if here.title in self.seen {
            print(f"Cycle detected at evidence: {here.title}");
            disengage;
        } else {
            self.seen.append(here.title);
            here.selected = True;
            self.selected_count += 1;
            print(f"Selected proof passage: {here.passage}");
            visit [->:ProofDependency:->] else {
                disengage;
            }
        }
    }
}

walker RelationAuditor {
    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Evidence entry {
        print(f"Auditing relations for: {here.title}");
        visit [->:Mentions:->] else {
            disengage;
        }
    }

    can inspect with Person | Release entry {
        print(f"Related record: {here.title} ({here.year})");
    }
}

