}

node QueueJob {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "queued";
    has profile: str = "";
    has kind: str = "queue";
}

edge Displays {
    has order: int = 0;
}

edge IncludesRun { }

edge IncludesQueue { }

walker Viewport {
    has width: int = 80;
    has height: int = 24;
    has compact: bool = False;
    has row_budget: int = 8;
    has rows_seen: int = 0;
    has hidden_rows: int = 0;

    can start with Root entry {
        if self.width < 40 {
            self.compact = True;
        } else {
            self.compact = False;
        }

        if self.height < 14 {
            self.row_budget = 3;
            print("[viewport] short terminal: rows are collapsed");
        }

        visit [-->] else {
            disengage;
        }
