    can render_dashboard with Dashboard entry {
        print(f"{here.title} | profile={here.selected_profile}");

        if self.compact {
            print("[compact layout] Runs and Queue remain visible");
        } else {
            print("[full layout] Runs and Queue");
        }

        visit [->:Displays:->] else {
            disengage;
        }
    }

    can render_section with Section entry {
        if self.compact {
            print(f"[{here.title}]");
        } else {
            print(f"--- {here.title}: {here.summary} ---");
        }

        visit [-->] else {
            disengage;
        }
    }

    can render_row with RunRecord | QueueJob entry {
        if self.rows_seen < self.row_budget {
            if self.compact {
                print(f"  {here.kind}: {here.title} [{here.status}]");
            } else {
                print(f"  {here.kind}: {here.title} | {here.profile} | {here.status}");
            }
            self.rows_seen += 1;
        } else {
            self.hidden_rows += 1;
        }
    }

    can summarize with Root exit {
        if self.hidden_rows > 0 {
            print(f"[viewport] {self.hidden_rows} additional rows available by scrolling");
        }
    }
}

