"""Graph-addressed communication for recursive completions."""

node Interaction {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "draft";
    has recursion_seen: bool = False;
    has message_seen: bool = False;
    has cycle_hits: int = 0;
}

node Completion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "draft";
    has recursion_seen: bool = False;
    has message_seen: bool = False;
    has cycle_hits: int = 0;
}

node Layer {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has state: str = "draft";
    has observed: bool = False;
}

node Message {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has kind: str = "";
    has message_seen: bool = False;
    has cycle_hits: int = 0;
}

edge Starts {
    has channel: str = "";
}

edge ChildCompletion {
    has relation: str = "child";
}

edge Publishes {
    has state: str = "working";
}

edge Sends {
    has kind: str = "";
}

edge Targets {
    has address: str = "completion";
}

walker RecursiveCompletionAudit {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can follow_interaction with Interaction entry {
        if here.recursion_seen {
            here.cycle_hits += 1;
            disengage;
        } else {
            here.recursion_seen = True;
            visit [->:Starts:->] else {
                disengage;
            }
        }
    }

    can follow_completion with Completion entry {
        if here.recursion_seen {
            here.cycle_hits += 1;
            disengage;
        } else {
            here.recursion_seen = True;
            visit [->:ChildCompletion:->] else {
                disengage;
            }
        }
    }
}

walker MessageRelayAudit {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_interaction with Interaction entry {
        if here.message_seen {
            here.cycle_hits += 1;
            disengage;
        } else {
            here.message_seen = True;
            visit [->:Starts:->] else {
                disengage;
            }
        }
    }

    can inspect_completion with Completion entry {
        if here.message_seen {
            here.cycle_hits += 1;
            disengage;
        } else {
            here.message_seen = True;
            visit [->:Sends:->] else {
                disengage;
            }
        }
    }

    can inspect_message with Message entry {
        if here.message_seen {
            here.cycle_hits += 1;
            disengage;
        } else {
            here.message_seen = True;
            visit [->:Targets:->] else {
                disengage;
            }
        }
    }
}

walker PublishedLayerAudit {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_interaction with Interaction entry {
        visit [->:Starts:->] else {
            disengage;
        }
    }

    can inspect_completion with Completion entry {
        visit [->:Publishes:->] else {
            disengage;
        }
    }

    can inspect_layer with Layer entry {
        here.observed = True;
    }
}

with entry {
    request = Interaction(
        title="Recursive completion review",
        year=2025,
        state="draft"
    );
    parent = Completion(
        title="Root completion",
        year=2025,
        state="accepted",
        available=True
    );
    child = Completion(
        title="Child completion",
        year=2025,
        state="draft",
        available=False
    );
    parent_layer = Layer(
        title="Root published layer",
        year=2025,
        state="accepted",
        available=True
    );
    child_layer = Layer(
        title="Child working layer",
        year=2025,
        state="draft",
        available=False
    );
    objective = Message(
        title="Objective for child",
        year=2025,
        kind="objective"
    );
    correction = Message(
        title="Correction for parent",
        year=2025,
        kind="correction"
    );

    root +>:Starts(channel="recursive-completion"):+> request;
    request +>:Starts(channel="completion"):+> parent;
    parent +>:ChildCompletion(relation="recursive-child"):+> child;
    parent +>:Publishes(state="accepted"):+> parent_layer;
    child +>:Publishes(state="draft"):+> child_layer;

    parent +>:Sends(kind="objective"):+> objective;
    objective +>:Targets(address="child-completion"):+> child;
    child +>:Sends(kind="correction"):+> correction;
    correction +>:Targets(address="parent-completion"):+> parent;

    root spawn RecursiveCompletionAudit();
    root spawn MessageRelayAudit();
    root spawn PublishedLayerAudit();
}

