"""Shutdown-safe result post-processing with typed graph traversal."""

node Controller {
    has title: str = "controller";
    has year: int = 0;
    has available: bool = True;
    has shutdown_closed: bool = True;
    has result_queue_size: int = 1;
}

node ResultGroup {
    has title: str = "result-group";
    has year: int = 0;
    has available: bool = True;
    has claimed: bool = False;
    has finalization_state: str = "queued";
}

node ModelCall {
    has title: str = "reflection-64";
    has year: int = 0;
    has available: bool = True;
    has lifecycle: str = "in_flight";
    has reflection_started: bool = True;
    has reflection_completed: bool = False;
    has cancellable: bool = True;
}

node TaskStatus {
    has title: str = "task-status";
    has year: int = 0;
    has available: bool = True;
    has status: str = "pending";
}

edge QueueItem {
    has sequence: int = 0;
}

edge Invokes {
    has purpose: str = "";
}

edge Persists {
    has reason: str = "";
}

walker ShutdownSafeProcessor {
    has shutdown_closed: bool = False;
    has hop_count: int = 0;
    has hop_limit: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can claim with Controller entry {
        if self.hop_count >= self.hop_limit {
            print("Traversal stopped at the cycle-safety hop limit");
            disengage;
        } else {
            self.hop_count = self.hop_count + 1;
            self.shutdown_closed = here.shutdown_closed;

            if here.result_queue_size > 0 {
                here.result_queue_size = here.result_queue_size - 1;
                print("Claimed one result group under result_list_lock");
            } else {
                print("Result queue was empty");
            }

            print("Released result_list_lock before post-processing work");
            visit [->:QueueItem:->] else {
                disengage;
            }
        }
    }

    can finalize with ResultGroup entry {
        if self.hop_count >= self.hop_limit {
            print("Traversal stopped at the cycle-safety hop limit");
            disengage;
        } else {
            self.hop_count = self.hop_count + 1;
            here.claimed = True;
            here.finalization_state = "processing_outside_lock";
            print(f"Finalizing {here.title} without holding result_list_lock");
            visit [->:Invokes:->] else {
                disengage;
            }
        }
    }

    can interrupt with ModelCall entry {
        if self.hop_count >= self.hop_limit {
            print("Traversal stopped at the cycle-safety hop limit");
            disengage;
        } else {
            self.hop_count = self.hop_count + 1;

            if self.shutdown_closed {
                if here.reflection_started {
                    if here.lifecycle == "in_flight" {
                        if here.cancellable {
                            here.lifecycle = "cancelled";
                            here.reflection_completed = False;
                            print(f"Cancelled in-flight model call {here.title}");
                        } else {
                            print(f"Bounded fallback recorded for {here.title}");
                        }
                    } else {
                        print(f"Model call {here.title} was already terminal");
                    }
                } else {
                    print(f"Skipped new reflection for {here.title} after shutdown admission closed");
                }
            } else {
                print(f"Reflection remains eligible for {here.title}");
            }

            visit [->:Persists:->] else {
                disengage;
            }
        }
    }

    can record with TaskStatus entry {
        if self.hop_count >= self.hop_limit {
            print("Traversal stopped at the cycle-safety hop limit");
            disengage;
        } else {
            self.hop_count = self.hop_count + 1;
            here.status = "cancelled";
            print(f"Persisted terminal task status: {here.status}");
            visit [-->] else {
                disengage;
            }
        }
    }
}

with entry {
    controller = Controller(
        title="GlobalController",
        shutdown_closed=True,
        result_queue_size=1
    );
    group = ResultGroup(title="K11-result-group");
    call = ModelCall(
        title="K11-P0-01:none:model-call:64",
        lifecycle="in_flight",
        reflection_started=True,
        cancellable=True
    );
    status = TaskStatus(title="K11 task status");

    root ++> controller;
    controller +>:QueueItem(sequence=1):+> group;
    group +>:Invokes(purpose="optional reflection"): +> call;
    call +>:Persists(reason="shutdown-safe terminal state"):+> status;

    root spawn ShutdownSafeProcessor();
}

"""Idempotent child-session cleanup with a benign terminal cancellation race."""

node Session {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Run {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has run_state: str = "active";
    has cancel_error: str = "";
}

edge ChildSession { }
edge OwnsRun { }

walker TerminateChildSessions {
    has seen_sessions: list[str] = [];
    has cancelled_runs: int = 0;
    has benign_conflicts: int = 0;
    has failures: int = 0;
    has cycle_hits: int = 0;
    has reported: bool = False;
    has terminal_conflict: str = "Cannot transition run from terminal state";

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can terminate with Session entry {
        if (here.title in self.seen_sessions) {
            self.cycle_hits += 1;
        } else {
            self.seen_sessions.append(here.title);
            visit [-->] else {
                disengage;
            }
        }
    }

    can cancel with Run entry {
        if (here.run_state == "terminal"
            && here.cancel_error == self.terminal_conflict) {
            self.benign_conflicts += 1;
        } else if (here.cancel_error != "") {
            self.failures += 1;
        } else if (here.run_state != "terminal") {
            here.run_state = "cancelled";
            self.cancelled_runs += 1;
        }
    }

    can report with Root exit {
        self.reported = True;
    }
}

with entry {
    parent = Session(title="parent-session", year=2024);

    child_a = Session(title="child-a", year=2024);
    run_a = Run(
        title="child-a-run",
        year=2024,
        run_state="terminal",
        cancel_error="Cannot transition run from terminal state"
    );

    child_b = Session(title="child-b", year=2024);
    run_b = Run(title="child-b-run", year=2024);

    child_c = Session(title="child-c", year=2024);
