"""Runtime resource admission with bounded dependency traversal and atomic publication."""

node RuntimeGeneration {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has generation_id: int = 0;
    has budget: int = 0;
    has published: bool = False;
}

node Resource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has logical_id: str = "";
    has generation_id: int = 0;
    has size: int = 0;
    has verified: bool = True;
    has materialized: bool = False;
}

edge Candidate {
    has role: str = "";
}

edge DependsOn {
    has kind: str = "";
}

walker Admission {
    has expected_generation: int = 0;
    has budget_left: int = 0;
    has steps: int = 0;
    has failures: int = 0;
    has max_steps: int = 8;
    has published: bool = False;

    can start with Root entry {
        print("Opening an isolated runtime candidate");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with RuntimeGeneration entry {
        self.expected_generation = here.generation_id;
        self.budget_left = here.budget;
        print(f"Validating generation {here.generation_id}");
        visit [->:Candidate:->] else {
            self.failures += 1;
            disengage;
        }
    }

    can materialize with Resource entry {
        if self.steps >= self.max_steps {
            print("Dependency cycle or excessive depth rejected");
            self.failures += 1;
            disengage;
        } else {
            self.steps += 1;
            if here.generation_id != self.expected_generation {
                print(f"Generation mismatch for {here.logical_id}");
                self.failures += 1;
            } elif here.verified == False {
                print(f"Verification failed for {here.logical_id}");
                self.failures += 1;
            } elif here.available == False {
                print(f"Unavailable resource {here.logical_id}");
                self.failures += 1;
            } elif here.size > self.budget_left {
                print(f"Budget exceeded by {here.logical_id}");
                self.failures += 1;
            } else {
                self.budget_left -= here.size;
                here.materialized = True;
                print(f"Materialized {here.logical_id}");
                visit [->:DependsOn:->] else {
                    print(f"No dependencies remain for {here.logical_id}");
                }
            }
        }
    }

    can report with Root exit {
        if self.failures == 0 {
            self.published = True;
            print("One complete immutable generation published");
        } else {
            print(f"Candidate rejected with {self.failures} failure(s)");
        }
    }
}

