node Capability {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has approved: bool = False;
    has actor_allowed: bool = False;
    has bot_allowed: bool = False;
}

node AuditEvent {
    has key: str = "";
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has action: str = "";
    has outcome: str = "";
}

edge Installed {
    has approved_by: str = "";
}

edge Declares { }

edge DependsOn { }

edge Recorded {
    has reason: str = "";
}

walker CapabilityBroker {
    has seen_plugins: list[str] = [];
    has denials: list[str] = [];
    has cycle_hits: int = 0;
    has reports: list[list[str]] = [];

    can start with Root entry {
        print("starting capability broker audit");
        visit [-->] else {
            disengage;
        }
    }

    can enter_guild with Guild entry {
        print(f"guild: {here.name}");
        visit [->:Installed:->] else {
            skip;
        }
    }

    can inspect_plugin with Plugin entry {
        if here.key in self.seen_plugins {
            self.cycle_hits += 1;
            print(f"cycle or revisit blocked at plugin {here.name}");
            skip;
        } else {
            self.seen_plugins.append(here.key);
            print(f"plugin {here.name} version {here.version}");
            visit [->:Declares:->];
            visit [->:DependsOn:->];
        }
    }

    can inspect_capability with Capability entry {
        if here.approved == False {
            self.denials.append(here.name);
            print(f"DENIED: {here.name} requires administrator approval");
        } else {
            if here.actor_allowed == False {
                self.denials.append(here.name);
                print(f"DENIED: {here.name} actor permission failed");
            } else {
                if here.bot_allowed == False {
                    self.denials.append(here.name);
                    print(f"DENIED: {here.name} bot permission failed");
                } else {
                    print(f"ALLOWED: {here.name}");
                }
            }
        }

        visit [->:Recorded:->] else {
            skip;
        }
    }

    can inspect_audit with AuditEvent entry {
        print(f"audit: {here.action} ({here.outcome})");
        visit [-->] else {
            skip;
        }
    }

    can finish with Root exit {
        print(f"summary: {len(self.denials)} denial(s), {self.cycle_hits} cycle revisit(s)");
        report self.denials;
    }
}

