        self.prefer_symlinks = here.prefer_symlinks;
        self.lock_mode = here.lock_mode;
        self.lock_fallback = here.lock_fallback;
        self.stale_lock_recovery = here.stale_lock_recovery;

        print(f"concurrency_cap={self.max_concurrent}, "
              f"materialization=symlink, lock={self.lock_mode}, "
              f"fallback={self.lock_fallback}, "
              f"stale_recovery={self.stale_lock_recovery}");
        visit [->:Dependency:->] else {
            disengage;
        }
    }

    can resolve with Package entry {
        key = here.exact_key();
        old_path = self.path_text;
        next_path = key if old_path == "" else f"{old_path} -> {key}";
        self.path_text = next_path;

        if key in self.active_keys {
            if key not in self.warning_keys {
                self.warning_keys.append(key);
                print(f"{self.warning_channel} "
                      f"path={self.path_text} "
                      f"package={here.org}/{here.name} "
                      f"version={here.version} "
                      f"digest={here.digest} "
                      f"back_edge={key}");
            }
            self.path_text = old_path;
        } else {
            if key in self.completed_keys {
                print(f"reusing completed exact node {key}");
                self.path_text = old_path;
            } else {
                self.active_keys.append(key);
                print(f"installing {key} as symlink overlay at "
                      f"{here.overlay_path}");
                visit [->:Dependency:->] else {
                    print(f"no dependencies for {key}");
                }
                self.active_keys.pop();
                self.completed_keys.append(key);
                print(f"completed {key} without copying payload descendants");
                self.path_text = old_path;
            }
        }
    }
}

