    has available: bool = True;
    has changed: bool = False;
}

node Test {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

edge ReExports {
    has symbol: str = "";
}

edge ImportedBy {
    has imported_name: str = "";
}

walker AffectedSet {
    has target: str = "affected run";
    has base_sha: str = "";
    has head_sha: str = "";
    has source_reached: bool = False;
    has visited_modules: list[str] = [];
    has visited_tests: list[str] = [];
    has selection: ChangeSet | None = None;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can collect_changes with ChangeSet entry {
        if here.title != self.target {
            skip;
        }
        self.selection = here;
        self.base_sha = here.base_sha;
        self.head_sha = here.head_sha;
        visit [-->] else {
            disengage;
        }
    }

    can inspect_module with Module entry {
        if here.title in self.visited_modules {
            skip;
        }
        self.visited_modules.append(here.title);
        if here.changed {
            self.source_reached = True;
        }
        visit [-->] else {
            disengage;
        }
    }

    can collect_test with Test entry {
        if here.title in self.visited_tests {
            skip;
        }
        self.visited_tests.append(here.title);
        if self.source_reached && self.selection is not None {
            self.selection.affected_tests.append(here.title);
            self.selection.affected_count += 1;
        }
    }

    can report with Root exit {
        if self.selection is not None {
            if self.selection.affected_count == 0 {
                print(f"Nothing affected between {self.base_sha} and {self.head_sha}");
            } else {
                print(f"Affected tests between {self.base_sha} and {self.head_sha}: {self.selection.affected_tests}");
            }
        }
    }
}

