    has target: str = "affected run";
    has selection: ChangeSet | None = None;
    has visited: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can load_selection with ChangeSet entry {
        if here.title != self.target {
            skip;
        }
        self.selection = here;
        visit [-->] else {
            disengage;
        }
    }

    can audit_module with Module entry {
        if here.title in self.visited {
            skip;
        }
        self.visited.append(here.title);
        visit [-->] else {
            disengage;
        }
    }

    can audit_test with Test entry {
        if self.selection is not None && here.title in self.selection.affected_tests {
            print(f"Scoped downstream lane runs {here.title}");
        }
    }
}

walker NothingAffectedStep {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can emit_step with ChangeSet entry {
        if here.affected_count == 0 {
            print(f"Nothing affected step: compared {here.base_sha} to {here.head_sha}");
        }
    }
}

