"""Native build-plan graph with typed inputs, dependency ordering, and cycle detection."""

node BuildPlan {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has plan_id: str = "";
    has profile: str = "debug";
    has target: str = "";
    has cache_key: str = "";
    has source_only: bool = True;
}

node SourceInput {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_id: str = "";
    has digest: str = "";
    has path: str = "";
}

node Toolchain {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has compiler: str = "";
    has runtime: str = "";
    has target: str = "";
    has linker: str = "";
}

edge DependsOn {
    has reason: str = "";
}

edge HasSource {
    has role: str = "resolved-source";
}

edge UsesToolchain {
    has role: str = "target-toolchain";
}

walker DependencyAuditor {
    has seen: list[str] = [];
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can order with BuildPlan entry {
        if here.plan_id in self.seen {
            self.findings.append(f"cycle rejected at {here.plan_id}");
            print(f"[cycle] rejected repeated plan {here.plan_id}");
            disengage;
        }

        self.seen.append(here.plan_id);
        self.findings.append(f"accepted {here.plan_id}");
        print(f"[plan] {here.plan_id} -> {here.target}, cache={here.cache_key}");
        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can report with exit {
        print(f"dependency findings: {self.findings}");
    }
}

walker SourceAuditor {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with BuildPlan entry {
        print(f"[source-boundary] plan {here.plan_id} uses a source-only plan");
        visit [->:HasSource:->] else {
            disengage;
        }
    }

    can inspectSource with SourceInput entry {
        print(f"[source] {here.source_id}, digest={here.digest}, path={here.path}");
    }
}

walker ToolchainAuditor {
    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with BuildPlan entry {
        print(f"[toolchain-boundary] validating target for {here.plan_id}");
        visit [->:UsesToolchain:->] else {
            disengage;
        }
    }

    can inspectToolchain with Toolchain entry {
        print(f"[toolchain] compiler={here.compiler}, runtime={here.runtime}, "
              f"target={here.target}, linker={here.linker}");
    }
}

