    has reason: str = "";
}

walker EmploymentAssessor {
    has seen_titles: list[str] = [];
    has visited_count: int = 0;
    has misses: int = 0;
    has unknowns: int = 0;
    has rejects: int = 0;
    has employee_star: int = 0;
    has employer_star: int = 0;
    has employee_seen: bool = False;
    has employer_seen: bool = False;
    has cycle_detected: bool = False;
    has finalized: bool = False;
    has result: str = "unknown";

    def claim(label: str) -> bool {
        if label in self.seen_titles {
            return False;
        }
        self.seen_titles.append(label);
        self.visited_count += 1;
        return True;
    }

    def allowed_weekday(day: str) -> bool {
        return day == "Budha" or day == "Shukra"
            or day == "Adi" or day == "Guru";
    }

    def allowed_nakshatra(star: str) -> bool {
        return star == "Ashwini" or star == "Rohini"
            or star == "Mrigashira" or star == "Pushya"
            or star == "Hasta" or star == "Anuradha"
            or star == "Revati";
    }

    def finish() {
        if self.finalized == False {
            self.finalized = True;
            if self.employee_seen and self.employer_seen {
                distance = ((self.employee_star - self.employer_star + 27) % 27) + 1;
                if distance == 2 {
                    self.rejects += 1;
                }
            } else {
                self.unknowns += 1;
            }

            if self.rejects > 0 {
                self.result = "reject";
            } else {
                if self.misses > 0 {
                    self.result = "fail";
                } else {
                    if self.unknowns > 0 {
                        self.result = "review";
                    } else {
                        self.result = "qualify";
                    }
                }
            }
        }
    }

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_assessment with ServiceAssessment entry {
        if self.claim(here.title) {
            if here.available {
                if here.yoni_maitri != "pass" {
                    if here.yoni_maitri == "unknown" {
                        self.unknowns += 1;
                    } else {
                        self.misses += 1;
                    }
                }
                if here.rasi_lord_friendship != "pass" {
                    if here.rasi_lord_friendship == "unknown" {
                        self.unknowns += 1;
                    } else {
                        self.misses += 1;
                    }
                }
            } else {
                self.unknowns += 1;
            }
            visit [-->] else {
                self.finish();
                disengage;
            }
        } else {
            self.cycle_detected = True;
            self.rejects += 1;
            self.result = "reject";
            disengage;
        }
    }

    can inspect_person with Person entry {
        if self.claim(here.title) {
            if here.role == "employee" {
                self.employee_seen = here.available and here.human
                    and here.star_index > 0;
                if self.employee_seen {
                    self.employee_star = here.star_index;
                } else {
                    self.unknowns += 1;
                }
            } else {
                if here.role == "employer" {
                    self.employer_seen = here.available and here.human
                        and here.star_index > 0;
                    if self.employer_seen {
                        self.employer_star = here.star_index;
                    } else {
                        self.unknowns += 1;
                    }
                } else {
                    self.unknowns += 1;
                }
            }
            visit [-->] else {
                self.finish();
                disengage;
            }
        } else {
            self.cycle_detected = True;
            self.rejects += 1;
            self.result = "reject";
            disengage;
        }
    }

    can inspect_chart with ElectionChart entry {
        if self.claim(here.title) {
            if here.available {
                if self.allowed_weekday(here.weekday) == False {
                    self.misses += 1;
                }
                if self.allowed_nakshatra(here.nakshatra) == False {
                    self.misses += 1;
                }
                if here.benefic_lagna == False {
                    self.misses += 1;
                }
                if here.surya_or_kuja_h10_h11 == False {
                    self.misses += 1;
                }
            } else {
                self.unknowns += 1;
            }
            visit [-->] else {
                self.finish();
                disengage;
            }
        } else {
            self.cycle_detected = True;
            self.rejects += 1;
            self.result = "reject";
            disengage;
        }
    }

    can inspect_context with ServiceContext entry {
        if self.claim(here.title) {
            if here.available {
                if here.service_kind == "public" {
                    if here.ghata_chandra {
                        self.rejects += 1;
                    }
                } else {
                    if here.service_kind == "not sure" {
                        self.unknowns += 1;
                    }
                }
            } else {
                self.unknowns += 1;
            }
            self.finish();
            visit [-->] else {
                disengage;
            }
        } else {
            self.cycle_detected = True;
            self.rejects += 1;
            self.result = "reject";
            disengage;
        }
    }

    can summarize with Root exit {
        report self.result;
    }
}

