"""Semantic impact analysis with bounded traversal, evidence, tests, and cycle safety."""

node ImpactAnalysis {
    has analysis_state: str = "current";
    has requested_depth: int = 3;
    has truncated: bool = False;
    has degraded_reason: str = "";
}

node ChangedSymbol {
    has symbol_id: str = "";
    has file: str = "";
    has line: int = 0;
    has language: str = "";
    has change_kind: str = "";
}

node ImpactedItem {
    has symbol_id: str = "";
    has file: str = "";
    has impact_kind: str = "";
    has relationship: str = "";
    has source_anchor: str = "";
    has reason: str = "";
    has path_distance: int = 0;
    has coverage_state: str = "unknown";
    has coverage_receipt: str = "";
    has mutation_state: str = "unknown";
    has measurement_provenance: str = "";
}

node LikelyTest {
    has test_id: str = "";
    has file: str = "";
    has reason: str = "";
    has relationship: str = "";
    has related_symbol: str = "";
    has distance: int = 0;
    has evidence_anchor: str = "";
}

edge AnalysisStart { }
edge ChangedInAnalysis { }

edge DirectImpact {
    has relationship: str = "";
    has reason: str = "";
    has source_anchor: str = "";
}

edge TransitiveImpact {
    has relationship: str = "";
    has reason: str = "";
    has source_anchor: str = "";
}

edge TestEvidence {
    has relationship: str = "";
    has reason: str = "";
}

walker ImpactWalker {
    has visited: list[str] = [];
    has max_depth: int = 3;
    has truncated: bool = False;
    has analysis_state: str = "current";
    has limit_reason: str = "";

    can begin with Root entry {
        visit [->:AnalysisStart:->] else {
            disengage;
        }
    }

    can configure with ImpactAnalysis entry {
        self.max_depth = here.requested_depth;
        self.analysis_state = here.analysis_state;
        visit [->:ChangedInAnalysis:->] else {
            disengage;
        }
    }

    can inspect_changed with ChangedSymbol entry {
        if here.symbol_id in self.visited {
            print(f"cycle guard: {here.symbol_id}");
        } else {
            self.visited.append(here.symbol_id);
            print(f"changed: {here.symbol_id} in {here.file}:{here.line}");
            visit [->:DirectImpact:->] else {
                disengage;
            }
        }
    }

    can inspect_impact with ImpactedItem entry {
        if here.symbol_id in self.visited {
            print(f"cycle guard: {here.symbol_id}");
        } else {
            self.visited.append(here.symbol_id);
            print(f"{here.impact_kind} impact: {here.symbol_id} "
                  f"via {here.relationship} at distance {here.path_distance}");
            print(f"reason: {here.reason}; source: {here.source_anchor}");
            print(f"coverage={here.coverage_state}; mutation={here.mutation_state}");

            if here.path_distance >= self.max_depth {
                self.truncated = True;
                self.analysis_state = "degraded";
                self.limit_reason = "maximum analysis depth reached";
                print(f"truncated at {here.symbol_id}");
            } else {
                visit [-->] else {
                    disengage;
                }
            }
        }
    }

    can record_test with LikelyTest entry {
        print(f"likely test: {here.test_id} in {here.file}");
        print(f"test reason: {here.reason}; evidence: {here.evidence_anchor}");
        visit [-->] else {
            disengage;
        }
    }

    can report with Root exit {
        state_label = "degraded" if self.truncated else self.analysis_state;
        print(f"analysis state: {state_label}");
        print(f"visited items: {len(self.visited)}");
        if self.truncated {
            print(f"limit reason: {self.limit_reason}");
        }
    }
}

