"""Bootstrap execution graph with dependency traversal and cycle detection."""

node Execution {
    has execution_id: str = "";
    has bootstrap_seconds: int = 0;
    has bootstrap_tokens: int = 0;
    has reused_bootstrap: bool = False;
}

node Phase {
    has phase_name: str = "";
    has duration_seconds: int = 0;
    has token_count: int = 0;
    has status: str = "pending";
}

node Workspace {
    has image_tag: str = "";
    has environment_ready: bool = False;
    has sync_seconds: int = 0;
}

edge ContainsPhase {
    has order: int = 0;
}

edge UsesWorkspace {
    has purpose: str = "";
}

edge DependsOn {
    has reason: str = "";
}

walker BootstrapAudit {
    has seen_phases: list[str] = [];
    has cycle_found: bool = False;
    has total_tokens: int = 0;

    can start with Root entry {
        print("Auditing bootstrap work and dependency reuse");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Execution entry {
        print(f"Execution {here.execution_id}: "
              f"{here.bootstrap_seconds}s, "
              f"{here.bootstrap_tokens} bootstrap tokens");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Phase entry {
        if here.phase_name in self.seen_phases {
            self.cycle_found = True;
            print(f"Cycle or repeated dependency detected at {here.phase_name}");
            disengage;
        } else {
            self.seen_phases.append(here.phase_name);
            self.total_tokens += here.token_count;
            print(f"Phase {here.phase_name}: {here.status}, "
                  f"{here.token_count} tokens");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect with Workspace entry {
        if here.environment_ready {
            print(f"Reusable workspace image: {here.image_tag}");
        } else {
            print(f"Cold workspace image: {here.image_tag}, "
                  f"sync cost {here.sync_seconds}s");
        }
    }
}

