"""Task roots and subtree severity rollups using one native graph walk per root."""

node Workspace {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has status: str = "";
    has severity: int = 0;
}

edge RootTask {
    has position: int = 0;
}

edge Subtask {
    has kind: str = "";
}

walker SeverityRollup {
    has root_title: str = "";
    has highest: int = 0;
    has nodes_scanned: int = 0;
    has seen_titles: list[str] = [];

    can rollup with Task entry {
        if here.title in self.seen_titles {
            print(f"cycle detected while scanning {self.root_title} at {here.title}");
            disengage;
        }

        self.seen_titles.append(here.title);
        self.nodes_scanned += 1;

        if here.severity > self.highest {
            self.highest = here.severity;
        }

        print(f"scan {self.root_title}: {here.title} "
              f"status={here.status} severity={here.severity}");

        visit [->:Subtask:->] else {
            print(f"rollup {self.root_title}: severity={self.highest}, "
                  f"nodes={self.nodes_scanned}");
            disengage;
        }
    }
}

