"""Reanchor a frozen ledger by propagating identity changes through dependents."""

node Ledger {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node FrozenRecord {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_path: str = "";
    has statement_id: str = "";
    has frozen_node_id: str = "";
    has prerequisite_frozen_node_id: str = "";
    has replacement_frozen_node_id: str = "";
    has statement_changed: bool = False;
    has reemitted: bool = False;
}

edge Contains {
    has relation: str = "ledger member";
}

edge PrerequisiteOf {
    has relation: str = "prerequisite";
}

walker ReanchorClosure {
    has seen_paths: list[str] = [];
    has last_replacement_frozen_node_id: str = "";
    has reemitted_count: int = 0;

    can begin with Root entry {
        print("Starting reanchor closure walk");
        visit [-->] else {
            disengage;
        }
    }

    can enter with Ledger entry {
        print(f"Walking ledger: {here.title}");
        self.last_replacement_frozen_node_id = "";
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can reanchor with FrozenRecord entry {
        if here.source_path in self.seen_paths {
            print(f"cycle guard stopped at {here.source_path}");
            disengage;
        }

        self.seen_paths.append(here.source_path);

        old_id = here.frozen_node_id;
        old_prerequisite = here.prerequisite_frozen_node_id;
        record_kind = "drift seed" if here.statement_changed else "transitive dependent";

        if here.statement_changed {
            here.replacement_frozen_node_id = here.frozen_node_id + "-reanchored";
        } else {
            here.replacement_frozen_node_id = here.frozen_node_id + "-closure";
        }

        if self.last_replacement_frozen_node_id != "" {
            here.prerequisite_frozen_node_id = self.last_replacement_frozen_node_id;
        }

        here.frozen_node_id = here.replacement_frozen_node_id;
        here.reemitted = True;
        self.last_replacement_frozen_node_id = here.frozen_node_id;
        self.reemitted_count += 1;

        print(
            f"{record_kind}: {here.source_path} "
            f"{old_id} -> {here.frozen_node_id}; "
            f"prerequisite {old_prerequisite} -> "
            f"{here.prerequisite_frozen_node_id}"
        );

        visit [->:PrerequisiteOf:->] else {
            disengage;
        }
    }

    can report with Root exit {
        print(f"Closed-DAG closure re-emitted {self.reemitted_count} records");
    }
}

