"""A native OSP model of serialized region writes and ancestor invalidation."""

node RegionAtlas {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tile_version: int = 0;
}

node GeoRegion {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has uses_hull: bool = False;
    has geometry_invalidated: bool = False;
}

edge ParentOf {
    has relation: str = "parent";
}

edge InWorld {
    has relation: str = "world view";
}

walker RegionTransaction {
    has requested_hull: bool = False;
    has hull_changed: bool = False;
    has wrote_region: bool = False;
    has transaction_open: bool = True;
    has committed: bool = False;
    has rolled_back: bool = False;
    has depth: int = 0;
    has max_depth: int = 8;
    has invalidation_count: int = 0;

    can start with Root entry {
        print(f"BEGIN region write: uses_hull={self.requested_hull}");
        visit [-->] else {
            self.rolled_back = True;
            self.transaction_open = False;
            print("ROLLBACK: target region was not found");
            disengage;
        }
    }

    can apply with GeoRegion entry {
        if self.depth >= self.max_depth {
            self.rolled_back = True;
            self.transaction_open = False;
            print("ROLLBACK: parent cycle or depth limit detected");
            disengage;
        } else {
            if self.wrote_region == False {
                prior_hull = here.uses_hull;
                self.hull_changed = prior_hull != self.requested_hull;
                here.uses_hull = self.requested_hull;
                self.wrote_region = True;
                print(f"locked {here.title}: {prior_hull} -> {here.uses_hull}");
            }
            here.geometry_invalidated = True;
            self.invalidation_count += 1;
            self.depth += 1;
            visit [->:ParentOf:->] else {
                visit [->:InWorld:->] else {
                    self.rolled_back = True;
                    self.transaction_open = False;
                    print("ROLLBACK: invalidation closure was incomplete");
                    disengage;
                }
            }
        }
    }

    can finish with RegionAtlas entry {
        if self.hull_changed {
            here.tile_version += 1;
        }
        self.committed = True;
        self.transaction_open = False;
        print(f"COMMIT: invalidated {self.invalidation_count} regions, tile_version={here.tile_version}");
        disengage;
    }
}

