    view = RegionAtlas(title="Europe atlas", year=2025, available=True);
    parent = GeoRegion(title="Europe", year=2025, available=True, uses_hull=True);
    target = GeoRegion(title="Alps", year=2025, available=True, uses_hull=False);

    root ++> target;
    target +>:ParentOf(relation="region parent"):+> parent;
    parent +>:InWorld(relation="world view"):+> view;

