"""Pipeline-parallel scheduler view that avoids copying KV metadata."""

node SchedulerOutput {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pp_world_size: int = 1;
    has is_last_rank: bool = False;
}

node CachedRequestData {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has new_token_ids: list[list[int]] = [];
    has all_batches_empty: bool = False;
    has pp_world_size: int = 1;
    has is_last_rank: bool = False;
}

node KvConnectorMetadata {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has block_hashes: list[str] = [];
    has block_ids: list[int] = [];
}

node WorkerLocalView {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has new_token_ids: list[list[int]] = [];
    has metadata_copied: bool = False;
}

edge ScheduledData { }
edge KVMetadataLink { }
edge LocalViewOf { }

walker PPWorker {
    has worker_name: str = "";
    has local_views: int = 0;

    can start with Root entry {
        print(f"{self.worker_name}: begin graph walk");
        visit [-->] else { disengage; }
    }

    can inspect_output with SchedulerOutput entry {
        rank_label = "last" if here.is_last_rank else "non-last";
        print(f"{self.worker_name}: {rank_label} PP rank sees {here.title}");
        visit [->:ScheduledData:->] else { disengage; }
    }

    can inspect_cached with CachedRequestData entry {
        if (here.pp_world_size > 1 and not here.is_last_rank
            and here.new_token_ids != [] and here.all_batches_empty) {
            local_view = WorkerLocalView(
                title="worker-local scheduler view",
                new_token_ids=[],
                metadata_copied=False
            );
            here +>:LocalViewOf:+> local_view;
            self.local_views += 1;
            print(f"{self.worker_name}: replaced only the local shell; KV metadata was not copied");
        } else {
            print(f"{self.worker_name}: retained the original cached request data");
        }
        visit [-->] else { disengage; }
    }

    can inspect_metadata with KvConnectorMetadata entry {
        print(f"{self.worker_name}: reached KV metadata {here.title}; original object remains shared");
    }

    can inspect_local_view with WorkerLocalView entry {
        print(f"{self.worker_name}: local new_token_ids={here.new_token_ids}, metadata_copied={here.metadata_copied}");
    }
}

