    );

    last_output = SchedulerOutput(
        title="SchedulerOutput on PP3",
        pp_world_size=4,
        is_last_rank=True
    );
    last_data = CachedRequestData(
        title="CachedRequestData on PP3",
        new_token_ids=[[], []],
        all_batches_empty=True,
        pp_world_size=4,
        is_last_rank=True
    );
    last_metadata = KvConnectorMetadata(
        title="last-rank KV metadata",
