"""Bounded tactical reachability over a player-known movement graph."""

node Tile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has terrain_ap: int = 1;
    has elevation: int = 0;
    has in_zoc: bool = False;
    has ally_occupied: bool = False;
    has enemy_occupied: bool = False;
    has hidden_occupied: bool = False;
    has jump_over_ally: bool = False;
    has mandatory_landing: bool = False;
    has landing_clear: bool = True;
}

node Actor {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has action_points: int = 9;
    has fatigue: int = 0;
    has elevation: int = 0;
    has in_zoc: bool = False;
    has rooted: bool = False;
    has stunned: bool = False;
}

edge Route {
    has ap_cost: int = 1;
    has jump_over_ally: bool = False;
    has mandatory_landing: bool = False;
}

walker Reachability {
    has owner: Actor | None = None;
    has remaining_ap: int = 0;
    has max_steps: int = 4;
    has steps: int = 0;
    has last_elevation: int = 0;
    has in_zoc: bool = False;
    has reachable_titles: list[str] = [];
    has seen_titles: list[str] = [];
    has blocked_moves: int = 0;

    can start with Root entry {
        if self.owner is None {
            disengage;
        }
        if self.owner.rooted or self.owner.stunned {
            disengage;
        }
        self.remaining_ap = self.owner.action_points - self.owner.fatigue;
        self.last_elevation = self.owner.elevation;
        self.in_zoc = self.owner.in_zoc;
        visit [-->] else {
            disengage;
        }
    }

    can expand with Tile entry {
        if here.title in self.seen_titles {
            skip;
        }
        if self.steps >= self.max_steps {
            skip;
        }

        self.seen_titles = self.seen_titles + [here.title];
        self.steps += 1;

        if here.enemy_occupied {
            self.blocked_moves += 1;
            skip;
        }
        if here.ally_occupied and not here.jump_over_ally {
            self.blocked_moves += 1;
            skip;
        }
        if here.jump_over_ally {
            if not here.mandatory_landing {
                self.blocked_moves += 1;
                skip;
            }
            if not here.landing_clear {
                self.blocked_moves += 1;
                skip;
            }
        }

        elevation_delta = here.elevation - self.last_elevation;
        elevation_cost = elevation_delta if elevation_delta > 0 else 0;
        zoc_cost = 4 if self.in_zoc else 0;
        move_cost = here.terrain_ap + elevation_cost + zoc_cost;

        if move_cost > self.remaining_ap {
            self.blocked_moves += 1;
            skip;
        }

        self.remaining_ap -= move_cost;
        self.last_elevation = here.elevation;
        self.in_zoc = here.in_zoc;
        self.reachable_titles = self.reachable_titles + [here.title];

        # Hidden occupants are deliberately ignored as unknown player state.
        visit [->:Route:->] else {
            disengage;
        }
    }
}

with entry {
    commander = Actor(
        title="Scout",
        action_points=10,
        fatigue=1,
        elevation=0,
        in_zoc=False,
        rooted=False,
        stunned=False
    );

    start = Tile(title="Start", terrain_ap=0);
    open_ground = Tile(
        title="Open Ground",
        terrain_ap=1,
        hidden_occupied=True
    );
    ally_blocked = Tile(
        title="Ally Occupied",
        terrain_ap=1,
        ally_occupied=True
    );
    jump_landing = Tile(
        title="Jump Landing",
        terrain_ap=1,
        elevation=2,
        in_zoc=False,
        jump_over_ally=True,
        mandatory_landing=True,
        landing_clear=True
    );
    enemy_front = Tile(
        title="Enemy Front",
        terrain_ap=1,
        enemy_occupied=True,
        jump_over_ally=True,
        mandatory_landing=True,
        landing_clear=True
    );

    root ++> start;
    start +>:Route(ap_cost=1):+> open_ground;
    start +>:Route(ap_cost=1):+> enemy_front;
    open_ground +>:Route(ap_cost=1):+> ally_blocked;
    open_ground +>:Route(
        ap_cost=1,
        jump_over_ally=True,
        mandatory_landing=True
    ):+> jump_landing;
    jump_landing +>:Route(ap_cost=1):+> open_ground;

    root spawn Reachability(owner=commander, max_steps=4);
}

