        if move_cost > self.remaining_ap {
            self.blocked_moves += 1;
            disengage;
        }

        self.remaining_ap -= move_cost;
        self.last_elevation = here.elevation;
        self.in_zoc = here.in_zoc;
        self.reachable_titles = self.reachable_titles + [here.title];

        visit [->:Route:->] else {
            disengage;
        }
    }
}

