"""Zed platform repository boundaries, dependency reachability, and cycle detection."""

node Organization {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "";
}

node Repository {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "";
}

node Capability {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has role: str = "";
}

edge Owns {
    has boundary: str = "";
}

edge Requires {
    has reason: str = "";
}

walker BoundaryAuditor {
    has seen: list[str] = [];

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can map with Organization entry {
        print(f"Auditing organization boundary: {here.title}");
        visit [->:Owns:->] else {
            disengage;
        }
    }

    can inspect with Repository | Capability entry {
        if here.title in self.seen {
            print(f"Cycle detected at {here.title}");
            disengage;
        } else {
            self.seen = self.seen + [here.title];
            status = "available" if here.available else "blocked";
            print(f"[{status}] {here.role}: {here.title} ({here.year})");
            visit [->:Requires:->] else {
                disengage;
            }
        }
    }
}

with entry {
    org = Organization(
        title="Zed Platform",
        year=2026,
        role="organization"
    );

    interfaces = Repository(
        title="zed-interfaces",
        year=2026,
        role="contract boundary"
    );

    core = Repository(
        title="zed-lib-core",
        year=2026,
        role="domain core"
    );

    orm = Repository(
        title="zed-orm-core",
        year=2026,
        role="ORM implementation"
    );

    onboarding = Capability(
        title="Organization Onboarding",
        year=2026,
        role="customer capability"
    );

    public_core = Repository(
        title="zed-pub-lib-core",
        year=2026,
        role="public client core"
    );

    root ++> org;
    org +>:Owns(boundary="platform")+> interfaces;
    org +>:Owns(boundary="customer")+> onboarding;
    interfaces +>:Requires(reason="generated contracts")+> core;
    core +>:Requires(reason="persistent model")+> orm;
    onboarding +>:Requires(reason="shared domain behavior")+> core;
    orm +>:Requires(reason="public API exposure")+> public_core;
    public_core +>:Requires(reason="contract feedback cycle")+> interfaces;

    root spawn BoundaryAuditor();
}

"""Session workflow projection with one shared task index and cycle-safe dependency traversal."""

node Workflow {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has projection_runs: int = 0;
    has task_index_builds: int = 0;
    has projected_todos: int = 0;
    has projected_tools: int = 0;
    has projected_tasks: int = 0;
}

node Todo {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has todo_id: str = "";
    has status: str = "";
}

node Tool {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tool_id: str = "";
    has todo_id: str = "";
    has state: str = "";
}

node Task {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has task_id: str = "";
    has parent_id: str = "";
    has state: str = "";
}

edge OwnsWorkflow { }
edge ContainsTodo { }
edge UsesTool { }
edge RunsTask { }
edge DependsOn { }

walker WorkflowProjector {
    has task_index: list[str] = [];

    can start with Root entry {
        visit [->:OwnsWorkflow:->] else {
            disengage;
        }
    }

    can enter_workflow with Workflow entry {
        here.projection_runs += 1;
        here.task_index_builds += 1;
        visit [->:ContainsTodo:->] else {
            disengage;
        }
    }

    can collect_todo with Todo entry {
        here.status = "projected";
        visit [->:UsesTool:->] else {
            disengage;
        }
    }

    can collect_tool with Tool entry {
        visit [->:RunsTask:->] else {
            disengage;
        }
    }

    can index_task with Task entry {
        self.task_index.append(here.task_id);
    }
}

walker DependencyAuditor {
    has seen_ids: list[str] = [];
    has cycle_hits: int = 0;

    can start with Root entry {
        visit [->:OwnsWorkflow:->] else {
            disengage;
        }
    }

    can inspect_workflow with Workflow entry {
        visit [->:ContainsTodo:->] else {
            disengage;
        }
    }

    can follow_dependency with Todo entry {
        if here.todo_id in self.seen_ids {
            self.cycle_hits += 1;
            disengage;
        } else {
            self.seen_ids.append(here.todo_id);
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }
}

with entry {
    workflow = Workflow(title="Session workflow", year=2025);

    plan = Todo(
        title="Build projection",
        todo_id="plan",
        status="pending"
    );
    inspect = Todo(
        title="Inspect execution",
        todo_id="inspect",
        status="pending"
    );
    finish = Todo(
        title="Finish session",
        todo_id="finish",
        status="pending"
    );

    planner = Tool(
        title="Planner tool",
        tool_id="planner",
        todo_id="plan",
        state="running"
    );
    inspector = Tool(
        title="Inspector tool",
        tool_id="inspector",
        todo_id="inspect",
        state="idle"
    );

    planner_task = Task(
        title="Projection task",
        task_id="task-plan",
        parent_id="plan",
        state="running"
    );
    inspector_task = Task(
        title="Inspection task",
        task_id="task-inspect",
        parent_id="inspect",
        state="queued"
    );

    root +>:OwnsWorkflow:+> workflow;
    workflow +>:ContainsTodo:+> plan;
    workflow +>:ContainsTodo:+> inspect;
    workflow +>:ContainsTodo:+> finish;

    plan +>:UsesTool:+> planner;
    inspect +>:UsesTool:+> inspector;
    planner +>:RunsTask:+> planner_task;
    inspector +>:RunsTask:+> inspector_task;

    plan +>:DependsOn:+> inspect;
    inspect +>:DependsOn:+> finish;
    finish +>:DependsOn:+> plan;

    root spawn WorkflowProjector();
    root spawn DependencyAuditor();
}

"""Audit an orphaned daemon and its MCP servers through native graph traversal."""

edge Hosts {
    has relation: str = "mcp-child";
}

edge DependsOn { }

node Daemon {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pid: int = 0;
    has systemd_managed: bool = False;
    has environment_loaded: bool = False;
    has recovery_hint: str = "vision stop";
    has state: str = "stopped";
    has takeover_needed: bool = False;
}

node Server {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has credential_variable: str = "";
    has credential_value: str = "";
    has state: str = "stopped";
    has audit_seen: bool = False;
}

walker DaemonAudit {
    has degraded_servers: int = 0;
    has cycle_detected: bool = False;
    has findings: list[str] = [];

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_daemon with Daemon entry {
        if here.state == "running" {
            if here.systemd_managed {
                here.takeover_needed = False;
            } else {
                here.takeover_needed = True;
                here.recovery_hint = "vision daemon stop";
                self.findings.append(f"orphan daemon pid {here.pid} needs takeover");
                self.findings.append(f"recovery hint: {here.recovery_hint}");
            }
            if here.environment_loaded {
                self.findings.append("daemon environment file loaded");
            } else {
                self.findings.append("daemon environment file was not loaded");
            }
        }
        visit [->:Hosts:->] else { disengage; }
    }

    can inspect_server with Server entry {
        if here.audit_seen {
            self.cycle_detected = True;
            self.findings.append(f"dependency cycle revisited at {here.title}");
            disengage;
        }

        here.audit_seen = True;

        if here.credential_variable != "" {
            if here.credential_value == "" {
                here.state = "degraded";
                here.available = False;
                self.degraded_servers += 1;
                self.findings.append(
                    f"{here.title} is degraded: {here.credential_variable} is empty"
                );
            } else {
                here.state = "running";
                here.available = True;
            }
        }

        visit [->:DependsOn:->] else {
            self.findings.append(f"checked {here.title}");
        }
    }

    can summarize with Root exit {
        print(f"degraded servers: {self.degraded_servers}");
        print(f"cycle detected: {self.cycle_detected}");
        for finding in self.findings {
            print(finding);
        }
        report self.findings;
    }
}

with entry {
    daemon = Daemon(
        title="vision",
        pid=1783846,
        systemd_managed=False,
        environment_loaded=False,
        state="running"
    );
    root ++> daemon;

    exa = Server(
        title="exa",
        credential_variable="EXA_API_KEY"
    );
    context7 = Server(
        title="context7",
        credential_variable="CONTEXT7_API_KEY"
    );

    daemon +>:Hosts(relation="mcp-child"):+> exa;
    daemon +>:Hosts(relation="mcp-child"):+> context7;
    exa +>:DependsOn:+> context7;
    context7 +>:DependsOn:+> exa;

    root spawn DaemonAudit();
}

"""CILI source admission: repeated requests share canonical structure and witnesses stay separate."""

node AdmissionRequest {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has raw_operands: int = 0;
    has source_profile: str = "";
}

node CanonicalEntity {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has canonical_kind: str = "";
    has tier_zero: bool = False;
    has persisted: bool = False;
}

node Physicality {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has trajectory_key: str = "";
    has canonical_key: str = "";
}

node StructuralWitness {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key: str = "";
    has provider: str = "";
    has span_start: int = 0;
    has span_end: int = 0;
    has explicit: bool = True;
    has logical: bool = True;
}

edge StructureLink {
    has relation: str = "";
}

walker AdmissionAudit {
    has seen_keys: list[str] = [];
    has request_count: int = 0;
    has canonical_count: int = 0;
    has physicality_count: int = 0;
    has witness_count: int = 0;
    has explicit_witness_count: int = 0;
    has logical_occurrence_count: int = 0;
    has revisit_count: int = 0;

    can start with Root entry {
        visit [->:StructureLink:->] else { disengage; }
    }

    can audit_request with AdmissionRequest entry {
        self.request_count += 1;
        visit [->:StructureLink:->] else { disengage; }
    }

    can audit_canonical with CanonicalEntity entry {
        if (here.key in self.seen_keys) {
            self.revisit_count += 1;
        } else {
            self.seen_keys = self.seen_keys + [here.key];
            self.canonical_count += 1;
            visit [->:StructureLink:->] else { disengage; }
        }
    }

    can audit_physicality with Physicality entry {
        if (here.key in self.seen_keys) {
            self.revisit_count += 1;
        } else {
            self.seen_keys = self.seen_keys + [here.key];
            self.physicality_count += 1;
            visit [->:StructureLink:->] else { disengage; }
        }
    }

    can audit_witness with StructuralWitness entry {
        if (here.key in self.seen_keys) {
            self.revisit_count += 1;
        } else {
            self.seen_keys = self.seen_keys + [here.key];
            self.witness_count += 1;
            if (here.explicit) {
                self.explicit_witness_count += 1;
            }
            if (here.logical) {
                self.logical_occurrence_count += 1;
            }
            visit [->:StructureLink:->] else { disengage; }
        }
    }
}

with entry {
    request = AdmissionRequest(
        key="request:first",
        source_profile="locked-CILI",
        raw_operands=2
    );
    replay = AdmissionRequest(
        key="request:replay",
        source_profile="locked-CILI",
        raw_operands=2
    );
    canonical = CanonicalEntity(
        key="canon:tier0:A",
        canonical_kind="atom",
        tier_zero=True,
        persisted=True
    );
    trajectory = Physicality(
        key="phys:trajectory:A",
        trajectory_key="trajectory:A",
        canonical_key="canon:tier0:A"
    );
    uax = StructuralWitness(
        key="witness:uax:0:1",
        provider="UAX",
        span_start=0,
        span_end=1,
        explicit=True,
        logical=True
    );
    grammar = StructuralWitness(
        key="witness:grammar:0:1",
        provider="grammar",
        span_start=0,
        span_end=1,
        explicit=True,
