    );

    root +>:StructureLink(relation="source-request"):+> request;
    root +>:StructureLink(relation="replayed-request"):+> replay;
    request +>:StructureLink(relation="canonical-lookup"):+> canonical;
    replay +>:StructureLink(relation="canonical-lookup"):+> canonical;
    canonical +>:StructureLink(relation="physicality"):+> trajectory;
    trajectory +>:StructureLink(relation="uax-witness"):+> uax;
    trajectory +>:StructureLink(relation="grammar-witness"):+> grammar;
    canonical +>:StructureLink(relation="recursive-plan-cycle"):+> canonical;

    root spawn AdmissionAudit();
}

"""Canonical content identity stays separate from source witnesses during graph traversal."""

node Document {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
}

node Content {
    has content_text: str = "";
    has canonical_key: str = "";
    has depth: int = 0;
}

node Witness {
    has provider: str = "";
    has source: str = "";
    has byte_offset: int = 0;
    has media: str = "";
}

edge Contains {
    has position: int = 0;
}

edge WitnessedBy { }

walker CanonicalAudit {
    has seen: list[str] = [];
    has canonical_count: int = 0;
    has witness_count: int = 0;

    can start with Root entry {
        print("Starting canonical decomposition audit");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can follow with Document entry {
        print(f"Document: {here.title} ({here.year})");
        visit [->:Contains:->] else {
            print(f"No content in {here.title}");
        }
    }

