"""Complex stationarity graph demo with explicit solver and provenance boundaries."""

node GraphRecord {
    has label: str = "";
    has solver_seen: bool = False;
    has provenance_seen: bool = False;
}

node SolverProblem(GraphRecord) {
    has mode: str = "strict";
    has action_real: float = 0.0;
    has action_imag: float = 0.0;
    has fz_real: float = 0.0;
    has fz_imag: float = 0.0;
    has fu_real: float = 0.0;
    has fu_imag: float = 0.0;
    has residual_merit: float = 0.0;
    has refusal: str = "";
    has downstream_blocked: bool = True;
}

node Geometry(GraphRecord) {
    has z_real: float = 0.0;
    has z_imag: float = 0.0;
    has u_real: float = 1.0;
    has u_imag: float = 0.0;
    has delta_xi_real: float = 0.0;
    has delta_xi_imag: float = 0.0;
    has update_rule: str = "U <- U * exp(delta_xi)";
    has materialized: bool = False;
}

node CarriedState(GraphRecord) {
    has covariance_real: float = 0.0;
    has covariance_imag: float = 0.0;
    has bilinear_real: float = 0.0;
    has bilinear_imag: float = 0.0;
    has particle_verdict: str = "";
}

node DownstreamRead(GraphRecord) {
    has read_kind: str = "";
    has visualization_value: str = "";
    has reaches_solver: bool = False;
}

edge SolverRoot { }
edge SolverInput {
    has role: str = "";
}
edge ReadRoot { }
edge ReadsGeometry {
    has reason: str = "";
}

walker StationaritySolver {
    has active_mode: str = "strict";
    has solver_nodes: int = 0;
    has geometry_nodes: int = 0;
    has state_nodes: int = 0;
    has mean_field_real: float = 0.0;
    has mean_field_imag: float = 0.0;

    can start with Root entry {
        visit [->:SolverRoot:->] else {
            disengage;
        }
    }

    can assemble with SolverProblem entry {
        if here.solver_seen {
            disengage;
        }
        here.solver_seen = True;
        self.active_mode = here.mode;
        self.solver_nodes = self.solver_nodes + 1;
        here.downstream_blocked = True;
        visit [->:SolverInput:->] else {
            disengage;
        }
    }

    can inspect_geometry with Geometry entry {
        if here.solver_seen {
            disengage;
        }
        here.solver_seen = True;
        self.geometry_nodes = self.geometry_nodes + 1;
        visit [->:SolverInput:->] else {
            disengage;
        }
    }

    can carry_state with CarriedState entry {
        if here.solver_seen {
            disengage;
        }
        here.solver_seen = True;
        self.state_nodes = self.state_nodes + 1;
        if self.active_mode == "certificates_blind_mean_field" {
            self.mean_field_real = self.mean_field_real + here.bilinear_real;
            self.mean_field_imag = self.mean_field_imag + here.bilinear_imag;
        }
        visit [->:SolverInput:->] else {
            disengage;
        }
    }
}

walker ProvenanceAudit {
    has read_nodes: int = 0;
    has geometry_reads: int = 0;

    can start with Root entry {
        visit [->:ReadRoot:->] else {
            disengage;
        }
    }

    can audit_read with DownstreamRead entry {
        if here.provenance_seen {
            disengage;
        }
        here.provenance_seen = True;
        here.reaches_solver = False;
        self.read_nodes = self.read_nodes + 1;
        visit [->:ReadsGeometry:->] else {
            disengage;
        }
    }

    can audit_geometry with Geometry entry {
        if here.provenance_seen {
            disengage;
        }
        here.provenance_seen = True;
        self.geometry_reads = self.geometry_reads + 1;
        visit [->:ReadsGeometry:->] else {
            disengage;
        }
    }
}

