walker Reachability {
    has target_signature: str = "";
    has seen: list[str] = [];
    has found: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can enter_file with SourceFile entry {
        print(f"Scanning {here.path}");
        visit [->:Contains:->] else { disengage; }
    }

