"""Deterministic Sentinel replay and evidence reduction over a typed graph."""

node SentinelCase {
    has title: str = "";
    has trusted_task: str = "";
    has invalid_input: bool = False;
    has unsupported_language: bool = False;
    has max_replays: int = 0;
    has provenance: str = "";
}

node EvidenceBranch {
    has label: str = "";
    has score: int = 0;
    has hard_failure: bool = False;
    has honey_tripwire: bool = False;
    has disagreement: bool = False;
    has source_ref: str = "";
}

node CounterfactualVariant {
    has label: str = "";
    has original_dangerous: bool = False;
    has attenuated_dangerous: bool = False;
    has unrelated_change: bool = False;
    has source_ref: str = "";
}

node Verdict {
    has label: str = "Clean";
    has reason: str = "";
    has provenance: str = "";
    has summary: str = "";
    has replay_count: int = 0;
}

edge VariantOf { }
edge DependsOn { }
edge EvidenceFor { }
edge Produces { }

walker Reducer {
    has final_verdict: Verdict | None = None;
    has seen_labels: list[str] = [];
    has evidence_score: int = 0;
    has hard_failure: bool = False;
    has honey_tripwire: bool = False;
    has disagreement: bool = False;
    has cycle_detected: bool = False;
    has replay_limit: int = 0;
    has replay_count: int = 0;
    has saw_invalid: bool = False;
    has saw_unsupported: bool = False;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_case with SentinelCase entry {
        self.replay_limit = here.max_replays;
        self.saw_invalid = here.invalid_input;
        self.saw_unsupported = here.unsupported_language;

        if self.final_verdict is not None {
            self.final_verdict.provenance = here.provenance;
        }

        visit [->:EvidenceFor:->] else {
            disengage;
        }
    }

    can inspect_branch with EvidenceBranch entry {
        if here.label in self.seen_labels {
            self.cycle_detected = True;
            disengage;
        }

        self.seen_labels.append(here.label);
        self.evidence_score = self.evidence_score + here.score;
        self.hard_failure = self.hard_failure or here.hard_failure;
        self.honey_tripwire = self.honey_tripwire or here.honey_tripwire;
        self.disagreement = self.disagreement or here.disagreement;

        visit [->:VariantOf:->] else {
            disengage;
        }
    }

    can replay with CounterfactualVariant entry {
        if here.label in self.seen_labels {
            self.cycle_detected = True;
            disengage;
        }

        self.seen_labels.append(here.label);

        if self.replay_count < self.replay_limit {
            self.replay_count = self.replay_count + 1;

            if here.original_dangerous
                and not here.attenuated_dangerous
                and not here.unrelated_change {
                self.disagreement = True;
                self.evidence_score = self.evidence_score + 2;
            }
        }

        visit [->:DependsOn:->] else {
            disengage;
        }
    }

    can conclude with exit {
        if self.final_verdict is not None {
            self.final_verdict.replay_count = self.replay_count;

            if self.saw_invalid {
                self.final_verdict.label = "InvalidInput";
                self.final_verdict.reason = "input validation failed";
            } elif self.saw_unsupported {
                self.final_verdict.label = "UnsupportedLanguage";
                self.final_verdict.reason = "language support is unavailable";
            } elif self.hard_failure or self.honey_tripwire {
                self.final_verdict.label = "Injection";
                self.final_verdict.reason = "hard evidence or behavioral tripwire fired";
            } elif self.disagreement {
                self.final_verdict.label = "Suspicious";
                self.final_verdict.reason = "counterfactual replay changed the dangerous trajectory";
            } else {
                self.final_verdict.label = "Clean";
                self.final_verdict.reason = "no deterministic attack evidence observed";
            }

            self.final_verdict.summary =
                f"{self.final_verdict.label}: {self.final_verdict.reason}; "
                f"score={self.evidence_score}; replays={self.replay_count}; "
                f"cycle={self.cycle_detected}; "
                f"provenance={self.final_verdict.provenance}";
        }
    }
}

