walker RoutingAuditor {
    has codex_success: bool = True;
    has callback_success: bool = False;
    has final_status: str = "not-attempted";
    has returned_to_ledger: bool = False;
    has hops: int = 0;
    has max_hops: int = 8;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Task | Preparation | CodexReview | Callback entry {
        self.hops += 1;

        if self.hops > self.max_hops {
            here.outcome = "cycle-limit";
            disengage;
        } else {
            if self.returned_to_ledger {
                here.outcome = self.final_status;
                disengage;
            } else {
                if here.kind == "codex" {
                    self.codex_success = here.state == "succeeded";
                }

                if here.kind == "callback" {
                    self.callback_success = here.state == "completed";

                    if self.codex_success {
                        if self.callback_success {
                            self.final_status = "completed";
                        } else {
                            self.final_status = "blocked";
                        }
                    } else {
                        self.final_status = "failed";
                    }

                    here.outcome = self.final_status;
                    self.returned_to_ledger = True;
                }

                visit [-->] else {
                    disengage;
                }
            }
        }
    }
}

