"""Tenant-scoped holons with guarded re-parenting and descendant restamping."""

node Tenant {
    has title: str = "";
    has tenant_code: str = "";
    has domain_code: str = "";
}

node Holon {
    has title: str = "";
    has tenant_code: str = "";
    has domain_code: str = "";
    has visit_mark: int = 0;
}

node Journey {
    has title: str = "";
    has config_version: int = 1;
    has owner_code: str | None = None;
    has domain_code: str = "";
    has available: bool = True;
}

edge Contains { }
edge CatalogEntry { }
edge Owns { }

walker TenantRestamper {
    has target_tenant_code: str = "";
    has target_domain_code: str = "";
    has walk_id: int = 1;

    can restamp with Holon entry {
        if here.visit_mark == self.walk_id {
            print(f"Cycle guard stopped at {here.title}");
            disengage;
        } else {
            here.visit_mark = self.walk_id;
            here.tenant_code = self.target_tenant_code;
            here.domain_code = self.target_domain_code;
            print(f"Restamped {here.title} to {here.tenant_code}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }
}

def reparent_holon(
    source: Tenant,
    target: Tenant,
    holon: Holon,
    is_superuser: bool
) -> bool {
    if not is_superuser {
        print(f"Denied re-parent of {holon.title}: superuser required");
        return False;
    }

    source del ->:Contains:-> holon;
    target +>:Contains:+> holon;
    holon spawn TenantRestamper(
        target_tenant_code=target.tenant_code,
        target_domain_code=target.domain_code
    );
    return True;
}

