walker ReferenceAuditor {
    has stale_count: int = 0;
    has checked_count: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with LibraryReference entry {
        if here.recognized {
            visit [->:PointsTo:->] else {
                self.stale_count += 1;
                print(f"STALE: {here.path} references missing DavItem {here.target_id}");
                visit [->:NextReference:->] else {
