"""Deterministic process blast-radius audit over a typed process forest."""

node ProcessMember {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has member_id: str = "";
    has process_class: str = "";
    has parent_domain: str = "";
    has generation: int = 0;
    has disposition: str = "alive";
    has restart_budget: int = 3;
    has heartbeat: int = 0;
}

node AgentDomain(ProcessMember) {
    has domain_name: str = "";
}

node Subagent(ProcessMember) {
    has task_name: str = "";
}

node ServingMember(ProcessMember) {
    has serving_role: str = "";
}

edge Supervises {
    has generation: int = 0;
}

walker BlastRadiusAudit {
    has scenario: str = "";
    has fault_target: str = "";
    has visited: list[str] = [];
    has expected_stopped: list[str] = [];
    has expected_restarted: list[str] = [];
    has observed_stopped: list[str] = [];
    has observed_restarted: list[str] = [];
    has disposition: str = "";
    has upward_path: str = "";
    has unrelated_progress: int = 0;
    has target_parent: str = "";
    has target_class: str = "";
    has pre_generation: int = 0;
    has post_generation: int = 0;

    can begin with Root entry {
        print(f"BEGIN scenario={self.scenario} target={self.fault_target}");
        visit [->:Supervises:->] else { disengage; }
    }

    can inspect with AgentDomain | Subagent | ServingMember entry {
        if here.member_id in self.visited {
            print(f"CYCLE member={here.member_id}");
            disengage;
        } else {
            self.visited = self.visited + [here.member_id];
            in_scope = here.member_id == self.fault_target;

            if self.scenario == "agent-stop" {
                if here.parent_domain == self.fault_target {
                    in_scope = True;
                }
            }

            if self.scenario == "corrupt-shared-state" {
                if here.parent_domain == self.fault_target {
                    in_scope = True;
                }
            }

            if here.member_id == self.fault_target {
                self.target_parent = here.parent_domain;
                self.target_class = here.process_class;
                self.pre_generation = here.generation;
            }

            if in_scope {
                if self.scenario == "restart-budget" {
                    self.disposition = "quarantine/operator-gate";
                    self.upward_path = "member -> supervisor (contained)";
                    self.expected_stopped = self.expected_stopped + [here.member_id];
                    self.observed_stopped = self.observed_stopped + [here.member_id];
                    self.post_generation = here.generation;
                } else {
                    self.disposition = "restart";
                    if self.scenario == "agent-stop" {
                        self.disposition = "domain-restart";
                    }
                    if self.scenario == "corrupt-shared-state" {
                        self.disposition = "owning-domain-replace";
                    }
                    self.upward_path = "member -> supervisor (contained)";
                    self.expected_stopped = self.expected_stopped + [here.member_id];
                    self.expected_restarted = self.expected_restarted + [here.member_id];
                    self.observed_stopped = self.observed_stopped + [here.member_id];
                    self.observed_restarted = self.observed_restarted + [here.member_id];
                    self.post_generation = here.generation + 1;
                }
                here.disposition = self.disposition;
            } else {
                here.heartbeat += 1;
                self.unrelated_progress += 1;
            }

            visit [->:Supervises:->] else { disengage; }
        }
    }

    can summarize with Root exit {
        gate_status = "PASS" if self.expected_stopped == self.observed_stopped
            and self.expected_restarted == self.observed_restarted else "FAIL";

        print(
            f"RECEIPT scenario={self.scenario} member={self.fault_target} "
            f"class={self.target_class} pre_generation={self.pre_generation} "
            f"post_generation={self.post_generation} parent_domain={self.target_parent} "
            f"disposition={self.disposition} budget=3 "
            f"expected_stopped={self.expected_stopped} "
            f"observed_stopped={self.observed_stopped} "
            f"expected_restart={self.expected_restarted} "
            f"observed_restart={self.observed_restarted} "
            f"upward={self.upward_path} "
            f"unrelated_progress={self.unrelated_progress} "
            f"root_identity=preserved gate={gate_status}"
        );
    }
}

