"""Recursive skill resolution with typed dependencies, deduplication, and cycle detection."""

node Manifest {
    has title: str = "";
    has transitive: bool = True;
}

node Skill {
    has title: str = "";
    has git: str = "";
    has commit: str = "";
    has path: str = "";
    has pinned: bool = True;
}

edge Declares {
    has manifest_path: str = "";
}

edge Requires {
    has requested_path: str = "";
}

walker Resolver {
    has seen_keys: list[str] = [];
    has active_keys: list[str] = [];
    has resolved_count: int = 0;
    has cycle_detected: bool = False;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_manifest with Manifest entry {
        print(f"manifest {here.title}: transitive={here.transitive}");
        if not here.transitive {
            print("transitive resolution disabled");
            disengage;
        }
        visit [->:Declares:->] else { disengage; }
    }

    can resolve_skill with Skill entry {
        key = here.git + "|" + here.commit + "|" + here.path;

        if key in self.active_keys {
            print(f"ERROR: dependency cycle detected at {key}");
            self.cycle_detected = True;
            disengage;
        }

        if key in self.seen_keys {
            print(f"deduplicated {key}");
            return;
        }

        self.seen_keys.append(key);
        self.active_keys.append(key);
        self.resolved_count += 1;
        print(f"resolved {here.title} from {key}");
        visit [->:Requires:->] else { }
        self.active_keys.remove(key);
    }
}

