"""Deterministic process blast-radius audit over a typed process forest."""

node ProcessMember {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has member_id: str = "";
    has process_class: str = "";
    has parent_domain: str = "";
    has generation: int = 1;
    has disposition: str = "alive";
    has heartbeat: int = 0;
}

node AgentDomain(ProcessMember) {
    has domain_name: str = "";
}

node Subagent(ProcessMember) {
    has task_name: str = "";
}

node ServingMember(ProcessMember) {
    has serving_role: str = "";
}

edge Supervises {
    has generation: int = 1;
}

walker BlastRadiusAudit {
    has scenario: str = "";
    has fault_target: str = "";
    has visited: list[str] = [];
    has expected_stopped: list[str] = [];
    has expected_restarted: list[str] = [];
    has observed_stopped: list[str] = [];
    has observed_restarted: list[str] = [];
    has target_parent: str = "";
    has target_class: str = "";
    has pre_generation: int = 0;
    has post_generation: int = 0;
    has unrelated_progress: int = 0;
    has steps: int = 0;
    has step_limit: int = 32;

    can begin with Root entry {
        if self.scenario == "agent-stop" {
            self.expected_stopped = ["agent-a", "sub-a", "sub-b"];
            self.expected_restarted = ["agent-a", "sub-a", "sub-b"];
        }

        if self.scenario == "subagent-panic" {
            self.expected_stopped = ["sub-b"];
            self.expected_restarted = ["sub-b"];
        }

        if self.scenario == "serving-replica-fault" {
            self.expected_stopped = ["replica-a"];
            self.expected_restarted = ["replica-a"];
        }

        visit [->:Supervises:->] else {
            disengage;
        }
    }

    can inspect with ProcessMember entry {
        if self.steps >= self.step_limit {
            disengage;
        } else {
            next_steps = self.steps + 1;
            self.steps = next_steps;

            if here.member_id in self.visited {
                disengage;
            } else {
                self.visited = self.visited + [here.member_id];

                in_scope = here.member_id == self.fault_target;

                if self.scenario == "agent-stop" {
                    if here.parent_domain == self.fault_target {
                        in_scope = True;
                    }
                }

                if in_scope {
                    self.target_parent = here.parent_domain;
                    self.target_class = here.process_class;
                    self.pre_generation = here.generation;
                    self.observed_stopped = self.observed_stopped + [here.member_id];
                    self.observed_restarted = self.observed_restarted + [here.member_id];

                    next_generation = here.generation + 1;
                    here.generation = next_generation;
                    self.post_generation = next_generation;
                    here.disposition = "contained-restart";
                } else {
                    next_heartbeat = here.heartbeat + 1;
                    here.heartbeat = next_heartbeat;
                    self.unrelated_progress = self.unrelated_progress + 1;
                }

                visit [->:Supervises:->] else {
                    disengage;
                }
            }
        }
    }

    can summarize with Root exit {
        gate_status = "PASS"
            if self.expected_stopped == self.observed_stopped
            and self.expected_restarted == self.observed_restarted
            else "FAIL";

        print(
            f"RECEIPT scenario={self.scenario} target={self.fault_target} "
            f"class={self.target_class} parent={self.target_parent} "
            f"pre_generation={self.pre_generation} "
            f"post_generation={self.post_generation} "
            f"expected_stopped={self.expected_stopped} "
            f"observed_stopped={self.observed_stopped} "
            f"expected_restarted={self.expected_restarted} "
            f"observed_restarted={self.observed_restarted} "
            f"unrelated_progress={self.unrelated_progress} "
            f"root_identity=preserved gate={gate_status}"
        );
    }
}

