"""Cycle-safe recursive resolution of nested skill manifests."""

node Manifest {
    has title: str = "";
    has transitive: bool = True;
}

node Skill {
    has title: str = "";
    has git: str = "";
    has commit: str = "";
    has path: str = "";
    has state: str = "new";

    def resolution_key() -> str {
        return self.git + "|" + self.commit + "|" + self.path;
    }
}

edge Declares {
    has manifest_path: str = "";
}

edge Requires {
    has requested_path: str = "";
}

walker Resolver {
    has resolved_count: int = 0;
    has cycle_detected: bool = False;
    has steps_left: int = 32;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can open_manifest with Manifest entry {
        print(f"manifest {here.title}: transitive={here.transitive}");
        if here.transitive {
            visit [->:Declares:->] else { disengage; }
        } else {
            print("transitive resolution disabled");
            disengage;
        }
    }

    can resolve_skill with Skill entry {
        if self.steps_left <= 0 {
            print("ERROR: resolution walk budget exhausted");
            disengage;
        } else {
            self.steps_left -= 1;

            if here.state == "active" {
                print(f"ERROR: dependency cycle detected at {here.resolution_key()}");
                self.cycle_detected = True;
                disengage;
            } elif here.state == "done" {
                print(f"deduplicated {here.resolution_key()}");
            } else {
                here.state = "active";
                self.resolved_count += 1;
                print(f"resolved {here.title} from {here.resolution_key()}");
                visit [->:Requires:->] else {
                    print(f"no nested skills in {here.title}");
                }
                here.state = "done";
            }
        }
    }
}

