node Application {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has app_key: str = "";
}

node Resource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has exact_key: str = "";
    has provenance: str = "created";
    has retention: str = "ordinary";
    has scope: str = "application";
    has references: int = 0;
    has registered: bool = True;
    has ambiguous: bool = False;
    has current_required: bool = False;
    has exact_identity: bool = True;
    has locked: bool = False;
    has planned_generation: int = 1;
    has observed_generation: int = 1;
    has state: str = "present";
}

edge Contains {
    has role: str = "payload";
}

edge DependsOn {
    has reason: str = "runtime dependency";
}

walker RemovalCoordinator {
    has mode: str = "application";
    has confirmation: str = "";
    has confirmation_digest: str = "";
    has plan_digest: str = "sha256:inventory-v1";
    has seen_keys: list[str] = [];
    has preserved: list[str] = [];
    has removed: list[str] = [];
    has cycle_detected: bool = False;
    has halted: bool = False;

    def preserve(item: Resource, reason: str) {
        self.preserved.append(item.title);
        print(f"PRESERVE {item.title}: {reason}");
    }

    def remove_exact(item: Resource) {
        print(f"REBIND and remove exact artifact {item.exact_key}");
        item.available = False;
        item.state = "removed";
        self.removed.append(item.title);
        print(f"OBSERVED removed {item.title}");
    }

    can start with Root entry {
        print(f"PLAN mode={self.mode} digest={self.plan_digest}");
        if self.confirmation != "REMOVE" {
            print("ABORT: literal REMOVE confirmation is required");
            self.halted = True;
        }
        if self.confirmation_digest != self.plan_digest {
            print("ABORT: plan digest changed before effects started");
            self.halted = True;
        }
        if self.mode != "application" {
            if self.mode != "purge" {
                print("ABORT: unknown removal mode");
                self.halted = True;
            }
        }
        if self.halted {
            disengage;
        } else {
            visit [-->] else {
                disengage;
            }
        }
    }

    can inspect with Application entry {
        if self.halted {
            disengage;
        } else {
            print(f"INVENTORY {here.app_key}: {here.title}");
            visit [->:Contains:->] else {
                disengage;
            }
        }
    }

    can evaluate with Resource entry {
        if self.halted {
            disengage;
        } elif here.exact_key in self.seen_keys {
            self.cycle_detected = True;
            print(f"CYCLE detected at {here.title}; stopping safely");
            self.halted = True;
            disengage;
        } else {
            self.seen_keys.append(here.exact_key);
            eligible = True;

            if here.state != "present" {
                self.preserve(here, "already reconciled");
                eligible = False;
            }
            if here.planned_generation != here.observed_generation {
                self.preserve(here, "plan drift");
                eligible = False;
            }
            if not here.registered {
                self.preserve(here, "unregistered");
                eligible = False;
            }
            if here.ambiguous {
                self.preserve(here, "ambiguous identity");
                eligible = False;
            }
            if here.references > 0 {
                self.preserve(here, "referenced");
                eligible = False;
            }
            if here.current_required {
                self.preserve(here, "current/LKG required");
                eligible = False;
            }
            if not here.exact_identity {
                self.preserve(here, "exact identity check failed");
                eligible = False;
            }
            if here.locked {
                self.preserve(here, "sharing or lock failure");
                eligible = False;
            }
            if here.provenance == "foreign" {
                self.preserve(here, "foreign provenance");
                eligible = False;
            }
            if self.mode == "application" {
                if here.scope != "application" {
                    self.preserve(
                        here, "environment state excluded from application removal"
                    );
                    eligible = False;
                }
            }
            if self.mode == "purge" {
                if here.scope != "application" {
                    if here.scope != "environment" {
                        self.preserve(here, "scope is not locally authorized");
                        eligible = False;
                    }
                }
            }
            if eligible {
                self.remove_exact(here);
            }

            if self.halted {
                disengage;
            } else {
                visit [->:DependsOn:->] else {
                    disengage;
                }
            }
        }
    }

    can summarize with Root exit {
        print(f"REMOVED={self.removed}");
        print(f"PRESERVED={self.preserved}");
        print(f"CYCLE={self.cycle_detected}");
    }
}

