walker CleanupAuditor {
    has verified_count: int = 0;
    has skipped_count: int = 0;
    has allow_destructive: bool = False;

    can begin with Root entry {
        print("cleanup discovery: completion is not import evidence");
        visit [-->] else { disengage; }
    }

    can inspect_download with Download entry {
        print(f"download {here.hash_hint} category={here.category} completed={here.completed}");
        visit [->:HasEvidence:->] else { disengage; }
    }

    can inspect_evidence with ImportEvidence entry {
        classification = "insufficient_evidence";
        if not here.download_completed {
            classification = "not_completed";
        } else {
            if here.active_reference {
                classification = "still_active";
            } else {
                if not here.imported {
                    classification = "not_imported";
                } else {
                    if here.ambiguous_match or here.title_only_match {
                        classification = "ambiguous_match";
                    } else {
                        if not here.hash_correlated or not here.event_correlated or here.evidence_ref == "" {
                            classification = "insufficient_evidence";
                        } else {
                            if not here.library_exists or here.library_size <= 0 {
                                classification = "library_file_missing";
                            } else {
                                if not here.path_separate {
                                    classification = "same_path_or_hardlink_uncertain";
                                } else {
                                    if not here.path_root_safe or not here.symlink_safe {
                                        classification = "insufficient_evidence";
                                    } else {
                                        classification = "import_verified";
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }

        candidate_found = classification == "import_verified";
        if candidate_found {
            self.verified_count += 1;
            print(f"evidence {here.evidence_ref}: {classification}; client_entry=eligible");
            if self.allow_destructive and here.explicit_confirmation {
                print("data deletion gate: ready pending immediate library revalidation");
            } else {
                print("data deletion gate: blocked by permission or confirmation");
            }
        } else {
            self.skipped_count += 1;
            print(f"evidence {here.evidence_ref}: {classification}; cleanup=skipped");
        }
        visit [->:Represents:->] else { disengage; }
    }

    can revalidate_library with LibraryFile entry {
        if here.exists and here.size_bytes > 0 and here.path_root_safe and here.symlink_safe {
            print(f"library revalidated: present size={here.size_bytes}");
            print("data deletion: still requires allow_destructive and explicit confirmation");
        } else {
            print("library revalidation failed: library_file_missing; removal=skipped");
        }
    }

    can summarize with Root exit {
        print(f"verified_candidates={self.verified_count} skipped={self.skipped_count}");
    }
}

