    has reliability: str = "";
}

edge EvidenceLink {
    has relation: str = "";
}

walker ImpactInvestigator {
    has entries_seen: int = 0;
    has sources_seen: int = 0;
    has hops_left: int = 8;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with StartupEntry entry {
        if self.hops_left <= 0 {
            print("Traversal limit reached; investigation stopped safely.");
            disengage;
        }
        self.hops_left -= 1;
        self.entries_seen += 1;
        print(f"Entry: {here.title} | impact={here.impact_status}");
        print(f"Source: {here.source_name}");
        visit [->:EvidenceLink:->] else {
