        }
    }

    can evaluate with EvidenceSource entry {
        if self.hops_left <= 0 {
            disengage;
        }
        self.hops_left -= 1;
        self.sources_seen += 1;
        print(f"Evidence: {here.title}");
        print(f"Capability: {here.capability}");
        print(f"Privilege: {here.privilege}");
        print(f"Reliability: {here.reliability}");
    }

    can finish with Root exit {
        print(f"Investigated {self.entries_seen} entries and {self.sources_seen} evidence sources.");
        print("Conclusion: per-entry startup impact remains Unknown.");
    }
}

