}

node Problem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has audit_order: int = 0;
    has cycle_detected: bool = False;
}

edge Includes {
    has group: str = "";
}

edge Prerequisite {
    has rationale: str = "";
}

walker DependencyAudit {
    has next_order: int = 1;
    has cycles_found: int = 0;
    has path: list[str] = [];

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit_catalog with Catalog entry {
        visit [->:Includes:->] else {
            disengage;
        }
        here.audited = self.cycles_found == 0;
    }

    can audit_problem with Problem entry {
        if here.title in self.path {
            here.cycle_detected = True;
            self.cycles_found += 1;
            disengage;
        } else {
            self.path.append(here.title);
            here.audit_order = self.next_order;
            self.next_order += 1;
            visit [->:Prerequisite:->] else {
                disengage;
            }
            self.path.pop();
        }
    }
}

