"""Native catalog dependency walk with explicit cycle protection."""

node Catalog {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has audited: bool = False;
}

node Problem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has expanded: bool = False;
    has active: bool = False;
    has cycle_detected: bool = False;
    has audit_order: int = 0;
}

edge Includes {
    has group: str = "";
}

edge Prerequisite {
    has rationale: str = "";
}

walker DependencyAudit {
    has next_order: int = 1;
    has cycles_found: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can audit_catalog with Catalog entry {
        here.audited = True;
        visit [->:Includes:->] else {
            disengage;
        }
    }

    can audit_problem with Problem entry {
        if here.active {
            here.cycle_detected = True;
            self.cycles_found += 1;
            disengage;
        }
        if here.expanded {
            disengage;
        }
        here.active = True;
        here.expanded = True;
