    has completed: bool = False;
    has imported: bool = False;
    has active_reference: bool = False;
    has hash_correlated: bool = False;
    has event_correlated: bool = False;
    has ambiguous_match: bool = False;
    has title_only_match: bool = False;
    has library_exists: bool = False;
    has library_size: int = 0;
    has path_separate: bool = False;
    has path_root_safe: bool = False;
    has symlink_safe: bool = False;
    has explicit_confirmation: bool = False;
    has decision: str = "";
}

node LibraryFile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has exists: bool = False;
    has size_bytes: int = 0;
    has path_separate: bool = False;
    has path_root_safe: bool = False;
    has symlink_safe: bool = False;
    has explicit_confirmation: bool = False;
}

edge Contains { }
edge HasEvidence { }
edge Represents { }

walker CleanupAuditor {
    has allow_destructive: bool = False;
    has verified_count: int = 0;
    has skipped_count: int = 0;

    can begin with Root entry {
        print("cleanup discovery: completion alone is not import evidence");
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_download with Download entry {
        print(f"download observed: completed={here.completed}");
        visit [->:HasEvidence:->] else {
            disengage;
        }
    }

    can inspect_evidence with ImportEvidence entry {
        classification = "insufficient_evidence";
        if not here.completed {
            classification = "not_completed";
        } elif here.active_reference {
            classification = "still_active";
        } elif not here.imported {
            classification = "not_imported";
        } elif here.ambiguous_match or here.title_only_match {
            classification = "ambiguous_match";
        } elif not here.hash_correlated or not here.event_correlated {
            classification = "insufficient_evidence";
        } elif not here.library_exists or here.library_size <= 0 {
            classification = "library_file_missing";
        } elif not here.path_separate {
            classification = "same_path_or_hardlink_uncertain";
        } elif not here.path_root_safe or not here.symlink_safe {
            classification = "insufficient_evidence";
        } else {
            classification = "import_verified";
        }

        here.decision = classification;
        if classification == "import_verified" {
            self.verified_count += 1;
            print("import_verified: client-entry removal may be proposed");
            if self.allow_destructive and here.explicit_confirmation {
                print("data removal remains gated by immediate library revalidation");
            } else {
                print("data removal blocked: permission or explicit confirmation missing");
            }
        } else {
            self.skipped_count += 1;
            print(f"cleanup skipped: {classification}");
        }

        visit [->:Represents:->] else {
            disengage;
        }
    }

    can revalidate_library with LibraryFile entry {
        if here.exists and here.size_bytes > 0 and here.path_separate and here.path_root_safe and here.symlink_safe {
            print(f"library revalidated: present size={here.size_bytes}");
            if self.allow_destructive and here.explicit_confirmation {
                print("demo decision: data removal permitted after final confirmation");
            } else {
                print("demo decision: client entry only; data removal denied");
            }
        } else {
            print("library revalidation failed: cleanup skipped");
        }
    }
}

