"""Coordinate bounded production canaries with dependency traversal and revisit guards."""

node Gate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has monitoring_ready: bool = False;
    has recovery_ready: bool = False;
    has auth_clear: bool = False;
}

node Canary {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_revision: str = "";
    has evidence_coverage: bool = False;
    has state_preserved: bool = False;
    has signed_delivery: bool = False;
    has stable_identity: bool = False;
    has idempotent_delivery: bool = False;
    has rollback_ready: bool = False;
    has owner_decision: str = "defer";
    has eligible: bool = False;
    has revisit_blocked: bool = False;
}

edge Schedules {
    has sequence: int = 0;
}

edge DependsOn {
    has reason: str = "";
}

walker Coordinator {
    has visited: list[str] = [];
    has gate_ready: bool = False;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_gate with Gate entry {
        if here.title in self.visited {
            disengage;
        }

        self.visited.append(here.title);
        self.gate_ready = here.monitoring_ready;
        if self.gate_ready {
            if here.recovery_ready {
                if here.auth_clear {
                    visit [->:Schedules:->] else {
                        disengage;
                    }
                }
            }
        }
    }

    can inspect_canary with Canary entry {
        if here.title in self.visited {
            here.revisit_blocked = True;
            disengage;
        }

        self.visited.append(here.title);

        if self.gate_ready {
            if here.evidence_coverage {
                if here.state_preserved {
                    if here.signed_delivery {
                        if here.stable_identity {
                            if here.idempotent_delivery {
                                if here.rollback_ready {
                                    here.eligible = True;
                                    here.owner_decision = "bounded canary";
                                }
                            }
                        }
                    }
                }
            }
        }

        visit [->:DependsOn:->] else {
            disengage;
        }
    }
}

