"""Docs build cache audit: walk workflow dependencies and expose redundant archives."""

node BuildResource {
    has title: str = "";

    def finding() -> str {
        return self.title;
    }
}

node Pipeline(BuildResource) {
    has trigger: str = "";

    override def finding() -> str {
        return f"workflow {self.title} ({self.trigger})";
    }
}

node Job(BuildResource) {
    has duration_seconds: int = 0;

    override def finding() -> str {
        return f"job {self.title}: {self.duration_seconds}s";
    }
}

node CacheLayer(BuildResource) {
    has restore_seconds: int = 0;
    has artifact_size_mb: int = 0;
    has redundant: bool = False;

    override def finding() -> str {
        label = "redundant node_modules archive" if self.redundant else "npm package cache";
        advice = "replace with npm ci" if self.redundant else "retain package cache";
        return f"{label} {self.title}: {self.artifact_size_mb} MB, {self.restore_seconds}s; {advice}";
    }
}

edge Contains {
    has order: int = 0;
}

edge UsesCache {
    has purpose: str = "";
}

walker CacheAuditor {
    has visited_titles: list[str] = [];
    has max_steps: int = 12;
    has steps_seen: int = 0;

    can start with Root entry {
        print("Auditing docs build dependency graph");
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Pipeline | Job | CacheLayer entry {
        if here.title in self.visited_titles {
            print(f"cycle detected at {here.title}");
            disengage;
        }
        if self.steps_seen >= self.max_steps {
            print("depth limit reached; stopping audit");
            disengage;
        }

        self.visited_titles.append(here.title);
        self.steps_seen += 1;
        print(here.finding());
        visit [-->] else {
            disengage;
        }
    }
}

