"""Coordinate bounded learning and job canaries through a verified production gate."""

node ProductionGate {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has monitoring_ready: bool = False;
    has recovery_ready: bool = False;
    has authorization_clear: bool = False;
    has gate_ready: bool = False;
}

node Canary {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has issue_number: int = 0;
    has source_revision: str = "";
    has private_state_preserved: bool = False;
    has signed_delivery: bool = False;
    has stable_identity: bool = False;
    has idempotent_delivery: bool = False;
    has rollback_ready: bool = False;
    has eligible: bool = False;
    has owner_decision: str = "defer";
}

node Evidence {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has source_revision: str = "";
    has accepted_count: int = 0;
    has deduplicated_count: int = 0;
    has coverage_percent: int = 0;
    has delivery_verified: bool = False;
    has target_cycle_visible: bool = False;
    has user_state_preserved: bool = False;
    has rollback_verified: bool = False;
}

edge Requires {
    has reason: str = "";
}

edge Enables {
    has sequence: int = 0;
}

edge ProducesEvidence {
    has revision: str = "";
}

walker Coordinator {
    has gate_ready: bool = False;
    has seen_titles: list[str] = [];

    can start with Root entry {
        print("starting bounded canary coordination");
        visit [->:Requires:->] else {
            disengage;
        }
    }

    can inspect_gate with ProductionGate entry {
        if here.title in self.seen_titles {
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            here.gate_ready = here.monitoring_ready
                and here.recovery_ready
                and here.authorization_clear;

            if here.gate_ready {
                self.gate_ready = True;
                print(f"production gate ready: {here.title}");
                visit [->:Enables:->] else {
                    disengage;
                }
            } else {
                print("production gate blocked; canaries remain disabled");
                disengage;
            }
        }
    }

    can inspect_canary with Canary entry {
        if here.title in self.seen_titles {
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            here.eligible = self.gate_ready
                and here.private_state_preserved
                and here.signed_delivery
                and here.stable_identity
                and here.idempotent_delivery
                and here.rollback_ready;

            if here.eligible {
                here.owner_decision = "bounded canary";
                print(f"canary #{here.issue_number} accepted: {here.title}");
            } else {
                here.owner_decision = "defer";
                print(f"canary #{here.issue_number} deferred: {here.title}");
            }

            visit [->:ProducesEvidence:->] else {
                disengage;
            }
        }
    }

    can inspect_evidence with Evidence entry {
        if here.title in self.seen_titles {
            print(f"cycle detected at {here.title}");
            disengage;
        } else {
            self.seen_titles.append(here.title);
            evidence_ready = here.coverage_percent == 100
                and here.delivery_verified
                and here.target_cycle_visible
                and here.user_state_preserved
                and here.rollback_verified;

            if evidence_ready {
                print(f"evidence complete: {here.title} from {here.source_revision}");
                print(f"accepted={here.accepted_count}, deduplicated={here.deduplicated_count}");
            } else {
                print(f"evidence incomplete: {here.title}; rollout stays bounded");
            }

            visit [-->] else {
                disengage;
            }
        }
    }
}

