        if self.retrieval_count >= self.budget {
            print(f"Budget reached before {here.title}");
            disengage;
        }

        if here.available {
            self.retrieval_count += 1;
            print(f"Retrieved {here.title} from {here.source}");
        } else {
            print(f"Filtered unavailable knowledge: {here.title}");
        }

        visit [->:DependsOn:->] else {
            disengage;
        }
    }
