        here.seen_by_broker = True;

        if self.retrieved_count >= self.budget {
            print(f"Budget reached before {here.title}");
            disengage;
        }

        if here.available and here.confidence >= 0.80 {
            self.retrieved_count += 1;
            print(f"Retrieved {here.title} from {here.source}");
        } else {
            print(f"Filtered knowledge: {here.title}");
        }

        visit [->:Supports:->] else {
            disengage;
        }
    }
}

