"""Model a dropped descendant and propagate its truncation marker."""

node ObservedSubtree {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has structurally_complete: bool = True;
    has subtree_complete: bool = True;
    has dropped_descendant: bool = False;
    has seen: bool = False;
}

node AccessibilityNode {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has subtree_truncated: bool = False;
}

edge Contains {
    has slot: int = 0;
}

edge ProjectsTo {
    has reason: str = "";
}

walker SnapshotProjector {
    has global_complete: bool = True;
    has nodes_observed: int = 0;

    can start with Root entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can project with ObservedSubtree entry {
        if here.seen {
            disengage;
        }

        here.seen = True;
        self.nodes_observed += 1;

        if here.structurally_complete == False
            && here.dropped_descendant == True {
            here.subtree_complete = False;
        }

        marker = here.subtree_complete == False;
        if marker {
            self.global_complete = False;
        }

        projected = AccessibilityNode(
            title=here.title,
            year=here.year,
            available=here.available,
            subtree_truncated=marker
        );

        marker_reason = "dropped descendant" if marker else "complete";
        here +>:ProjectsTo(reason=marker_reason):+> projected;

        print(f"{here.title}: subtree_truncated={marker}");

        visit [->:Contains:->] else {
            disengage;
        }
    }
}

