        available=True,
        structurally_complete=False,
        subtree_complete=True,
        dropped_descendant=True
    );

    fixture +>:Contains(slot=0):+> retained;
    root +>:Contains(slot=0):+> fixture;

    projector = SnapshotProjector();
    root spawn projector;

    print(f"complete={projector.global_complete}, "
          f"nodes_observed={projector.nodes_observed}");
