"""Deterministic context package resolution with provenance checks and cycle safety."""

node ContextPackage {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has package_type: str = "project";
    has owner: str = "";
    has target: str = "";
    has mandatory: bool = False;
    has priority: int = 0;
}

node CanonicalSource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has path: str = "";
    has content_hash: str = "";
    has expected_hash: str = "";
    has owner: str = "";
    has revision: str = "";
    has expected_revision: str = "";
    has status_eligible: bool = True;
    has target_allowed: bool = True;

    def is_valid -> bool {
        return self.available
            and self.owner != ""
            and self.content_hash == self.expected_hash
            and self.revision == self.expected_revision
            and self.status_eligible
            and self.target_allowed;
    }
}

node RuntimeTarget {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has compiler_version: str = "";
}

edge DependsOn {
    has mandatory: bool = True;
}

edge DeclaresSource { }
edge EntryPackage { }

walker ContextCompiler {
    has target_name: str = "";
    has visited: list[str] = [];
    has cycle_found: bool = False;
    has failed: bool = False;
    has depth: int = 0;

    can start with Root entry {
        visit [-->] else { disengage; }
    }

    can inspect_target with RuntimeTarget entry {
        if here.title != self.target_name {
            self.failed = True;
            print(f"BLOCK target mismatch: {here.title}");
        } else {
            print(f"TARGET {here.title} compiler={here.compiler_version}");
        }
        visit [->:EntryPackage:->] else { disengage; }
    }

    can resolve_package with ContextPackage entry {
        if self.depth >= 12 {
            self.cycle_found = True;
            self.failed = True;
            print(f"BLOCK dependency cycle or excessive depth at {here.title}");
            disengage;
        } elif here.title in self.visited {
            self.cycle_found = True;
            self.failed = True;
            print(f"BLOCK dependency cycle at {here.title}");
            disengage;
        } else {
            self.visited.append(here.title);
            self.depth += 1;
            if here.available and here.owner != "" and here.target == self.target_name {
                print(f"RESOLVE {here.title} owner={here.owner}");
            } else {
                self.failed = True;
                print(f"BLOCK package policy: {here.title}");
            }
            visit [-->] else { disengage; }
        }
    }

    can validate_source with CanonicalSource entry {
        if here.is_valid() {
            print(f"PIN {here.path} hash={here.content_hash} revision={here.revision}");
        } else {
            self.failed = True;
            print(f"BLOCK source provenance: {here.path}");
        }
    }
}

