    has qps: float = 0.0;
    has latency_ms: float = 0.0;
    has cpu_percent: float = 0.0;
    has rss_mb: float = 0.0;
    has storage_mb: float = 0.0;
    has exact_served_partitions: int = 0;
    has partial_top_k: bool = False;
    has hidden_full_fanout: bool = False;
    has identity_valid: bool = True;
    has accounting_complete: bool = True;
    has all_or_error: bool = True;
}

node PartitionDomain {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has domain_id: str = "";
    has route_id: str = "";
    has generation: int = 0;
    has hnsw_served: bool = True;
    has exact_served: bool = False;
    has probes: int = 0;
}

node PhysicalPack {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has pack_id: str = "";
    has route_id: str = "";
    has generation: int = 0;
    has bytes: int = 0;
}

edge SelectedDomain {
    has route_id: str = "";
    has generation: int = 0;
    has probes: int = 0;
}

edge PackBinding {
    has route_id: str = "";
    has generation: int = 0;
}

walker PartitionAudit {
    has expected_route: str = "";
    has expected_generation: int = 0;
    has expected_domains: int = 0;
    has expected_packs: int = 0;
    has logical_domains: int = 0;
    has physical_packs: int = 0;
    has physical_bytes: int = 0;
    has errors: int = 0;

    can start with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect with Snapshot entry {
        print(f"dataset={here.dataset_id} source={here.source_binary} topology={here.topology_id}");
        print(f"route={here.route_id} generation={here.generation} requested_probes={here.requested_probes} selected_probes={here.selected_probes}");
        print(f"requested_ef={here.requested_ef_search} selected_ef={here.selected_ef_search} candidates={here.candidates} edges={here.edges} bytes={here.bytes}");
        print(f"rpcs={here.rpcs} merge_work={here.merge_work} recall={here.recall} qps={here.qps} latency_ms={here.latency_ms}");
        print(f"cpu_percent={here.cpu_percent} rss_mb={here.rss_mb} storage_mb={here.storage_mb}");

        if here.route_id != self.expected_route {
            print("[FAIL CLOSED] route identity mismatch");
            self.errors = self.errors + 1;
        }
        if here.generation != self.expected_generation {
            print("[FAIL CLOSED] stale generation");
            self.errors = self.errors + 1;
        }
        if here.selected_probes != here.requested_probes {
            print("[FAIL CLOSED] partial probe selection");
            self.errors = self.errors + 1;
        }
        if here.partial_top_k {
            print("[FAIL CLOSED] partial top-K");
            self.errors = self.errors + 1;
        }
        if here.hidden_full_fanout {
            print("[FAIL CLOSED] hidden full fanout");
            self.errors = self.errors + 1;
        }
        if not here.identity_valid {
            print("[FAIL CLOSED] missing identity evidence");
            self.errors = self.errors + 1;
        }
        if not here.accounting_complete {
            print("[FAIL CLOSED] missing logical or physical accounting");
            self.errors = self.errors + 1;
        }
        if not here.all_or_error {
            print("[FAIL CLOSED] partial result accepted");
            self.errors = self.errors + 1;
        }
        if here.exact_served_partitions > 0 {
            print("[FAIL CLOSED] exact-served partition detected");
            self.errors = self.errors + 1;
        }

        visit [->:SelectedDomain:->] else {
            disengage;
        }
    }

    can inspect with PartitionDomain entry {
        self.logical_domains = self.logical_domains + 1;

        if here.route_id != self.expected_route {
            print(f"[FAIL CLOSED] domain {here.domain_id} has the wrong route");
            self.errors = self.errors + 1;
        }
        if here.generation != self.expected_generation {
            print(f"[FAIL CLOSED] domain {here.domain_id} has a stale generation");
            self.errors = self.errors + 1;
        }
        if not here.hnsw_served {
            print(f"[FAIL CLOSED] domain {here.domain_id} was not HNSW-served");
            self.errors = self.errors + 1;
        }
        if here.exact_served {
            print(f"[FAIL CLOSED] domain {here.domain_id} used exact scan");
            self.errors = self.errors + 1;
        }

        print(f"logical_domain={here.domain_id} probes={here.probes}");
        visit [->:PackBinding:->] else {
            disengage;
        }
    }

    can inspect with PhysicalPack entry {
        self.physical_packs = self.physical_packs + 1;
        self.physical_bytes = self.physical_bytes + here.bytes;

        if here.route_id != self.expected_route {
            print(f"[FAIL CLOSED] pack {here.pack_id} has the wrong route");
            self.errors = self.errors + 1;
        }
        if here.generation != self.expected_generation {
            print(f"[FAIL CLOSED] pack {here.pack_id} has a stale generation");
            self.errors = self.errors + 1;
        }

        print(f"physical_pack={here.pack_id} bytes={here.bytes}");
    }

    can summarize with Root exit {
        if self.logical_domains != self.expected_domains {
            print("[FAIL CLOSED] logical-domain count mismatch");
            self.errors = self.errors + 1;
        }
        if self.physical_packs != self.expected_packs {
            print("[FAIL CLOSED] physical-pack count mismatch");
            self.errors = self.errors + 1;
        }

        status_label = "PASS" if self.errors == 0 else "FAIL CLOSED";
        print(f"partition audit {status_label}: domains={self.logical_domains} packs={self.physical_packs} bytes={self.physical_bytes} errors={self.errors}");
    }
}

