"""Metadata-driven smart-proxy routing demo using native Jac graph traversal."""

node Command {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has keyless: bool = False;
    has routed: bool = False;
}

node KeySpec {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has key_name: str = "";
    has position: int = 0;
}

node ProxyTarget {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has slot_name: str = "";
    has dispatch_count: int = 0;
}

edge HasKeySpec {
    has position: int = 0;
}

edge RoutesTo {
    has route_label: str = "";
}

walker SmartProxy {
    has seen_titles: list[str] = [];
    has extracted_keys: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can route with Command entry {
        if (here.title in self.seen_titles) {
            disengage;
        } else {
            self.seen_titles.append(here.title);
            if (here.keyless) {
                here.routed = False;
            } else {
                here.routed = True;
                visit [->:HasKeySpec:->] else {
                    here.routed = False;
                    disengage;
                }
            }
        }
    }

    can extract with KeySpec entry {
        if (here.title in self.seen_titles) {
            disengage;
        } else {
            self.seen_titles.append(here.title);
            self.extracted_keys += 1;
            visit [->:RoutesTo:->] else {
                disengage;
            }
        }
    }

    can dispatch with ProxyTarget entry {
        if (here.title in self.seen_titles) {
            disengage;
        } else {
            self.seen_titles.append(here.title);
            here.dispatch_count += 1;
        }
    }
}

with entry {
    get_command = Command(title="GET");
