    secondary = ProxyTarget(title="Secondary shard", slot_name="secondary");

    root ++> get_command;
    root ++> mget_command;
    root ++> ping_command;

    get_command +>:HasKeySpec(position=1):+> get_key;
    mget_command +>:HasKeySpec(position=1):+> mget_key;

    get_key +>:RoutesTo(route_label="metadata key specification"):+> primary;
    mget_key +>:RoutesTo(route_label="metadata key specification"):+> secondary;

    root spawn SmartProxy();
}

"""Cross-folder email thread traversal with explicit cycle detection."""

node MailAccount {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has account_id: str = "";
}

node Mailbox {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has mailbox_name: str = "";
}

node Email {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has account_id: str = "";
    has mailbox_name: str = "";
    has message_id: str = "";
    has thread_id: str = "";
    has in_reply_to: str = "";
}

edge HasMailbox { }
edge ContainsMail { }
edge ReplyChain { }

walker ThreadCollector {
    has target_thread: str = "";
    has visited_messages: list[str] = [];
    has collected_count: int = 0;
    has cycle_count: int = 0;
    has dead_end_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_account with MailAccount entry {
        visit [->:HasMailbox:->] else {
            disengage;
        }
    }

    can inspect_mailbox with Mailbox entry {
        visit [->:ContainsMail:->] else {
            disengage;
        }
    }

    can inspect_message with Email entry {
        if here.thread_id == self.target_thread {
            if here.message_id in self.visited_messages {
                self.cycle_count += 1;
            } else {
                self.visited_messages.append(here.message_id);
                self.collected_count += 1;
                visit [->:ReplyChain:->] else {
                    self.dead_end_count += 1;
                    disengage;
                }
            }
        }
    }
}

