"""Failure-propagation graph for shared bot dependencies and resources."""

node Feature {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has bot: str = "";
    has user_symptom: str = "";
    has seen: bool = False;
}

node Dependency {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has failure_mode: str = "healthy";
    has shared_across_bots: bool = False;
    has seen: bool = False;
}

node SharedResource {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has capacity: int = 0;
    has seen: bool = False;
}

edge DependsOn {
    has shared: bool = False;
    has containment: str = "none";
}

edge UsesResource {
    has holding: str = "";
}

walker FailureMapper {
    has visited_count: int = 0;

    can start with Root entry {
        print("Failure propagation map");
        visit [-->] else {
            disengage;
        }
    }

    can inspect_feature with Feature entry {
        if here.seen {
            print(f"Guarded repeated feature: {here.title}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"Feature [{here.bot}] {here.title}: {here.user_symptom}");
            visit [->:DependsOn:->] else {
                disengage;
            }
        }
    }

    can inspect_dependency with Dependency entry {
        if here.seen {
            print(f"Cycle/shared-dependency guard: {here.title}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            if here.available {
                print(f"Dependency {here.title} is {here.failure_mode}");
            } else {
                print(f"Dependency {here.title} is DOWN");
            }
            visit [->:UsesResource:->] else {
                disengage;
            }
        }
    }

    can inspect_resource with SharedResource entry {
        if here.seen {
            print(f"Shared-resource guard: {here.title}");
        } else {
            here.seen = True;
            self.visited_count += 1;
            print(f"Resource {here.title} capacity={here.capacity}");
        }
    }
}

with entry {
    chat = Feature(
        title="chat turn",
