    redis +>:UsesResource(holding="global Redis slot"):+> redis_slot;
    postgres +>:UsesResource(holding="pool connection"):+> db_pool;

    root spawn FailureMapper();
}

"""Atomic region writes with typed parent edges and cycle-safe invalidation."""

node WorldView {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has tile_version: int = 0;
}

node Region {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has uses_hull: bool = False;
    has invalidated: bool = False;
    has deleted: bool = False;
    has last_transaction: int = 0;
}

edge Contains { }
edge ParentOf { }

walker RegionWriter {
    has view: WorldView | None = None;
    has target_region: str = "";
    has requested_hull: bool = False;
    has operation: str = "update";
    has transaction_id: int = 0;

    can begin with Root entry {
        visit [-->];
    }

    can enter_view with WorldView entry {
        visit [->:Contains:->];
    }

    can lock_apply_and_invalidate with Region entry {
        if here.last_transaction == self.transaction_id {
            print(f"cycle guarded at {here.title}");
            disengage;
        }

        here.last_transaction = self.transaction_id;

        if here.title == self.target_region {
            if self.operation == "delete" {
                here.deleted = True;
                here.available = False;
                here.invalidated = True;
                if self.view is not None {
                    self.view.tile_version += 1;
                }
                print(f"transaction {self.transaction_id}: deleted {here.title}");
            } else {
                old_hull = here.uses_hull;
                here.uses_hull = self.requested_hull;
                here.invalidated = True;
                if old_hull != here.uses_hull {
                    if self.view is not None {
                        self.view.tile_version += 1;
                    }
                    print(f"transaction {self.transaction_id}: updated {here.title}");
                } else {
                    print(f"transaction {self.transaction_id}: unchanged {here.title}");
                }
            }
        } else {
            here.invalidated = True;
            print(f"transaction {self.transaction_id}: invalidated {here.title}");
        }

        visit [<--:ParentOf:--] else {
            disengage;
        }
    }
}

with entry {
    atlas = WorldView(title="Atlas");
    continent = Region(title="Continent", year=2020);
    country = Region(title="Country", year=2020);
    province = Region(title="Province", year=2020);

    root ++> atlas;
    atlas +>:Contains:+> province;
    continent +>:ParentOf:+> country;
    country +>:ParentOf:+> province;
    province +>:ParentOf:+> continent;

    root spawn RegionWriter(
        view=atlas,
        target_region="Province",
        requested_hull=True,
        operation="update",
        transaction_id=1
    );

    root spawn RegionWriter(
        view=atlas,
        target_region="Province",
        requested_hull=False,
        operation="update",
        transaction_id=2
    );

    root spawn RegionWriter(
        view=atlas,
        target_region="Province",
        operation="delete",
        transaction_id=3
    );

    print(f"final tile version: {atlas.tile_version}");
}

"""Native tactical reachability without per-destination pathfinding."""

node Actor {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has name: str = "";
    has owned: bool = True;
    has action_points: int = 9;
    has fatigue: int = 0;
    has elevation: int = 0;
    has rooted: bool = False;
    has stunned: bool = False;
}

node Tile {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has label: str = "";
    has terrain_cost: int = 1;
    has elevation: int = 0;
    has known_occupancy: str = "empty";
    has in_zoc: bool = False;
}

edge StartsOn: Actor --> Tile { }

edge Passage: Tile --> Tile {
    has ap_cost: int = 1;
    has zoc_surcharge: int = 0;
    has jump: bool = False;
    has mandatory_landing: bool = False;
}

walker Reachability {
    has remaining_ap: int = 0;
    has fatigue: int = 0;
    has actor_elevation: int = 0;
    has rooted: bool = False;
    has stunned: bool = False;
    has step_limit: int = 4;
    has steps: int = 0;
    has seen: list[Tile] = [];
    has reachable: list[str] = [];

    can begin with Root entry {
        visit [-->];
    }

    can load_actor with Actor entry {
        if not here.owned {
            disengage;
        }
        self.remaining_ap = here.action_points - here.fatigue;
        self.fatigue = here.fatigue;
        self.actor_elevation = here.elevation;
        self.rooted = here.rooted;
        self.stunned = here.stunned;
        visit [->:StartsOn:->];
    }

    can inspect with Tile entry {
        if here in self.seen {
            skip;
        }
        self.seen.append(here);

        if self.rooted or self.stunned {
            disengage;
        }

        if here.known_occupancy == "enemy" or here.known_occupancy == "ally" {
            skip;
        }

        elevation_ok = here.elevation >= self.actor_elevation - 1;
        if elevation_ok {
            self.reachable.append(here.label);
        }

        if self.steps >= self.step_limit {
            disengage;
        }

        self.steps += 1;
        visit [edge ->:Passage:->] else {
            disengage;
        }
    }

    can cross with Passage entry {
        transition_cost = here.ap_cost + here.zoc_surcharge;
        if self.remaining_ap < transition_cost {
            disengage;
        }
        if here.jump and not here.mandatory_landing {
            disengage;
        }
        self.remaining_ap -= transition_cost;
    }
}

with entry {
    scout = Actor(
        title="Scout",
        name="Scout",
        action_points=9,
        fatigue=1,
        elevation=2
    );
    start = Tile(
        title="Start",
        label="Start",
        terrain_cost=2,
        elevation=2,
        in_zoc=True
    );
    ridge = Tile(
        title="Ridge",
        label="Ridge",
        terrain_cost=2,
        elevation=2
    );
    ally = Tile(
        title="Ally",
        label="Ally",
        known_occupancy="ally"
    );
    landing = Tile(
        title="Landing",
        label="Landing",
        terrain_cost=2,
        elevation=2
    );
    enemy = Tile(
        title="Enemy",
        label="Enemy",
        known_occupancy="enemy"
    );
    goal = Tile(
        title="Goal",
        label="Goal",
        terrain_cost=2,
        elevation=2
    );

    zoc_penalty = 4 if start.in_zoc else 0;

    root ++> scout;
    root ++> ally;
    scout +>:StartsOn:+> start;
    start +>:Passage(
        ap_cost=start.terrain_cost,
        zoc_surcharge=zoc_penalty
    ):+> ridge;
    start +>:Passage(
        ap_cost=start.terrain_cost,
        jump=True,
        mandatory_landing=True
    ):+> landing;
    ridge +>:Passage(ap_cost=ridge.terrain_cost):+> enemy;
    landing +>:Passage(ap_cost=landing.terrain_cost):+> goal;

    root spawn Reachability();
}

