"""A native interview catalog audits prerequisite links and detects cycles."""

node Catalog {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has owner: str = "";
}

node InterviewProblem {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has group: str = "";
    has invalidated: bool = False;
}

node Pattern {
    has title: str = "";
    has year: int = 0;
    has available: bool = True;
    has label: str = "";
}

edge Contains {
    has position: int = 0;
}

edge Covers {
    has note: str = "";
}

edge Prerequisite {
    has required: bool = True;
}

walker CatalogAuditor {
    has checked_titles: list[str] = [];
    has cycle_count: int = 0;
    has invalidation_count: int = 0;

    can begin with Root entry {
        visit [-->] else {
            disengage;
        }
    }

    can inspect_catalog with Catalog entry {
        visit [->:Contains:->] else {
            disengage;
        }
    }

    can inspect_problem with InterviewProblem entry {
        if here.title in self.checked_titles {
            self.cycle_count += 1;
            disengage;
        }

        self.checked_titles.append(here.title);

        if here.available == False {
            here.invalidated = True;
            self.invalidation_count += 1;
        }

        visit [->:Prerequisite:->] else {
            disengage;
        }
    }
}

with entry {
    catalog = Catalog(
        title="cppFan Native Interviews",
        year=2026,
        owner="cppFan"
    );

    trie = Pattern(
        title="Prefix lookup",
        year=2026,
        label="trie"
    );

    bfs = Pattern(
        title="Layered reachability",
        year=2026,
        label="multi-source BFS"
    );

    edit = InterviewProblem(
        title="Prefix Signal",
        year=2026,
        group="strings"
    );

    distance = InterviewProblem(
        title="Grid Relay",
        year=2026,
        group="graphs"
    );

    transform = InterviewProblem(
        title="Edit Ledger",
        year=2026,
        group="dp",
        available=False
    );

    root ++> catalog;
    catalog +>:Contains(position=1):+> edit;
    catalog +>:Contains(position=2):+> distance;
    catalog +>:Contains(position=3):+> transform;

    edit +>:Covers(note="transfer variant"):+> trie;
    distance +>:Covers(note="transfer variant"):+> bfs;
    transform +>:Covers(note="guided exercise differs"):+> edit;

    edit +>:Prerequisite(required=True):+> distance;
    distance +>:Prerequisite(required=True):+> transform;
    transform +>:Prerequisite(required=True):+> edit;

    root spawn CatalogAuditor();
}
